    (N'8746722D-D5AB-494F-9429-0012D0F2519D', N'GR30-HSK6-428', N'Trợ từ: 啦、嘛', N'', 6, N'助词', N'啦、嘛', N'Điểm ngữ pháp HSK 6 thuộc nhóm Từ loại (Trợ từ). Dùng trong mẫu câu diễn đạt chuẩn: 啦、嘛. Cung cấp quy tắc kết hợp cú pháp chuẩn xác và sắc thái ngôn ngữ phù hợp trình độ HSK 6.', N'Khó', N'[{"zh": "在中文交流中，我们经常使用“啦”表达相关语义。", "pinyin": "Zài Zhōngwén jiāoliú zhōng, wǒmen jīngcháng shǐyòng...", "meaningVi": "Trong giao tiếp tiếng Trung, chúng ta thường sử dụng điểm ngữ pháp này để biểu đạt ý nghĩa tương ứng."}, {"zh": "请大家注意这个语法点的具体位置和语序。", "pinyin": "Qǐng dàjiā zhùyì zhè ge yǔfǎdiǎn de jùtǐ wèizhì hé yǔxù.", "meaningVi": "Xin mọi người chú ý vị trí cụ thể và trật tự từ của điểm ngữ pháp này."}]', N'{"question": "Điểm ngữ pháp “啦” thuộc nhóm cấu trúc nào trong ngữ pháp HSK 6?", "options": ["A. Trợ từ - Chuẩn HSK 6", "B. Danh từ riêng", "C. Thành ngữ cổ", "D. Tiếng lóng Internet"], "correctIndex": 0, "explanation": "“Trợ từ: 啦、嘛” là điểm ngữ pháp thuộc chương trình HSK 6."}', N'PENDING_REVIEW', N'BDA7B174-3734-4D2A-9EB6-726EF7EF038E', N'2026-11-05 16:17:38.431253', N'2026-11-06 04:13:45', N'助词', N'词类', N'语气助词', N'HSK 3.0 (2025-11)', N'428', NULL, NULL, NULL, N'Biên soạn ngữ pháp chuẩn HSK 3.0 (Cấp 6)'),
    (N'17175D8C-DE80-41B9-8E0B-00F5F14720CD', N'GP-HSK3-L13B', N'Động từ ly hợp trong tiếng Trung', N'Zǒu dé yuè kuài yuè hǎo', 3, N'HSK 2.0 Ng? pháp c?t lõi', N'Động từ + (Thời lượng / Tân ngữ) + Danh từ gốc', N'Những động từ có cấu tạo Động-Tân (như 散步, 见面, 唱歌) khi mang bổ ngữ thời lượng hoặc 了/过 sẽ tách ra ở giữa.', N'3', N'[{"zh": "晚饭后我常在公园里散半小时步。", "pinyin": "Wǎn fàn hòu wǒ cháng zài gōng yuán lǐ sàn bàn xiǎo shí bù。", "meaningVi": "Sau bữa tối tôi hay đi dạo nửa tiếng trong công viên."}, {"zh": "我和老朋友见了一次面。", "pinyin": "Wǒ hé lǎo péngyou jiàn le yī cì miàn。", "meaningVi": "Tôi và bạn cũ đã gặp mặt nhau một lần."}]', N'{"question": "Câu nào vận dụng đúng cấu trúc ''Động từ ly hợp trong tiếng Trung'' (Động từ + (Thời lượng / Tân ngữ) + Danh từ gốc)?", "options": ["晚饭后我常在公园里散半小时步。 (Sau bữa tối tôi hay đi dạo nửa tiếng trong công viên.)", "Đảo sai trật tự thành phần câu so với công thức chuẩn.", "Dùng sai hư từ và kết cấu ngữ pháp trọng tâm.", "Thiếu thành phần ngữ pháp bắt buộc trong câu."], "correctIndex": 0, "explanation": "Những động từ có cấu tạo Động-Tân (như 散步, 见面, 唱歌) khi mang bổ ngữ thời lượng hoặc 了/过 sẽ tách ra ở giữa."}', N'PUBLISHED', N'8740279E-4223-43BE-B424-9071F24126AE', N'2026-11-11 10:10:25.304391', N'2026-11-11 10:10:25.304391', N'HSK20_CORE', N'SYNTAX', NULL, N'HSK 2.0 (Curated Vietnamese)', NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'100% Vietnamese HSK 2.0 grammar'),
    (N'C8A4C00A-AC8D-4417-B3B6-01F3F886BFD8', N'GR30-HSK1-044', N'Mẫu câu: 主谓句3：名词谓语句', N'', 1, N'句型', N'主谓句3：名词谓语句', N'Điểm ngữ pháp HSK 1 thuộc nhóm Loại câu (Mẫu câu). Dùng trong mẫu câu diễn đạt chuẩn: 主谓句3：名词谓语句. Cung cấp quy tắc kết hợp cú pháp chuẩn xác và sắc thái ngôn ngữ phù hợp trình độ HSK 1.', N'Dễ', N'[{"zh": "在中文交流中，我们经常使用“主谓句3：名词谓语句”表达相关语义。", "pinyin": "Zài Zhōngwén jiāoliú zhōng, wǒmen jīngcháng shǐyòng...", "meaningVi": "Trong giao tiếp tiếng Trung, chúng ta thường sử dụng điểm ngữ pháp này để biểu đạt ý nghĩa tương ứng."}, {"zh": "请大家注意这个语法点的具体位置和语序。", "pinyin": "Qǐng dàjiā zhùyì zhè ge yǔfǎdiǎn de jùtǐ wèizhì hé yǔxù.", "meaningVi": "Xin mọi người chú ý vị trí cụ thể và trật tự từ của điểm ngữ pháp này."}]', N'{"question": "Điểm ngữ pháp “主谓句3：名词谓语句” thuộc nhóm cấu trúc nào trong ngữ pháp HSK 1?", "options": ["A. Mẫu câu - Chuẩn HSK 1", "B. Danh từ riêng", "C. Thành ngữ cổ", "D. Tiếng lóng Internet"], "correctIndex": 0, "explanation": "“Mẫu câu: 主谓句3：名词谓语句” là điểm ngữ pháp thuộc chương trình HSK 1."}', N'ARCHIVED', NULL, N'2026-11-05 16:17:38.431253', N'2026-11-11 08:55:45.565313', N'句型', N'句子的类型', N'单句', N'HSK 3.0 (2025-11)', N'44', NULL, NULL, NULL, N'Generic placeholder template example (''在中文交流中，我们经常使用...'')'),
    (N'D872FF83-9558-439C-A599-0235BEA0B183', N'GR30-HSK3-228', N'Mẫu câu đặc biệt: 强调说话人的看法或态度', N'', 3, N'特殊句型', N'强调说话人的看法或态度', N'Điểm ngữ pháp HSK 3 thuộc nhóm Loại câu (Mẫu câu đặc biệt). Dùng trong mẫu câu diễn đạt chuẩn: 强调说话人的看法或态度. Cung cấp quy tắc kết hợp cú pháp chuẩn xác và sắc thái ngôn ngữ phù hợp trình độ HSK 3.', N'Trung bình', N'[{"zh": "在中文交流中，我们经常使用“强调说话人的看法或态度”表达相关语义。", "pinyin": "Zài Zhōngwén jiāoliú zhōng, wǒmen jīngcháng shǐyòng...", "meaningVi": "Trong giao tiếp tiếng Trung, chúng ta thường sử dụng điểm ngữ pháp này để biểu đạt ý nghĩa tương ứng."}, {"zh": "请大家注意这个语法点的具体位置和语序。", "pinyin": "Qǐng dàjiā zhùyì zhè ge yǔfǎdiǎn de jùtǐ wèizhì hé yǔxù.", "meaningVi": "Xin mọi người chú ý vị trí cụ thể và trật tự từ của điểm ngữ pháp này."}]', N'{"question": "Điểm ngữ pháp “强调说话人的看法或态度” thuộc nhóm cấu trúc nào trong ngữ pháp HSK 3?", "options": ["A. Mẫu câu đặc biệt - Chuẩn HSK 3", "B. Danh từ riêng", "C. Thành ngữ cổ", "D. Tiếng lóng Internet"], "correctIndex": 0, "explanation": "“Mẫu câu đặc biệt: 强调说话人的看法或态度” là điểm ngữ pháp thuộc chương trình HSK 3."}', N'ARCHIVED', NULL, N'2026-11-05 16:17:38.431253', N'2026-11-11 10:10:25.304391', N'特殊句型', N'句子的类型', N'“是……的”句2', N'HSK 3.0 (2025-11)', N'228', NULL, NULL, NULL, N'Biên soạn ngữ pháp chuẩn HSK 3.0 (Cấp 3)'),
    (N'9D123181-AE78-4586-AAE3-0250BA6CC01F', N'GR30-HSK2-139', N'Câu phức: 虽然……，但是……', N'', 2, N'复句', N'虽然……，但是……', N'Điểm ngữ pháp HSK 2 thuộc nhóm Loại câu (Câu phức). Dùng trong mẫu câu diễn đạt chuẩn: 虽然……，但是……. Cung cấp quy tắc kết hợp cú pháp chuẩn xác và sắc thái ngôn ngữ phù hợp trình độ HSK 2.', N'Dễ', N'[{"zh": "在中文交流中，我们经常使用“虽然……，但是……”表达相关语义。", "pinyin": "Zài Zhōngwén jiāoliú zhōng, wǒmen jīngcháng shǐyòng...", "meaningVi": "Trong giao tiếp tiếng Trung, chúng ta thường sử dụng điểm ngữ pháp này để biểu đạt ý nghĩa tương ứng."}, {"zh": "请大家注意这个语法点的具体位置和语序。", "pinyin": "Qǐng dàjiā zhùyì zhè ge yǔfǎdiǎn de jùtǐ wèizhì hé yǔxù.", "meaningVi": "Xin mọi người chú ý vị trí cụ thể và trật tự từ của điểm ngữ pháp này."}]', N'{"question": "Điểm ngữ pháp “虽然……，但是……” thuộc nhóm cấu trúc nào trong ngữ pháp HSK 2?", "options": ["A. Câu phức - Chuẩn HSK 2", "B. Danh từ riêng", "C. Thành ngữ cổ", "D. Tiếng lóng Internet"], "correctIndex": 0, "explanation": "“Câu phức: 虽然……，但是……” là điểm ngữ pháp thuộc chương trình HSK 2."}', N'ARCHIVED', NULL, N'2026-11-05 16:17:38.431253', N'2026-11-11 10:10:25.304391', N'复句', N'句子的类型', N'转折复句', N'HSK 3.0 (2025-11)', N'139', NULL, NULL, NULL, N'Biên soạn ngữ pháp chuẩn HSK 3.0 (Cấp 2)'),
    (N'1B30A109-A1AF-4116-B0F7-0255545E6C00', N'GP-HSK2-L07A', N'Giới từ 离 (lí) diễn tả khoảng cách', N'Nǐ jiā lí gōng sī yuǎn ma', 2, N'HSK 2.0 Ng? pháp c?t lõi', N'Địa điểm A + 离 + Địa điểm B + (很 / 不) + 远 / 近', N'Dùng nói khoảng cách không gian hoặc thời gian giữa hai mốc.', N'2', N'[{"zh": "我家离学校很近。", "pinyin": "Wǒ jiā lí xué xiào hěn jìn。", "meaningVi": "Nhà tôi cách trường học rất gần."}, {"zh": "火车站离飞机场有多远？", "pinyin": "Huǒ chē zhàn lí fēi jī chǎng yǒu duō yuǎn？", "meaningVi": "Ga tàu cách sân bay bao xa?"}]', N'{"question": "Câu nào vận dụng đúng cấu trúc ''Giới từ 离 (lí) diễn tả khoảng cách'' (Địa điểm A + 离 + Địa điểm B + (很 / 不) + 远 / 近)?", "options": ["我家离学校很近。 (Nhà tôi cách trường học rất gần.)", "Đảo sai trật tự thành phần câu so với công thức chuẩn.", "Dùng sai hư từ và kết cấu ngữ pháp trọng tâm.", "Thiếu thành phần ngữ pháp bắt buộc trong câu."], "correctIndex": 0, "explanation": "Dùng nói khoảng cách không gian hoặc thời gian giữa hai mốc."}', N'PUBLISHED', N'A39B8E6A-EE6E-478D-AA01-51DAD45D4E0E', N'2026-11-11 10:10:25.304391', N'2026-11-11 10:10:25.304391', N'HSK20_CORE', N'SYNTAX', NULL, N'HSK 2.0 (Curated Vietnamese)', NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'100% Vietnamese HSK 2.0 grammar'),
    (N'1DFB2253-1043-4373-BFA9-02A27551C473', N'GP-HSK3-L16A', N'Bổ ngữ mức độ trạng thái: Tính từ / Động từ + 得 + Cụm miêu tả', N'Wǒ xiàn zài lèi dé bù xiǎng dòng', 3, N'HSK 2.0 Ng? pháp c?t lõi', N'Chủ ngữ + Tính từ + 得 + Cụm vị ngữ', N'Dùng để phóng đại hoặc miêu tả mức độ rõ nét thông qua kết quả kéo theo.', N'3', N'[{"zh": "我现在累得不想动。", "pinyin": "Wǒ xiàn zài lèi dé bù xiǎng dòng。", "meaningVi": "Bây giờ tôi mệt đến mức không muốn cử động."}, {"zh": "听了这个好消息，他高兴得睡不着觉。", "pinyin": "Tīng le zhè ge hǎo xiāo xī， tā gāo xìng dé shuì bù zhe jué。", "meaningVi": "Nghe tin vui này, anh ấy vui đến nỗi không ngủ được."}]', N'{"question": "Câu nào vận dụng đúng cấu trúc ''Bổ ngữ mức độ trạng thái: Tính từ / Động từ + 得 + Cụm miêu tả'' (Chủ ngữ + Tính từ + 得 + Cụm vị ngữ)?", "options": ["我现在累得不想动。 (Bây giờ tôi mệt đến mức không muốn cử động.)", "Đảo sai trật tự thành phần câu so với công thức chuẩn.", "Dùng sai hư từ và kết cấu ngữ pháp trọng tâm.", "Thiếu thành phần ngữ pháp bắt buộc trong câu."], "correctIndex": 0, "explanation": "Dùng để phóng đại hoặc miêu tả mức độ rõ nét thông qua kết quả kéo theo."}', N'PUBLISHED', N'8DA33634-03F8-4F90-9BF6-86AC2A793D7D', N'2026-11-11 10:10:25.304391', N'2026-11-11 10:10:25.304391', N'HSK20_CORE', N'SYNTAX', NULL, N'HSK 2.0 (Curated Vietnamese)', NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'100% Vietnamese HSK 2.0 grammar'),
    (N'529C1DEF-C2BE-47E6-8C02-02F1540C0E31', N'GR30-HSK1-033', N'Kiểu cấu trúc: 介宾短语', N'', 1, N'结构类型', N'介宾短语', N'Điểm ngữ pháp HSK 1 thuộc nhóm Cụm từ (Kiểu cấu trúc). Dùng trong mẫu câu diễn đạt chuẩn: 介宾短语. Cung cấp quy tắc kết hợp cú pháp chuẩn xác và sắc thái ngôn ngữ phù hợp trình độ HSK 1.', N'Dễ', N'[{"zh": "在中文交流中，我们经常使用“介宾短语”表达相关语义。", "pinyin": "Zài Zhōngwén jiāoliú zhōng, wǒmen jīngcháng shǐyòng...", "meaningVi": "Trong giao tiếp tiếng Trung, chúng ta thường sử dụng điểm ngữ pháp này để biểu đạt ý nghĩa tương ứng."}, {"zh": "请大家注意这个语法点的具体位置和语序。", "pinyin": "Qǐng dàjiā zhùyì zhè ge yǔfǎdiǎn de jùtǐ wèizhì hé yǔxù.", "meaningVi": "Xin mọi người chú ý vị trí cụ thể và trật tự từ của điểm ngữ pháp này."}]', N'{"question": "Điểm ngữ pháp “介宾短语” thuộc nhóm cấu trúc nào trong ngữ pháp HSK 1?", "options": ["A. Kiểu cấu trúc - Chuẩn HSK 1", "B. Danh từ riêng", "C. Thành ngữ cổ", "D. Tiếng lóng Internet"], "correctIndex": 0, "explanation": "“Kiểu cấu trúc: 介宾短语” là điểm ngữ pháp thuộc chương trình HSK 1."}', N'ARCHIVED', NULL, N'2026-11-05 16:17:38.431253', N'2026-11-11 08:55:45.559780', N'结构类型', N'短语', N'其他结构类型', N'HSK 3.0 (2025-11)', N'33', NULL, NULL, NULL, N'Generic placeholder template example (''在中文交流中，我们经常使用...'')'),
