    (N'D91D71DB-E649-4CEE-8E34-523CBAC985B3', N'GR30-HSK4-255', N'Phó từ: 却', N'', 4, N'副词', N'却', N'Điểm ngữ pháp HSK 4 thuộc nhóm Từ loại (Phó từ). Dùng trong mẫu câu diễn đạt chuẩn: 却. Cung cấp quy tắc kết hợp cú pháp chuẩn xác và sắc thái ngôn ngữ phù hợp trình độ HSK 4.', N'Trung bình', N'[{"zh": "在中文交流中，我们经常使用“却”表达相关语义。", "pinyin": "Zài Zhōngwén jiāoliú zhōng, wǒmen jīngcháng shǐyòng...", "meaningVi": "Trong giao tiếp tiếng Trung, chúng ta thường sử dụng điểm ngữ pháp này để biểu đạt ý nghĩa tương ứng."}, {"zh": "请大家注意这个语法点的具体位置和语序。", "pinyin": "Qǐng dàjiā zhùyì zhè ge yǔfǎdiǎn de jùtǐ wèizhì hé yǔxù.", "meaningVi": "Xin mọi người chú ý vị trí cụ thể và trật tự từ của điểm ngữ pháp này."}]', N'{"question": "Điểm ngữ pháp “却” thuộc nhóm cấu trúc nào trong ngữ pháp HSK 4?", "options": ["A. Phó từ - Chuẩn HSK 4", "B. Danh từ riêng", "C. Thành ngữ cổ", "D. Tiếng lóng Internet"], "correctIndex": 0, "explanation": "“Phó từ: 却” là điểm ngữ pháp thuộc chương trình HSK 4."}', N'ARCHIVED', NULL, N'2026-11-05 16:17:38.431253', N'2026-11-11 10:10:25.304391', N'副词', N'词类', N'关联副词', N'HSK 3.0 (2025-11)', N'255', NULL, NULL, NULL, N'Biên soạn ngữ pháp chuẩn HSK 3.0 (Cấp 4)'),
    (N'347FB868-718A-4D26-8100-524EE55087F0', N'GP-HSK4-L15B', N'Cụm từ 连……也 / 都…… (lián... yě/dōu...) — đến cả... cũng...', N'Jiào yù hái zi de yì shù', 4, N'HSK 2.0 Ng? pháp c?t lõi', N'（连）+ Thành phần nhấn mạnh + 也 / 都 + Vị ngữ', N'Nhấn mạnh mức độ cực đoan của sự việc thông qua một ví dụ điển hình nhất.', N'4', N'[{"zh": "如果连父母都不相信孩子，孩子怎么敢尝试呢？", "pinyin": "Rú guǒ lián fù mǔ dōu bù xiāng xìn hái zi， hái zi zěnme gǎn cháng shì ne？", "meaningVi": "Nếu đến cả cha mẹ cũng không tin tưởng con cái, làm sao trẻ dám thử sức đây?"}, {"zh": "这个小男孩聪明极了，连这么难的题都解出来了。", "pinyin": "Zhè ge xiǎo nán hái cōng míng jí le， lián zhè me nán de tí dōu jiě chū lái le。", "meaningVi": "Cậu bé này thông minh cực kỳ, đến cả bài khó thế này cũng giải ra được."}]', N'{"question": "Câu nào vận dụng đúng cấu trúc ''Cụm từ 连……也 / 都…… (lián... yě/dōu...) — đến cả... cũng...'' (（连）+ Thành phần nhấn mạnh + 也 / 都 + Vị ngữ)?", "options": ["如果连父母都不相信孩子，孩子怎么敢尝试呢？ (Nếu đến cả cha mẹ cũng không tin tưởng con cái, làm sao trẻ dám thử sức đây?)", "Đảo sai trật tự thành phần câu so với công thức chuẩn.", "Dùng sai hư từ và kết cấu ngữ pháp trọng tâm.", "Thiếu thành phần ngữ pháp bắt buộc trong câu."], "correctIndex": 0, "explanation": "Nhấn mạnh mức độ cực đoan của sự việc thông qua một ví dụ điển hình nhất."}', N'PUBLISHED', N'D551AD89-18F8-417A-BC0F-0FCBD23C1448', N'2026-11-11 10:10:25.304391', N'2026-11-11 10:10:25.304391', N'HSK20_CORE', N'SYNTAX', NULL, N'HSK 2.0 (Curated Vietnamese)', NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'100% Vietnamese HSK 2.0 grammar'),
    (N'09D85F41-34F9-4038-BD87-52921A666E8F', N'GP-HSK4-L09B', N'Bổ ngữ xu hướng 过来 (guòlái) chỉ sự vượt qua khó khăn / hồi phục', N'Yáng guāng zǒng zài fēng yǔ hòu', 4, N'HSK 2.0 Ng? pháp c?t lõi', N'Động từ + 过来', N'Biểu thị thoát khỏi trạng thái bất lợi, vượt qua thử thách hoặc hồi tỉnh trở lại bình thường.', N'4', N'[{"zh": "不管多难的日子，我们最终还是挺过来了。", "pinyin": "Bù guǎn duō nán de rì zi， wǒ men zuì zhōng hái shì tǐng guò lái le。", "meaningVi": "Bất kể những ngày tháng khó khăn thế nào, cuối cùng chúng ta vẫn vượt qua được."}, {"zh": "休息了一个小时，他终于醒过来了。", "pinyin": "Xiū xī le yí gè xiǎo shí， tā zhōng yú xǐng guò lái le。", "meaningVi": "Nghỉ ngơi một tiếng xong, cậu ấy cuối cùng cũng tỉnh lại rồi."}]', N'{"question": "Câu nào vận dụng đúng cấu trúc ''Bổ ngữ xu hướng 过来 (guòlái) chỉ sự vượt qua khó khăn / hồi phục'' (Động từ + 过来)?", "options": ["不管多难的日子，我们最终还是挺过来了。 (Bất kể những ngày tháng khó khăn thế nào, cuối cùng chúng ta vẫn vượt qua được.)", "Đảo sai trật tự thành phần câu so với công thức chuẩn.", "Dùng sai hư từ và kết cấu ngữ pháp trọng tâm.", "Thiếu thành phần ngữ pháp bắt buộc trong câu."], "correctIndex": 0, "explanation": "Biểu thị thoát khỏi trạng thái bất lợi, vượt qua thử thách hoặc hồi tỉnh trở lại bình thường."}', N'PUBLISHED', N'D0A7BB74-A49C-4D2A-B5FB-C34AF6410CF9', N'2026-11-11 10:10:25.304391', N'2026-11-11 10:10:25.304391', N'HSK20_CORE', N'SYNTAX', NULL, N'HSK 2.0 (Curated Vietnamese)', NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'100% Vietnamese HSK 2.0 grammar'),
    (N'26225AAE-7A7F-4413-B51F-53677188DEE7', N'GR30-HSK2-144', N'Trạng thái hành động: 用动态助词“过”表示', N'', 2, N'Ngữ pháp', N'用动态助词“过”表示', N'Điểm ngữ pháp HSK 2 thuộc nhóm Trạng thái hành động. Dùng trong mẫu câu diễn đạt chuẩn: 用动态助词“过”表示. Cung cấp quy tắc kết hợp cú pháp chuẩn xác và sắc thái ngôn ngữ phù hợp trình độ HSK 2.', N'Dễ', N'[{"zh": "在中文交流中，我们经常使用“用动态助词“过”表示”表达相关语义。", "pinyin": "Zài Zhōngwén jiāoliú zhōng, wǒmen jīngcháng shǐyòng...", "meaningVi": "Trong giao tiếp tiếng Trung, chúng ta thường sử dụng điểm ngữ pháp này để biểu đạt ý nghĩa tương ứng."}, {"zh": "请大家注意这个语法点的具体位置和语序。", "pinyin": "Qǐng dàjiā zhùyì zhè ge yǔfǎdiǎn de jùtǐ wèizhì hé yǔxù.", "meaningVi": "Xin mọi người chú ý vị trí cụ thể và trật tự từ của điểm ngữ pháp này."}]', N'{"question": "Điểm ngữ pháp “用动态助词“过”表示” thuộc nhóm cấu trúc nào trong ngữ pháp HSK 2?", "options": ["A. Trạng thái hành động - Chuẩn HSK 2", "B. Danh từ riêng", "C. Thành ngữ cổ", "D. Tiếng lóng Internet"], "correctIndex": 0, "explanation": "“Trạng thái hành động: 用动态助词“过”表示” là điểm ngữ pháp thuộc chương trình HSK 2."}', N'ARCHIVED', NULL, N'2026-11-05 16:17:38.431253', N'2026-11-11 10:10:25.304391', N'', N'动作的态', N'经历态', N'HSK 3.0 (2025-11)', N'144', NULL, NULL, NULL, N'Biên soạn ngữ pháp chuẩn HSK 3.0 (Cấp 2)'),
