    (N'F6E317A6-CDC4-4ED1-A878-C389279A4699', N'GR30-HSK3-235', N'Câu phức: 不但……，而且……', N'', 3, N'复句', N'不但……，而且……', N'Điểm ngữ pháp HSK 3 thuộc nhóm Loại câu (Câu phức). Dùng trong mẫu câu diễn đạt chuẩn: 不但……，而且……. Cung cấp quy tắc kết hợp cú pháp chuẩn xác và sắc thái ngôn ngữ phù hợp trình độ HSK 3.', N'Trung bình', N'[{"zh": "在中文交流中，我们经常使用“不但……，而且……”表达相关语义。", "pinyin": "Zài Zhōngwén jiāoliú zhōng, wǒmen jīngcháng shǐyòng...", "meaningVi": "Trong giao tiếp tiếng Trung, chúng ta thường sử dụng điểm ngữ pháp này để biểu đạt ý nghĩa tương ứng."}, {"zh": "请大家注意这个语法点的具体位置和语序。", "pinyin": "Qǐng dàjiā zhùyì zhè ge yǔfǎdiǎn de jùtǐ wèizhì hé yǔxù.", "meaningVi": "Xin mọi người chú ý vị trí cụ thể và trật tự từ của điểm ngữ pháp này."}]', N'{"question": "Điểm ngữ pháp “不但……，而且……” thuộc nhóm cấu trúc nào trong ngữ pháp HSK 3?", "options": ["A. Câu phức - Chuẩn HSK 3", "B. Danh từ riêng", "C. Thành ngữ cổ", "D. Tiếng lóng Internet"], "correctIndex": 0, "explanation": "“Câu phức: 不但……，而且……” là điểm ngữ pháp thuộc chương trình HSK 3."}', N'ARCHIVED', NULL, N'2026-11-05 16:17:38.431253', N'2026-11-11 10:10:25.304391', N'复句', N'句子的类型', N'递进复句', N'HSK 3.0 (2025-11)', N'235', NULL, NULL, NULL, N'Biên soạn ngữ pháp chuẩn HSK 3.0 (Cấp 3)'),
    (N'0B2EC3F4-75AC-417A-BB45-C3FD0B6F4785', N'GR30-HSK6-433', N'Cụm từ cố định: 那倒（也）是', N'', 6, N'固定短语', N'那倒（也）是', N'Điểm ngữ pháp HSK 6 thuộc nhóm Cụm từ (Cụm từ cố định). Dùng trong mẫu câu diễn đạt chuẩn: 那倒（也）是. Cung cấp quy tắc kết hợp cú pháp chuẩn xác và sắc thái ngôn ngữ phù hợp trình độ HSK 6.', N'Khó', N'[{"zh": "在中文交流中，我们经常使用“那倒（也）是”表达相关语义。", "pinyin": "Zài Zhōngwén jiāoliú zhōng, wǒmen jīngcháng shǐyòng...", "meaningVi": "Trong giao tiếp tiếng Trung, chúng ta thường sử dụng điểm ngữ pháp này để biểu đạt ý nghĩa tương ứng."}, {"zh": "请大家注意这个语法点的具体位置和语序。", "pinyin": "Qǐng dàjiā zhùyì zhè ge yǔfǎdiǎn de jùtǐ wèizhì hé yǔxù.", "meaningVi": "Xin mọi người chú ý vị trí cụ thể và trật tự từ của điểm ngữ pháp này."}]', N'{"question": "Điểm ngữ pháp “那倒（也）是” thuộc nhóm cấu trúc nào trong ngữ pháp HSK 6?", "options": ["A. Cụm từ cố định - Chuẩn HSK 6", "B. Danh từ riêng", "C. Thành ngữ cổ", "D. Tiếng lóng Internet"], "correctIndex": 0, "explanation": "“Cụm từ cố định: 那倒（也）是” là điểm ngữ pháp thuộc chương trình HSK 6."}', N'PENDING_REVIEW', N'DBD90CE4-F540-40DC-9061-F8BF0D2C94AC', N'2026-11-05 16:17:38.431253', N'2026-11-06 04:13:45', N'固定短语', N'短语', N'其他', N'HSK 3.0 (2025-11)', N'433', NULL, NULL, NULL, N'Biên soạn ngữ pháp chuẩn HSK 3.0 (Cấp 6)'),
    (N'9970F078-59E0-4F7B-9C0F-C45105E713C3', N'GR30-HSK1-050', N'Loại câu: Câu cầu khiến (祈使句)', N'', 1, N'句类', N'(请) + Động từ / (不要/别 + Động từ) + (吧)!', N'Câu cầu khiến dùng để yêu cầu, đề nghị, khuyên nhủ hoặc ra lệnh cho người khác thực hiện hoặc ngừng thực hiện một hành động.', N'Dễ', N'[{"zh": "请您坐在这里喝茶。", "pinyin": "Qǐng nín zuò zài zhèlǐ hē chá.", "meaningVi": "Xin mời ngài ngồi ở đây uống trà."}, {"zh": "上课时间请大家不要说话！", "pinyin": "Shàngkè shíjiān qǐng dàjiā bú yào shuōhuà!", "meaningVi": "Trong giờ học xin mọi người đừng nói chuyện!"}]', N'{"question": "Chọn câu biểu thị lời nhờ vả lịch sự:", "options": ["A. 请进，请坐！", "B. 他是学生吗？", "C. 今天太热了！", "D. 我有一本书。"], "correctIndex": 0, "explanation": "“请进，请坐！” là câu cầu khiến lịch sự dùng từ “请”."}', N'PUBLISHED', N'9C981888-67BD-41BB-B5B0-57D0A1268DD6', N'2026-11-05 16:17:38.431253', N'2026-11-11 08:55:45.654728', N'句类', N'句子的类型', N'祈使句', N'HSK 3.0 (2025-11)', N'50', NULL, NULL, NULL, N'Đã khắc phục tiêu đề/công thức chuẩn ngữ pháp HSK'),
    (N'2B80D0B3-2F33-4C48-86B0-C481298AF715', N'GR30-HSK1-006', N'Động từ năng nguyện: 可以', N'', 1, N'动词', N'S + 可以 + V + (O)', N'Biểu thị sự cho phép hoặc khả năng khách quan. Thường dùng trong câu hỏi xin phép lịch sự hoặc lời khuyên hữu ích.', N'Dễ', N'[{"zh": "在中文交流中，我们经常使用“S”表达相关语义。", "pinyin": "Zài Zhōngwén jiāoliú zhōng, wǒmen jīngcháng shǐyòng...", "meaningVi": "Trong giao tiếp tiếng Trung, chúng ta thường sử dụng điểm ngữ pháp này để biểu đạt ý nghĩa tương ứng."}, {"zh": "请大家注意这个语法点的具体位置和语序。", "pinyin": "Qǐng dàjiā zhùyì zhè ge yǔfǎdiǎn de jùtǐ wèizhì hé yǔxù.", "meaningVi": "Xin mọi người chú ý vị trí cụ thể và trật tự từ của điểm ngữ pháp này."}]', N'{"question": "Điểm ngữ pháp “S” thuộc nhóm cấu trúc nào trong ngữ pháp HSK 1?", "options": ["A. Động từ năng nguyện - Chuẩn HSK 1", "B. Danh từ riêng", "C. Thành ngữ cổ", "D. Tiếng lóng Internet"], "correctIndex": 0, "explanation": "“Động từ năng nguyện: 可以” là điểm ngữ pháp thuộc chương trình HSK 1."}', N'ARCHIVED', NULL, N'2026-11-05 16:17:38.431253', N'2026-11-11 08:55:45.545273', N'动词', N'词类', N'能愿动词', N'HSK 3.0 (2025-11)', N'6', NULL, NULL, NULL, N'Generic placeholder template example (''在中文交流中，我们经常使用...'')'),
    (N'39A1A3B3-CAF3-4A3D-9347-C4C4239E3A89', N'GR30-HSK5-381', N'Trạng ngữ: 多项状语', N'', 5, N'状语', N'多项状语', N'Điểm ngữ pháp HSK 5 thuộc nhóm Thành phần câu (Trạng ngữ). Dùng trong mẫu câu diễn đạt chuẩn: 多项状语. Cung cấp quy tắc kết hợp cú pháp chuẩn xác và sắc thái ngôn ngữ phù hợp trình độ HSK 5.', N'Khó', N'[{"zh": "在中文交流中，我们经常使用“多项状语”表达相关语义。", "pinyin": "Zài Zhōngwén jiāoliú zhōng, wǒmen jīngcháng shǐyòng...", "meaningVi": "Trong giao tiếp tiếng Trung, chúng ta thường sử dụng điểm ngữ pháp này để biểu đạt ý nghĩa tương ứng."}, {"zh": "请大家注意这个语法点的具体位置和语序。", "pinyin": "Qǐng dàjiā zhùyì zhè ge yǔfǎdiǎn de jùtǐ wèizhì hé yǔxù.", "meaningVi": "Xin mọi người chú ý vị trí cụ thể và trật tự từ của điểm ngữ pháp này."}]', N'{"question": "Điểm ngữ pháp “多项状语” thuộc nhóm cấu trúc nào trong ngữ pháp HSK 5?", "options": ["A. Trạng ngữ - Chuẩn HSK 5", "B. Danh từ riêng", "C. Thành ngữ cổ", "D. Tiếng lóng Internet"], "correctIndex": 0, "explanation": "“Trạng ngữ: 多项状语” là điểm ngữ pháp thuộc chương trình HSK 5."}', N'PENDING_REVIEW', N'7FD34D65-4149-434B-8265-9E1E00018B44', N'2026-11-05 16:17:38.431253', N'2026-11-06 04:13:45', N'状语', N'句子成分', N'', N'HSK 3.0 (2025-11)', N'381', NULL, NULL, NULL, N'Biên soạn ngữ pháp chuẩn HSK 3.0 (Cấp 5)');
