    (N'4FA736B0-5523-41D8-8925-DA2B82EA5CB0', N'GR30-HSK3-229', N'Mẫu câu đặc biệt: 主语+动词+宾语+动词+补语', N'', 3, N'特殊句型', N'主语+动词+宾语+动词+补语', N'Điểm ngữ pháp HSK 3 thuộc nhóm Loại câu (Mẫu câu đặc biệt). Dùng trong mẫu câu diễn đạt chuẩn: 主语+动词+宾语+动词+补语. Cung cấp quy tắc kết hợp cú pháp chuẩn xác và sắc thái ngôn ngữ phù hợp trình độ HSK 3.', N'Trung bình', N'[{"zh": "在中文交流中，我们经常使用“主语”表达相关语义。", "pinyin": "Zài Zhōngwén jiāoliú zhōng, wǒmen jīngcháng shǐyòng...", "meaningVi": "Trong giao tiếp tiếng Trung, chúng ta thường sử dụng điểm ngữ pháp này để biểu đạt ý nghĩa tương ứng."}, {"zh": "请大家注意这个语法点的具体位置和语序。", "pinyin": "Qǐng dàjiā zhùyì zhè ge yǔfǎdiǎn de jùtǐ wèizhì hé yǔxù.", "meaningVi": "Xin mọi người chú ý vị trí cụ thể và trật tự từ của điểm ngữ pháp này."}]', N'{"question": "Điểm ngữ pháp “主语” thuộc nhóm cấu trúc nào trong ngữ pháp HSK 3?", "options": ["A. Mẫu câu đặc biệt - Chuẩn HSK 3", "B. Danh từ riêng", "C. Thành ngữ cổ", "D. Tiếng lóng Internet"], "correctIndex": 0, "explanation": "“Mẫu câu đặc biệt: 主语+动词+宾语+动词+补语” là điểm ngữ pháp thuộc chương trình HSK 3."}', N'ARCHIVED', NULL, N'2026-11-05 16:17:38.431253', N'2026-11-11 10:10:25.304391', N'特殊句型', N'句子的类型', N'重动句', N'HSK 3.0 (2025-11)', N'229', NULL, NULL, NULL, N'Biên soạn ngữ pháp chuẩn HSK 3.0 (Cấp 3)'),
    (N'07C34D5B-4C62-45D4-B9F8-DAB615A30DE6', N'GR30-HSK2-110', N'Cụm từ: Cụm tính từ (形容词性短语)', N'', 2, N'功能类型', N'Phó từ mức độ + Tính từ / Tính từ + Bổ ngữ mức độ', N'Cụm từ có chức năng ngữ pháp tương đương một tính từ, thường đóng vai trò vị ngữ hoặc định ngữ, miêu tả tính chất, trạng thái hoặc mức độ của sự vật, hành động.', N'Dễ', N'[{"zh": "今天准备考试，大家都非常忙。", "pinyin": "Jīntiān zhǔnbèi kǎoshì, dàjiā dōu fēicháng máng.", "meaningVi": "Hôm nay chuẩn bị thi, mọi người đều vô cùng bận rộn."}, {"zh": "路上车多，请你开车开得慢一点儿。", "pinyin": "Lù shang chē duō, qǐng nǐ kāi chē kāi de màn yìdiǎnr.", "meaningVi": "Trên đường nhiều xe, xin bạn hãy lái xe chậm một chút."}]', N'{"question": "Tìm cụm tính từ miêu tả trạng thái trong câu: “跑完步以后，他感到浑身很累。”", "options": ["A. 很累", "B. 跑完步", "C. 感到", "D. 浑身"], "correctIndex": 0, "explanation": "“很累” (Phó từ mức độ + Tính từ) là cụm tính từ chỉ trạng thái."}', N'ARCHIVED', NULL, N'2026-11-05 16:17:38.431253', N'2026-11-11 10:10:25.304391', N'功能类型', N'短语', N'形容词性短语', N'HSK 3.0 (2025-11)', N'110', NULL, NULL, NULL, N'Đã khắc phục tiêu đề/công thức chuẩn ngữ pháp HSK'),
    (N'59FFDE8C-56BF-480D-9E27-DAF58776405B', N'GR30-HSK3-150', N'Hậu tố: —家、—子、—员', N'', 3, N'后缀', N'—家、—子、—员', N'Điểm ngữ pháp HSK 3 thuộc nhóm Ngữ tố (Hậu tố). Dùng trong mẫu câu diễn đạt chuẩn: —家、—子、—员. Cung cấp quy tắc kết hợp cú pháp chuẩn xác và sắc thái ngôn ngữ phù hợp trình độ HSK 3.', N'Trung bình', N'[{"zh": "在中文交流中，我们经常使用“这个句型”表达相关语义。", "pinyin": "Zài Zhōngwén jiāoliú zhōng, wǒmen jīngcháng shǐyòng...", "meaningVi": "Trong giao tiếp tiếng Trung, chúng ta thường sử dụng điểm ngữ pháp này để biểu đạt ý nghĩa tương ứng."}, {"zh": "请大家注意这个语法点的具体位置和语序。", "pinyin": "Qǐng dàjiā zhùyì zhè ge yǔfǎdiǎn de jùtǐ wèizhì hé yǔxù.", "meaningVi": "Xin mọi người chú ý vị trí cụ thể và trật tự từ của điểm ngữ pháp này."}]', N'{"question": "Điểm ngữ pháp “这个句型” thuộc nhóm cấu trúc nào trong ngữ pháp HSK 3?", "options": ["A. Hậu tố - Chuẩn HSK 3", "B. Danh từ riêng", "C. Thành ngữ cổ", "D. Tiếng lóng Internet"], "correctIndex": 0, "explanation": "“Hậu tố: —家、—子、—员” là điểm ngữ pháp thuộc chương trình HSK 3."}', N'ARCHIVED', NULL, N'2026-11-05 16:17:38.431253', N'2026-11-11 10:10:25.304391', N'后缀', N'语素', N'', N'HSK 3.0 (2025-11)', N'150', NULL, NULL, NULL, N'Biên soạn ngữ pháp chuẩn HSK 3.0 (Cấp 3)'),
    (N'38CA141A-DD92-4108-B7EE-DAF9F6121AF4', N'GR30-HSK2-134', N'Cấu trúc câu đặc biệt: A比B+动词+得+形容词/A+动词+得+比+B+形容词', N'', 2, N'特殊句式', N'A比B+动词+得+形容词/A+动词+得+比+B+形容词', N'Điểm ngữ pháp HSK 2 thuộc nhóm Loại câu (Cấu trúc câu đặc biệt). Dùng trong mẫu câu diễn đạt chuẩn: A比B+动词+得+形容词/A+动词+得+比+B+形容词. Cung cấp quy tắc kết hợp cú pháp chuẩn xác và sắc thái ngôn ngữ phù hợp trình độ HSK 2.', N'Dễ', N'[{"zh": "在中文交流中，我们经常使用“A比B”表达相关语义。", "pinyin": "Zài Zhōngwén jiāoliú zhōng, wǒmen jīngcháng shǐyòng...", "meaningVi": "Trong giao tiếp tiếng Trung, chúng ta thường sử dụng điểm ngữ pháp này để biểu đạt ý nghĩa tương ứng."}, {"zh": "请大家注意这个语法点的具体位置和语序。", "pinyin": "Qǐng dàjiā zhùyì zhè ge yǔfǎdiǎn de jùtǐ wèizhì hé yǔxù.", "meaningVi": "Xin mọi người chú ý vị trí cụ thể và trật tự từ của điểm ngữ pháp này."}]', N'{"question": "Điểm ngữ pháp “A比B” thuộc nhóm cấu trúc nào trong ngữ pháp HSK 2?", "options": ["A. Cấu trúc câu đặc biệt - Chuẩn HSK 2", "B. Danh từ riêng", "C. Thành ngữ cổ", "D. Tiếng lóng Internet"], "correctIndex": 0, "explanation": "“Cấu trúc câu đặc biệt: A比B+动词+得+形容词/A+动词+得+比+B+形容词” là điểm ngữ pháp thuộc chương trình HSK 2."}', N'ARCHIVED', NULL, N'2026-11-05 16:17:38.431253', N'2026-11-11 10:10:25.304391', N'特殊句式', N'句子的类型', N'比较句1', N'HSK 3.0 (2025-11)', N'134', NULL, NULL, NULL, N'Biên soạn ngữ pháp chuẩn HSK 3.0 (Cấp 2)'),
