    (N'92E606FD-DC0B-4DCD-91A5-E9ADB3C90126', N'GR30-HSK1-027', N'Thán từ: 喂', N'', 1, N'叹词', N'喂', N'Điểm ngữ pháp HSK 1 thuộc nhóm Từ loại (Thán từ). Dùng trong mẫu câu diễn đạt chuẩn: 喂. Cung cấp quy tắc kết hợp cú pháp chuẩn xác và sắc thái ngôn ngữ phù hợp trình độ HSK 1.', N'Dễ', N'[{"zh": "在中文交流中，我们经常使用“喂”表达相关语义。", "pinyin": "Zài Zhōngwén jiāoliú zhōng, wǒmen jīngcháng shǐyòng...", "meaningVi": "Trong giao tiếp tiếng Trung, chúng ta thường sử dụng điểm ngữ pháp này để biểu đạt ý nghĩa tương ứng."}, {"zh": "请大家注意这个语法点的具体位置和语序。", "pinyin": "Qǐng dàjiā zhùyì zhè ge yǔfǎdiǎn de jùtǐ wèizhì hé yǔxù.", "meaningVi": "Xin mọi người chú ý vị trí cụ thể và trật tự từ của điểm ngữ pháp này."}]', N'{"question": "Điểm ngữ pháp “喂” thuộc nhóm cấu trúc nào trong ngữ pháp HSK 1?", "options": ["A. Thán từ - Chuẩn HSK 1", "B. Danh từ riêng", "C. Thành ngữ cổ", "D. Tiếng lóng Internet"], "correctIndex": 0, "explanation": "“Thán từ: 喂” là điểm ngữ pháp thuộc chương trình HSK 1."}', N'ARCHIVED', NULL, N'2026-11-05 16:17:38.431253', N'2026-11-11 08:55:45.553778', N'叹词', N'词类', N'', N'HSK 3.0 (2025-11)', N'27', NULL, NULL, NULL, N'Generic placeholder template example (''在中文交流中，我们经常使用...'')'),
    (N'BE305CED-2C39-5EA2-833E-EAAC98870BB8', N'GP-HSK20-11B', N'Đơn vị tiền tệ Trung Quốc (块 / 毛) và lượng từ 个', N'', 1, N'HSK 2.0 Ngữ pháp cốt lõi', N'Number + 块 / Number + 个 + Noun', N'Trong khẩu ngữ dùng 块 (kuài - đồng/tệ) và 毛 (máo - hào); 个 (gè) là lượng từ phổ biến nhất đứng giữa số từ và danh từ.', N'Dễ', N'[{"zh": "两块五毛", "pinyin": "liǎng kuài wǔ máo", "meaningVi": "2 tệ 5 hào", "meaningEn": "Two pieces", "sourceUrl": "https://resources.allsetlearning.com/chinese/grammar/ASGL6JOE"}, {"zh": "二十三块八毛", "pinyin": "èrshí sān kuài bāmáo", "meaningVi": "23 tệ 8 hào", "meaningEn": "Twenty-three pieces", "sourceUrl": "https://resources.allsetlearning.com/chinese/grammar/ASGL9KQM"}, {"zh": "十个男人，七个傻，八个坏。", "pinyin": "shí gè nánrén， qī gè shǎ， bā gè huài 。", "meaningVi": "Mười người đàn ông thì bảy người ngốc, tám người xấu.", "meaningEn": "Ten men, seven silly, and eight bad.", "sourceUrl": "https://resources.allsetlearning.com/chinese/grammar/ASGI0T9S"}]', N'{"question": "Câu nào vận dụng đúng điểm ngữ pháp ''Đơn vị tiền tệ Trung Quốc (块 / 毛) và lượng từ 个'' (Number + 块 / Number + 个 + Noun)?", "options": ["两块五毛 (2 tệ 5 hào)", "Đảo sai trật tự thành phần câu so với công thức chuẩn.", "Dùng sai hư từ và kết cấu ngữ pháp trọng tâm.", "Thiếu thành phần ngữ pháp bắt buộc trong câu."], "correctIndex": 0, "explanation": "Trong khẩu ngữ dùng 块 (kuài - đồng/tệ) và 毛 (máo - hào); 个 (gè) là lượng từ phổ biến nhất đứng giữa số từ và danh từ."}', N'PUBLISHED', N'64363C63-96DB-4695-8E4E-79A9547F8E71', N'2026-11-11 08:55:45.619955', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, N'HSK 2.0 (AllSet Grammar Wiki)', N'GP-HSK20-11B', NULL, NULL, NULL, N'Sourced & verified from AllSet Learning Chinese Grammar Wiki (data/hsk20/sources/allset_grammar_hsk1.csv)'),
