    (N'45335771-603C-4723-A083-EB50E2C5307D', N'GR30-HSK4-339', N'Cách biểu đạt con số: 小数、分数、百分数、倍数的表示法', N'', 4, N'数的表示法', N'小数、分数、百分数、倍数的表示法', N'Điểm ngữ pháp HSK 4 thuộc nhóm Cách biểu đạt đặc biệt (Cách biểu đạt con số). Dùng trong mẫu câu diễn đạt chuẩn: 小数、分数、百分数、倍数的表示法. Cung cấp quy tắc kết hợp cú pháp chuẩn xác và sắc thái ngôn ngữ phù hợp trình độ HSK 4.', N'Trung bình', N'[{"zh": "在中文交流中，我们经常使用“小数”表达相关语义。", "pinyin": "Zài Zhōngwén jiāoliú zhōng, wǒmen jīngcháng shǐyòng...", "meaningVi": "Trong giao tiếp tiếng Trung, chúng ta thường sử dụng điểm ngữ pháp này để biểu đạt ý nghĩa tương ứng."}, {"zh": "请大家注意这个语法点的具体位置和语序。", "pinyin": "Qǐng dàjiā zhùyì zhè ge yǔfǎdiǎn de jùtǐ wèizhì hé yǔxù.", "meaningVi": "Xin mọi người chú ý vị trí cụ thể và trật tự từ của điểm ngữ pháp này."}]', N'{"question": "Điểm ngữ pháp “小数” thuộc nhóm cấu trúc nào trong ngữ pháp HSK 4?", "options": ["A. Cách biểu đạt con số - Chuẩn HSK 4", "B. Danh từ riêng", "C. Thành ngữ cổ", "D. Tiếng lóng Internet"], "correctIndex": 0, "explanation": "“Cách biểu đạt con số: 小数、分数、百分数、倍数的表示法” là điểm ngữ pháp thuộc chương trình HSK 4."}', N'ARCHIVED', NULL, N'2026-11-05 16:17:38.431253', N'2026-11-11 10:10:25.304391', N'数的表示法', N'特殊表达法', N'', N'HSK 3.0 (2025-11)', N'339', NULL, NULL, NULL, N'Biên soạn ngữ pháp chuẩn HSK 3.0 (Cấp 4)'),
    (N'5B178766-AD66-4F72-AFAA-EC607A137BB3', N'GR-HSK1-02', N'Đại từ nghi vấn 什么 (Cái gì)', N'Yíwèn dàicí "shénme"', 1, N'cơ bản', N'Động từ + 什么 (+ Danh từ)?', N'Đại từ 什么 dùng để đặt câu hỏi về đồ vật, tên gọi hoặc sự việc. Trật tự từ trong câu hỏi tiếng Trung giữ nguyên như câu trần thuật.', N'Dễ', N'[{"zh":"你叫什么名字？","pinyin":"Nǐ jiào shénme míngzi?","meaningVi":"Bạn tên là gì?"},{"zh":"这是什么书？","pinyin":"Zhè shì shénme shū?","meaningVi":"Đây là sách gì?"}]', NULL, N'PUBLISHED', N'AAAAAAAA-3333-3333-3333-333333333333', N'2026-11-04 11:43:53.599720', N'2026-11-11 08:55:45.654728', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
