    (N'04FB95F2-EEED-4A62-BB90-00803FF18B26', 3, N'层', N'層', N'céng', N'tầng, lớp', N'layer', N'量', NULL, N'[{"zh": "我们公司的办公室位于这栋现代化大厦的十六层。", "pinyin": "Wǒmen gōngsī de bàngōngshì wèiyú zhè dòng xiàndàihuà dàshà de shíliù céng.", "meaningVi": "Văn phòng công ty chúng tôi nằm ở tầng 16 của tòa cao ốc hiện đại này."}]', N'PUBLISHED', N'54C011CD-652B-41AB-AC23-06C892A3B608', N'2026-11-10 06:58:49.176666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'céng'),
    (N'B1102511-0725-51E8-B2E0-00818DA308D0', 4, N'购买', NULL, N'gòumǎi', N'mua, mua sắm', NULL, N'动', NULL, N'[{"chinese": "绿色低碳消费理念日益深入人心，越来越多的消费者主动选择购买由循环可再生材料制成的新型环保产品。", "pinyin": "Lǜsè dītàn xiāofèi lǐniàn rìyì shēnrù-rénxīn, yuèláiyuè duō de xiāofèizhě zhǔdòng xuǎnzé gòumǎi yóu xúnhuán kězàishēng cáiliào zhìchéng de xīnxíng huánbǎo chǎnpǐn.", "translation": "Quan niệm tiêu dùng xanh carbon thấp ngày càng đi sâu vào lòng người, ngày càng có nhiều người tiêu dùng chủ động chọn mua các sản phẩm thân thiện với môi trường làm từ vật liệu tuần hoàn tái chế kiểu mới."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:19.010000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'gòumǎi'),
    (N'0B590598-B7A0-578D-BF62-008349525267', 4, N'随着', N'隨著', N'suí zhe', N'cùng với, theo đà', N'along with', N'介', NULL, N'[{"zh": "随着科学技术的飞速进步，人们的生活方式发生了巨变。", "pinyin": "Suízhe kēxué jìshù de fēisù jìnbù, rénmen de shēnghuó fāngshì fāshēng le jùbiàn.", "meaningVi": "Cùng với sự tiến bộ vượt bậc của khoa học kỹ thuật, phương thức sinh hoạt của con người đã diễn ra thay đổi to lớn."}]', N'PUBLISHED', N'226C0C08-EE32-4846-B8F3-FED582E3F873', N'2026-11-10 13:22:15.693333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'suízhe'),
    (N'E4C2E4B4-8DE1-439E-A076-00959BCA2CD6', 3, N'羽毛球', NULL, N'yǔmáoqiú', N'môn cầu lông, quả cầu lông', NULL, N'名', NULL, N'[{"chinese": "周末我和弟弟常常在院子里打羽毛球。", "pinyin": "Zhōumò wǒ hé dìdi chángcháng zài yuànzi lǐ dǎ yǔmáoqiú.", "translation": "Cuối tuần tôi và em trai thường đánh cầu lông trong sân."}]', N'ARCHIVED', NULL, N'2026-11-10 06:58:48.790000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'yǔmáoqiú'),
    (N'455FF706-2461-4845-96DC-00A3201C3A43', 3, N'洗衣机', NULL, N'xǐyījī', N'máy giặt', NULL, N'名', NULL, N'[{"chinese": "妈妈把脏衣服放进洗衣机里清洗。", "pinyin": "Māma bǎ zāng yīfu fàng jìn xǐyījī lǐ qīngxǐ.", "translation": "Mẹ bỏ quần áo bẩn vào máy giặt để giặt sạch."}]', N'ARCHIVED', NULL, N'2026-11-10 06:58:49.013333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'xǐyījī'),
    (N'EF8C4074-0FE8-571D-8906-00B2C68745A2', 4, N'懒', N'嬾', N'lǎn', N'lười biếng, lười nhác (lǎn)', N'lazy', N'形', NULL, N'[{"zh": "科技创新虽然让日常生活变得极为便利，但人绝不能因此变得懒惰而丧失勤奋劳动的能力。", "pinyin": "Kējì chuàngxīn suīrán ràng rìcháng shēnghuó biànde jíwéi biànlì, dàn rén jué bù néng yīncǐ biànde lǎnduò ér sàngshī qínfèn láodòng de nénglì.", "meaningVi": "Đổi mới khoa học công nghệ tuy khiến cuộc sống thường nhật trở nên vô cùng tiện lợi, nhưng con người tuyệt đối không được vì thế mà trở nên lười biếng và đánh mất năng lực lao động chăm chỉ."}]', N'PUBLISHED', N'D0A7BB74-A49C-4D2A-B5FB-C34AF6410CF9', N'2026-11-10 13:22:18.933333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'lǎn'),
    (N'D0CBD46B-1DBC-53D9-9055-00BF6158A6D4', 4, N'使用', N'使用', N'shǐ yòng', N'sử dụng, dùng, áp dụng', N'to use', N'动', NULL, N'[{"zh": "在全球化交流中，熟练使用多种语言能够帮助人们消除沟通上的隔阂。", "pinyin": "Zài quánqiúhuà jiāoliú zhōng, shúliàn shǐyòng duō zhǒng yǔyán nénggòu bāngzhù rénmen xiāochú gōutōng shang de géhé.", "meaningVi": "Trong giao lưu toàn cầu hóa, việc sử dụng thành thạo nhiều ngôn ngữ có thể giúp mọi người xóa bỏ những rào cản ngăn cách trong giao tiếp."}]', N'PUBLISHED', N'1C92848C-099F-4B61-A466-F6381B0E9519', N'2026-11-10 13:22:18.276666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'shǐyòng'),
    (N'0AF2E606-77C0-502D-A44C-00CA9BDCBB32', 4, N'杂志', N'雜誌', N'zá zhì', N'tạp chí', N'magazine', N'名', NULL, N'[{"zh": "他在业余时间喜欢翻阅各类摄影科技杂志，了解前沿最新资讯。", "pinyin": "Tā zài yèyú shíjiān xǐhuan fānyuè gè lèi shèyǐng kējì zázhì, liǎojiě qiányán zuìxīn zīxùn.", "meaningVi": "Vào thời gian rảnh anh ấy thích lật đọc các loại tạp chí công nghệ nhiếp ảnh để tìm hiểu thông tin mới nhất."}]', N'PUBLISHED', N'575F094F-5298-41BE-B343-46849DDB0E1E', N'2026-11-10 13:22:16.960000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'zázhì'),
    (N'4CC3C2DD-223B-592F-9EC2-00F08BB7DADF', 4, N'兴奋', N'興奮', N'xīng fèn', N'phấn khích, hào hứng', N'excited', N'形、动', NULL, N'[{"zh": "听到自己被理想名校录取的消息后，他激动兴奋得整夜难以入眠。", "pinyin": "Tīngdào zìjǐ bèi lǐxiǎng míngxiào lùqǔ de xiāoxi hòu, tā jīdòng xīngfèn de zhěng yè nányǐ rùmián.", "meaningVi": "Sau khi nghe tin mình được trường đại học lý tưởng trúng tuyển, anh xúc động phấn khích cả đêm trằn trọc."}]', N'PUBLISHED', N'90A35972-4CD6-46CB-8FC0-FF111D8DFB71', N'2026-11-10 13:22:16.123333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'xīngfèn'),
    (N'B151A72A-73AA-56A0-BA5F-0126AD81FF45', 4, N'目标', NULL, N'mùbiāo', N'mục tiêu, đích đến', NULL, N'名', NULL, N'[{"chinese": "国家制定了发展绿色清洁能源的宏伟目标，力争在未来十年内显著降低工业碳排放。", "pinyin": "Guójiā zhìdìng le fāzhǎn lǜsè qīngjié néngyuán de hóngwěi mùbiāo, lìzhēng zài wèilái shí nián nèi xiǎnzhù jiàngdī gōngyè tàn páifàng.", "translation": "Nhà nước đã đặt ra mục tiêu to lớn phát triển năng lượng xanh sạch, phấn đấu trong mười năm tới giảm thiểu đáng kể lượng khí thải carbon công nghiệp."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:18.490000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'mùbiāo'),
