    (N'89960C28-B9BD-5357-B6CC-017BF8C958AF', 4, N'时间表', NULL, N'shíjiānbiǎo', N'thời gian biểu, lịch trình', NULL, N'名', NULL, N'[{"chinese": "制定科学合理的时间表能够帮助我们有条不紊地推进工作。", "pinyin": "Zhìdìng kēxué hélǐ de shíjiānbiǎo nénggòu bāngzhù wǒmen yǒutiáobùwěn de tuījìn gōngzuò.", "translation": "Lập thời gian biểu khoa học hợp lý có thể giúp chúng ta thúc đẩy công việc một cách bài bản ngăn nắp."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:15.780000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'shíjiānbiǎo'),
    (N'6C88E01F-EB82-52FD-A85E-01A635C59AA4', 4, N'相互', NULL, N'xiānghù', N'lẫn nhau, qua lại', NULL, N'副', NULL, N'[{"chinese": "同事之间相互支持与包容是团队取得成功的基石。", "pinyin": "Tóngshì zhījiān xiānghù zhīchí yǔ bāoróng shì tuánduì qǔdé chénggōng de jīshí.", "translation": "Giữa các đồng nghiệp ủng hộ và bao dung lẫn nhau là nền tảng giúp tập thể thành công."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:15.660000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'xiānghù'),
    (N'550C8E21-464E-49D1-A8D2-01BDE1444143', 3, N'放假', NULL, N'fàngjià', N'nghỉ lễ, nghỉ hè, nghỉ phép', NULL, N'动', NULL, N'[{"chinese": "下个星期学校就要放暑假了。", "pinyin": "Xià gè xīngqī xuéxiào jiù yào fàng shǔjià le.", "translation": "Tuần sau trường học sắp được nghỉ hè rồi."}]', N'ARCHIVED', NULL, N'2026-11-10 06:58:48.263333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'fàngjià'),
    (N'4393880D-C297-5E53-B0F5-01F7174B7250', 4, N'吃惊', N'吃驚', N'chī jīng', N'giật mình, kinh ngạc', N'to be startled', N'动', NULL, N'[{"zh": "得知平时成绩平平的同桌竟然在全国数学奥赛中夺冠，大家无不大吃一惊。", "pinyin": "Dézhī píngshí chéngjì píngpíng de tóngzhuō jìngrán zài quánguó shùxué àosài zhōng duóguàn, dàjiā wúbù dàchīyìjīng.", "meaningVi": "Biết tin bạn cùng bàn bình thường học lực tầm trung lại giành chức vô địch toán Olympic toàn quốc, ai nấy đều hết sức kinh ngạc."}]', N'PUBLISHED', N'C6B083F2-715D-4E95-A8FC-4A0414E25C30', N'2026-11-10 13:22:16', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'chījīng'),
    (N'01E213B8-5C0F-5E5E-870A-022448D0BA94', 4, N'同样', NULL, N'tóngyàng', N'giống nhau, tương tự, đồng dạng', NULL, N'形', NULL, N'[{"chinese": "面对同样的风景，不同心态的人往往会产生完全不同的感受。", "pinyin": "Miànduì tóngyàng de fēngjǐng, bù tóng xīntài de rén wǎngwǎng huì chǎnshēng wánquán bù tóng de gǎnshòu.", "translation": "Đứng trước cùng một phong cảnh, những người với tâm thế khác nhau thường sẽ có những cảm nhận hoàn toàn khác biệt."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:17.350000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'tóngyàng'),
    (N'1C3F122A-BA03-5717-877A-025083046FE2', 4, N'本来', N'本來', N'běn lái', N'vốn dĩ, ban đầu', N'original', N'形、副', NULL, N'[{"zh": "这项工作本来应该由他负责，但由于生病只好请同事代劳。", "pinyin": "Zhè xiàng gōngzuò běnlái yīnggāi yóu tā fùzé, dàn yóuyú shēngbìng zhǐhǎo qǐng tóngshì dàiláo.", "meaningVi": "Công việc này vốn dĩ phải do anh ấy phụ trách, nhưng do ốm đành nhờ đồng nghiệp làm giúp."}]', N'PUBLISHED', N'1E19300E-0BA0-4EA1-9D52-2247C8892171', N'2026-11-10 13:22:16.663333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'běnlái'),
    (N'97BC2FC3-8287-56B6-8E78-02DEDE1018E9', 4, N'按照', N'按照', N'àn zhào', N'theo, dựa theo, căn cứ vào', N'according to', N'介', NULL, N'[{"zh": "孩子们按照老师制订的时间表规律作息，学习状态和精神面貌都非常好。", "pinyin": "Háizimen ànzhào lǎoshī zhìdìng de shíjiānbiǎo guīlǜ zuòxī, xuéxí zhuàngtài hé jīngshén miànmào dōu fēicháng hǎo.", "meaningVi": "Các bạn nhỏ sinh hoạt điều độ theo đúng thời gian biểu do thầy cô lập ra, tình trạng học tập và tinh thần đều rất tốt."}]', N'PUBLISHED', N'1E19300E-0BA0-4EA1-9D52-2247C8892171', N'2026-11-10 13:22:18.176666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'ànzhào'),
