    (N'DD6325F0-43D5-4126-9B18-0C5C70BE582B', 3, N'成绩', N'成績', N'chéng jì', N'thành tích, điểm số', N'achievement', N'名', NULL, N'[{"zh": "他在这次汉语水平考试中取得了优秀的成绩。", "pinyin": "Tā zài zhè cì hànyǔ shuǐpíng kǎoshì zhōng qǔdé le yōuxiù de chéngjì.", "meaningVi": "Cậu ấy đã đạt thành tích xuất sắc trong kỳ thi năng lực tiếng Hán lần này."}]', N'PUBLISHED', N'54C011CD-652B-41AB-AC23-06C892A3B608', N'2026-11-10 06:58:48.133333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'chéngjì'),
    (N'C8EA72D1-A87E-46DC-B81D-0C60F40D45A6', 3, N'请客', NULL, N'qǐngkè', N'mời khách, chiêu đãi', NULL, N'动', NULL, N'[{"chinese": "今天是我生日，晚上我请客吃烤鸭。", "pinyin": "Jīntiān shì wǒ shēngrì, wǎnshang wǒ qǐngkè chī kǎoyā.", "translation": "Hôm nay là sinh nhật tôi, tối nay tôi chiêu đãi ăn vịt quay."}]', N'ARCHIVED', NULL, N'2026-11-10 06:58:48.160000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'qǐngkè'),
    (N'16540282-F603-506E-BE1A-0C848FE390A1', 4, N'肚子', N'肚子', N'dǔ zi', N'bụng, dạ dày', N'belly', N'名', NULL, N'[{"zh": "跑完五公里越野赛后，他觉得肚子饿得咕咕叫，急需补充营养。", "pinyin": "Pǎo wán wǔ gōnglǐ yuèyěsài hòu, tā juéde dùzi è de gūgū jiào, jíxū bǔchōng yíngyǎng.", "meaningVi": "Chạy xong 5 cây số giải việt dã, anh thấy bụng đói cồn cào, đang rất cần nạp dinh dưỡng."}]', N'PUBLISHED', N'ED099B26-70B5-4C9F-A171-97FBB6A69E4C', N'2026-11-10 13:22:15.943333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'dǔzi'),
    (N'3048C8BE-3A56-4541-BDC9-0C8F97EC5E95', 2, N'吧', N'吧', N'ba', N'nhé, đi, chăng (trợ từ ngữ khí)', N'(modal particle indicating suggestion or surmise)', N'Trợ từ', NULL, N'[{"zh": "我们一起走吧！", "pinyin": "Wǒmen yìqǐ zǒu ba!", "meaningVi": "Chúng ta cùng đi nhé!"}]', N'PUBLISHED', N'AFE42FE5-7D93-47A6-B77B-447DAD1E36F6', N'2026-11-11 10:10:25.304391', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary inserted cleanly', N'', N'ba'),
    (N'FD7DDA83-0D5A-549B-A248-0C998AD0D799', 4, N'生意', NULL, N'shēngyi', N'kinh doanh, buôn bán, làm ăn (shēngyi)', NULL, N'名', NULL, N'[{"chinese": "随着跨境电商平台的迅速崛起，许多传统外贸商家的海外生意变得越来越红火。", "pinyin": "Suízhe kuàjìng diànshāng píngtái de xùnsù juéqǐ, xǔduō chuántǒng wàimào shāngjiā de hǎiwài shēngyi biànde yuèláiyuè hónghuo.", "translation": "Cùng với sự trỗi dậy nhanh chóng của các nền tảng thương mại điện tử xuyên biên giới, việc làm ăn buôn bán ra nước ngoài của nhiều thương nhân ngoại thương truyền thống ngày càng phát đạt hồng phát."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:18.490000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'shēngyi'),
    (N'64CAA8C0-EF39-4781-ABEB-0C9E556A418D', 4, N'工具', N'工具', N'gōng jù', N'công cụ, đồ dùng', N'tool', N'Danh từ', NULL, N'[{"zh": "学习语言时，词典是很有用的工具。", "pinyin": "Xuéxí yǔyán shí, cídiǎn shì hěn yǒuyòng de gōngjù.", "meaningVi": "Khi học ngôn ngữ, từ điển là công cụ rất hữu ích."}]', N'PUBLISHED', N'4D554AD3-4530-48D4-846E-25F026EEFF5D', N'2026-11-11 10:10:25.304391', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary inserted cleanly', N'', N'gōngjù'),
    (N'C219A408-7130-54DF-B9DB-0CA5FE7F12C0', 4, N'否则', N'否則', N'fǒu zé', N'nếu không thì, bằng không', N'if not', N'连', NULL, N'[{"zh": "出门时请务必随手关灯关水，否则会造成大量宝贵资源的无端浪费。", "pinyin": "Chūmén shí qǐng wùbì suíshǒu guān dēng guān shuǐ, fǒuzé huì zàochéng dàliàng bǎoguì zīyuán de wúduān làngfèi.", "meaningVi": "Khi ra khỏi cửa xin hãy nhớ tiện tay tắt đèn khóa nước, nếu không thì sẽ gây lãng phí vô ích một lượng lớn tài nguyên quý giá."}]', N'PUBLISHED', N'ED099B26-70B5-4C9F-A171-97FBB6A69E4C', N'2026-11-10 13:22:17.960000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'fǒuzé'),
    (N'D6490D6B-5C87-52FE-B8BE-0CAA4DFA3677', 4, N'专门', N'專門', N'zhuān mén', N'chuyên môn, đặc biệt, chuyên', N'specialist', N'副、形', NULL, N'[{"zh": "为了深入探寻古丝绸之路的历史遗迹，他专门利用年假自驾走了一趟大西北。", "pinyin": "Wèile shēnrù tànxún gǔ Sīchóu zhī Lù de lìshǐ yíjì, tā zhuānmén lìyòng niánjià zìjià zǒu le yí tàng Dà Xīběi.", "meaningVi": "Để tìm hiểu sâu sắc về các di tích lịch sử trên Con đường Tơ lụa cổ đại, anh ấy đã đặc biệt dùng kỳ nghỉ phép năm tự lái xe đi một chuyến miền Đại Tây Bắc."}]', N'PUBLISHED', N'3815613C-581A-4EA8-92A8-F907E35F8BD4', N'2026-11-10 13:22:18.680000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'zhuānmén'),
    (N'745469DE-8ADD-5830-9F9C-0CAC30007E1A', 4, N'广播', N'廣播', N'guǎng bō', N'phát thanh, đài phát thanh, phát sóng', N'broadcast', N'动、名', NULL, N'[{"zh": "中央人民广播电台每天用多种语言向全世界广播中国的发展成就与文化魅力。", "pinyin": "Zhōngyāng Rénmín Guǎngbō Diàntái měitiān yòng duō zhǒng yǔyán xiàng quán shìjiè guǎngbō Zhōngguó de fāzhǎn chéngjiù yǔ wénhuà mèilì.", "meaningVi": "Đài Tiếng nói Nhân dân Trung ương mỗi ngày dùng nhiều thứ tiếng phát thanh ra toàn thế giới về thành tựu phát triển và sức hút văn hóa của Trung Quốc."}]', N'PUBLISHED', N'95268DAC-D50C-442A-8436-85C845D1C72F', N'2026-11-10 13:22:18.323333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'guǎngbō'),
    (N'E1502F47-3A4D-56CF-9914-0CBB74747834', 4, N'优点', N'優點', N'yōu diǎn', N'ưu điểm, thế mạnh, điểm tốt', N'merit', N'名', NULL, N'[{"zh": "智能家居系统最大的优点在于能够通过手机远程控制家电设备，既省时又省电。", "pinyin": "Zhìnéng jiājū xìtǒng zuì dà de yōudiǎn zàiyú nénggòu tōngguò shǒujī yuǎnchéng kòngzhì jiādiàn shèbèi, jì shěng shí yòu shěng diàn.", "meaningVi": "Ưu điểm lớn nhất của hệ thống nhà thông minh nằm ở chỗ có thể điều khiển từ xa thiết bị gia dụng qua điện thoại, vừa tiết kiệm thời gian vừa tiết kiệm điện."}]', N'PUBLISHED', N'1C6EDD2A-ED7C-40CB-9435-0BBAEA6C573A', N'2026-11-10 13:22:18.416666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'yōudiǎn'),
    (N'74B2C970-FBB2-525C-815C-0CCF40BC752E', 4, N'活', NULL, N'huó', N'sống; công việc, việc làm', NULL, N'动、形、名', NULL, N'[{"chinese": "这些精细的木工活需要极大的耐心和高超技巧。", "pinyin": "Zhèxiē jīngxì de mùgōnghuó xūyào jídà de nàixīn hé gāochāo jìqiǎo.", "translation": "Những công việc mộc tỉ mỉ này cần sự kiên nhẫn cao độ và tay nghề điêu luyện."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:15.650000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'huó'),
    (N'F3199EB5-853F-56D0-869E-0CE386D2AF74', 4, N'烦', NULL, N'fán', N'phiền não, bực bội', NULL, N'形、动', NULL, N'[{"chinese": "遇到不顺心的琐事时不要轻易心烦，换个角度思考问题往往能豁然开朗。", "pinyin": "Yùdào bú shùnxīn de suǒshì shí bú yào qīngyì xīnfán, huàn gè jiǎodù sīkǎo wèntí wǎngwǎng néng huòránkāilǎng.", "translation": "Gặp chuyện vụn vặt không vừa ý chớ vội phiền lòng, đổi góc độ suy nghĩ vấn đề thường sẽ bừng sáng thông suốt."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:16.190000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'fán'),
    (N'6BDD2F06-FFB8-4CAE-8BA8-0D24B0E3DBDB', 2, N'一会儿', NULL, N'yíhuìr', N'một lát, một lúc', NULL, N'数量、（副）', NULL, N'[{"zh": "请等我一会儿，我马上来。", "pinyin": "Qǐng děng wǒ yíhuìr, wǒ mǎshàng lái.", "meaningVi": "Xin đợi tôi một lát, tôi đến ngay."}]', N'ARCHIVED', NULL, N'2026-11-10 06:02:08.093333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'yíhuìr'),
    (N'56A3B421-032E-46B9-8B3D-0D5A6F50A378', 2, N'路', N'路', N'lù', N'đường, con đường', N'road', N'Danh từ / qv', NULL, N'[{"zh": "他每天都用路。", "pinyin": "Tā měitiān dōu yòng lù.", "meaningVi": "Anh ấy mỗi ngày đều dùng đường, con đường."}]', N'PUBLISHED', N'A39B8E6A-EE6E-478D-AA01-51DAD45D4E0E', N'2026-11-10 06:02:08.350000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'lù'),
    (N'BAF8BC47-338C-472E-9B77-0DA27A969D51', 3, N'看来', NULL, N'kànlái', N'xem ra, dường như', NULL, N'动', NULL, N'[{"chinese": "天空中乌云密布，看来马上就要迎来一场暴风雨。", "pinyin": "Tiānkōng zhōng wūyún mìbù, kànlai mǎshàng jiù yào yínglái yì chǎng bàofēngyǔ.", "translation": "Mây đen giăng kín bầu trời, xem ra sắp sửa đón một trận mưa bão lớn."}]', N'ARCHIVED', NULL, N'2026-11-10 06:58:49.196666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'kànlái'),
