    (N'5F1E5BE3-AF4A-58E5-A725-105840AD11DC', 4, N'儿童', N'兒童', N'ér tóng', N'trẻ em, thiếu nhi', N'child', N'名', NULL, N'[{"zh": "全社会都应当高度重视并共同保障儿童的受教育权利与身心健康成长。", "pinyin": "Quán shèhuì dōu yīngdāng gāodù zhòngshì bìng gòngtóng bǎozhàng értóng de shòujiàoyù quánlì yǔ shēnxīn jiànkāng chéngzhǎng.", "meaningVi": "Toàn xã hội đều cần hết sức coi trọng và cùng nhau bảo đảm quyền được học tập cũng như sự phát triển lành mạnh của trẻ em."}]', N'PUBLISHED', N'ED099B26-70B5-4C9F-A171-97FBB6A69E4C', N'2026-11-10 13:22:15.983333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'értóng'),
    (N'CC7EFFB8-7A6A-59B2-B09F-105B6B2D1D20', 4, N'俩', N'倆', N'liǎ', N'hai người, hai (cách nói khẩu ngữ)', N'two (colloquial equivalent of 兩個|两个)', N'数量', NULL, N'[{"zh": "他们俩是从小一起长大的好朋友，感情非常深厚。", "pinyin": "Tāmen liǎ shì cóngxiǎo yìqǐ zhǎngdà de hǎo péngyou, gǎnqíng fēicháng shēnhòu.", "meaningVi": "Hai người họ là bạn thân lớn lên cùng nhau từ bé, tình cảm vô cùng sâu đậm."}]', N'PUBLISHED', N'C27413F4-ADC8-436F-9436-1530C708008E', N'2026-11-10 13:22:16.260000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'liǎ'),
    (N'6AD5CCD6-D029-5F8D-A20A-109DCE5C094E', 4, N'礼貌', N'禮貌', N'lǐ mào', N'lịch sự, lễ phép, phép lịch sự', N'courtesy', N'名、形', NULL, N'[{"zh": "在异国他乡向当地居民问路或求助时，微笑和有礼貌的问候是最好的国际通用通行证。", "pinyin": "Zài yìguó tāxiāng xiàng dāngdì jūmín wènlù huò qiúzhù shí, wēixiào hé yǒu lǐmào de wènhòu shì zuì hǎo de guójì tōngyòng tōngxíngzhèng.", "meaningVi": "Nơi đất khách quê người khi hỏi đường hoặc nhờ vả cư dân bản địa, nụ cười và lời chào hỏi có lễ phép lịch thiệp chính là tấm thẻ thông hành thông dụng quốc tế tốt nhất."}]', N'PUBLISHED', N'D0A7BB74-A49C-4D2A-B5FB-C34AF6410CF9', N'2026-11-10 13:22:18.800000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'lǐmào'),
