    (N'586DFD6C-C2FB-5E77-849F-112B8C6D7B64', 4, N'垃圾', NULL, N'lājī', N'rác, rác rưởi', NULL, N'名', NULL, N'[{"chinese": "请大家自觉将生活垃圾分类投放，共同维护小区的清洁环境。", "pinyin": "Qǐng dàjiā zìjué jiāng shēnghuó lājī fēnlèi tóufàng, gòngtóng wéihù xiǎoqū de qīngjié huánjìng.", "translation": "Xin mọi người tự giác phân loại và vứt rác sinh hoạt đúng quy định, cùng giữ gìn môi trường sạch sẽ cho khu dân cư."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:16.556666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'lājī'),
    (N'FEBE862F-BECE-506E-9ADD-1176681FC2CE', 4, N'估计', N'估計', N'gū jì', N'ước tính, dự đoán', N'to estimate', N'动', NULL, N'[{"zh": "按照现在的施工速度，我估计下个月就能竣工。", "pinyin": "Ànzhào xiànzài de shīgōng sùdù, wǒ gūjì xià gè yuè jiù néng jùngōng.", "meaningVi": "Theo tốc độ thi công hiện nay, tôi ước tính tháng sau là có thể hoàn thành."}]', N'PUBLISHED', N'4D554AD3-4530-48D4-846E-25F026EEFF5D', N'2026-11-10 13:22:15.576666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'gūjì'),
