    (N'B22CF1E5-7158-5A33-ABC9-16699CB7CDAD', 4, N'感受', NULL, N'gǎnshòu', N'cảm nhận, trải nghiệm cảm xúc', NULL, N'动、名', NULL, N'[{"chinese": "通过亲手学包中国饺子，外国朋友们深切感受到了浓厚的中国春节家庭年味。", "pinyin": "Tōngguò qīnshǒu xué bāo Zhōngguó jiǎozi, wàiguó péngyoumen shēnqiè gǎnshòu dào le nónghòu de Zhōngguó Chūnjié jiātíng niánwèi.", "translation": "Thông qua việc tự tay học gói sủi cảo Trung Quốc, những người bạn nước ngoài đã cảm nhận sâu sắc phong vị Tết gia đình ấm cúng đậm đà của Trung Quốc."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:18.330000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'gǎnshòu'),
    (N'C6227FC2-4B47-4E14-BABA-169A84BA1574', 2, N'手', NULL, N'shǒu', N'tay, bàn tay', NULL, N'名', NULL, N'[{"zh": "饭前便后都要洗手。", "pinyin": "Fàn qián biàn hòu dōu yào xǐ shǒu.", "meaningVi": "Trước khi ăn và sau khi đi vệ sinh đều phải rửa tay."}]', N'ARCHIVED', NULL, N'2026-11-10 06:02:08.310000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'shǒu'),
    (N'7EE97CD5-6852-47B0-BB93-169D7D91D7AA', 2, N'外', N'外', N'wài', N'ngoài, bên ngoài', N'outside', N'Danh từ', NULL, N'[{"zh": "教室外有很多学生。", "pinyin": "Jiàoshì wài yǒu hěn duō xuésheng.", "meaningVi": "Ngoài phòng học có rất nhiều học sinh."}]', N'PUBLISHED', N'BAEB54F4-86EC-4EDB-A501-F632FD7921D7', N'2026-11-11 10:10:25.304391', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary inserted cleanly', N'', N'wài'),
    (N'7D321F0A-CC06-4A81-875D-16A37EA1C914', 1, N'听', N'听', N'tīng', N'nghe', N'to listen', N'Động từ', NULL, N'[{"zh": "我喜欢听音乐。", "pinyin": "Wǒ xǐhuan tīng yīnyuè.", "meaningVi": "Tôi thích nghe nhạc."}]', N'PUBLISHED', N'BC8E2F7F-91CD-4014-8BC4-BF4AEE182E41', N'2026-11-10 17:06:23.681999', N'2026-11-11 08:55:45.497257', N'209', N'听', N'', N'1', 85, N'HSK 2.0', N'209', NULL, NULL, NULL, NULL, N'Verified HSK 2.0 (THEMATIC_HSK20_MAPPING)', N'', N'tīng');
