    (N'64270CDD-9CBF-5F97-A86F-16A6F5B58E3A', 4, N'皮鞋', NULL, N'píxié', N'giày da', NULL, N'名', NULL, N'[{"chinese": "参加正式的外事商务宴会时，男士通常需要穿着得体的西服和干净的皮鞋。", "pinyin": "Cānjiā zhèngshì de wàishì shāngwù yànhuì shí, nánshì tōngcháng xūyào chuānzhuó détǐ de xīfú hé gānjìng de píxié.", "translation": "Khi tham gia yến tiệc ngoại giao thương mại trang trọng, phái nam thường cần mặc âu phục lịch sự và đi giày da sạch sẽ."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:17.860000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'píxié'),
    (N'95166732-F849-4E39-B708-16BBB0205BB8', 3, N'关', N'關', N'guān', N'đóng, tắt', N'mountain pass', N'动、（名）', NULL, N'[{"zh": "睡觉前请记得把门窗和灯都关好。", "pinyin": "Shuìjiào qián qǐng jìde bǎ ménchuāng hé dēng dōu guān hǎo.", "meaningVi": "Trước khi đi ngủ xin nhớ đóng kỹ cửa sổ và tắt đèn."}]', N'PUBLISHED', N'1078E609-B723-452D-A0DE-54A99A508DD4', N'2026-11-10 06:58:48.926666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'guān'),
    (N'5EF71CCE-39EB-5918-B966-1713CECB3EAE', 4, N'通', NULL, N'tōng', N'thông, thông suốt, đi qua (tōng)', NULL, N'动、形、（量）', NULL, N'[{"chinese": "随着这条跨越崇山峻岭的高速公路正式全线通车，原本闭塞的偏远古镇迎来了全新的发展生机。", "pinyin": "Suízhe zhè tiáo kuàyuè chóngshān-jùnlǐng de gāosù gōnglù zhèngshì quánxiàn tōngchē, yuánběn bìsè de piānyuǎn gǔzhèn yínglái le quánxīn de fāzhǎn shēngjī.", "translation": "Cùng với việc tuyến đường cao tốc băng qua muôn trùng núi non hiểm trở này chính thức thông xe toàn tuyến, cổ trấn xa xôi hẻo lánh vốn khép kín đã đón chào cơ hội phát triển hoàn toàn mới."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:18.836666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'tōng'),
    (N'B194AFCF-8288-4553-8625-17187CDD09C7', 3, N'女生', NULL, N'nǚshēng', N'học sinh nữ, bạn gái', NULL, N'名', NULL, N'[{"chinese": "我们班的女生不仅学习好，而且擅长体育。", "pinyin": "Wǒmen bān de nǚshēng bùjǐn xuéxí hǎo, érqiě shàncháng tǐyù.", "translation": "Nữ sinh lớp chúng tôi không chỉ học giỏi mà còn giỏi thể thao."}]', N'ARCHIVED', NULL, N'2026-11-10 06:58:48.943333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'nǚshēng'),
    (N'20EE5C80-018C-4A99-85EB-172F8188E1C3', 3, N'段', N'段', N'duàn', N'đoạn (thời gian, văn bản)', N'paragraph', N'量', NULL, N'[{"zh": "这一段课文请你读一下。", "pinyin": "Zhè yí duàn kèwén qǐng nǐ dú yíxià.", "meaningVi": "Đoạn bài đọc này xin mời bạn đọc một lát."}]', N'PUBLISHED', N'AF110A35-04E1-4A4F-A064-B0964F562D76', N'2026-11-10 06:58:48.266666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'duàn'),
    (N'0A35DF96-A8BC-5A8F-B19A-173557E04F05', 4, N'高于', NULL, N'gāoyú', N'cao hơn, vượt mức', NULL, N'动', NULL, N'[{"chinese": "这款新型环保节能空调的工作能效比显著高于国家规定的基准线。", "pinyin": "Zhè kuǎn xīnxíng huánbǎo jiénéng kōngtiáo de gōngzuò néngxiàobǐ xiǎnzhù gāoyú guójiā guīdìng de jīzhǔnxiàn.", "translation": "Hệ số hiệu suất năng lượng của chiếc điều hòa tiết kiệm điện thân thiện môi trường kiểu mới này cao hơn rõ rệt so với mức chuẩn do nhà nước quy định."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:17.303333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'gāoyú'),
    (N'F1F99E61-FE29-4395-B527-17395BE6792F', 1, N'他', N'他', N'tā', N'anh ấy, ông ấy, cậu ấy', N'he or him', N'Đại từ', NULL, N'[{"zh": "他是我的同学。", "pinyin": "Tā shì wǒ de tóngxué.", "meaningVi": "Cậu ấy là bạn học của tôi."}]', N'PUBLISHED', N'F6AC147D-5091-4495-B018-A935385F4B87', N'2026-11-10 17:06:23.681996', N'2026-11-11 08:55:45.494256', N'200', N'他', N'', N'1', 84, N'HSK 2.0', N'200', NULL, NULL, NULL, NULL, N'Verified HSK 2.0 (DIALOGUE_TEXT_MATCH)', N'', N'tā'),
    (N'B90DEFD9-B15B-4FC3-96C6-1739CF462D18', 3, N'男生', NULL, N'nánshēng', N'học sinh nam, con trai', NULL, N'名', NULL, N'[{"chinese": "我们班一共有十五个男生和十个女生。", "pinyin": "Wǒmen bān yígòng yǒu shíwǔ gè nánshēng hé shí gè nǚshēng.", "translation": "Lớp chúng tôi có tổng cộng mười lăm nam sinh và mười nữ sinh."}]', N'ARCHIVED', NULL, N'2026-11-10 06:58:48.506666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'nánshēng'),
    (N'A47E702A-90B1-5451-8CDF-174BFCD72470', 4, N'表格', N'表格', N'biǎo gé', N'biểu mẫu, bảng biểu', N'form', N'名', NULL, N'[{"zh": "申请参加国际留学生文化交流项目的同学，请在截止日期前将电子表格发送到指定邮箱。", "pinyin": "Shēnqǐng cānjiā guójì liúxuéshēng wénhuà jiāoliú xiàngmù de tóngxué, qǐng zài jiézhǐ rìqī qián jiāng diànzǐ biǎogé fāsòng dào zhǐdìng yóuxiāng.", "meaningVi": "Các bạn học sinh đăng ký tham gia chương trình giao lưu văn hóa lưu học sinh quốc tế xin vui lòng gửi biểu mẫu điện tử về hộp thư quy định trước ngày hạn chót."}]', N'PUBLISHED', N'1E19300E-0BA0-4EA1-9D52-2247C8892171', N'2026-11-10 13:22:18.386666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'biǎogé'),
    (N'3E2D710B-F5F4-4B49-B02F-17521E0BADD6', 1, N'东西', N'東西', N'dōng xī', N'đồ vật, đồ đạc', N'thing', N'Danh từ', NULL, N'[{"zh": "你想买什么东西？", "pinyin": "Nǐ xiǎng mǎi shénme dōngxi?", "meaningVi": "Bạn muốn mua đồ gì?"}]', N'PUBLISHED', N'5879091F-51C4-4985-B63B-6BDFC004D6E6', N'2026-11-10 17:06:23.681434', N'2026-11-11 08:55:45.414814', N'40', N'东西', N'', N'1', 80, N'HSK 2.0', N'40', NULL, NULL, NULL, NULL, N'Verified HSK 2.0 (DIALOGUE_AND_THEME_MATCH)', N'', N'dōngxī'),
    (N'0D949629-32DB-5C45-ACBA-175EC11FB8E3', 4, N'人数', NULL, N'rénshù', N'số lượng người, số người', NULL, N'名', NULL, N'[{"chinese": "为了保护脆弱的丹霞地貌，景区管理中心严格限制了每天进入核心景区的游客人数。", "pinyin": "Wèile bǎohù cuìruò de dānxiá dìmào, jǐngqū guǎnlǐ zhōngxīn yángé xiànzhì le měitiān jìnrù héxīn jǐngqū de yóukè rénshù.", "translation": "Nhằm bảo vệ địa mạo Đan Hà mong manh, trung tâm quản lý khu du lịch đã hạn chế nghiêm ngặt số lượng du khách vào khu vực lõi mỗi ngày."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:18.683333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'rénshù'),
    (N'1F89E9BC-2A07-486B-857C-1766D299E628', 3, N'工作日', NULL, N'gōngzuòrì', N'ngày làm việc trong tuần', NULL, N'名', NULL, N'[{"chinese": "从周一至周五是正常的工作日，周末大家可以在家休息。", "pinyin": "Cóng zhōuyī zhì zhōuwǔ shì zhèngcháng de gōngzuòrì, zhōumò dàjiā kěyǐ zài jiā xiūxi.", "translation": "Từ thứ Hai đến thứ Sáu là ngày làm việc bình thường, cuối tuần mọi người có thể ở nhà nghỉ ngơi."}]', N'ARCHIVED', NULL, N'2026-11-10 06:58:49.433333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'gōngzuòrì'),
    (N'DCF97A37-59D5-5EF6-B96E-179B8F163AFD', 4, N'味', NULL, N'wèi', N'vị, mùi vị', NULL, N'名', NULL, N'[{"chinese": "这道传统北京烤鸭散发着诱人的香味。", "pinyin": "Zhè dào chuántǒng Běijīng kǎoyā sànfà zhe yòurén de xiāngwèi.", "translation": "Món vịt quay Bắc Kinh truyền thống này tỏa ra mùi thơm hấp dẫn."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:15.600000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'wèi'),
