    (N'10429533-DC4B-4E05-B0CB-1A88634F1E1C', 4, N'组成', N'組成', N'zǔ chéng', N'cấu thành, tạo thành', N'to form', N'Động từ / Danh động từ', NULL, N'[{"zh": "我们班由来自五个国家的同学组成。", "pinyin": "Wǒmen bān yóu láizì wǔ ge guójiā de tóngxué zǔchéng.", "meaningVi": "Lớp chúng tôi gồm các bạn học đến từ năm quốc gia tạo thành."}]', N'PUBLISHED', N'3815613C-581A-4EA8-92A8-F907E35F8BD4', N'2026-11-11 10:10:25.304391', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary inserted cleanly', N'', N'zǔchéng'),
    (N'9675B043-945F-4647-BD23-1AA2E6AE3A8F', 3, N'使', N'使', N'shǐ', N'khiến cho, làm cho', N'to make', N'动', NULL, N'[{"zh": "经常给予孩子真诚的肯定与赞美，能使他们内心充满自信与安全感。", "pinyin": "Jīngcháng jǐyǔ háizi zhēnchéng de kěndìng yǔ zànměi, néng shǐ tāmen nèixīn chōngmǎn zìxìn yǔ ānquángǎn.", "meaningVi": "Thường xuyên dành cho con sự công nhận và khen ngợi chân thành có thể khiến nội tâm các em ngập tràn tự tin và cảm giác an toàn."}]', N'PUBLISHED', N'9283A715-761A-4561-89AB-CF23CA4DD9E6', N'2026-11-11 10:10:25.304391', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary inserted cleanly', N'', N'shǐ'),
    (N'0CFD64C7-C0EB-5CA5-9C79-1AE25B3C0A8C', 4, N'油', NULL, N'yóu', N'dầu, mỡ, dầu mỏ (nhiên liệu)', NULL, N'名', NULL, N'[{"chinese": "为了保护脆弱的近海湿地水质，港口管理部门严禁各类船只向海湾倾倒机油和生活废油。", "pinyin": "Wèile bǎohù cuìruò de jìnhǎi shīdì shuǐzhì, gǎngkǒu guǎnlǐ bùmén yánjìn gè lèi chuánzhī xiàng hǎiwān qīngdǎo jīyóu hé shēnghuó fèiyóu.", "translation": "Nhằm bảo vệ chất lượng nước đất ngập nước ven biển mong manh, cơ quan quản lý cảng nghiêm cấm mọi loại tàu bè đổ dầu máy và dầu thải sinh hoạt ra vịnh biển."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:18.623333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'yóu'),
