    (N'6F668DCF-3743-5E10-98C0-21422C4CC85F', 4, N'幽默', N'幽默', N'yōu mò', N'hài hước, hóm hỉnh', N'(loanword) humor', N'形', NULL, N'[{"zh": "王老师讲课风格幽默风趣，课堂上总是充满了同学们的欢声笑语。", "pinyin": "Wáng lǎoshī jiǎngkè fēnggé yōumò fēngqù, kètáng shang zǒngshì chōngmǎn le tóngxuémen de huānshēng xiàoyǔ.", "meaningVi": "Phong cách giảng dạy của thầy Vương rất hài hước hóm hỉnh, trong lớp học luôn tràn ngập tiếng cười nói vui vẻ của học sinh."}]', N'PUBLISHED', N'1C6EDD2A-ED7C-40CB-9435-0BBAEA6C573A', N'2026-11-10 13:22:17.986666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'yōumò'),
    (N'D23F7FEC-CAA0-4849-9A6F-2156874048A1', 3, N'面包', N'麵包', N'miàn bāo', N'bánh mì', N'bread', N'Danh từ', NULL, N'[{"zh": "早餐我想吃面包。", "pinyin": "Zǎocān wǒ xiǎng chī miànbāo.", "meaningVi": "Bữa sáng tôi muốn ăn bánh mì."}]', N'PUBLISHED', N'B9B9A099-644D-4591-821E-11620077739E', N'2026-11-11 10:10:25.304391', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary inserted cleanly', N'', N'miànbāo'),
    (N'960E78E6-1EDB-5FC2-B2D8-21650C417DBE', 4, N'难忘', NULL, N'nánwàng', N'khó quên, đáng nhớ', NULL, N'动', NULL, N'[{"chinese": "那次深入偏远山区支教的志愿者经历，成为了全班同学一生中最难忘的青春记忆。", "pinyin": "Nà cì shēnrù piānyuǎn shānqū zhījiào de zhìyuànzhě jīnglì, chéngwéi le quán bān tóngxué yìshēng zhōng zuì nánwàng de qīngchūn jìyì.", "translation": "Chuyến tình nguyện dạy học nơi vùng núi hẻo lánh năm đó đã trở thành kỷ niệm thanh xuân khó quên nhất đời của cả lớp."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:15.963333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'nánwàng'),
    (N'39915C74-5E63-41A3-A62A-2180B6147979', 3, N'班级', NULL, N'bānjí', N'lớp học, tập thể lớp', NULL, N'名', NULL, N'[{"chinese": "他在班级里乐于助人，同学们都很喜欢他。", "pinyin": "Tā zài bānjí lǐ lèyúzhùrén, tóngxuémen dōu hěn xǐhuan tā.", "translation": "Cậu ấy trong lớp hay giúp đỡ người khác, các bạn học đều rất quý mến cậu."}]', N'ARCHIVED', NULL, N'2026-11-10 06:58:49.076666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'bānjí'),
    (N'76422872-0C3C-5318-B192-21A9BEB4E434', 4, N'寒假', N'寒假', N'hán jià', N'kỳ nghỉ đông', N'winter vacation', N'名', NULL, N'[{"zh": "今年寒假，我们全家人打算前往南方一座温暖的海滨城市度假。", "pinyin": "Jīnnián hánjià, wǒmen quánjiā rén dǎsuan qiánwǎng nánfāng yí zuò wēnnuǎn de hǎibīn chéngshì dùjià.", "meaningVi": "Kỳ nghỉ đông năm nay, cả nhà chúng tôi dự định đi nghỉ dưỡng tại một thành phố biển ấm áp ở phương nam."}]', N'PUBLISHED', N'95268DAC-D50C-442A-8436-85C845D1C72F', N'2026-11-10 13:22:16.806666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'hánjià'),
    (N'1C45BB1C-BB8B-4A0B-AF7A-21B59A9B02D1', 3, N'空调', N'空調', N'kōng tiáo', N'máy điều hòa nhiệt độ', N'air conditioning', N'名', NULL, N'[{"zh": "房间里太热了，快把空调打开吧。", "pinyin": "Fángjiān lǐ tài rè le, kuài bǎ kōngtiáo dǎkāi ba.", "meaningVi": "Trong phòng nóng quá, mau bật điều hòa lên đi."}]', N'PUBLISHED', N'C13B7402-A763-42FE-8B13-2BC56DEA4E05', N'2026-11-10 06:58:48.660000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'kōngtiáo'),
    (N'58B3B359-590A-4342-A923-21DFC48B994B', 4, N'受到', N'受到', N'shòu dào', N'nhận được, bị', N'to receive', N'动', NULL, N'[{"zh": "他的精彩表演受到了全场观众的热烈鼓掌。", "pinyin": "Tā de jīngcǎi biǎoyǎn shòudào le quánchǎng guānzhòng de rèliè gǔzhǎng.", "meaningVi": "Màn biểu diễn đặc sắc của cậu ấy đã nhận được tràng pháo tay nhiệt liệt của khán giả."}]', N'PUBLISHED', N'226C0C08-EE32-4846-B8F3-FED582E3F873', N'2026-11-11 10:10:25.304391', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary inserted cleanly', N'', N'shòudào');
