    (N'E3FFE050-5120-5887-8692-22299EECC4C7', 4, N'信息', NULL, N'xìnxī', N'thông tin', NULL, N'名', NULL, N'[{"chinese": "在当今高度互联的数字化信息时代，迅速筛选真伪信息是一项核心素养。", "pinyin": "Zài dāngjīn gāodù hùlián de shùzìhuà xìnxī shídài, xùnsù shāixuǎn zhēnwěi xìnxī shì yì xiàng héxīn sùyǎng.", "translation": "Trong thời đại thông tin số hóa kết nối cao ngày nay, nhanh chóng chọn lọc thông tin thật giả là tố chất cốt lõi."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:16.116666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'xìnxī'),
    (N'C8586A13-2FC7-4AA3-8D9A-225ED62D5110', 3, N'复习', N'復習', N'fù xí', N'ôn tập, ôn lại', N'variant of 復習|复习', N'动', NULL, N'[{"zh": "考试前系统地复习学过的语法点有助于加深记忆。", "pinyin": "Kǎoshì qián xìtǒng de fùxí xué guò de yǔfǎ diǎn yǒu zhù yú jiāshēn jìyì.", "meaningVi": "Trước kỳ thi ôn tập có hệ thống các điểm ngữ pháp đã học giúp khắc sâu ghi nhớ."}]', N'PUBLISHED', N'AF110A35-04E1-4A4F-A064-B0964F562D76', N'2026-11-10 06:58:49.250000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'fùxí'),
    (N'0AEE3BD8-C5A7-53A2-9CEB-228F61801F75', 4, N'正常', N'正常', N'zhèng cháng', N'bình thường, quy chuẩn', N'regular', N'形', NULL, N'[{"zh": "经过工程人员连夜抢修，剧场的电力供应系统目前已经全部恢复正常。", "pinyin": "Jīngguò gōngchéng rényuán liányè qiǎngxiū, jùchǎng de diànlì gōngyìng xìtǒng mùqián yǐjīng quánbù huīfù zhèngcháng.", "meaningVi": "Qua một đêm nỗ lực sửa chữa của nhân viên kỹ thuật, hệ thống cấp điện của nhà hát hiện nay đã hoàn toàn khôi phục bình thường."}]', N'PUBLISHED', N'575F094F-5298-41BE-B343-46849DDB0E1E', N'2026-11-10 13:22:17.840000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'zhèngcháng'),
    (N'9F2211CB-92BE-5EE1-99FB-229A1320CD67', 4, N'聚', NULL, N'jù', N'tụ họp, sum họp, gom lại (jù)', NULL, N'动', NULL, N'[{"chinese": "在未来的星际探索时代，散布在不同科研基地的青年学者们依然会定期通过全息技术欢聚一堂。", "pinyin": "Zài wèilái de xīngjì tànsuǒ shídài, sànbù zài bùtóng kēyán jīdì de qīngnián xuézhěmen yīrán huì dìngqī tōngguò quánxī jìshù huānjù yì táng.", "translation": "Trong thời đại khám phá giữa các vì sao tương lai, các học giả trẻ phân tán ở các căn cứ nghiên cứu khác nhau vẫn sẽ định kỳ sum họp vui vẻ cùng nhau qua công nghệ ba chiều toàn phần."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:18.993333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'jù'),
    (N'6AEFD411-13E6-4AD8-96A8-22D70E63EEA7', 2, N'舒服', NULL, N'shūfu', N'dễ chịu, thoải mái', NULL, N'形', NULL, N'[{"zh": "喝了一杯热牛奶，感觉舒服多了。", "pinyin": "Hē le yì bēi rè niúnǎi, gǎnjué shūfu duō le.", "meaningVi": "Uống một cốc sữa nóng, cảm thấy dễ chịu hơn nhiều."}]', N'ARCHIVED', NULL, N'2026-11-10 06:02:08.290000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'shūfu'),
    (N'FEF0ECCB-5E92-49E7-817F-22E80FDE35C9', 3, N'检票', NULL, N'jiǎnpiào', N'soát vé, kiểm tra vé', NULL, N'动', NULL, N'[{"chinese": "旅客们请自觉排好队伍，准备在检票口按序检票乘车。", "pinyin": "Lǚkèmen qǐng zìjué pái hǎo duìwǔ, zhǔnbèi zài jiǎnpiàokǒu ànxù jiǎnpiào chéngchē.", "translation": "Hành khách xin tự giác xếp hàng, chuẩn bị lần lượt soát vé ở cửa kiểm soát để lên xe."}]', N'ARCHIVED', NULL, N'2026-11-10 06:58:49.450000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'jiǎnpiào'),
    (N'E56395AC-AD6A-4A92-AA45-2307F7F48575', 4, N'干燥', N'乾燥', N'gān zào', N'khô ráo, khô hanh', N'to dry (of weather', N'a / an', NULL, N'[{"zh": "北方的冬天天气比较干燥，要多喝水。", "pinyin": "Běifāng de dōngtiān tiānqì bǐjiào gānzào, yào duō hē shuǐ.", "meaningVi": "Mùa đông ở phương Bắc thời tiết khá hanh khô, cần uống nhiều nước."}]', N'PUBLISHED', N'4D554AD3-4530-48D4-846E-25F026EEFF5D', N'2026-11-11 10:10:25.304391', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary inserted cleanly', N'', N'gānzào'),
    (N'8C4A61BF-57B0-5FA7-AE2C-232778F55211', 4, N'死', N'死', N'sǐ', N'chết, mất mát; cực kỳ, cứng nhắc', N'to die', N'动、形、（副）', NULL, N'[{"zh": "面对未来快速迭代的新知识与新技术，我们决不能死读书、读死书，而要注重灵活实践与创新运用。", "pinyin": "Miànduì wèilái kuàisù diédài de xīn zhīshi yǔ xīn jìshù, wǒmen jué bù néng sǐ dúshū, dú sǐ shū, ér yào zhùzhòng línghuó shíjiàn yǔ chuàngxīn yùnyòng.", "meaningVi": "Đối mặt với những kiến thức và công nghệ mới cập nhật liên tục trong tương lai, chúng ta tuyệt đối không thể đọc sách cứng nhắc chết nhắc, mà cần chú trọng thực hành linh hoạt và ứng dụng sáng tạo."}]', N'PUBLISHED', N'226C0C08-EE32-4846-B8F3-FED582E3F873', N'2026-11-10 13:22:18.963333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'sǐ'),
    (N'6CE2CB2E-944B-4E6A-B679-2349ED203FDF', 3, N'身高', NULL, N'shēngāo', N'chiều cao cơ thể', NULL, N'名', NULL, N'[{"chinese": "他的身高有一米八，打篮球特别厉害。", "pinyin": "Tā de shēngāo yǒu yì mǐ bā, dǎ lánqiú tèbié lìhai.", "translation": "Chiều cao của anh ấy là một mét tám, chơi bóng rổ rất cừ."}]', N'ARCHIVED', NULL, N'2026-11-10 06:58:48.853333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'shēngāo'),
