    (N'F32D9A72-5182-5BDB-88C8-2602EF82586E', 4, N'耐心', N'耐心', N'nài xīn', N'kiên nhẫn, lòng kiên nhẫn', N'to be patient', N'形、名', NULL, N'[{"zh": "科学实验往往需要经历成百上千次的反复测试与失败，只有保持极大的耐心才能攻克科研难关。", "pinyin": "Kēxué shíyàn wǎngwǎng xūyào jīnglì chéng bǎi shàng qiān cì de fǎnfù cèshì yǔ shībài, zhǐyǒu bǎochí jídà de nàixīn cái néng gōngkè kēyán nánguān.", "meaningVi": "Thí nghiệm khoa học thường cần trải qua hàng trăm hàng ngàn lần thử nghiệm và thất bại lặp đi lặp lại, chỉ có duy trì lòng kiên nhẫn cực lớn mới có thể vượt qua ải khó khăn nghiên cứu."}]', N'PUBLISHED', N'362CB9D4-5F0C-4C98-A09B-BC3EBFCDBAA3', N'2026-11-10 13:22:18.503333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'nàixīn'),
    (N'1008D691-D08B-52F8-8FCD-2622DB90A20E', 4, N'感情', N'感情', N'gǎn qíng', N'tình cảm, cảm xúc', N'feeling', N'名', NULL, N'[{"zh": "人机对话语言模型虽然越来越聪明逼真，但依然无法替代人类之间真挚深沉的情感交流。", "pinyin": "Rén-jī duìhuà yǔyán móxíng suīrán yuèláiyuè cōngmíng bīzhēn, dàn yīrán wúfǎ tìdài rénlèi zhījiān zhēnzhì shēnchén de qínggǎn jiāoliú.", "meaningVi": "Mô hình ngôn ngữ đối thoại giữa người và máy tuy ngày càng thông minh sống động, nhưng vẫn không thể thay thế được sự giao lưu tình cảm chân thành sâu sắc giữa con người với nhau."}]', N'PUBLISHED', N'4D554AD3-4530-48D4-846E-25F026EEFF5D', N'2026-11-10 13:22:18.460000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'gǎnqíng'),
    (N'4E734ABC-0C86-555A-8CA0-2632B6AB9A38', 4, N'果汁', NULL, N'guǒzhī', N'nước ép trái cây, nước hoa quả', NULL, N'名', NULL, N'[{"chinese": "招待来自各国的国际交流生时，志愿者们贴心地准备了新鲜的果汁和传统中国绿茶。", "pinyin": "Zhāodài láizì gè guó de guójì jiāoliúshēng shí, zhìyuànzhěmen tiēxīn de zhǔnbèi le xīnxiān de guǒzhī hé chuántǒng Zhōngguó lǜchá.", "translation": "Khi tiếp đãi các sinh viên giao lưu quốc tế đến từ các nước, các tình nguyện viên đã chu đáo chuẩn bị nước ép hoa quả tươi và trà xanh truyền thống Trung Quốc."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:18.350000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'guǒzhī'),
    (N'3AB31339-8DF1-5C36-BC0D-2658FDEF9941', 4, N'另外', N'另外', N'lìng wài', N'ngoài ra, hơn nữa, mặt khác', N'additional', N'代、副、连', NULL, N'[{"zh": "除了严格限制工业污水直排以外，另外还要加快推进城市生活垃圾的减量化与分类回收。", "pinyin": "Chúle yángé xiànzhì gōngyè wūshuǐ zhípái yǐwài, lìngwài hái yào jiākuài tuījìn chéngshì shēnghuó lājī de jiǎnliànghuà yǔ fēnlèi huíshōu.", "meaningVi": "Ngoài việc hạn chế nghiêm ngặt xả thải trực tiếp nước thải công nghiệp, mặt khác còn phải đẩy nhanh việc giảm lượng và phân loại thu gom rác thải sinh hoạt đô thị."}]', N'PUBLISHED', N'C27413F4-ADC8-436F-9436-1530C708008E', N'2026-11-10 13:22:18.570000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'lìngwài'),
