    (N'3D95C214-0CBE-50AD-BAAA-26A7AF0F227C', 4, N'难道', N'難道', N'nán dào', N'chẳng lẽ, há lẽ', N'don''t tell me ...', N'副', NULL, N'[{"zh": "难道面对眼前的微小挫折，你就要轻易放弃自己多年坚持的崇高理想吗？", "pinyin": "Nándào miànduì yǎnqián de wēixiǎo cuòzhé, nǐ jiù yào qīngyì fàngqì zìjǐ duō nián jiānchí de chónggāo lǐxiǎng ma?", "meaningVi": "Chẳng lẽ đối mặt với chút trắc trở nhỏ trước mắt mà bạn lại dễ dàng từ bỏ lý tưởng cao cả mình kiên trì bao năm sao?"}]', N'PUBLISHED', N'362CB9D4-5F0C-4C98-A09B-BC3EBFCDBAA3', N'2026-11-10 13:22:16.096666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'nándào'),
    (N'78A1D13D-ABAA-5FD7-9B68-26B20390F512', 4, N'调查', N'調查', N'diào chá', N'điều tra, khảo sát', N'investigation', N'动', NULL, N'[{"zh": "文化研究所开展了一项问卷调查，以了解当下年轻群体对传统戏曲的兴趣偏好。", "pinyin": "Wénhuà yánjiūsuǒ kāizhǎn le yí xiàng wènjuàn diàochá, yǐ liǎojiě dāngxià niánqīng qúntǐ duì chuántǒng xìqǔ de xìngqù piānhào.", "meaningVi": "Viện nghiên cứu văn hóa đã triển khai một cuộc điều tra bằng bảng hỏi để tìm hiểu sở thích của giới trẻ hiện nay đối với hí khúc truyền thống."}]', N'PUBLISHED', N'E7F82F5D-5ED2-440B-8369-FE116EE51ABC', N'2026-11-10 13:22:17.893333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'diàochá'),
    (N'66B2DF64-A921-5CCD-82C4-26B6AC41439E', 4, N'暖和', N'暖和', N'nuǎn huo', N'ấm áp, dễ chịu', N'warm', N'形、动', NULL, N'[{"zh": "春天来了，微风吹在脸上感觉非常暖和，各所高校里的跨文化交流活动也活跃起来。", "pinyin": "Chūntiān lái le, wēifēng chuī zài liǎn shang gǎnjué fēicháng nuǎnhuo, gè suǒ gāoxiào lǐ de kuà-wénhuà jiāoliú huódòng yě huóyuè qǐlai.", "meaningVi": "Mùa xuân đã đến, gió nhẹ thổi vào mặt cảm thấy rất đỗi ấm áp, các hoạt động giao lưu đa văn hóa trong các trường đại học cũng sôi nổi hẳn lên."}]', N'PUBLISHED', N'362CB9D4-5F0C-4C98-A09B-BC3EBFCDBAA3', N'2026-11-10 13:22:18.346666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'nuǎnhuo'),
