    (N'B7A58BB0-D1C7-580D-9AB9-2784D57DE353', 4, N'护士', N'護士', N'hù shì', N'y tá', N'nurse', N'名', NULL, N'[{"zh": "景区医疗急救站的护士技术娴熟，迅速帮扭伤脚踝的徒步登山爱好者处理好了伤口。", "pinyin": "Jǐngqū yīliáo jíjiùzhàn de hùshi jìshù xiánshú, xùnsù bāng niǔshāng jiǎohuái de túbù dēngshān àihàozhě chǔlǐ hǎo le shāngkǒu.", "meaningVi": "Cô y tá của trạm cấp cứu y tế khu danh thắng có tay nghề thuần thục, đã nhanh chóng xử lý gọn gàng vết thương cho người đam mê leo núi bị trẹo mắt cá chân."}]', N'PUBLISHED', N'DC410BC5-6799-4156-BEF8-3A2CCBE4A1A6', N'2026-11-10 13:22:18.750000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'hùshì'),
    (N'B6195B86-2AB7-584C-9006-27D9C89ACDBA', 4, N'表现', NULL, N'biǎoxiàn', N'biểu hiện, thể hiện, phong độ', NULL, N'动', NULL, N'[{"chinese": "这款由我国自主研发的高铁列车在极寒高温等严酷气候测试中，各系统均表现出极佳的稳定性能。", "pinyin": "Zhè kuǎn yóu wǒ guó zìzhǔ yánfā de gāotiě lièchē zài jíhán gāowēn děng yánkù qìhòu cèshì zhōng, gè xìtǒng jūn biǎoxiàn chū jí jiā de wěndìng xìngnéng.", "translation": "Đoàn tàu cao tốc do nước ta tự chủ nghiên cứu phát triển này trong các bài kiểm tra khí hậu khắc nghiệt như cực lạnh và nhiệt độ cao, các hệ thống đều thể hiện tính năng ổn định xuất sắc."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:18.510000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'biǎoxiàn'),
    (N'75E620AE-9538-5E9E-BD24-27DAC305BEAA', 4, N'艺术', N'藝術', N'yì shù', N'nghệ thuật', N'art', N'名', NULL, N'[{"zh": "未来的艺术创作不再局限于画布与乐器，数字虚拟现实与生成算法正在开拓人类前所未有的艺术表现维度。", "pinyin": "Wèilái de yìshù chuàngzuò bú zài júxiàn yú huàbù yǔ yuèqì, shùzì xūnǐ xiànshí yǔ shēngchéng suànfǎ zhèngzài kāituò rénlèi qiánsuǒwèiyǒu de yìshù biǎoxiàn wéidù.", "meaningVi": "Sáng tác nghệ thuật tương lai không còn bó hẹp nơi khung vẽ và nhạc cụ, thực tế ảo kỹ thuật số cùng thuật toán tạo sinh đang mở ra những chiều kích biểu đạt nghệ thuật chưa từng có của con người."}]', N'PUBLISHED', N'C8DC9FD6-E848-464D-A0F0-80259D92C427', N'2026-11-10 13:22:18.996666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'yìshù'),
    (N'13E17412-C0C0-4AEE-87DF-27DC9914CF6F', 2, N'过', NULL, N'guo', N'từng (trợ từ chỉ trải nghiệm)', NULL, N'助', NULL, N'[{"zh": "我去过中国北京和上海旅游。", "pinyin": "Wǒ qù guò Zhōngguó Běijīng hé Shànghǎi lǚyóu.", "meaningVi": "Tôi từng đi du lịch Bắc Kinh và Thượng Hải của Trung Quốc."}]', N'ARCHIVED', NULL, N'2026-11-10 06:02:08.510000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'guo'),
    (N'D2855034-A75F-5D15-878F-2804FEF0A5EB', 4, N'增加', N'增加', N'zēng jiā', N'tăng thêm, gia tăng', N'to raise', N'动', NULL, N'[{"zh": "举办国际留学生文化节，有力地增加了各国青年学者之间的了解与深厚友谊。", "pinyin": "Jǔbàn guójì liúxuéshēng wénhuàjié, yǒulì de zēngjiā le gè guó qīngnián xuézhě zhījiān de liǎojiě yǔ shēnhòu yǒuyì.", "meaningVi": "Việc tổ chức ngày hội văn hóa lưu học sinh quốc tế đã tăng cường mạnh mẽ sự hiểu biết và tình bạn sâu sắc giữa các học giả trẻ của các quốc gia."}]', N'PUBLISHED', N'575F094F-5298-41BE-B343-46849DDB0E1E', N'2026-11-10 13:22:18.310000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'zēngjiā');
  INSERT INTO [vocabularies] ([Id], [HskLevel], [Hanzi], [Traditional], [Pinyin], [MeaningVi], [MeaningEn], [PartOfSpeech], [AudioUrl], [ExamplesJson], [Status], [LessonId], [CreatedAt], [UpdatedAt], [SourceId], [Entry], [Homograph], [LevelLabel], [SourcePdfPage], [SourceDataset], [SourceEntryId], [SuggestedMeaningVi], [UpdatedByUserId], [ReviewedByUserId], [ReviewedAt], [ReviewNotes], [NormalizedHomograph], [NormalizedPinyin]) VALUES
    (N'6F1D0EA5-CAEE-5806-8FAB-28148FF01484', 4, N'此次', NULL, N'cǐ cì', N'lần này, đợt này', NULL, N'', NULL, N'[{"chinese": "在此次联合国生物多样性公约缔约方大会上，各国代表共同签署了保护生态地球的联合宣言。", "pinyin": "Zài cǐ cì Liánhéguó Shēngwù Duōyàngxìng Gōngyuē Dìyuēfāng Dàhuì shang, gè guó dàibiǎo gòngtóng qiānshǔ le bǎohù shēngtài Dìqiú de liánhé xuānyán.", "translation": "Tại Hội nghị các bên tham gia Công ước Đa dạng Sinh học Liên Hợp Quốc lần này, đại diện các nước đã cùng ký kết tuyên bố chung về bảo vệ Trái đất sinh thái."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:18.620000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'cǐcì'),
    (N'4E0C54CA-6E9B-585A-AC6F-2816290FEE03', 4, N'价格', N'價格', N'jià gé', N'giá cả, mức giá', N'price', N'名', NULL, N'[{"zh": "这家书店的艺术画册不仅印刷精美，而且价格十分合理。", "pinyin": "Zhè jiā shūdiàn de yìshù huàcè bùjǐn yìnshuā jīngměi, érqiě jiàgé shífēn hélǐ.", "meaningVi": "Các tập tranh nghệ thuật của hiệu sách này không chỉ in ấn đẹp mắt mà giá cả còn rất hợp lý."}]', N'PUBLISHED', N'DC410BC5-6799-4156-BEF8-3A2CCBE4A1A6', N'2026-11-10 13:22:17.316666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'jiàgé'),
    (N'E14A7CE7-3041-44E2-A189-283EBC1B4791', 2, N'要', N'要', N'yào', N'muốn, cần, phải, sắp', N'important', N'Động từ', NULL, N'[{"zh": "我要一杯热茶。", "pinyin": "Wǒ yào yì bēi rè chá.", "meaningVi": "Tôi muốn một cốc trà nóng."}]', N'PUBLISHED', N'7FB11B06-A247-43A7-8A74-1A73A796D060', N'2026-11-11 10:10:25.304391', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary inserted cleanly', N'', N'yào'),
    (N'2CA354CB-C6FD-55C0-80C2-284103DB6F2F', 4, N'饼干', N'餅乾', N'bǐng gān', N'bánh quy, bánh bích quy', N'biscuit', N'名', NULL, N'[{"zh": "下午茶歇时间，同事们在茶水间冲了一壶咖啡，配着几块香脆的燕麦饼干。", "pinyin": "Xiàwǔ cháxiē shíjiān, tóngshìmen zài cháshuǐjiān chōng le yì hú kāfēi, pèi zhe jǐ kuài xiāngcuì de yànmài bǐnggān.", "meaningVi": "Lúc nghỉ giải lao trà chiều, các đồng nghiệp pha một ấm cà phê trong phòng trà, ăn kèm mấy chiếc bánh quy yến mạch giòn thơm."}]', N'PUBLISHED', N'1E19300E-0BA0-4EA1-9D52-2247C8892171', N'2026-11-10 13:22:16.100000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'bǐnggān'),
    (N'1614ACFF-8F5E-4850-B145-284D59D1EB20', 3, N'打扫', N'打掃', N'dǎ sǎo', N'quét dọn, dọn dẹp', N'to clean', N'动', NULL, N'[{"zh": "周末我们把整个房间都打扫干净了。", "pinyin": "Zhōumò wǒmen bǎ zhènggè fángjiān dōu dǎsǎo gānjìng le.", "meaningVi": "Cuối tuần chúng tôi đã dọn dẹp sạch sẽ cả căn phòng."}]', N'PUBLISHED', N'54C011CD-652B-41AB-AC23-06C892A3B608', N'2026-11-10 06:58:48.493333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'dǎsǎo'),
    (N'9679769A-D7B0-549C-A9A8-289100C29BA4', 4, N'作者', N'作者', N'zuò zhě', N'tác giả, người viết', N'author', N'名', NULL, N'[{"zh": "这本书的作者通过生动的故事，向读者普及了全球气候变暖的知识。", "pinyin": "Zhè běn shū de zuòzhě tōngguò shēngdòng de gùshi, xiàng dúzhě pǔjí le quánqiú qìhòu biànnuǎn de zhīshi.", "meaningVi": "Tác giả của cuốn sách này thông qua những câu chuyện sinh động đã phổ biến kiến thức về hiện tượng nóng lên toàn cầu tới độc giả."}]', N'PUBLISHED', N'3815613C-581A-4EA8-92A8-F907E35F8BD4', N'2026-11-10 13:22:17.933333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'zuòzhě'),
    (N'C61021B1-4BB6-4F44-A7F1-289F02C101FF', 4, N'语言', N'語言', N'yǔ yán', N'ngôn ngữ, tiếng nói', N'language', N'名', NULL, N'[{"zh": "语言是世界各国人民之间增进沟通与理解的重要桥梁。", "pinyin": "Yǔyán shì shìjiè gèguó rénmín zhījiān zēngjìn gōutōng yǔ lǐjiě de zhòngyào qiáoliáng.", "meaningVi": "Ngôn ngữ là nhịp cầu quan trọng thúc đẩy giao lưu và thấu hiểu giữa nhân dân các nước trên thế giới."}]', N'PUBLISHED', N'1C6EDD2A-ED7C-40CB-9435-0BBAEA6C573A', N'2026-11-11 10:10:25.304391', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary inserted cleanly', N'', N'yǔyán'),
    (N'7AEC8800-1469-4545-AD6B-289F609DBF88', 3, N'季节', N'季節', N'jì jié', N'mùa, mùa màng', N'time', N'名', NULL, N'[{"zh": "一年有四个季节，我最喜欢秋天。", "pinyin": "Yì nián yǒu sì gè jìjié, wǒ zuì xǐhuan qiūtiān.", "meaningVi": "Một năm có bốn mùa, tôi thích nhất là mùa thu."}]', N'PUBLISHED', N'9BE95DDD-C208-444A-8445-DB5B67016DC4', N'2026-11-10 06:58:48.190000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'jìjié'),
    (N'1CD18CB4-5E32-51B0-8C0A-28A9EBCD6C29', 4, N'而', N'而', N'ér', N'mà, và, lại (liên từ biểu thị kết nối hoặc tương phản)', N'and', N'连', NULL, N'[{"zh": "文化不是封闭孤立的，而是要在文明互鉴与交流融合中才能焕发出勃勃生机。", "pinyin": "Wénhuà bú shì fēngbì gūlì de, ér shì yào zài wénmíng hùjiàn yǔ jiāoliú rónghé zhōng cái néng huànfā chū bóbó shēngjī.", "meaningVi": "Văn hóa không phải là thứ khép kín cô lập, mà phải thông qua học hỏi lẫn nhau và giao lưu hòa nhập giữa các nền văn minh thì mới tỏa sáng sức sống dạt dào."}]', N'PUBLISHED', N'ED099B26-70B5-4C9F-A171-97FBB6A69E4C', N'2026-11-10 13:22:18.380000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'ér'),
    (N'AD52ABAC-6C54-58B1-B9C9-28AF87FD7161', 4, N'词语', NULL, N'cíyǔ', N'từ ngữ, thuật ngữ', NULL, N'名', NULL, N'[{"chinese": "随着科学技术的飞速演进，人工智能、量子计算、低碳生活等一系列新时代词语不断丰富着现代汉语词汇库。", "pinyin": "Suízhe kēxué jìshù de fēisù yǎnjìn, réngōng zhìnéng, liàngzǐ jìsuàn, dītàn shēnghuó děng yí xìliè xīn shídài cíyǔ búduàn fēngfù zhe xiàndài Hànyǔ cíhuìkù.", "translation": "Cùng với sự tiến triển vượt bậc của khoa học công nghệ, hàng loạt từ ngữ thời đại mới như trí tuệ nhân tạo, tính toán lượng tử, lối sống carbon thấp không ngừng làm giàu thêm cho kho từ vựng tiếng Hán hiện đại."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:19.003333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'cíyǔ'),
    (N'42B6515F-4292-5611-843E-28CBB997FA6F', 4, N'抱歉', N'抱歉', N'bào qiàn', N'xin lỗi, lấy làm tiếc', N'to be sorry', N'形', NULL, N'[{"zh": "非常抱歉因路上突发交通管制耽搁了时间，让大家在会议室久等了。", "pinyin": "Fēicháng bàoqiàn yīn lù shang tūfā jiāotōng guǎnzhì dāngē le shíjiān, ràng dàjiā zài huìyìshì jiǔ děng le.", "meaningVi": "Rất xin lỗi vì trên đường bất ngờ phân luồng giao thông làm lỡ dở thời gian, để mọi người đợi lâu."}]', N'PUBLISHED', N'1E19300E-0BA0-4EA1-9D52-2247C8892171', N'2026-11-10 13:22:16.170000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'bàoqiàn'),
    (N'14FDC6DB-557B-5486-925D-29240E62B2B8', 4, N'敢', NULL, N'gǎn', N'dám, can đảm', NULL, N'动', NULL, N'[{"chinese": "只要你有克服困难的坚定决心，就没有什么不敢面对的挑战。", "pinyin": "Zhǐyào nǐ yǒu kèfú kùnnan de jiāndìng juéxīn, jiù méiyǒu shénme bù gǎn miànduì de tiǎozhàn.", "translation": "Chỉ cần bạn có quyết tâm kiên định vượt qua khó khăn thì không có thử thách nào là không dám đương đầu."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:17.826666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'gǎn'),
    (N'DC5D33C5-B4F4-4205-AEBA-292EB0F76C29', 3, N'西南', NULL, N'xīnán', N'phía tây nam', NULL, N'名', NULL, N'[{"chinese": "成都位于中国的西南部，生活节奏很慢。", "pinyin": "Chéngdū wèiyú Zhōngguó de xīnánbù, shēnghuó jiézòu hěn màn.", "translation": "Thành Đô nằm ở phía tây nam của Trung Quốc, nhịp sống rất thong thả."}]', N'ARCHIVED', NULL, N'2026-11-10 06:58:48.356666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'xīnán'),
