    (N'4F62D1C7-BBF1-5D1F-ADAB-3278A6B0B28F', 4, N'赶上', NULL, N'gǎnshàng', N'bắt kịp, theo kịp', NULL, N'动', NULL, N'[{"chinese": "我们要抓紧时间加倍努力，争取早日赶上国际先进科技水平。", "pinyin": "Wǒmen yào zhuājǐn shíjiān jiābèi nǔlì, zhēngqǔ zǎorì gǎnshàng guójì xiānjìn kējì shuǐpíng.", "translation": "Chúng ta cần tranh thủ thời gian nhân đôi nỗ lực, phấn đấu sớm ngày theo kịp trình độ công nghệ tiên tiến quốc tế."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:16.870000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'gǎnshàng'),
    (N'F78BB56D-C872-5AA3-AF10-327F243D46A2', 4, N'流利', N'流利', N'liú lì', N'lưu loát, trôi chảy', N'fluent', N'形', NULL, N'[{"zh": "经过在中文系三年刻苦学习，这位外国留学生已经能说一口十分流利的普通话。", "pinyin": "Jīngguò zài zhōngwénxì sān nián kèkǔ xuéxí, zhè wèi wàiguó liúxuéshēng yǐjīng néng shuō yì kǒu shífēn liúlì de pǔtōnghuà.", "meaningVi": "Qua 3 năm học chăm chỉ ở khoa tiếng Trung, bạn du học sinh này đã có thể nói tiếng phổ thông rất lưu loát."}]', N'PUBLISHED', N'C27413F4-ADC8-436F-9436-1530C708008E', N'2026-11-10 13:22:16.190000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'liúlì'),
