    (N'5F495680-6993-4589-AC25-3296C1D29A6B', 4, N'吵', N'吵', N'chǎo', N'ồn ào, làm ồn, cãi nhau', N'to quarrel', N'Động từ', NULL, N'[{"zh": "图书馆里不能太吵，大家要保持安静。", "pinyin": "Túshūguǎn lǐ bù néng tài chǎo, dàjiā yào bǎochí ānjìng.", "meaningVi": "Trong thư viện không được quá ồn ào, mọi người cần giữ yên lặng."}]', N'PUBLISHED', N'C6B083F2-715D-4E95-A8FC-4A0414E25C30', N'2026-11-11 10:10:25.304391', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary inserted cleanly', N'', N'chǎo'),
    (N'F281CF22-03DF-5D2B-A704-32AB4D8B86FB', 4, N'旅客', NULL, N'lǚkè', N'hành khách, lữ khách', NULL, N'名', NULL, N'[{"chinese": "候车大厅里坐满了等待乘车的旅客，大家都在安静等候。", "pinyin": "Hòuchē dàtīng lǐ zuòmǎn le děngdài chéngchē de lǚkè, dàjiā dōu zài ānjìng děnghòu.", "translation": "Sảnh chờ chật kín hành khách đang chờ lên xe, mọi người đều trật tự chờ đợi."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:16.460000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'lǚkè'),
