    (N'79998DDC-D3E8-5961-A502-338D37612E1F', 4, N'紧张', N'緊張', N'jǐn zhāng', N'căng thẳng, hồi hộp; gấp rút', N'nervous', N'形', NULL, N'[{"zh": "平时在都市快节奏的工作容易让人神经紧绷，到山野间旅行能有效缓解长期积累的紧张情绪。", "pinyin": "Píngshí zài dūshì kuài jiézòu de gōngzuò róngyì ràng rén shénjīng jǐnbēng, dào shānyě jiān lǚxíng néng yǒuxiào huǎnjiě chángqī jīlěi de jǐnzhāng qíngxù.", "meaningVi": "Ngày thường làm việc với nhịp sống hối hả nơi đô thị dễ khiến con người căng thẳng thần kinh, đi du lịch giữa núi rừng hoang sơ có thể xoa dịu hiệu quả tâm trạng căng thẳng tích tụ lâu ngày."}]', N'PUBLISHED', N'CB223D54-B351-4EBC-9A47-018CA23AE6CE', N'2026-11-10 13:22:18.806666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'jǐnzhāng'),
    (N'07217978-3521-4286-B36D-339E2372A1C7', 2, N'次', N'次', N'cì', N'lần, lượt (lượng từ)', N'next in sequence', N'qv / a', NULL, N'[{"zh": "他每天都用次。", "pinyin": "Tā měitiān dōu yòng cì.", "meaningVi": "Anh ấy mỗi ngày đều dùng lần, lượt (lượng từ)."}]', N'PUBLISHED', N'993A640F-2A33-4E82-A7BE-0787339EF4DD', N'2026-11-10 06:02:08.450000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'cì'),
    (N'24336DE3-445C-5A0E-AB72-33C21D83CC32', 4, N'笨', N'笨', N'bèn', N'chậm chạp, vụng về', N'stupid', N'形', NULL, N'[{"zh": "世界上从来没有天生愚笨之人，后天的勤奋与专注才是成才的关键。", "pinyin": "Shìjiè shang cónglái méiyǒu tiānshēng yúbèn zhī rén, hòutiān de qínfèn yǔ zhuānzhù cái shì chéngcái de guānjiàn.", "meaningVi": "Trên đời không bao giờ có người sinh ra đã ngốc nghếch, sự chăm chỉ và tập trung mới là chìa khóa thành tài."}]', N'PUBLISHED', N'1E19300E-0BA0-4EA1-9D52-2247C8892171', N'2026-11-10 13:22:16.203333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'bèn'),
    (N'9CF20593-650E-49E7-B7E5-33E08CCB81E1', 3, N'后天', NULL, N'hòutiān', N'ngày kia, ngày mốt', NULL, N'名', NULL, N'[{"chinese": "明天我要开会，后天下午我们再见面吧。", "pinyin": "Míngtiān wǒ yào kāihuì, hòutiān xiàwǔ wǒmen zài jiànmiàn ba.", "translation": "Ngày mai tôi phải họp, chiều ngày kia chúng ta hãy gặp lại nhé."}]', N'ARCHIVED', NULL, N'2026-11-10 06:58:48.936666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'hòutiān'),
    (N'846C9638-A3CE-484B-AC2F-33EF6D30B5A1', 4, N'打扮', N'打扮', N'dǎ ban', N'trang điểm, ăn diện', N'to decorate', N'Động từ / Danh từ', NULL, N'[{"zh": "今天是朋友的婚礼，她认真打扮了一下。", "pinyin": "Jīntiān shì péngyou de hūnlǐ, tā rènzhēn dǎban le yíxià.", "meaningVi": "Hôm nay là đám cưới bạn, cô ấy chăm chút trang điểm một chút."}]', N'PUBLISHED', N'C6B083F2-715D-4E95-A8FC-4A0414E25C30', N'2026-11-11 10:10:25.304391', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary inserted cleanly', N'', N'dǎban'),
    (N'BEB00744-F37D-43EE-8671-3421B1BDF5DB', 2, N'妻子', N'妻子', N'qī zǐ', N'vợ', N'wife', N'Danh từ', NULL, N'[{"zh": "他每天都用妻子。", "pinyin": "Tā měitiān dōu yòng qīzi.", "meaningVi": "Anh ấy mỗi ngày đều dùng vợ."}]', N'PUBLISHED', N'162494EB-C345-47A0-BF11-2BC4FA7A2726', N'2026-11-10 06:02:08.416666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'qīzǐ'),
    (N'B473F9E1-2336-5738-8BF2-3424577BFBCC', 4, N'放松', NULL, N'fàngsōng', N'thư giãn, thả lỏng', NULL, N'动', NULL, N'[{"chinese": "周末闲暇时去风景优美的森林公园散步，是身心得到彻底放松的极佳方式。", "pinyin": "Zhōumò xiánxiá shí qù fēngjǐng yōuměi de sēnlíngōngyuán sànbù, shì shēnxīn dédào chèdǐ fàngsōng de jí jiā fāngshì.", "translation": "Cuối tuần rảnh rỗi đến công viên rừng rậm phong cảnh tươi đẹp đi dạo là cách tuyệt vời để thả lỏng cơ thể."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:16.173333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'fàngsōng'),
