    (N'6460008C-4428-459D-94F0-3850E0E8C99D', 2, N'第一', N'第一', N'dì yī', N'thứ nhất, đầu tiên', N'first', N'Lượng từ', NULL, N'[{"zh": "他每天都用第一。", "pinyin": "Tā měitiān dōu yòng dì.", "meaningVi": "Anh ấy mỗi ngày đều dùng first (第一)."}]', N'PUBLISHED', N'9CE302E9-87FE-4705-9836-74E75E2BFE70', N'2026-11-11 10:10:25.304391', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary inserted cleanly', N'', N'dìyī'),
    (N'E77DB6AE-8607-523B-9FD4-3865C1D41259', 4, N'分数', NULL, N'fēnshù', N'điểm số, điểm thi', NULL, N'名', NULL, N'[{"chinese": "考卷的分数虽然很重要，但学习掌握扎实知识的过程更加可贵。", "pinyin": "Kǎojuàn de fēnshù suīrán hěn zhòngyào, dàn xuéxí zhǎngwò zhāshi zhīshi de guòchéng gèngjiā kěguì.", "translation": "Điểm số trên bài thi tuy quan trọng, nhưng quá trình học tập nắm vững kiến thức chắc chắn còn đáng quý hơn."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:16.903333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'fēnshù'),
    (N'2CC42E2B-3336-4A6A-BA37-387EB46AB0A9', 3, N'果汁', N'果汁', N'guǒ zhī', N'nước ép trái cây, nước hoa quả', N'fruit juice', N'名', NULL, N'[{"zh": "招待来自各国的国际交流生时，志愿者们贴心地准备了新鲜的果汁和传统中国绿茶。", "pinyin": "Zhāodài láizì gè guó de guójì jiāoliúshēng shí, zhìyuànzhěmen tiēxīn de zhǔnbèi le xīnxiān de guǒzhī hé chuántǒng Zhōngguó lǜchá.", "meaningVi": "Khi tiếp đãi các sinh viên giao lưu quốc tế đến từ các nước, các tình nguyện viên đã chu đáo chuẩn bị nước ép hoa quả tươi và trà xanh truyền thống Trung Quốc."}]', N'PUBLISHED', N'522FC009-A8BB-411F-A048-62C62D56E649', N'2026-11-11 10:10:25.304391', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary inserted cleanly', N'', N'guǒzhī');
