    (N'1DD770AB-14C1-526E-BEDF-388AEFE41ACB', 4, N'困难', N'困難', N'kùn nán', N'khó khăn, trở ngại, gian nan', N'difficult', N'形、名', NULL, N'[{"zh": "在荒漠化极其严重的戈壁滩上植树造林，面临着缺水和风沙侵袭等重重巨大困难。", "pinyin": "Zài huāngmòhuà jíqí yánzhòng de gēbìtān shang zhíshù zàolín, miànlín zhe quēshuǐ hé fēngshā qīnxí děng chóngchóng jùdà kùnnan.", "meaningVi": "Việc trồng cây gây rừng trên bãi cát sa mạc hóa cực kỳ nghiêm trọng đối mặt với vô vàn khó khăn to lớn như thiếu nước và bão cát xâm thực."}]', N'PUBLISHED', N'D0A7BB74-A49C-4D2A-B5FB-C34AF6410CF9', N'2026-11-10 13:22:18.573333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'kùnnán'),
    (N'FE019D6E-D616-4F23-9D1E-38CE52C9EC7B', 3, N'搬', N'搬', N'bān', N'chuyển, dời', N'to move', N'动', NULL, N'[{"zh": "几个热心的小伙子主动帮老奶奶把沉重的箱子搬上了楼。", "pinyin": "Jǐ gè rèxīn de xiǎohuǒzi zhǔdòng bāng lǎonǎinai bǎ chénzhòng de xiāngzi bān shàng le lóu.", "meaningVi": "Mấy chàng trai trẻ nhiệt tình chủ động giúp bà cụ vác chiếc hòm nặng lên lầu."}]', N'PUBLISHED', N'46AC4A4F-4F6A-4B90-BBBF-37FF149FD73D', N'2026-11-10 06:58:49.263333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'bān'),
    (N'43A85671-5CB7-5BDF-A39A-38D0BF0405B8', 4, N'步', NULL, N'bù', N'bước, bước chân, nhịp bước', NULL, N'名', NULL, N'[{"chinese": "读万卷书不如行万里路，迈开脚步去丈量世界，才能真正开阔眼界与胸襟。", "pinyin": "Dú wàn juàn shū bùrú xíng wàn lǐ lù, màikāi jiǎobù qù zhàngliáng shìjiè, cái néng zhēnzhèng kāikuò yǎnjiè yǔ xiōngjīn.", "translation": "Đọc vạn cuốn sách không bằng đi vạn dặm đường, hãy rảo bước chân để đo lường thế giới thì mới thực sự mở rộng được tầm mắt và tấm lòng."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:18.773333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'bù'),
    (N'CD85B003-D40A-505B-B540-38D1BDFCA8D7', 4, N'小组', NULL, N'xiǎozǔ', N'nhóm, tổ công tác', NULL, N'名', NULL, N'[{"chinese": "我们小组经过通力合作，顺利完成了调研报告。", "pinyin": "Wǒmen xiǎozǔ jīngguò tōnglì hézuò, shùnlì wánchéng le diàoyán bàogào.", "translation": "Nhóm chúng tôi qua sự chung sức hợp tác đã hoàn thành thuận lợi bản báo cáo khảo sát."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:15.616666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'xiǎozǔ'),
    (N'65E943B6-84CF-490E-909D-38EFFFDBE987', 1, N'我们', N'我們', N'wǒ men', N'chúng tôi, chúng mình, chúng ta', N'we', N'Đại từ', NULL, N'[{"zh": "我们都是朋友。", "pinyin": "Wǒmen dōu shì péngyou.", "meaningVi": "Chúng tôi đều là bạn bè."}]', N'PUBLISHED', N'AAAAAAAA-1111-1111-1111-111111111111', N'2026-11-10 17:06:23.682003', N'2026-11-11 08:55:45.498259', N'222', N'我们', N'', N'1', 85, N'HSK 2.0', N'222', NULL, NULL, NULL, NULL, N'Verified HSK 2.0 (THEMATIC_HSK20_MAPPING)', N'', N'wǒmen'),
    (N'9A81A816-C75E-4A34-8FE9-390955F3A064', 3, N'遍', NULL, N'biàn', N'lần, lượt (từ đầu đến cuối)', NULL, N'量', NULL, N'[{"chinese": "这首中文歌我听了好多遍。", "pinyin": "Zhè shǒu zhōngwén gē wǒ tīng le hǎoduō biàn.", "translation": "Bài hát tiếng Trung này tôi đã nghe rất nhiều lần."}]', N'ARCHIVED', NULL, N'2026-11-10 06:58:48.290000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'biàn'),
    (N'DCF78EC1-CBD0-47D0-B041-3912F00DEA7C', 2, N'回去', NULL, N'huíqù', N'trở về, quay về', NULL, N'动', NULL, N'[{"zh": "时间不早了，我该坐车回去了。", "pinyin": "Shíjiān bù zǎo le, wǒ gāi zuò chē huíqu le.", "meaningVi": "Thời gian không còn sớm nữa, tôi phải đi xe về nhà thôi."}]', N'ARCHIVED', NULL, N'2026-11-10 06:02:08.493333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'huíqù'),
    (N'FA0F4F84-8E7D-45C4-AB0D-3924428273AB', 2, N'身体', N'身體', N'shēn tǐ', N'sức khỏe, thân thể', N'(human) body', N'Danh từ', NULL, N'[{"zh": "他每天都用身体。", "pinyin": "Tā měitiān dōu yòng shēntǐ.", "meaningVi": "Anh ấy mỗi ngày đều dùng sức khỏe, thân thể."}]', N'PUBLISHED', N'162494EB-C345-47A0-BF11-2BC4FA7A2726', N'2026-11-10 06:02:08.456666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'shēntǐ'),
    (N'F126A18A-3546-5A42-925E-394D364E98D3', 4, N'演唱', NULL, N'yǎnchàng', N'ca hát, biểu diễn ca khúc', NULL, N'动', NULL, N'[{"chinese": "在世界地球日环保公益晚会上，著名歌唱家深情演唱了那首赞美大自然母亲的经典环保歌曲。", "pinyin": "Zài Shìjiè Dìqiúrì huánbǎo gōngyì wǎnhuì shang, zhùmíng gēchàngjiā shēnqíng yǎnchàng le nà shǒu zànměi dàzìrán mǔqīn de jīngdiǎn huánbǎo gēqǔ.", "translation": "Trong đêm hội công ích bảo vệ môi trường Ngày Trái đất Thế giới, ca sĩ danh tiếng đã hát say sưa ca khúc kinh điển ca ngợi người mẹ thiên nhiên."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:18.626666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'yǎnchàng'),
    (N'C2A3DEFD-B8A5-4F0D-827F-39558A1DDC95', 2, N'进来', NULL, N'jìnlái', N'vào đây, bước vào', NULL, N'动', NULL, N'[{"zh": "门开着呢，快请进来坐吧。", "pinyin": "Mén kāi zhe ne, kuài qǐng jìnlái zuò ba.", "meaningVi": "Cửa đang mở đấy, mau mời vào ngồi đi."}]', N'ARCHIVED', NULL, N'2026-11-10 06:02:08.430000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'jìnlái'),
    (N'84F8ACDE-1B58-52F2-B61D-3971AF0CEA30', 4, N'同时', NULL, N'tóngshí', N'đồng thời, cùng lúc; hơn nữa', NULL, N'名、连', NULL, N'[{"chinese": "读书不仅能让我们获取知识，同时也是一种极好的心灵放松方式。", "pinyin": "Dúshū bùjǐn néng ràng wǒmen huòqǔ zhīshi, tóngshí yě shì yì zhǒng jí hǎo de xīnlíng fàngsōng fāngshì.", "translation": "Đọc sách không chỉ giúp chúng ta tiếp thu tri thức, mà đồng thời còn là một phương thức thư giãn tâm hồn tuyệt vời."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:17.150000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'tóngshí'),
    (N'7F4FB1A9-F8D5-4CCD-BDC6-3971BB2EA971', 3, N'山', NULL, N'shān', N'ngọn núi, dãy núi', NULL, N'名', NULL, N'[{"chinese": "远处连绵起伏的高山在青翠绿树的掩映下格外壮丽。", "pinyin": "Yuǎnchù liánmián qǐfú de gāoshān zài qīngcuì lǜshù de yǎnyìng xià géwài zhuànglì.", "translation": "Những rặng núi cao trùng điệp phía xa dưới bóng cây xanh ngắt hiện lên vô cùng hùng vĩ."}]', N'ARCHIVED', NULL, N'2026-11-10 06:58:49.353333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'shān'),
    (N'A9DF33BC-4433-4F68-B6F3-39739B76FC93', 3, N'风', NULL, N'fēng', N'gió', NULL, N'名', NULL, N'[{"chinese": "外面的风很大，多穿一件衣服吧。", "pinyin": "Wàimiàn de fēng hěn dà, duō chuān yí jiàn yīfu ba.", "translation": "Gió ngoài trời to lắm, hãy mặc thêm một chiếc áo nhé."}]', N'ARCHIVED', NULL, N'2026-11-10 06:58:48.673333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'fēng'),
    (N'668149A4-E519-598A-9DE8-3984B43C2DCA', 4, N'反对', N'反對', N'fǎn duì', N'phản đối', N'to fight against', N'动', NULL, N'[{"zh": "虽然方案遭到部分人的反对，但多数人认为改革势在必行。", "pinyin": "Suīrán fāng''àn zāodào bùfen rén de fǎnduì, dàn duōshù rén rènwéi gǎigé shìzàibìxíng.", "meaningVi": "Tuy phương án gặp phải sự phản đối của một số người, nhưng đa số cho rằng cải cách là điều tất yếu."}]', N'PUBLISHED', N'ED099B26-70B5-4C9F-A171-97FBB6A69E4C', N'2026-11-10 13:22:16.550000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'fǎnduì'),
    (N'259051A1-CDA1-4081-A13A-398C7EA45C0A', 3, N'小心', N'小心', N'xiǎo xīn', N'cẩn thận, cẩn trọng', N'to be careful', N'动、形', NULL, N'[{"zh": "地面很滑，下楼梯的时候一定要小心。", "pinyin": "Dìmiàn hěn huá, xià lóutī de shíhou yídìng yào xiǎoxīn.", "meaningVi": "Mặt sàn rất trơn, khi đi xuống cầu thang nhất định phải cẩn thận."}]', N'PUBLISHED', N'B417E51A-3AEB-4800-8E35-6B9327F24D8C', N'2026-11-10 06:58:49.060000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'xiǎoxīn'),
    (N'1AC082C2-9859-4271-9EDC-39A8740E86CC', 2, N'出门', NULL, N'chūmén', N'ra ngoài, rời khỏi nhà', NULL, N'动', NULL, N'[{"zh": "他每天早晨七点准时出门上班。", "pinyin": "Tā měitiān zǎochén qī diǎn zhǔnshí chūmén shàngbān.", "meaningVi": "Mỗi sáng anh ấy đúng bảy giờ đều ra khỏi nhà đi làm."}]', N'ARCHIVED', NULL, N'2026-11-10 06:02:08.490000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'chūmén'),
    (N'15B1A457-B66C-4649-B567-39AE3B453BEA', 3, N'附近', N'附近', N'fù jìn', N'lân cận, gần đây', N'(in the) vicinity', N'名', NULL, N'[{"zh": "学校附近有一家环境安静的书店。", "pinyin": "Xuéxiào fùjìn yǒu yì jiā huánjìng ānjìng de shūdiàn.", "meaningVi": "Gần trường học có một hiệu sách môi trường rất yên tĩnh."}]', N'PUBLISHED', N'AF110A35-04E1-4A4F-A064-B0964F562D76', N'2026-11-10 06:58:49.093333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'fùjìn'),
    (N'74102C39-FCFE-5309-B138-39BC13666851', 4, N'云', NULL, N'yún', N'mây, đám mây', NULL, N'名', NULL, N'[{"chinese": "蓝天飘着几朵白云，今天的天气非常适合出门郊游。", "pinyin": "Lántiān piāozhe jǐ duǒ báiyún, jīntiān de tiānqì fēicháng shìhé chūmén jiāoyóu.", "translation": "Bầu trời xanh lững lờ vài đám mây trắng, thời tiết hôm nay rất thích hợp ra ngoài dã ngoại."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:16.250000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'yún'),
    (N'1EA7CEE0-85EA-519D-BE36-39BF52E3505B', 4, N'姑娘', NULL, N'gūniang', N'cô gái, thiếu nữ', NULL, N'名', NULL, N'[{"chinese": "那位来自江南水乡的姑娘说话声音温柔而且十分有礼貌。", "pinyin": "Nà wèi láizì Jiāngnán shuǐxiāng de gūniang shuōhuà shēngyīn wēnróu érqiě shífēn yǒu lǐmào.", "translation": "Cô gái đến từ vùng sông nước Giang Nam đó nói chuyện giọng nhỏ nhẹ và vô cùng lịch sự."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:16.436666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'gūniang'),
