    (N'9BA9B11D-2270-5204-8D83-3C08F23A2FDF', 4, N'能否', NULL, N'néng fǒu', N'liệu có thể hay không', NULL, N'', NULL, N'[{"chinese": "这个科技项目能否顺利按期完成，关键在于技术团队的通力合作。", "pinyin": "Zhè gè kējì xiàngmù néng fǒu shùnlì ànqī wánchéng, guānjiàn zàiyú jìshù tuánduì de tōnglì hézuò.", "translation": "Dự án công nghệ này liệu có thể hoàn thành đúng hạn hay không, then chốt nằm ở sự hợp tác hết mình của đội ngũ kỹ thuật."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:16.860000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'néngfǒu'),
    (N'B2DB4DF0-64BD-5C81-A808-3C123B83002F', 4, N'例如', N'例如', N'lì rú', N'ví dụ, chẳng hạn như (liên từ ví dụ)', N'for example', N'动', NULL, N'[{"zh": "大自然给予了人类许多宝贵的启示，例如飞机机翼的设计就借鉴了鸟类飞行的空气动力学原理。", "pinyin": "Dàzìrán jǐyǔ le rénlèi xǔduō bǎoguì de qǐshì, lìrú fēijī jīyì de shèjì jiù jièjiàn le niǎolèi fēixíng de kōngqì dònglìxué yuánlǐ.", "meaningVi": "Mẹ thiên nhiên ban tặng cho con người vô số gợi mở quý giá, chẳng hạn như thiết kế cánh máy bay đã học hỏi nguyên lý khí động học khi bay của loài chim."}]', N'PUBLISHED', N'C27413F4-ADC8-436F-9436-1530C708008E', N'2026-11-10 13:22:18.550000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'lìrú'),
    (N'893F43EC-C735-5232-ACAA-3C2B0935FA23', 4, N'直接', N'直接', N'zhí jiē', N'trực tiếp, thẳng thắn', N'direct', N'形', NULL, N'[{"zh": "未来的脑机接口技术有望使脑部指令直接转化为计算机代码，实现人机思维的无缝互联。", "pinyin": "Wèilái de nǎo-jī jiēkǒu jìshù yǒuwàng shǐ nǎobù zhǐlìng zhíjiē zhuǎnhuà wéi jìsuànjī dàimǎ, shíxiàn rén-jī sīwéi de wúfèng hùlián.", "meaningVi": "Công nghệ giao diện não - máy tính trong tương lai có triển vọng giúp các mệnh lệnh của não bộ được chuyển hóa trực tiếp thành mã máy tính, hiện thực hóa sự kết nối tư duy liền mạch giữa người và máy."}]', N'PUBLISHED', N'575F094F-5298-41BE-B343-46849DDB0E1E', N'2026-11-10 13:22:18.980000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'zhíjiē'),
    (N'6FEB90D3-3861-4DA6-8F4B-3C38DB08D297', 3, N'叔叔', N'叔叔', N'shū shū', N'chú, chú em', N'father''s younger brother', N'名', NULL, N'[{"zh": "叔叔今天送给我一本非常有趣的课外书。", "pinyin": "Shūshu jīntiān sòng gěi wǒ yì běn fēicháng yǒuqù de kèwàishū.", "meaningVi": "Hôm nay chú tặng tôi một cuốn sách đọc thêm rất thú vị."}]', N'PUBLISHED', N'9283A715-761A-4561-89AB-CF23CA4DD9E6', N'2026-11-10 06:58:48.750000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'shūshū'),
    (N'B1DF891C-D7CF-4FFA-946F-3C76FFF0C108', 2, N'公斤', N'公斤', N'gōng jīn', N'ki-lô-gam (kg)', N'kilogram (kg)', N'量', NULL, N'[{"zh": "这袋大米正好有十公斤重。", "pinyin": "Zhè dài dàmǐ zhènghǎo yǒu shí gōngjīn zhòng.", "meaningVi": "Túi gạo này nặng đúng mười ki-lô-gam."}]', N'PUBLISHED', N'32FD54DF-03F5-490E-A36A-A4D89F79773D', N'2026-11-11 10:10:25.304391', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary inserted cleanly', N'', N'gōngjīn'),
    (N'88D1B817-A863-55A6-B921-3C770A5CEBB0', 4, N'条件', N'條件', N'tiáo jiàn', N'điều kiện, tiêu chuẩn, hoàn cảnh', N'condition', N'名', NULL, N'[{"zh": "这家文化艺术中心拥有先进的舞台音响设施，具备承办大型演出的优良条件。", "pinyin": "Zhè jiā wénhuà yìshù zhōngxīn yǒngyǒu xiānjìn de wǔtái yīnxiǎng shèshī, jùbèi chéngbàn dàxíng yǎnchū de yōuliáng tiáojiàn.", "meaningVi": "Trung tâm văn hóa nghệ thuật này sở hữu thiết bị âm thanh sân khấu tiên tiến, hội đủ điều kiện tuyệt vời để tổ chức các buổi biểu diễn quy mô lớn."}]', N'PUBLISHED', N'D551AD89-18F8-417A-BC0F-0FCBD23C1448', N'2026-11-10 13:22:17.836666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'tiáojiàn'),
    (N'0ED530D7-04C1-5DFF-83F1-3C9068E221DE', 4, N'扫码', NULL, N'sǎomǎ', N'quét mã (mã QR, mã vạch)', NULL, N'动', NULL, N'[{"chinese": "在中国各大城市的景区和餐厅，外国游客只需用手机扫码就能轻松完成在线支付。", "pinyin": "Zài Zhōngguó gè dà chéngshì de jǐngqū hé cāntīng, wàiguó yóukè zhǐ xū yòng shǒujī sǎomǎ jiù néng qīngsōng wánchéng zàixiàn zhīfù.", "translation": "Tại các khu danh thắng và nhà hàng ở các thành phố lớn Trung Quốc, du khách nước ngoài chỉ cần dùng điện thoại quét mã là có thể dễ dàng thanh toán trực tuyến."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:18.333333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'sǎomǎ'),
