    (N'E75E466B-2858-45EA-AC21-3CDB6F2B471D', 3, N'怎么办', NULL, N'zěnme bàn', N'làm sao bây giờ, phải làm sao', NULL, N'', NULL, N'[{"chinese": "如果迷路了，我们该怎么办？", "pinyin": "Rúguǒ mílù le, wǒmen gāi zěnme bàn?", "translation": "Nếu bị lạc đường thì chúng ta phải làm sao bây giờ?"}]', N'ARCHIVED', NULL, N'2026-11-10 06:58:48.766666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'zěnmebàn'),
    (N'92D3E6A3-8DF5-5029-B515-3CE95D7811A0', 4, N'指', N'指', N'zhǐ', N'chỉ, trỏ; ngón tay; ý chỉ', N'finger', N'动', NULL, N'[{"zh": "老师用手指着地图上的标志，详细给同学们讲解丝绸之路的路线。", "pinyin": "Lǎoshī yòng shǒuzhǐ zhǐzhe dìtú shàng de biāozhì, xiángxì gěi tóngxuémen jiǎngjiě Sīchóu zhī Lù de lùxiàn.", "meaningVi": "Thầy giáo dùng ngón tay chỉ vào các ký hiệu trên bản đồ, giải thích chi tiết cho học sinh lộ trình Con đường Tơ lụa."}]', N'PUBLISHED', N'575F094F-5298-41BE-B343-46849DDB0E1E', N'2026-11-10 13:22:17.206666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'zhǐ'),
