    (N'9DE58CFB-F685-4295-BD62-3D3CA5E87B67', 1, N'了', N'了', N'le', N'rồi (trợ từ ngữ khí/biến hóa)', N'(modal particle intensifying preceding clause)', N'Trợ từ', NULL, N'[{"zh": "他去北京了。", "pinyin": "Tā qù Běijīng le.", "meaningVi": "Anh ấy đi Bắc Kinh rồi."}]', N'PUBLISHED', N'778CF4E8-1BDD-4C63-8352-C9DB74CFAA70', N'2026-11-10 17:06:23.681461', N'2026-11-11 08:55:45.453263', N'108', N'了', N'', N'1', 82, N'HSK 2.0', N'108', NULL, NULL, NULL, NULL, N'Verified HSK 2.0 (DIALOGUE_AND_THEME_MATCH)', N'', N'le'),
    (N'C2E43CF0-626C-59AE-92BC-3D4222F51ACB', 4, N'提前', N'提前', N'tí qián', N'sớm hơn, trước thời hạn', N'to shift to an earlier date', N'动', NULL, N'[{"zh": "为了保证按时登机，请各位旅客至少提前两个小时到达机场。", "pinyin": "Wèile bǎozhèng ànshí dēngjī, qǐng gèwèi lǚkè zhìshǎo tíqián liǎng gè xiǎoshí dàodá jīchǎng.", "meaningVi": "Để đảm bảo lên máy bay đúng giờ, xin mời quý hành khách đến sân bay sớm ít nhất hai tiếng đồng hồ."}]', N'PUBLISHED', N'D551AD89-18F8-417A-BC0F-0FCBD23C1448', N'2026-11-10 13:22:16.946666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'tíqián');
