    (N'EE5A4980-938E-5557-B5E2-3D7A6DC883AF', 4, N'车位', NULL, N'chēwèi', N'chỗ đỗ xe, vị trí đỗ xe', NULL, N'名', NULL, N'[{"chinese": "借助城市智能停车大脑系统，车主可以通过车机导航提前精准预订目的地附近的空余停车位。", "pinyin": "Jièzhù chéngshì zhìnéng tíngchē dànǎo xìtǒng, chēzhǔ kěyǐ tōngguò chējī dǎoháng tíqián jīngzhǔn yùdìng mùdìdì fùjìn de kōngyú chēwèi.", "translation": "Nhờ vào hệ thống bộ não đỗ xe thông minh của thành phố, chủ xe có thể định vị dẫn đường qua màn hình ô tô để đặt trước chuẩn xác chỗ đỗ xe còn trống gần điểm đến."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:19.010000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'chēwèi'),
    (N'9851CB2C-C5E8-420A-9114-3DB40F497C51', 2, N'得', N'得', N'dé', N'được, đạt được', N'structural particle: used after a verb (or adjective as main verb)', N'动', NULL, N'[{"zh": "他在数学竞赛中得了一等奖。", "pinyin": "Tā zài shùxué jìngsài zhōng dé le yìděngjiǎng.", "meaningVi": "Cậu ấy đã đạt giải nhất trong kỳ thi học sinh giỏi toán."}]', N'PUBLISHED', N'993A640F-2A33-4E82-A7BE-0787339EF4DD', N'2026-11-10 06:02:08.470000', N'2026-11-11 17:41:23.320707', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'dé'),
    (N'2BCBB125-1BFB-560E-95F7-3DD7AD0C65F7', 4, N'钥匙', N'鑰匙', N'yào shi', N'chìa khóa', N'key', N'名', NULL, N'[{"zh": "出门上班前请务必确认好门禁卡和家门钥匙是否已经带齐。", "pinyin": "Chūmén shàngbān qián qǐng wùbì quèrèn hǎo ménjìnkǎ hé jiāmén yàoshi shìfǒu yǐjīng dài qí.", "meaningVi": "Trước khi ra khỏi nhà đi làm xin hãy kiểm tra chắc chắn thẻ từ và chìa khóa nhà đã mang đủ hay chưa."}]', N'PUBLISHED', N'C8DC9FD6-E848-464D-A0F0-80259D92C427', N'2026-11-10 13:22:15.830000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'yàoshi'),
    (N'4A2A94C1-5EF2-421B-9E78-3DE2A3701924', 3, N'秋', N'秋', N'qiū', N'mùa thu', N'a swing', N'tg / g', NULL, N'[{"zh": "为了学好汉语，我们需要了解秋。", "pinyin": "Wèile xuéhǎo Hànyǔ, wǒmen xūyào liǎojiě qiū.", "meaningVi": "Để học tốt tiếng Trung, chúng ta cần hiểu rõ a swing (秋)."}]', N'PUBLISHED', N'8740279E-4223-43BE-B424-9071F24126AE', N'2026-11-11 10:10:25.304391', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary inserted cleanly', N'', N'qiū'),
