    (N'25D71194-4D75-5581-999C-452495C5D1DF', 4, N'至少', N'至少', N'zhì shǎo', N'ít nhất, tối thiểu', N'at least', N'副', NULL, N'[{"zh": "根据城市绿色发展规划，新建居住小区的绿化覆盖率至少应当达到百分之三十五以上。", "pinyin": "Gēnjù chéngshì lǜsè fāzhǎn guīhuà, xīnjiàn jūzhù xiǎoqū de lǜhuà fùgàilǜ zhìshǎo yīngdāng dádào bǎifēnzhī sānshíwǔ yǐshàng.", "meaningVi": "Căn cứ vào quy hoạch phát triển xanh đô thị, tỷ lệ phủ xanh của các khu dân cư xây mới ít nhất phải đạt trên 35%."}]', N'PUBLISHED', N'575F094F-5298-41BE-B343-46849DDB0E1E', N'2026-11-10 13:22:18.650000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'zhìshǎo'),
    (N'535D4336-2DCE-51AD-A5D5-456C9E1EDE99', 4, N'教师', NULL, N'jiàoshī', N'giáo viên, nhà giáo', NULL, N'名', NULL, N'[{"chinese": "教师是人类灵魂的工程师，肩负着传播知识与文明的神圣使命。", "pinyin": "Jiàoshī shì rénlèi línghún de gōngchéngshī, jiānfùzhe chuánbō zhīshi yǔ wénmíng de shénshèng shǐmìng.", "translation": "Giáo viên là kỹ sư tâm hồn của nhân loại, mang trên vai sứ mệnh thiêng liêng truyền bá tri thức và văn minh."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:16.826666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'jiàoshī'),
