    (N'C87DA2AF-5657-5B62-B961-45E2F4B5F9FD', 4, N'基本', NULL, N'jīběn', N'cơ bản', NULL, N'形、副', NULL, N'[{"chinese": "通过前两个月的刻苦学习，他已经基本掌握了汉语日常交际口语。", "pinyin": "Tōngguò qián liǎng gè yuè de kèkǔ xuéxí, tā yǐjīng jīběn zhǎngwò le hànyǔ rìcháng jiāojì kǒuyǔ.", "translation": "Qua hai tháng đầu khổ học, anh ấy đã cơ bản nắm được khẩu ngữ giao tiếp hàng ngày bằng tiếng Hán."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:16.920000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'jīběn'),
    (N'BD07F6A1-D8E4-4089-8E82-45E4D873BB6D', 3, N'聊', NULL, N'liáo', N'trò chuyện, tán gẫu', NULL, N'动', NULL, N'[{"chinese": "我们坐下来喝杯热茶，好好聊一聊最近的经历。", "pinyin": "Wǒmen zuò xiàlai hē bēi rèchá, hǎohǎo liáo yì liáo zuìjìn de jīnglì.", "translation": "Chúng ta ngồi xuống uống tách trà nóng, trò chuyện kỹ về những trải nghiệm dạo này nhé."}]', N'ARCHIVED', NULL, N'2026-11-10 06:58:49.140000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'liáo'),
    (N'896D5107-3437-5883-8B01-46238BCC3FCC', 4, N'节假日', NULL, N'jiéjiàrì', N'ngày lễ tết, ngày nghỉ công cộng', NULL, N'名', NULL, N'[{"chinese": "每逢法定节假日，各大景区都会迎来客流高峰。", "pinyin": "Měiféng fǎdìng jiéjiàrì, gè dà jǐngqū dōu huì yínglái kèliú gāofēng.", "translation": "Mỗi dịp ngày lễ tết quy định của pháp luật, các khu danh lam thắng cảnh lớn đều đón lượng du khách đỉnh điểm."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:15.676666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'jiéjiàrì'),
