    (N'51740BB8-A1A4-4EEF-B2D7-50B906387C04', 3, N'放', N'放', N'fàng', N'đặt, để, bỏ vào', N'to release', N'动', NULL, N'[{"zh": "请把书放在桌子上。", "pinyin": "Qǐng bǎ shū fàng zài zhuōzi shang.", "meaningVi": "Xin hãy để sách lên trên bàn."}]', N'PUBLISHED', N'AF110A35-04E1-4A4F-A064-B0964F562D76', N'2026-11-10 06:58:48.200000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'fàng'),
    (N'01AEB3B3-18DC-51CE-A63D-50CC46717456', 4, N'逛', N'逛', N'guàng', N'đi dạo, tản bộ ngắm cảnh', N'to stroll', N'动', NULL, N'[{"zh": "周末闲暇时，很多市民喜欢携家带口去市中心的步行商业街逛逛。", "pinyin": "Zhōumò xiánxiá shí, hěn duō shìmín xǐhuan xié jiā dài kǒu qù shìzhōngxīn de bùxíng shāngyèjiē guàngguang.", "meaningVi": "Lúc rảnh rỗi cuối tuần, nhiều người dân thành phố thích cùng gia đình đi dạo mua sắm ở phố đi bộ trung tâm."}]', N'PUBLISHED', N'95268DAC-D50C-442A-8436-85C845D1C72F', N'2026-11-10 13:22:15.830000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'guàng'),
    (N'4E025C53-7D70-5ED1-96CE-50D11547E7B7', 4, N'做梦', NULL, N'zuòmèng', N'nằm mơ, mơ mộng', NULL, N'动', NULL, N'[{"chinese": "昨晚孩子做梦梦见自己变成了一位宇航员，驾驶着宇宙飞船去探索神秘的外太空。", "pinyin": "Zuówǎn háizi zuòmèng mèngjiàn zìjǐ biànchéng le yí wèi yǔhángyuán, jiàshǐ zhe yǔzhòu fēichuán qù tànsuǒ shénmì de wài tàikōng.", "translation": "Đêm qua đứa trẻ nằm mơ thấy mình biến thành một phi hành gia, lái tàu vũ trụ đi khám phá không gian bên ngoài kỳ bí."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:18.120000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'zuòmèng'),
    (N'B37E322E-8053-4016-918D-50DB77AEBF0C', 4, N'整齐', N'整齊', N'zhěng qí', N'ngăn nắp, gọn gàng', N'orderly', N'a / ad', NULL, N'[{"zh": "他每天早上都会把房间收拾得整整齐齐。", "pinyin": "Tā měitiān zǎoshang dōu huì bǎ fángjiān shōushi de zhěngzhěng qíqí.", "meaningVi": "Mỗi sáng anh ấy đều thu dọn phòng ốc gọn gàng ngăn nắp."}]', N'PUBLISHED', N'575F094F-5298-41BE-B343-46849DDB0E1E', N'2026-11-11 10:10:25.304391', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary inserted cleanly', N'', N'zhěngqí'),
    (N'F02329A6-DF59-4A6A-A0B3-50FF170E563D', 2, N'出来', NULL, N'chūlái', N'đi ra, xuất hiện', NULL, N'动', NULL, N'[{"zh": "天晴了，天边的彩虹出来了。", "pinyin": "Tiān qíng le, tiānbiān de cǎihóng chūlái le.", "meaningVi": "Trời tạnh ráo rồi, cầu vồng nơi chân trời đã xuất hiện."}]', N'ARCHIVED', NULL, N'2026-11-10 06:02:08.463333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'chūlái'),
