    (N'85751E37-B237-423F-8308-519D06275517', 3, N'语言', NULL, N'yǔyán', N'ngôn ngữ, tiếng nói', NULL, N'名', NULL, N'[{"chinese": "语言是世界各国人民之间增进沟通与理解的重要桥梁。", "pinyin": "Yǔyán shì shìjiè gèguó rénmín zhījiān zēngjìn gōutōng yǔ lǐjiě de zhòngyào qiáoliáng.", "translation": "Ngôn ngữ là nhịp cầu quan trọng thúc đẩy giao lưu và thấu hiểu giữa nhân dân các nước trên thế giới."}]', N'ARCHIVED', NULL, N'2026-11-10 06:58:49.393333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'yǔyán'),
    (N'E3E32E99-F8A0-5D77-82C1-51E5310AB44A', 4, N'美好', NULL, N'měihǎo', N'tươi đẹp, tốt đẹp', NULL, N'形', NULL, N'[{"chinese": "青年人应当珍惜大学美好时光，刻苦学习，为实现崇高理想打下坚实基础。", "pinyin": "Qīngniánrén yīngdāng zhēnxī dàxué měihǎo shíguāng, kèkǔ xuéxí, wèi shíxiàn chónggāo lǐxiǎng dǎxià jiānshí jīchǔ.", "translation": "Người trẻ tuổi cần trân trọng thời gian đại học tươi đẹp, khổ công học tập để đặt nền móng vững chắc cho lý tưởng."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:16.070000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'měihǎo'),
    (N'ECF324FB-2146-59F4-8DAD-522C185CDDD1', 4, N'吸引', N'吸引', N'xī yǐn', N'thu hút, lôi cuốn, hấp dẫn', N'to attract (interest', N'动', NULL, N'[{"zh": "国家湿地公园优美的自然风光和清新的空气，每年都吸引着数以百万计的游客前来休闲度假。", "pinyin": "Guójiā shīdì gōngyuán yōuměi de zìrán fēngguāng hé qīngxīn de kōngqì, měinián dōu xīyǐn zhe shù yǐ bǎiwàn jì de yóukè qiánlái xiūxián dùjià.", "meaningVi": "Phong cảnh thiên nhiên tươi đẹp và bầu không khí trong lành của công viên đất ngập nước quốc gia hàng năm đều thu hút hàng triệu du khách đến nghỉ dưỡng thư giãn."}]', N'PUBLISHED', N'90A35972-4CD6-46CB-8FC0-FF111D8DFB71', N'2026-11-10 13:22:18.570000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'xīyǐn'),
    (N'E882E1D5-B2A1-5B1F-9315-5236A93DB7FC', 4, N'省', N'省', N'shěng', N'tỉnh thành; tiết kiệm', N'to save', N'名', NULL, N'[{"zh": "作为中国东部经济大省，江苏省在新材料与高端制造领域实力雄厚。", "pinyin": "Zuòwéi Zhōngguó dōngbù jīngjì dà shěng, Jiāngsū Shěng zài xīn cáiliào yǔ gāoduān zhìzào lǐngyù shílì xiónghòu.", "meaningVi": "Là tỉnh kinh tế lớn miền đông Trung Quốc, tỉnh Giang Tô có thực lực hùng hậu trong lĩnh vực sản xuất cao cấp."}]', N'PUBLISHED', N'1C92848C-099F-4B61-A466-F6381B0E9519', N'2026-11-10 13:22:16.200000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'shěng'),
    (N'07E6B72B-518D-5FE3-94BE-52718240A43E', 4, N'道歉', N'道歉', N'dào qiàn', N'xin lỗi, tạ lỗi', N'to apologize', N'动', NULL, N'[{"zh": "意识到自己的粗心失误给同事造成了困扰后，他立即诚恳地向对方当面道歉。", "pinyin": "Yìshí dào zìjǐ de cūxīn shīwù gěi tóngshì zàochéng le kùnrǎo hòu, tā lìjí chéngkěn de xiàng duìfāng dāngmiàn dàoqiàn.", "meaningVi": "Nhận ra sơ suất bất cẩn của mình gây phiền toái cho đồng nghiệp, anh lập tức chân thành xin lỗi trực tiếp."}]', N'PUBLISHED', N'E7F82F5D-5ED2-440B-8369-FE116EE51ABC', N'2026-11-10 13:22:16.230000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'dàoqiàn'),
    (N'BE007282-EA0D-4E78-BFFB-528B02222258', 3, N'可是', NULL, N'kěshì', N'nhưng mà, thế nhưng', NULL, N'连', NULL, N'[{"chinese": "我很想去参加聚会，可是今天太忙了。", "pinyin": "Wǒ hěn xiǎng qù cānjiā jùhuì, kěshì jīntiān tài máng le.", "translation": "Tôi rất muốn đi tham gia buổi liên hoan, nhưng mà hôm nay bận quá."}]', N'ARCHIVED', NULL, N'2026-11-10 06:58:48.313333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'kěshì'),
    (N'FA35DC84-421E-5E19-B860-529956692021', 4, N'零食', NULL, N'língshí', N'đồ ăn vặt, thức ăn vặt', NULL, N'名', NULL, N'[{"chinese": "看电影时，很多年轻人喜欢一边吃着薯片零食一边享受剧情。", "pinyin": "Kàn diànyǐng shí, hěn duō niánqīngrén xǐhuan yìbiān chīzhe shǔpiàn língshí yìbiān xiǎngshòu jùqíng.", "translation": "Khi xem phim, nhiều bạn trẻ thích vừa ăn đồ ăn vặt như khoai tây chiên vừa thưởng thức cốt truyện."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:16.733333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'língshí'),
