    (N'E4B3EACA-9875-50AA-AE39-5C22E4D5C672', 4, N'会员', NULL, N'huìyuán', N'hội viên, thành viên', NULL, N'名', NULL, N'[{"chinese": "成为这家国际青年旅行社的终身会员，可以在全球数百个国家享受预订折扣与专属向导服务。", "pinyin": "Chéngwéi zhè jiā guójì qīngnián lǚxíngshè de zhōngshēn huìyuán, kěyǐ zài quánqiú shù bǎi gè guójiā xiǎngshòu yùdìng zhékòu yǔ zhuānshǔ xiàngdǎo fúwù.", "translation": "Trở thành hội viên trọn đời của hãng lữ hành thanh niên quốc tế này có thể được hưởng giảm giá đặt chỗ và dịch vụ hướng dẫn viên riêng tại hàng trăm quốc gia trên toàn cầu."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:18.686666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'huìyuán'),
    (N'2F2C0EAD-F683-4A15-920D-5C52DB6E05BF', 4, N'墙', N'墻', N'qiáng', N'bức tường', N'wall', N'Danh từ', NULL, N'[{"zh": "教室的墙上挂着一张世界地图。", "pinyin": "Jiàoshì de qiáng shàng guà zhe yì zhāng shìjiè dìtú.", "meaningVi": "Trên tường phòng học treo một tấm bản đồ thế giới."}]', N'PUBLISHED', N'17F5C0E2-6A2D-45BC-99EA-637AA85D6508', N'2026-11-11 10:10:25.304391', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary inserted cleanly', N'', N'qiáng'),
    (N'7337218B-121C-4A1D-94D0-5C63FB8FD3B4', 3, N'游客', NULL, N'yóukè', N'khách du lịch, du khách', NULL, N'名', NULL, N'[{"chinese": "每到旅游黄金周，故宫博物院都会迎来成千上万的中外游客。", "pinyin": "Měi dào lǚyóu huángjīnzhōu, Gùgōng Bówùyuàn dōu huì yínglái chéngqiānshàngwàn de zhōngwài yóukè.", "translation": "Cứ mỗi dịp tuần lễ vàng du lịch, Viện bảo tàng Cố Cung đều đón chào hàng vạn du khách trong và ngoài nước."}]', N'ARCHIVED', NULL, N'2026-11-10 06:58:49.273333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'yóukè'),
    (N'4E9195DA-E15C-4856-8524-5C655B838477', 3, N'别人', N'別人', N'bié rén', N'người khác', N'other people', N'代', NULL, N'[{"zh": "学会倾听别人的意见，往往能够让自己更快地成长。", "pinyin": "Xuéhuì qīngtīng biérén de yìjiàn, wǎngwǎng nénggòu ràng zìjǐ gèng kuài de chéngzhǎng.", "meaningVi": "Học cách lắng nghe ý kiến của người khác thường giúp bản thân trưởng thành nhanh chóng hơn."}]', N'PUBLISHED', N'B8B44E04-3823-441C-B43C-88E473DEDCE4', N'2026-11-10 06:58:49.236666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'biérén'),
    (N'DAF836A2-6CCF-574D-8B81-5C7C67D297EB', 4, N'只好', N'只好', N'zhǐ hǎo', N'đành phải, buộc phải', N'without any better option', N'副', NULL, N'[{"zh": "由于海上突刮大风导致渡轮停航，游客们只好在风景秀丽的海岛上多停留了一天。", "pinyin": "Yóuyú hǎishang tū guā dàfēng dǎozhì dùlún tíngháng, yóukèmen zhǐhǎo zài fēngjǐng xiùlì de hǎidǎo shang duō tíngliú le yì tiān.", "meaningVi": "Do trên biển bất ngờ nổi gió lớn khiến phà ngừng chạy, du khách đành phải nán lại hòn đảo phong cảnh tươi đẹp thêm một ngày."}]', N'PUBLISHED', N'575F094F-5298-41BE-B343-46849DDB0E1E', N'2026-11-10 13:22:18.716666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'zhǐhǎo'),
    (N'2D701895-2FA7-56CD-BB5A-5CF217C6F83A', 4, N'安排', N'安排', N'ān pái', N'sắp xếp, bố trí', N'to arrange', N'动', NULL, N'[{"zh": "组委会已经为远道而来的各位专家学者妥善安排好了食宿和交通。", "pinyin": "Zǔwěihuì yǐjīng wèi yuǎndào ér lái de gèwèi zhuānjiā xuézhě tuǒshàn ānpái hǎo le shísù hé jiāotōng.", "meaningVi": "Ban tổ chức đã sắp xếp chu đáo nơi ăn chốn ở và phương tiện đi lại cho các chuyên gia học giả từ phương xa đến."}]', N'PUBLISHED', N'1E19300E-0BA0-4EA1-9D52-2247C8892171', N'2026-11-10 13:22:17.796666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'ānpái'),
