    (N'16E3ED8A-E854-4C4D-9010-5D5598178A57', 2, N'贵', N'貴', N'guì', N'đắt, quý, quý giá', N'expensive', N'Tính từ', NULL, N'[{"zh": "这件衣服太贵了。", "pinyin": "Zhè jiàn yīfu tài guì le.", "meaningVi": "Bộ quần áo này đắt quá."}]', N'PUBLISHED', N'32FD54DF-03F5-490E-A36A-A4D89F79773D', N'2026-11-11 10:10:25.304391', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary inserted cleanly', N'', N'guì'),
    (N'FCD8A881-4084-4FE1-B9E8-5D56C43D0DB6', 4, N'只要', N'只要', N'zhǐ yào', N'chỉ cần', N'if only', N'连', NULL, N'[{"zh": "只要你努力学习，就一定能通过考试。", "pinyin": "Zhǐyào nǐ nǔlì xuéxí, jiù yídìng néng tōngguò kǎoshì.", "meaningVi": "Chỉ cần bạn nỗ lực học tập thì nhất định có thể vượt qua kỳ thi."}]', N'PUBLISHED', N'575F094F-5298-41BE-B343-46849DDB0E1E', N'2026-11-11 10:10:25.304391', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary inserted cleanly', N'', N'zhǐyào'),
    (N'81930979-B261-5596-ABD4-5D76ED83841B', 4, N'整个', NULL, N'zhěnggè', N'toàn bộ, toàn thể, cả (thế giới, căn phòng)', NULL, N'形', NULL, N'[{"chinese": "科技的日新月异不仅改变了个人的生活方式，更深刻重塑了整个国际社会的经济产业形态。", "pinyin": "Kējì de rìxīn-yuèyì bùjǐn gǎibiàn le gèrén de shēnghuó fāngshì, gèng shēnkè chóngsù le zhěng gè guójì shèhuì de jīngjì chǎnyè xíngtài.", "translation": "Khoa học công nghệ đổi mới từng ngày không những thay đổi phương thức sống của mỗi cá nhân, mà còn tái định hình sâu sắc hình thái ngành nghề kinh tế của toàn bộ xã hội quốc tế."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:18.950000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'zhěnggè'),
    (N'0F03A994-7CA4-4C02-B19C-5DBC911B1C66', 3, N'帮助', NULL, N'bāngzhù', N'giúp đỡ, sự trợ giúp', NULL, N'动', NULL, N'[{"chinese": "在老师的耐心帮助下，我的成绩有了很大提高。", "pinyin": "Zài lǎoshī de nàixīn bāngzhù xià, wǒ de chéngjì yǒu le hěn dà tígāo.", "translation": "Dưới sự giúp đỡ kiên nhẫn của thầy cô giáo, thành tích của tôi đã tiến bộ rất nhiều."}]', N'ARCHIVED', NULL, N'2026-11-10 06:58:48.403333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'bāngzhù'),
    (N'AEA52E5B-8130-5017-8912-5DDC6792DCA6', 4, N'咳', NULL, N'ké', N'ho, tiếng ho khẽ', NULL, N'动', NULL, N'[{"chinese": "感冒初起时喉咙干痒难耐，忍不住轻轻咳了几声。", "pinyin": "Gǎnmào chūqǐ shí hóulóng gānyǎng nánnài, rěnbuzhù qīngqīng ké le jǐ shēng.", "translation": "Lúc mới bắt đầu cảm cúm họng ngứa ngáy khó chịu, không kìm được khẽ ho mấy tiếng."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:15.873333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'ké'),
    (N'F0009FB9-C080-56D7-8621-5DF56830FC89', 4, N'降低', N'降低', N'jiàng dī', N'hạ thấp, làm giảm, giảm bớt', N'to reduce', N'动', NULL, N'[{"zh": "通过在工厂车间安装先进的消音过滤装置，有效降低了工业生产对周边居民造成的噪音影响。", "pinyin": "Tōngguò zài gōngchǎng chējiān ānzhuāng xiānjìn de xiāoyīn guòlǜ zhuāngzhì, yǒuxiào jiàngdī le gōngyè shēngchǎn duì zhōubiān jūmín zàochéng de zàoyīn yǐngxiǎng.", "meaningVi": "Bằng cách lắp đặt thiết bị tiêu âm lọc tiếng ồn tiên tiến trong phân xưởng nhà máy, đã giảm thiểu hiệu quả tiếng ồn do sản xuất công nghiệp gây ra cho cư dân xung quanh."}]', N'PUBLISHED', N'CB223D54-B351-4EBC-9A47-018CA23AE6CE', N'2026-11-10 13:22:18.080000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'jiàngdī'),
    (N'3171FCF2-D43B-4CE8-A9FF-5E0E82450E10', 2, N'楼', NULL, N'lóu', N'tòa nhà, tầng, lầu', NULL, N'名', NULL, N'[{"zh": "我家住在六楼，没有电梯。", "pinyin": "Wǒ jiā zhù zài liù lóu, méiyǒu diàntī.", "meaningVi": "Nhà tôi ở tầng sáu, không có thang máy."}]', N'ARCHIVED', NULL, N'2026-11-10 06:02:08.423333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'lóu'),
    (N'67417251-C904-5B89-93B8-5E1C6693CF92', 4, N'失败', N'失敗', N'shī bài', N'thất bại, không thành công', N'to be defeated', N'动、形', NULL, N'[{"zh": "虽然初期培育耐旱植物品种的试验遭遇了数次失败，但科研人员毫不气馁，最终成功攻克了技术难关。", "pinyin": "Suīrán chūqī péiyù nàihàn zhíwù pǐnzhǒng de shìyàn zāoyù le shù cì shībài, dàn kēyán rényuán háo bù qìněi, zhōngyú chénggōng gōngkè le jìshù nánguān.", "meaningVi": "Tuy thử nghiệm nhân giống thực vật chịu hạn thời kỳ đầu đã gặp thất bại vài lần, nhưng các nhà nghiên cứu không hề nản lòng, cuối cùng đã vượt qua ải kỹ thuật thành công."}]', N'PUBLISHED', N'1C92848C-099F-4B61-A466-F6381B0E9519', N'2026-11-10 13:22:18.580000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'shībài'),
    (N'525AE4A7-4438-4335-8458-5E4871554BA0', 3, N'需要', N'需要', N'xū yào', N'cần, nhu cầu', N'to need', N'动、名', NULL, N'[{"zh": "如果你需要帮助，请随时告诉我。", "pinyin": "Rúguǒ nǐ xūyào bāngzhù, qǐng suíshí gàosu wǒ.", "meaningVi": "Nếu bạn cần giúp đỡ, xin hãy báo cho tôi bất cứ lúc nào."}]', N'PUBLISHED', N'B417E51A-3AEB-4800-8E35-6B9327F24D8C', N'2026-11-10 06:58:48.290000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'xūyào'),
