    (N'13028EC7-0CDF-5AD0-BFDA-6029EDFA45DB', 4, N'公路', NULL, N'gōnglù', N'đường bộ, đường cái, xa lộ', NULL, N'名', NULL, N'[{"chinese": "科学家正在试验能够实现无线光伏发电和自动融雪的未来绿色超级智慧公路。", "pinyin": "Kēxuéjiā zhèngzài shìyàn nénggòu shíxiàn wúxiàn guāngfú fādiàn hé zìdòng róngxuě de wèilái lǜsè chāojí zhìhuì gōnglù.", "translation": "Các nhà khoa học đang thử nghiệm tuyến siêu xa lộ thông minh xanh tương lai có thể phát điện quang điện không dây và tự động làm tan tuyết."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:18.880000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'gōnglù'),
    (N'B22A3B2C-3FDB-53A3-916B-6033581B5C89', 4, N'大大', NULL, N'dàdà', N'rất nhiều, đáng kể', NULL, N'副', NULL, N'[{"chinese": "新算法的采用大大提升了超级计算机处理海量数据的速度。", "pinyin": "Xīn suànfǎ de cǎiyòng dàdà tíshēng le chāojí jìsuànjī chǔlǐ hǎiliàng shùjù de sùdù.", "translation": "Việc áp dụng thuật toán mới đã nâng cao đáng kể tốc độ xử lý dữ liệu khổng lồ của siêu máy tính."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:16.800000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'dàdà'),
    (N'E86AA38C-28E6-5392-A5FF-603DC4C99F3B', 4, N'之后', NULL, N'zhīhòu', N'sau khi, sau đó', NULL, N'名', NULL, N'[{"chinese": "在成功研发出这款新型节能芯片之后，公司迅速启动了大规模量产计划。", "pinyin": "Zài chénggōng yánfā chū zhè kuǎn xīnxíng jiénéng xīnpiàn zhīhòu, gōngsī xùnsù qǐdòng le dà guīmó liàngchǎn jìhuà.", "translation": "Sau khi nghiên cứu và phát triển thành công con chip tiết kiệm năng lượng kiểu mới này, công ty đã nhanh chóng khởi động kế hoạch sản xuất hàng loạt quy mô lớn."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:18.410000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'zhīhòu'),
    (N'011B08BC-D448-50EE-B215-603EE0C1EA60', 4, N'小吃', NULL, N'xiǎochī', N'đồ ăn vặt, món ăn nhẹ, món ngon truyền thống', NULL, N'名', NULL, N'[{"chinese": "虽然未来快节奏生活带来了预制营养餐，但承载着地方文化印记的传统街头小吃依然无可替代。", "pinyin": "Suīrán wèilái kuài jiézòu shēnghuó dàilái le yùzhì yíngyǎng cān, dàn chéngzài zhe dìfāng wénhuà yìnjì de chuántǒng jiētóu xiǎochī yīrán wúkě-tìdài.", "translation": "Tuy nhịp sống hối hả tương lai mang đến các bữa ăn dinh dưỡng chế biến sẵn, nhưng những món ăn vặt đường phố truyền thống mang đậm dấu ấn văn hóa địa phương vẫn là thứ không thể thay thế."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:18.920000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'xiǎochī'),
