    (N'9C1650CF-56A0-4836-BD46-605040B0C47A', 1, N'米饭', N'米飯', N'mǐ fàn', N'cơm trắng', N'(cooked) rice', N'Danh từ', NULL, N'[{"zh": "我想吃米饭。", "pinyin": "Wǒ xiǎng chī mǐfàn.", "meaningVi": "Tôi muốn ăn cơm."}]', N'PUBLISHED', N'9C981888-67BD-41BB-B5B0-57D0A1268DD6', N'2026-11-10 17:06:23.681467', N'2026-11-11 08:55:45.462801', N'125', N'米饭', N'', N'1', 83, N'HSK 2.0', N'125', NULL, NULL, NULL, NULL, N'Verified HSK 2.0 (THEMATIC_HSK20_MAPPING)', N'', N'mǐfàn'),
    (N'AD902283-22D8-5460-85F7-606A5150C3A8', 4, N'美景', NULL, N'měijǐng', N'cảnh đẹp, mỹ cảnh', NULL, N'名', NULL, N'[{"chinese": "登上海拔千米的泰山之巅极目远眺，壮丽磅礴的云海美景令人震撼不已。", "pinyin": "Dēng shàng hǎibá qiān mǐ de Tàishān zhī diān jímù yuǎntiào, zhuànglì pángbó de yánhǎi měijǐng lìng rén zhènhàn bùyǐ.", "translation": "Leo lên đỉnh Thái Sơn cao nghìn mét phóng tầm mắt, cảnh đẹp biển mây hùng vĩ khiến lòng người chấn động."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:16.210000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'měijǐng'),
    (N'0B1C5E72-4D83-595F-925F-6082E1E37A0E', 4, N'作为', NULL, N'zuòwéi', N'với tư cách là, đóng vai trò là', NULL, N'动、介', NULL, N'[{"chinese": "作为一名人民教师，他始终把教书育人放在工作的首位。", "pinyin": "Zuòwéi yì míng rénmín jiàoshī, tā shǐzhōng bǎ jiāoshū yùrén fàng zài gōngzuò de shǒuwèi.", "translation": "Với tư cách là một nhà giáo nhân dân, thầy luôn đặt việc dạy chữ rèn người lên vị trí hàng đầu."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:16.760000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'zuòwéi'),
