    (N'C4F6E9A4-D4D8-49C8-8A2B-616FA9724747', 2, N'笑', N'咲', N'xiào', N'cười', N'laugh', N'Động từ / Danh động từ', NULL, N'[{"zh": "他每天都用笑。", "pinyin": "Tā měitiān dōu yòng xiào.", "meaningVi": "Anh ấy mỗi ngày đều dùng cười."}]', N'PUBLISHED', N'2AF32B19-E92E-4019-B5C5-2453918CC44E', N'2026-11-10 06:02:08.290000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'xiào');
