    (N'B5CACBC2-455E-57BA-9089-6723F3675788', 4, N'剩', N'剩', N'shèng', N'thừa, còn lại', N'to remain', N'动', NULL, N'[{"zh": "全社会都在积极倡导节约粮食的理念，外出就餐时点菜要适量，吃剩的饭菜应当主动打包带走。", "pinyin": "Quán shèhuì dōu zài jījí chàngdǎo jiéyuē liángshi de lǐniàn, wàichū jiùcān shí diǎn cài yào shìliàng, chī shèng de fàncài yīngdāng zhǔdòng dǎbāo dài zǒu.", "meaningVi": "Toàn xã hội đều đang tích cực tuyên truyền quan niệm tiết kiệm lương thực, khi đi ăn ngoài gọi món vừa phải, đồ ăn thức uống còn thừa nên chủ động đóng gói mang về."}]', N'PUBLISHED', N'1C92848C-099F-4B61-A466-F6381B0E9519', N'2026-11-10 13:22:18.560000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'shèng'),
    (N'BA1DE72D-003E-5263-AFA9-675073DBDB24', 4, N'复印', N'複印', N'fù yìn', N'photo, sao chụp tài liệu', N'to photocopy', N'动', NULL, N'[{"zh": "开展环保法律法规普法进社区活动时，宣传志愿者提前复印了数百份图文并茂的宣传小册子。", "pinyin": "Kāizhǎn huánbǎo fǎlǜ fǎguī pǔfǎ jìn shèqū huódòng shí, xuānchuán zhìyuànzhě tíqián fùyìn le shù bǎi fèn túwén-bìngmào de xuānchuán xiǎocèzi.", "meaningVi": "Khi triển khai hoạt động phổ biến pháp luật bảo vệ môi trường vào cộng đồng, các tình nguyện viên tuyên truyền đã photo sẵn hàng trăm cuốn cẩm nang hình ảnh sinh động."}]', N'PUBLISHED', N'4D554AD3-4530-48D4-846E-25F026EEFF5D', N'2026-11-10 13:22:18.576666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'fùyìn'),
    (N'FEE267F7-D912-5889-A254-67567BE82C42', 4, N'仔细', N'仔細', N'zǐ xì', N'kỹ lưỡng, tỉ mỉ', N'careful', N'形', NULL, N'[{"zh": "签合同前一定要仔细阅读每一个条款，以免日后产生纠纷。", "pinyin": "Qiān hétong qián yídìng yào zǐxì yuèdú měi yí gè tiáokuǎn, yǐmiǎn rìhòu chǎnshēng jiūfēn.", "meaningVi": "Trước khi ký hợp đồng nhất định phải đọc kỹ từng điều khoản, tránh phát sinh tranh chấp về sau."}]', N'PUBLISHED', N'3815613C-581A-4EA8-92A8-F907E35F8BD4', N'2026-11-10 13:22:16.756666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'zǐxì'),
    (N'F3952C78-A47E-4520-9BF7-675DEC40F73D', 4, N'聊天', N'聊天', N'liáo tiān', N'nói chuyện, tán gẫu', N'to chat', N'Động từ / Danh động từ', NULL, N'[{"zh": "晚饭后，我们一家人喜欢坐在一起聊天。", "pinyin": "Wǎnfàn hòu, wǒmen yì jiā rén xǐhuan zuò zài yìqǐ liáotiān.", "meaningVi": "Sau bữa tối, cả gia đình tôi thích ngồi cùng nhau trò chuyện."}]', N'PUBLISHED', N'C27413F4-ADC8-436F-9436-1530C708008E', N'2026-11-11 10:10:25.304391', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary inserted cleanly', N'', N'liáotiān');
  INSERT INTO [vocabularies] ([Id], [HskLevel], [Hanzi], [Traditional], [Pinyin], [MeaningVi], [MeaningEn], [PartOfSpeech], [AudioUrl], [ExamplesJson], [Status], [LessonId], [CreatedAt], [UpdatedAt], [SourceId], [Entry], [Homograph], [LevelLabel], [SourcePdfPage], [SourceDataset], [SourceEntryId], [SuggestedMeaningVi], [UpdatedByUserId], [ReviewedByUserId], [ReviewedAt], [ReviewNotes], [NormalizedHomograph], [NormalizedPinyin]) VALUES
    (N'8384F49D-D8BD-54D3-B7A0-67600857DD0D', 4, N'各个', NULL, N'gègè', N'từng, mỗi', NULL, N'代、副', NULL, N'[{"chinese": "来自各个学院的学生代表都准时参加了今天的大会。", "pinyin": "Láizì gègè xuéyuàn de xuéshēng dàibiǎo dōu zhǔnshí cānjiā le jīntiān de dàhuì.", "translation": "Đại diện sinh viên đến từ từng học viện đều đã tham gia đại hội hôm nay đúng giờ."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:16.280000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'gègè'),
    (N'C0FA76B4-2350-4842-915B-67790A92BF37', 1, N'上午', N'上午', N'shàng wǔ', N'buổi sáng', N'morning', N'Danh từ', NULL, N'[{"zh": "我上午去学校。", "pinyin": "Wǒ shàngwǔ qù xuéxiào.", "meaningVi": "Buổi sáng tôi đến trường."}]', N'PUBLISHED', N'775BEE30-1000-4623-AC03-50DEC5A6BD58', N'2026-11-10 17:06:23.681989', N'2026-11-11 08:55:45.479656', N'178', N'上午', N'', N'1', 84, N'HSK 2.0', N'178', NULL, NULL, NULL, NULL, N'Verified HSK 2.0 (THEMATIC_HSK20_MAPPING)', N'', N'shàngwǔ'),
    (N'76C406E9-AD7B-58AB-B3C1-67B7A1F248A6', 4, N'研究', NULL, N'yánjiū', N'nghiên cứu, tìm hiểu kỹ lưỡng', NULL, N'动', NULL, N'[{"chinese": "科学家们通过多年深入系统的科学研究，终于找到了治理这种土壤污染的新方法。", "pinyin": "Kēxuéjiāmen tōngguò duō nián shēnrù xìtǒng de kēxué yánjiū, zhōngyú zhǎodào le zhìlǐ zhè zhǒng tǔrǎng wūrǎn de xīn fāngfǎ.", "translation": "Các nhà khoa học thông qua nhiều năm nghiên cứu khoa học chuyên sâu và có hệ thống cuối cùng đã tìm ra phương pháp mới để xử lý loại ô nhiễm đất này."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:18.040000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'yánjiū'),
    (N'759A879B-636E-582C-AA42-67C7BD8D589E', 4, N'凉', NULL, N'liáng', N'mát mẻ, mát mẻ dễ chịu; nguội (liáng)', NULL, N'形', NULL, N'[{"chinese": "秋天的高原清晨天气微凉，登山前最好随身备上一件保暖防风外套。", "pinyin": "Qiūtiān de gāoyuán qīngchén tiānqì wēiliáng, dēngshān qián zuì hǎo suíshēn bèi shang yí jiàn bǎonuǎn fángfēng wàitào.", "translation": "Buổi sớm mùa thu trên cao nguyên trời se se mát lạnh, trước khi leo núi tốt nhất nên chuẩn bị sẵn một chiếc áo khoác chắn gió giữ ấm bên mình."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:18.700000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'liáng'),
    (N'3285410C-5759-5E37-9C99-6806F1296CE4', 4, N'京剧', N'京劇', N'jīng jù', N'Kinh kịch (nghệ thuật sân khấu truyền thống Bắc Kinh)', N'Beijing opera', N'名', NULL, N'[{"zh": "为了让孩子们感受中华优秀传统文化的魅力，学校特别组织大家去大剧院观看京剧表演。", "pinyin": "Wèile ràng háizimen gǎnshòu Zhōnghuá yōuxiù chuántǒng wénhuà de mèilì, xuéxiào tèbié zǔzhī dàjiā qù dà jùyuàn guānkàn jīngjù biǎoyǎn.", "meaningVi": "Để các em nhỏ cảm nhận được sức hút của văn hóa truyền thống ưu tú Trung Hoa, nhà trường đã đặc biệt tổ chức cho mọi người đến đại nhà hát xem biểu diễn Kinh kịch."}]', N'PUBLISHED', N'CB223D54-B351-4EBC-9A47-018CA23AE6CE', N'2026-11-10 13:22:18.106666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'jīngjù'),
    (N'B71F529D-F8AA-443E-8CED-6824F69762E3', 2, N'一起', N'一起', N'yì qǐ', N'cùng nhau', N'in the same place', N's / d', NULL, N'[{"zh": "他每天都用一起。", "pinyin": "Tā měitiān dōu yòng yìqǐ.", "meaningVi": "Anh ấy mỗi ngày đều dùng cùng nhau."}]', N'PUBLISHED', N'7FB11B06-A247-43A7-8A74-1A73A796D060', N'2026-11-10 06:02:08.130000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'yìqǐ'),
    (N'A1278F92-A2AF-470A-9460-683CAA2B231D', 1, N'她', N'她', N'tā', N'cô ấy, bà ấy, chị ấy', N'she', N'Đại từ', NULL, N'[{"zh": "她是我的好朋友。", "pinyin": "Tā shì wǒ de hǎo péngyou.", "meaningVi": "Cô ấy là bạn thân của tôi."}]', N'PUBLISHED', N'ACE8837E-E67D-4CF7-9EC3-625A16EC3B8F', N'2026-11-10 17:06:23.681996', N'2026-11-11 08:55:45.495259', N'202', N'她', N'', N'1', 85, N'HSK 2.0', N'202', NULL, NULL, NULL, NULL, N'Verified HSK 2.0 (BALANCED_HSK20_CURRICULUM_FIT)', N'', N'tā'),
    (N'B5E4F8FC-AA0C-55E5-B3A4-689819BEA5F0', 4, N'鼓励', N'鼓勵', N'gǔ lì', N'khuyến khích, khích lệ, động viên', N'to encourage', N'动', NULL, N'[{"zh": "父母应当积极鼓励年轻人勇敢背包走向广阔的世界，在独立探索中锻炼独立自强的优秀品格。", "pinyin": "Fùmǔ yīngdāng jījí gǔlì niánqīngrén yǒnggǎn bēibāo zǒuxiàng guǎngkuò de shìjiè, zài dúlì tànsuǒ zhōng duànliàn dúlì-zìqiáng de yōuxiù pǐngé.", "meaningVi": "Cha mẹ nên tích cực khuyến khích người trẻ dũng cảm khoác ba lô bước ra thế giới rộng lớn, để rèn luyện phẩm chất ưu tú độc lập tự cường qua những chuyến khám phá tự thân."}]', N'PUBLISHED', N'4D554AD3-4530-48D4-846E-25F026EEFF5D', N'2026-11-10 13:22:18.850000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'gǔlì'),
    (N'7C45A511-7360-4053-A408-689B0E8C067F', 2, N'公共汽车', N'公共汽車', N'gōng gòng qì chē', N'xe buýt', N'bus', N'Từ vựng', NULL, N'[{"zh": "他每天都用公共汽车。", "pinyin": "Tā měitiān dōu yòng gōng.", "meaningVi": "Anh ấy mỗi ngày đều dùng bus (公共汽车)."}]', N'PUBLISHED', N'32FD54DF-03F5-490E-A36A-A4D89F79773D', N'2026-11-11 10:10:25.304391', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary inserted cleanly', N'', N'gōnggòngqìchē'),
    (N'FCD84F58-F99C-5B46-9731-69123173F1C0', 4, N'开玩笑', N'開玩笑', N'kāi wán xiào', N'nói đùa, đùa giỡn', N'to play a joke', N'Động từ', NULL, N'[{"zh": "朋友之间适当开个善意的幽默玩笑，能够有效活跃聚会的气氛。", "pinyin": "Péngyou zhījiān shìdàng kāi gè shànyì de yōumò wánxiào, nénggòu yǒuxiào huóyuè jùhuì de qìfēn.", "meaningVi": "Bạn bè giữa nhau nói đùa một câu hóm hỉnh thiện chí có thể khuấy động không khí buổi gặp mặt."}]', N'PUBLISHED', N'D0A7BB74-A49C-4D2A-B5FB-C34AF6410CF9', N'2026-11-10 13:22:16.160000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'kāiwánxiào'),
    (N'ED817948-B600-5DC8-9A30-69438E589953', 4, N'互相', N'互相', N'hù xiāng', N'lẫn nhau, cùng nhau', N'each other', N'副', NULL, N'[{"zh": "同事实习期间应当互相支持帮助，共同提升团队协作能力。", "pinyin": "Tóngshì shíxí qījiān yīngdāng hùxiāng zhīchí bāngzhù, gòngtóng tíshēng tuánduì xiézuò nénglì.", "meaningVi": "Đồng nghiệp trong thời gian thực tập nên giúp đỡ hỗ trợ lẫn nhau để cùng nâng cao năng lực phối hợp đội ngũ."}]', N'PUBLISHED', N'DC410BC5-6799-4156-BEF8-3A2CCBE4A1A6', N'2026-11-10 13:22:16.406666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'hùxiāng'),
