    (N'187F8DDA-8D63-5E17-903E-6C76D80F42CD', 4, N'女性', NULL, N'nǚxìng', N'phụ nữ, phái nữ', NULL, N'名', NULL, N'[{"chinese": "在现代多元社会中，越来越多的杰出女性在科学与商业领域崭露头角。", "pinyin": "Zài xiàndài duōyuán shèhuì zhōng, yuèláiyuè duō de jiéchū nǚxìng zài kēxué yǔ shāngyè lǐngyù zhǎnlùtóujiǎo.", "translation": "Trong xã hội đa nguyên hiện đại, ngày càng nhiều phụ nữ kiệt xuất khẳng định tài năng trong lĩnh vực khoa học và kinh doanh."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:15.883333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'nǚxìng'),
    (N'79EAD21C-8C3E-5FB3-82A8-6C91D826CFA0', 4, N'食品', N'食品', N'shí pǐn', N'thực phẩm, đồ ăn thức uống', N'foodstuff', N'名', NULL, N'[{"zh": "未来的现代生物农业技术将为全球人口提供更加安全、纯净且营养全面均衡的优质绿色健康食品。", "pinyin": "Wèilái de xiàndài shēngwù nóngyè jìshù jiāng wèi quánqiú rénkǒu tígōng gèngjiā ānquán, chúnjìng qiě yíngyǎng quánmiàn jūnhéng de yōuzhì lǜsè jiànkāng shípǐn.", "meaningVi": "Công nghệ nông nghiệp sinh học hiện đại trong tương lai sẽ cung cấp cho dân số toàn cầu những nguồn thực phẩm xanh sạch an toàn, thuần khiết và dinh dưỡng toàn diện cân bằng hơn."}]', N'PUBLISHED', N'1C92848C-099F-4B61-A466-F6381B0E9519', N'2026-11-10 13:22:19.030000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'shípǐn'),
    (N'95BB5B31-7033-5215-A1DF-6CC79AFFBE43', 4, N'之中', NULL, N'zhīzhōng', N'trong số, ở giữa, trong lúc', NULL, N'名', NULL, N'[{"chinese": "在日常生活点滴之中，父母的言行举止潜移默化地影响着孩子的品格养成。", "pinyin": "Zài rìcháng shēnghuó diǎndī zhīzhōng, fùmǔ de yánxíng-jǔzhǐ qiǎnyí-mòhuà de yǐngxiǎng zhe háizi de pǐngé yǎngchéng.", "translation": "Trong từng chi tiết nhỏ của cuộc sống thường ngày, lời nói hành động của cha mẹ âm thầm tác động đến việc hình thành phẩm chất của con cái."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:18.103333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'zhīzhōng'),
    (N'FA05B911-FB1E-4086-8F08-6CDB8D70FEDF', 3, N'难听', NULL, N'nántīng', N'khó nghe, không êm tai', NULL, N'形', NULL, N'[{"chinese": "刺耳的噪音听起来实在让人感到难听和心烦。", "pinyin": "Cì''ěr de zàoyīn tīng qǐlai shízài ràng rén gǎndào nántīng hé xīnfán.", "translation": "Tiếng ồn chói tai nghe thật sự khiến người ta cảm thấy khó nghe và khó chịu trong lòng."}]', N'ARCHIVED', NULL, N'2026-11-10 06:58:49.303333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'nántīng'),
