    (N'700737A5-A7A9-599E-913E-6D14D0A7AF8C', 4, N'上门', NULL, N'shàngmén', N'đến tận nhà, phục vụ tại nhà', NULL, N'动', NULL, N'[{"chinese": "这家家电品牌为所有购买客户提供免费上门安装与调试服务。", "pinyin": "Zhè jiā jiādiàn pǐnpái wèi suǒyǒu gòumǎi kèhù tígōng miǎnfèi shàngmén ānzhuāng yǔ tiáoshì fúwù.", "translation": "Thương hiệu đồ điện gia dụng này cung cấp dịch vụ lắp đặt và chỉnh máy miễn phí tận nhà cho khách mua."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:15.840000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'shàngmén'),
    (N'D5C7CDA1-75AD-5CDD-A982-6D3C85B02F98', 4, N'来不及', N'來不及', N'lái bù jí', N'không kịp (thời gian)', N'there''s not enough time (to do sth)', N'动', NULL, N'[{"zh": "今天早晨闹钟坏了，我起床晚了，连早饭都来不及吃就急匆匆赶去公司。", "pinyin": "Jīntiān zǎochen nàozhōng huài le, wǒ qǐchuáng wǎn le, lián zǎofàn dōu láibují chī jiù jícōngcōng gǎn qù gōngsī.", "meaningVi": "Sáng nay đồng hồ báo thức bị hỏng, tôi dậy muộn, ngay cả bữa sáng cũng không kịp ăn đã vội vã chạy đến công ty."}]', N'PUBLISHED', N'D0A7BB74-A49C-4D2A-B5FB-C34AF6410CF9', N'2026-11-10 13:22:18.016666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'láibùjí'),
