    (N'423F6DF3-771D-5D3B-9EC5-6EBE55EF6D74', 4, N'改变', N'改變', N'gǎi biàn', N'thay đổi, biến đổi', N'to change', N'动', NULL, N'[{"zh": "科学知识不仅能够丰富个人的精神世界，更能从根本上改变一个人的命运。", "pinyin": "Kēxué zhīshi bùjǐn nénggòu fēngfù gèrén de jīngshén shìjiè, gèng néng cóng gēnběn shang gǎibiàn yí gè rén de mìngyùn.", "meaningVi": "Tri thức khoa học không chỉ làm phong phú thế giới tinh thần cá nhân mà còn có thể thay đổi số phận con người từ gốc rễ."}]', N'PUBLISHED', N'4D554AD3-4530-48D4-846E-25F026EEFF5D', N'2026-11-10 13:22:15.906666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'gǎibiàn'),
    (N'1492101C-5985-5D8D-B075-6EC24EFED936', 4, N'入', NULL, N'rù', N'vào, bước vào', NULL, N'动', NULL, N'[{"chinese": "经过漫长的等待，全体乘客终于按顺序依次检票入场登机。", "pinyin": "Jīngguò màncháng de děngdài, quántǐ chéngkè zhōngyú àn shùnxù yīcì jiǎnpiào rùchǎng dēngjī.", "translation": "Trải qua thời gian dài chờ đợi, toàn thể hành khách cuối cùng cũng lần lượt soát vé vào trong để lên máy bay."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:16.896666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'rù'),
    (N'F1A4829B-3D40-4CC2-877B-6EC6E666AEE1', 2, N'周', NULL, N'zhōu', N'tuần, một tuần', NULL, N'名、（量）', NULL, N'[{"zh": "下周一我们要举行运动会。", "pinyin": "Xià zhōuyī wǒmen yào jǔxíng yùndònghuì.", "meaningVi": "Thứ hai tuần sau chúng tôi sẽ tổ chức đại hội thể thao."}]', N'ARCHIVED', NULL, N'2026-11-10 06:02:08.386666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'zhōu'),
    (N'A317AA20-313F-5199-9DCC-6EF8636C1864', 4, N'其次', N'其次', N'qí cì', N'thứ hai, tiếp theo', N'next', N'代', NULL, N'[{"zh": "选择职业首先要考虑个人兴趣，其次要看长远发展前景。", "pinyin": "Xuǎnzé zhíyè shǒuxiān yào kǎolǜ gèrén xìngqù, qícì yào kàn chángyuǎn fāzhǎn qiánjǐng.", "meaningVi": "Chọn nghề trước tiên phải cân nhắc sở thích cá nhân, tiếp theo mới xem xét triển vọng phát triển lâu dài."}]', N'PUBLISHED', N'362CB9D4-5F0C-4C98-A09B-BC3EBFCDBAA3', N'2026-11-10 13:22:16.416666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'qícì'),
    (N'8DA551F9-AADD-534C-815D-6EFCA74DCF0B', 4, N'降价', NULL, N'jiàngjià', N'giảm giá, hạ giá', NULL, N'动', NULL, N'[{"chinese": "为了迎接传统戏曲文化节，各大剧场纷纷对学生票和团体票实行大幅降价优惠。", "pinyin": "Wèile yíngjiē chuántǒng xìqǔ wénhuàjié, gè dà jùchǎng fēnfēn duì xuéshēngpiào hé tuántǐpiào shíxíng dàfú jiàngjià yōuhuì.", "translation": "Để chào mừng lễ hội văn hóa hí khúc truyền thống, các đại kịch viện đua nhau thực hiện ưu đãi giảm giá mạnh cho vé sinh viên và vé đoàn thể."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:17.910000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'jiàngjià'),
    (N'F2D5FBCC-D341-5586-8B0C-6F05CB171DC7', 4, N'也许', N'也許', N'yě xǔ', N'có lẽ, có thể', N'perhaps', N'副', NULL, N'[{"zh": "也许我们在人生的下个转角处，就会邂逅意想不到的美丽风景。", "pinyin": "Yěxǔ wǒmen zài rénshēng de xià gè zhuǎnjiǎochù, jiù huì xièhòu yìxiǎngbùdào de měilì fēngjǐng.", "meaningVi": "Có lẽ ở khúc quanh tiếp theo của cuộc đời, chúng ta sẽ bắt gặp phong cảnh tươi đẹp ngoài sức tưởng tượng."}]', N'PUBLISHED', N'C8DC9FD6-E848-464D-A0F0-80259D92C427', N'2026-11-10 13:22:15.843333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'yěxǔ'),
    (N'52EB1044-1FBD-54D5-8689-6F16EF2666EC', 4, N'网购', NULL, N'wǎnggòu', N'mua sắm qua mạng, mua hàng online', NULL, N'动', NULL, N'[{"chinese": "未来无人机低空物流配送的成熟，将使全国大部分地区的网购商品在下单后半小时内极速送达。", "pinyin": "Wèilái wúrénjī dīkōng wùliú pèisòng de chéngshú, jiāng shǐ quánguó dà bùfen dìqū de wǎnggòu shāngpǐn zài xiàdān hòu bàn xiǎoshí nèi jísù sòngdá.", "translation": "Sự chín muồi của dịch vụ giao hàng bằng máy bay không người lái tầm thấp trong tương lai sẽ giúp hàng hóa mua sắm qua mạng ở đại đa số các vùng trên cả nước được giao thần tốc trong nửa giờ sau khi đặt đơn."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:18.993333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'wǎnggòu'),
    (N'1D88747B-3B15-5A9E-B9D9-6F24CFF331FD', 4, N'毕业生', NULL, N'bìyèshēng', N'sinh viên tốt nghiệp', NULL, N'名', NULL, N'[{"chinese": "母校热烈祝贺全体应届毕业生顺利完成学业，勇敢踏上崭新人生征途。", "pinyin": "Mǔxiào rèliè zhùhè quántǐ yīngjiè bìyèshēng shùnlì wánchéng xuéyè, yǒnggǎn tà shàng zhǎnxīn rénshēng zhēngtú.", "translation": "Trường mẹ nồng nhiệt chúc mừng toàn thể sinh viên tốt nghiệp thuận lợi hoàn thành khóa học, dũng cảm bước vào hành trình mới."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:16.186666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'bìyèshēng'),
    (N'D5645F3B-BFFD-4878-B4A1-6F58860E6FFA', 3, N'然后', N'然後', N'rán hòu', N'sau đó, rồi thì', N'after', N'连', NULL, N'[{"zh": "我们先吃晚饭，然后再去散步吧。", "pinyin": "Wǒmen xiān chī wǎnfàn, ránhòu zài qù sànbù ba.", "meaningVi": "Chúng ta ăn cơm tối trước, sau đó hãy đi dạo bộ nhé."}]', N'PUBLISHED', N'8740279E-4223-43BE-B424-9071F24126AE', N'2026-11-10 06:58:48.270000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'ránhòu'),
    (N'7B9FDAE3-4B66-5079-985E-6F6AF9B194FD', 4, N'于是', N'於是', N'yú shì', N'thế là, do đó', N'thereupon', N'连', NULL, N'[{"zh": "天空中突然飘起了密集的雪花，大家于是加快了回家的步伐。", "pinyin": "Tiānkōng zhōng tūrán piāo qǐ le mìjí de xuěhuā, dàjiā yúshì jiākuài le huí jiā de bùfá.", "meaningVi": "Bầu trời bất ngờ đổ những bông tuyết dày đặc, thế là mọi người rảo bước nhanh hơn về nhà."}]', N'PUBLISHED', N'1C6EDD2A-ED7C-40CB-9435-0BBAEA6C573A', N'2026-11-10 13:22:16.110000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'yúshì'),
    (N'807E64CE-1BE3-40ED-A3A7-6F8FE48CBE84', 3, N'分', N'分', N'fēn', N'phút, điểm, phân chia', N'to divide', N'Lượng từ / Danh từ', NULL, N'[{"zh": "现在三点五分。", "pinyin": "Xiànzài sān diǎn wǔ fēn.", "meaningVi": "Bây giờ là ba giờ năm phút."}]', N'PUBLISHED', N'AF110A35-04E1-4A4F-A064-B0964F562D76', N'2026-11-11 10:10:25.304391', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary inserted cleanly', N'', N'fēn'),
    (N'D8098966-79E2-5BAF-BD74-6FCDC80317A8', 4, N'餐厅', NULL, N'cāntīng', N'nhà hàng, phòng ăn', NULL, N'名', NULL, N'[{"chinese": "这家位于市中心运河畔的主题文化餐厅不仅环境雅致，菜品也极具江南水乡特色。", "pinyin": "Zhè jiā wèiyú shìzhōngxīn yùnhépàn de zhǔtí wénhuà cāntīng bùjǐn huánjìng yǎzhì, càipǐn yě jí jù jiāngnán shuǐxiāng tèsè.", "translation": "Nhà hàng văn hóa bên bờ kênh trung tâm thành phố này không chỉ không gian trang nhã mà món ăn còn mang đậm phong vị sông nước Giang Nam."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:15.966666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'cāntīng'),
    (N'31685DBA-6806-5C6E-A502-6FEBBB14598E', 4, N'奖学金', NULL, N'jiǎngxuéjīn', N'học bổng', NULL, N'名', NULL, N'[{"chinese": "凭借优异的学习成绩，她获得了本学期的一等奖学金。", "pinyin": "Píngjiè yōuyì de xuéxí chéngjì, tā huòdé le běn xuéqī de yīděng jiǎngxuéjīn.", "translation": "Nhờ thành tích học tập xuất sắc, cô ấy đã giành được học bổng hạng nhất trong học kỳ này."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:15.610000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'jiǎngxuéjīn'),
