    (N'ACCFF832-F532-5021-AA38-7A2BD620D84B', 4, N'森林', N'森林', N'sēn lín', N'rừng, rừng rậm', N'forest', N'名', NULL, N'[{"zh": "这片原始森林覆盖面积广阔，生长着许多国家珍稀保护植物。", "pinyin": "Zhè piàn yuánshǐ sēnlín fùgài miànjī guǎngkuò, shēngzhǎngzhe xǔduō guójiā zhēnxī bǎohù zhíwù.", "meaningVi": "Cánh rừng nguyên sinh này có diện tích che phủ rộng lớn, là nơi sinh trưởng của nhiều loài thực vật quý hiếm cấp quốc gia."}]', N'PUBLISHED', N'1C92848C-099F-4B61-A466-F6381B0E9519', N'2026-11-10 13:22:16.470000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'sēnlín'),
    (N'64CC6A25-F7CD-4157-8041-7A474498AD7F', 1, N'电影', N'電影', N'diàn yǐng', N'phim điện ảnh', N'movie', N'Danh từ', NULL, N'[{"zh": "星期天我们去看电影。", "pinyin": "Xīngqītiān wǒmen qù kàn diànyǐng.", "meaningVi": "Chủ nhật chúng tôi đi xem phim."}]', N'PUBLISHED', N'BC8E2F7F-91CD-4014-8BC4-BF4AEE182E41', N'2026-11-10 17:06:23.681433', N'2026-11-11 08:55:45.414814', N'38', N'电影', N'', N'1', 80, N'HSK 2.0', N'38', NULL, NULL, NULL, NULL, N'Verified HSK 2.0 (THEMATIC_HSK20_MAPPING)', N'', N'diànyǐng'),
    (N'FC769284-F79E-46D1-ACA6-7ABACA69B64C', 1, N'朋友', N'朋友', N'péng yǒu', N'bạn bè, bạn', N'friend', N'Danh từ', NULL, N'[{"zh": "他是我的好朋友。", "pinyin": "Tā shì wǒ de hǎo péngyou.", "meaningVi": "Cậu ấy là bạn tốt của tôi."}]', N'PUBLISHED', N'EA11A07D-2642-4D98-B3FD-588CC8CB7BFE', N'2026-11-10 17:06:23.681981', N'2026-11-11 08:55:45.472696', N'156', N'朋友', N'', N'1', 83, N'HSK 2.0', N'156', NULL, NULL, NULL, NULL, N'Verified HSK 2.0 (DIALOGUE_TEXT_MATCH)', N'', N'péngyǒu'),
    (N'96FDAEDA-CFED-52CC-9A99-7AD65B76849F', 4, N'一切', N'一切', N'yī qiè', N'tất cả, mọi thứ', N'everything', N'代', NULL, N'[{"zh": "为了孩子健康成长，父母愿意付出一切努力。", "pinyin": "Wèile háizi jiànkāng chéngzhǎng, fùmǔ yuànyì fùchū yíqiè nǔlì.", "meaningVi": "Vì sự trưởng thành khỏe mạnh của con cái, cha mẹ sẵn sàng bỏ ra mọi nỗ lực."}]', N'PUBLISHED', N'C8DC9FD6-E848-464D-A0F0-80259D92C427', N'2026-11-10 13:22:15.560000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'yīqiè'),
    (N'22F82D98-A3A7-4920-96C4-7B1E4E524594', 1, N'菜', N'菜', N'cài', N'món ăn, rau', N'dish (type of food)', N'Danh từ', NULL, N'[{"zh": "妈妈做的菜很好吃。", "pinyin": "Māma zuò de cài hěn hǎochī.", "meaningVi": "Món ăn mẹ nấu rất ngon."}]', N'PUBLISHED', N'9C981888-67BD-41BB-B5B0-57D0A1268DD6', N'2026-11-10 17:06:23.681424', N'2026-11-11 08:55:45.409805', N'16', N'菜', N'', N'1', 80, N'HSK 2.0', N'16', NULL, NULL, NULL, NULL, N'Verified HSK 2.0 (THEMATIC_HSK20_MAPPING)', N'', N'cài'),
    (N'787FDE8F-42E8-50E0-9B69-7B4AA8785AFD', 4, N'有趣', N'有趣', N'yǒu qù', N'thú vị, hay ho', N'interesting', N'形', NULL, N'[{"zh": "李老师用生动风趣的语言为大家讲述了一段非常有趣的中国历史典故。", "pinyin": "Lǐ lǎoshī yòng shēngdòng fēngqù de yǔyán wèi dàjiā jiǎngshù le yí duàn fēicháng yǒuqù de Zhōngguó lìshǐ diǎngù.", "meaningVi": "Thầy Lý dùng ngôn ngữ sinh động dí dỏm kể cho mọi người nghe một điển tích lịch sử Trung Quốc hết sức thú vị."}]', N'PUBLISHED', N'1C6EDD2A-ED7C-40CB-9435-0BBAEA6C573A', N'2026-11-10 13:22:15.913333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'yǒuqù'),
    (N'9550430A-BA97-5D93-8DA6-7B94FA17EFF6', 4, N'预习', N'預習', N'yù xí', N'chuẩn bị bài trước, soạn bài trước', N'to prepare a lesson', N'动', NULL, N'[{"zh": "明天我们要前往自然历史博物馆开展生态研学活动，请同学们今晚提前认真预习相关生物演化资料。", "pinyin": "Míngtiān wǒmen yào qiánwǎng zìrán lìshǐ bówùguǎn kāizhǎn shēngtài yánxué huódòng, qǐng tóngxuémen jīnwǎn tíqián rènzhēn yùxí xiāngguān shēngwù yǎnhuà zīliào.", "meaningVi": "Ngày mai chúng ta sẽ đến bảo tàng lịch sử tự nhiên để triển khai hoạt động học tập ngoại khóa sinh thái, tối nay các em nhớ chuẩn bị bài trước cẩn thận các tài liệu về tiến hóa sinh vật liên quan."}]', N'PUBLISHED', N'1C6EDD2A-ED7C-40CB-9435-0BBAEA6C573A', N'2026-11-10 13:22:18.673333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'yùxí'),
    (N'FBA1FEEF-5297-4522-91BB-7BA2A515E744', 1, N'我', N'我', N'wǒ', N'tôi, mình, tao', N'I', N'Đại từ', NULL, N'[{"zh": "我是越南人。", "pinyin": "Wǒ shì yuènán rén.", "meaningVi": "Tôi là người Việt Nam."}]', N'PUBLISHED', N'AAAAAAAA-1111-1111-1111-111111111111', N'2026-11-10 17:06:23.682003', N'2026-11-11 08:55:45.498259', N'221', N'我', N'', N'1', 85, N'HSK 2.0', N'221', NULL, NULL, NULL, NULL, N'Verified HSK 2.0 (EXPLICIT_L1_L3_ANCHOR)', N'', N'wǒ'),
    (N'A3510C38-B144-5F47-9D19-7BCBAE02C61E', 4, N'巧', NULL, N'qiǎo', N'khéo léo, tình cờ, đúng lúc, vừa vặn', NULL, N'形', NULL, N'[{"chinese": "今天真是太巧了，我刚走到书店门口就碰到了多年未见的小学同桌。", "pinyin": "Jīntiān zhēn shì tài qiǎo le, wǒ gāng zǒu dào shūdiàn ménkǒu jiù pèng dào le duō nián wèi jiàn de xiǎoxué tóngzhuō.", "translation": "Hôm nay thật là quá tình cờ khéo léo, tôi vừa bước đến cửa hiệu sách thì đã gặp lại người bạn cùng bàn tiểu học bao năm chưa gặp."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:17.983333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'qiǎo'),
    (N'AF0E138C-C6C6-57FF-834D-7BCECBC420D5', 4, N'树林', NULL, N'shùlín', N'rừng cây, lùm cây, khu rừng', NULL, N'名', NULL, N'[{"chinese": "未来的城市规划将建筑群巧妙地隐藏在郁郁葱葱的天然树林与人工绿海之中，实现城林相融。", "pinyin": "Wèilái de chéngshì guīhuà jiāng jiànzhùqún qiǎomiào de yǐncáng zài yùyù-cōngcōng de tiānrán shùlín yǔ réngōng lǜhǎi zhīzhōng, shíxiàn chéng-lín xiāngróng.", "translation": "Quy hoạch đô thị tương lai khéo léo giấu các cụm tòa nhà giữa những rừng cây tự nhiên xanh tươi bạt ngàn và biển xanh nhân tạo, thực hiện sự giao hòa giữa thành phố và rừng xanh."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:18.956666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'shùlín'),
    (N'94B40D28-51F5-5D5B-AEA7-7BFC8DBEF8FF', 4, N'老虎', N'老虎', N'lǎo hǔ', N'con hổ, cọp', N'tiger', N'名', NULL, N'[{"zh": "在自然保护区里，几只威风凛凛的野生东北老虎正在雪地中漫步。", "pinyin": "Zài zìrán bǎohùqū lǐ, jǐ zhī wēifēng-lǐnlǐn de yěshēng Dōngběi lǎohǔ zhèngzài xuědì zhōng mànbù.", "meaningVi": "Trong khu bảo tồn thiên nhiên, vài con hổ Siberia hoang dã oai phong lẫm liệt đang dạo bước trên nền tuyết trắng."}]', N'PUBLISHED', N'D0A7BB74-A49C-4D2A-B5FB-C34AF6410CF9', N'2026-11-10 13:22:17.570000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'lǎohǔ'),
    (N'8B063AC2-7326-5D97-8D63-7C3614AC2F31', 4, N'输', N'輸', N'shū', N'thua, thất bại', N'to lose', N'动', NULL, N'[{"zh": "虽然在这次辩论赛中遗憾输掉了比赛，但我们学到了很多知识。", "pinyin": "Suīrán zài zhè cì biànlùnsài zhōng yíhàn shūdiào le bǐsài, dàn wǒmen xuédào le hěn duō zhīshi.", "meaningVi": "Dù tiếc nuối để thua trận trong cuộc thi tranh biện lần này, nhưng chúng tôi đã học được rất nhiều kiến thức."}]', N'PUBLISHED', N'226C0C08-EE32-4846-B8F3-FED582E3F873', N'2026-11-10 13:22:16.506666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'shū'),
    (N'B6E016A7-2DD0-417A-8148-7C3691374E56', 1, N'高兴', N'高興', N'gāo xìng', N'vui vẻ, phấn khởi', N'happy', N'Tính từ', NULL, N'[{"zh": "今天认识你很高兴。", "pinyin": "Jīntiān rènshi nǐ hěn gāoxìng.", "meaningVi": "Hôm nay quen biết bạn tôi rất vui."}]', N'PUBLISHED', N'778CF4E8-1BDD-4C63-8352-C9DB74CFAA70', N'2026-11-10 17:06:23.681439', N'2026-11-11 08:55:45.435258', N'57', N'高兴', N'', N'1', 81, N'HSK 2.0', N'57', NULL, NULL, NULL, NULL, N'Verified HSK 2.0 (THEMATIC_HSK20_MAPPING)', N'', N'gāoxìng'),
    (N'596FC4F4-034D-5874-B083-7C9E1AD393EA', 4, N'肯定', N'肯定', N'kěn dìng', N'chắc chắn, khẳng định', N'to be sure', N'动、形、副', NULL, N'[{"zh": "付出辛勤汗水并坚持不懈的人，未来肯定能够在属于自己的舞台上大放异彩。", "pinyin": "Fùchū xīnqín hànshuǐ bìng jiānchíbúxiè de rén, wèilái kěndìng nénggòu zài shǔyú zìjǐ de wǔtái shang dà fàng yìcǎi.", "meaningVi": "Người bỏ ra mồ hôi công sức kiên trì không ngừng, tương lai chắc chắn có thể tỏa sáng trên sân khấu thuộc về mình."}]', N'PUBLISHED', N'D0A7BB74-A49C-4D2A-B5FB-C34AF6410CF9', N'2026-11-10 13:22:16.073333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'kěndìng'),
