    (N'0BCCA278-B82D-5B40-BF6D-7E244CEBC4A1', 4, N'列', NULL, N'liè', N'liệt kê; dãy, hàng; đoàn (tàu)', NULL, N'动、量', NULL, N'[{"chinese": "老师在黑板上列出了本节课需要重点掌握的五个语法知识点。", "pinyin": "Lǎoshī zài hēibǎn shàng lièchū le běn jié kè xūyào zhòngdiǎn zhǎngwò de wǔ gè yǔfǎ zhīshidiǎn.", "translation": "Thầy giáo đã liệt kê lên bảng năm điểm ngữ pháp trọng tâm cần nắm vững trong tiết học này."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:17.116666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'liè'),
    (N'E63351E3-4A12-42E2-9938-7E92EFF4F328', 3, N'发烧', N'發燒', N'fā shāo', N'phát sốt, bị sốt', N'to have a high temperature (from illness)', N'动', NULL, N'[{"zh": "他昨天淋了雨，今天开始发烧了。", "pinyin": "Tā zuótiān lín le yǔ, jīntiān kāishǐ fāshāo le.", "meaningVi": "Hôm qua cậu ấy dầm mưa, hôm nay đã bắt đầu phát sốt."}]', N'PUBLISHED', N'AF110A35-04E1-4A4F-A064-B0964F562D76', N'2026-11-10 06:58:48.546666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'fāshāo'),
    (N'A8287551-7E69-5540-8E6E-7EB7A6C52EFE', 4, N'回忆', N'回憶', N'huí yì', N'nhớ lại, hồi ức, ký ức', N'to recall', N'动', NULL, N'[{"zh": "童年时期与父母一起阅读绘本的温馨时光，成了他长大后最珍贵美好的甜蜜回忆。", "pinyin": "Tóngnián shíqī yǔ fùmǔ yìqǐ yuèdú huìběn de wēnxīn shíguāng, chéng le tā zhǎngdà hòu zuì zhēnguì měihǎo de tiánmì huíyì.", "meaningVi": "Khoảng thời gian ấm áp cùng cha mẹ đọc truyện tranh thời thơ ấu đã trở thành ký ức ngọt ngào và quý giá nhất của anh sau khi khôn lớn."}]', N'PUBLISHED', N'DC410BC5-6799-4156-BEF8-3A2CCBE4A1A6', N'2026-11-10 13:22:18.143333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'huíyì'),
    (N'CC955395-A49F-513B-97AD-7F02FC50A6D6', 4, N'语法', N'語法', N'yǔ fǎ', N'ngữ pháp', N'grammar', N'名', NULL, N'[{"zh": "学习汉语时要深刻理解语法背后的逻辑思维，而不应机械死记硬背句型。", "pinyin": "Xuéxí hànyǔ shí yào shēnkè lǐjiě yǔfǎ bèihòu de luóji sīwéi, ér bù yīng jīxiè sǐjìyìngbèi jùxíng.", "meaningVi": "Học tiếng Hán cần hiểu sâu sắc tư duy logic sau ngữ pháp, chứ không nên học vẹt máy móc mẫu câu."}]', N'PUBLISHED', N'1C6EDD2A-ED7C-40CB-9435-0BBAEA6C573A', N'2026-11-10 13:22:16.220000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'yǔfǎ'),
    (N'CF1AD4F3-1643-45F9-9F13-7F534E031320', 2, N'让', N'讓', N'ràng', N'cho phép, để cho, bảo', N'to yield', N'Động từ', NULL, N'[{"zh": "他每天都用让。", "pinyin": "Tā měitiān dōu yòng ràng.", "meaningVi": "Anh ấy mỗi ngày đều dùng cho phép, để cho, bảo."}]', N'PUBLISHED', N'162494EB-C345-47A0-BF11-2BC4FA7A2726', N'2026-11-10 06:02:08.480000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'ràng'),
    (N'C6DE6F61-281E-5311-839A-7F7820C89E90', 4, N'信心', N'信心', N'xìn xīn', N'lòng tin, sự tự tin', N'confidence', N'名', NULL, N'[{"zh": "充分的考前复习准备与良好的心理素质，赋予了考生们攻坚克难的坚定信心。", "pinyin": "Chōngfèn de kǎoqián fùxí zhǔnbèi yǔ liánghǎo de xīnlǐ sùzhì, fùyǔ le kǎoshēngmen gōngjiānkènán de jiāndìng xìnxīn.", "meaningVi": "Sự chuẩn bị ôn tập kỹ càng cùng tâm lý vững vàng đã trao cho các thí sinh niềm tin kiên định để vượt khó."}]', N'PUBLISHED', N'90A35972-4CD6-46CB-8FC0-FF111D8DFB71', N'2026-11-10 13:22:15.980000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'xìnxīn'),
    (N'04BBCD6D-8BE5-547A-9313-7F911F4758BF', 4, N'并', NULL, N'bìng', N'và, đồng thời; kết hợp (dùng trước phủ định để nhấn mạnh)', NULL, N'动、副、连', NULL, N'[{"chinese": "他仔细阅读了合作协议的所有条款，并郑重签下了自己的名字。", "pinyin": "Tā zǐxì yuèdú le hézuò xiéyì de suǒyǒu tiáokuǎn, bìng zhèngzhòng qiānxià le zìjǐ de míngzi.", "translation": "Anh ấy đã đọc kỹ tất cả điều khoản của thỏa thuận hợp tác, đồng thời trịnh trọng ký tên mình vào."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:17.186666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'bìng'),
    (N'558C3482-0F06-5A17-9872-7FD53751CC2B', 4, N'部', NULL, N'bù', N'bộ, phần; lượng từ (phim, xe, máy)', NULL, N'名、量', NULL, N'[{"chinese": "这部新上映的科幻电影凭借出色的特效赢得了票房和口碑的双丰收。", "pinyin": "Zhè bù xīn shàngyìng de kēhuàn diànyǐng píngjiè chūsè de tèxiào yíngdé le piàofáng hé kǒubēi de shuāng fēngshōu.", "translation": "Bộ phim khoa học viễn tưởng mới công chiếu này nhờ kỹ xảo xuất sắc đã gặt hái thành công lớn về cả doanh thu và tiếng vang."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:16.876666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'bù'),
    (N'740294CC-CEA5-5BE5-8FD7-7FF5F1C98913', 4, N'招聘', N'招聘', N'zhāo pìn', N'tuyển dụng, chiêu mộ', N'recruitment', N'动', NULL, N'[{"zh": "这家国际知名科技企业今年秋天面向全国高校招聘优秀软件工程师。", "pinyin": "Zhè jiā guójì zhìmíng kējì qǐyè jīnnián qiūtiān miànxiàng quánguó gāoxiào zhāopìn yōuxiù ruǎnjiàn gōngchéngshī.", "meaningVi": "Doanh nghiệp công nghệ nổi tiếng quốc tế này mùa thu năm nay tuyển dụng kỹ sư phần mềm xuất sắc từ các trường đại học toàn quốc."}]', N'PUBLISHED', N'575F094F-5298-41BE-B343-46849DDB0E1E', N'2026-11-10 13:22:16.823333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'zhāopìn'),
    (N'36EAD390-D221-5DA8-9F04-8040299AECC8', 4, N'头痛', NULL, N'tóutòng', N'đau đầu, nhức đầu', NULL, N'形', NULL, N'[{"chinese": "刚登上四千米高海拔雪山时，他稍微有些高原反应和轻微头痛，休息片刻后便逐渐好转。", "pinyin": "Gāng dēng shang sìqiān mǐ gāo hǎibá xuěshān shí, tā shāowēi yǒuxiē gāoyuán fǎnyìng hé qīngwēi tóutòng, xiūxi piànkè hòu biàn zhújiàn hǎozhuǎn.", "translation": "Vừa đặt chân lên đỉnh núi tuyết cao bốn ngàn mét so với mực nước biển, anh ấy hơi bị sốc độ cao và nhức đầu nhẹ, sau khi nghỉ ngơi chốc lát thì dần dần đỡ hẳn."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:18.730000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'tóutòng'),
    (N'971C9535-FCE2-5EB7-9B46-8056C1C8B6F9', 4, N'球队', NULL, N'qiúduì', N'đội bóng, đội thể thao', NULL, N'名', NULL, N'[{"chinese": "经过艰苦的体能训练，这支年轻的足球队在联赛中取得了优异成绩。", "pinyin": "Jīngguò jiānkǔ de tǐnéng xùnliàn, zhè zhī niánqīng de zúqiúduì zài liánsài zhōng qǔdé le yōuyì chéngjì.", "translation": "Trải qua tập luyện thể lực gian khổ, đội bóng đá trẻ này đã giành được thành tích xuất sắc trong giải đấu."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:16.680000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'qiúduì'),
