    (N'5D4B8C6D-7E79-4835-AA4A-80C56CA31C9A', 2, N'下面', NULL, N'xiàmiàn', N'phía dưới, bên dưới', NULL, N'名', NULL, N'[{"zh": "桌子下面趴着一只可爱的小白猫。", "pinyin": "Zhuōzi xiàmiàn pā zhe yì zhī kě''ài de xiǎo bái māo.", "meaningVi": "Dưới gầm bàn có một chú mèo trắng nhỏ đáng yêu đang nằm."}]', N'ARCHIVED', NULL, N'2026-11-10 06:02:08.383333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'xiàmiàn'),
    (N'F98083BD-98E5-57D4-85FF-80EBAD4ECE7C', 4, N'厂', NULL, N'chǎng', N'xưởng, nhà xưởng, nhà máy', NULL, N'名', NULL, N'[{"chinese": "经过技术改造，这家老机械厂的生产效率得到了极大提高。", "pinyin": "Jīngguò jìshù gǎizào, zhè jiā lǎo jīxièchǎng de shēngchǎn xiàolǜ dédào le jídà tígāo.", "translation": "Trải qua cải tiến kỹ thuật, hiệu suất sản xuất của nhà xưởng cơ khí cũ này đã được nâng cao đáng kể."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:17.126666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'chǎng'),
