    (N'C175293E-30CE-5712-8246-8763E9D19C43', 4, N'对于', NULL, N'duìyú', N'đối với, về (vấn đề gì)', NULL, N'介', NULL, N'[{"chinese": "对于初学汉语的外国留学生来说，汉字的声调是一大难关。", "pinyin": "Duìyú chūxué hànyǔ de wàiguó liúxuéshēng láishuō, hànzì de shēngdiào shì yí dà nánguān.", "translation": "Đối với các du học sinh nước ngoài mới học tiếng Hán, thanh điệu của chữ Hán là một ải khó lớn."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:17.176666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'duìyú'),
    (N'18D6E50B-3378-4791-A513-87685DB79E26', 2, N'篮球', NULL, N'lánqiú', N'bóng rổ', NULL, N'名', NULL, N'[{"zh": "周末哥哥常和朋友去打篮球。", "pinyin": "Zhōumò gēge cháng hé péngyou qù dǎ lánqiú.", "meaningVi": "Cuối tuần anh trai thường cùng bạn đi chơi bóng rổ."}]', N'ARCHIVED', NULL, N'2026-11-10 06:02:08.373333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'lánqiú'),
    (N'E6AA6430-75E9-52C6-8C9D-877DBC4E2A88', 4, N'演出', N'演出', N'yǎn chū', N'biểu diễn, buổi biểu diễn', N'to act (in a play)', N'动', NULL, N'[{"zh": "来自各国的青年艺术家们同台献艺，为观众带来了一场精彩纷呈的多元文化演出。", "pinyin": "Láizì gè guó de qīngnián yìshùjiāmen tóng tái xiànyì, wèi guānzhòng dàilái le yì chǎng jīngcǎi fēnchéng de duōyuán wénhuà yǎnchū.", "meaningVi": "Các nghệ sĩ trẻ đến từ nhiều quốc gia đã cùng nhau đứng chung sân khấu, mang đến cho khán giả một buổi biểu diễn đa văn hóa đặc sắc rực rỡ."}]', N'PUBLISHED', N'C8DC9FD6-E848-464D-A0F0-80259D92C427', N'2026-11-10 13:22:18.356666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'yǎnchū'),
    (N'78C0306A-85F9-5EBD-8533-878279375F16', 4, N'记者', N'記者', N'jì zhě', N'phóng viên, nhà báo', N'reporter', N'名', NULL, N'[{"zh": "几位关注未成年人心理健康的记者专程来到学校，就家庭教育现状进行了深入采访。", "pinyin": "Jǐ wèi guānzhù wèichéngniánrén xīnlǐ jiànkāng de jìzhě zhuānchéng lái dào xuéxiào, jiù jiātíng jiàoyù xiànzhuàng jìnxíng le shēnrù cǎifǎng.", "meaningVi": "Mấy phóng viên quan tâm đến sức khỏe tâm lý trẻ vị thành niên đã đặc biệt đến trường để phỏng vấn sâu về hiện trạng giáo dục gia đình."}]', N'PUBLISHED', N'DC410BC5-6799-4156-BEF8-3A2CCBE4A1A6', N'2026-11-10 13:22:18.233333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'jìzhě'),
    (N'98FCCD55-78DF-5CE9-AB6E-8799CF4E1256', 4, N'小伙子', NULL, N'xiǎohuǒzi', N'chàng trai trẻ, thanh niên', NULL, N'名', NULL, N'[{"chinese": "这位热心肠的当地小伙子不仅主动给迷路的游客指路，还热情地当起了免费向导。", "pinyin": "Zhè wèi rèxīncháng de dāngdì xiǎohuǒzi bùjǐn zhǔdòng gěi mílù de yóukè zhǐlù, hái rèqíng de dāng qǐ le miǎnfèi xiàngdǎo.", "translation": "Chàng trai trẻ nhiệt tình người bản địa này không chỉ chủ động chỉ đường cho du khách lạc lối, mà còn niềm nở làm hướng dẫn viên miễn phí."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:18.736666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'xiǎohuǒzi'),
    (N'A6381DA4-D598-4719-9ED4-879A70B2004D', 3, N'新闻', N'新聞', N'xīn wén', N'tin tức, bản tin', N'news', N'名', NULL, N'[{"zh": "爸爸一边吃早饭一边在看早间新闻。", "pinyin": "Bàba yìbiān chī zǎofàn yìbiān zài kàn zǎojiān xīnwén.", "meaningVi": "Bố vừa ăn sáng vừa xem bản tin thời sự buổi sáng."}]', N'PUBLISHED', N'B417E51A-3AEB-4800-8E35-6B9327F24D8C', N'2026-11-10 06:58:48.833333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'xīnwén');
