    (N'7E62C79A-41F5-5035-9873-87A687B0E2D3', 4, N'推出', NULL, N'tuīchū', N'tung ra, ra mắt, giới thiệu', NULL, N'动', NULL, N'[{"chinese": "这家科技领军企业近期正式推出了具备划时代意义的新一代人工智能助手。", "pinyin": "Zhè jiā kējì lǐngjūn qǐyè jìnqī zhèngshì tuīchū le jùbèi huàshídài yìyì de xīn yídài réngōng zhìnéng zhùshǒu.", "translation": "Doanh nghiệp công nghệ dẫn đầu này dạo gần đây đã chính thức tung ra trợ lý AI thế hệ mới mang ý nghĩa thời đại."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:16.030000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'tuīchū'),
    (N'5F6EE32F-A73A-4563-9229-87C648B9E50F', 3, N'自行车', NULL, N'zìxíngchē', N'xe đạp', NULL, N'名', NULL, N'[{"chinese": "天气好的时候，我喜欢骑自行车去上班。", "pinyin": "Tiānqì hǎo de shíhou, wǒ xǐhuan qí zìxíngchē qù shàngbān.", "translation": "Những khi thời tiết đẹp, tôi thích đạp xe đạp đi làm."}]', N'ARCHIVED', NULL, N'2026-11-10 06:58:48.353333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'zìxíngchē'),
    (N'8C897B31-A5D8-5190-AF6E-87E08F7C4329', 4, N'弄', N'弄', N'nòng', N'làm, làm cho, xử lý', N'to do', N'动', NULL, N'[{"zh": "他不小心把重要的文件弄湿了，现在正在想办法补救。", "pinyin": "Tā bù xiǎoxīn bǎ zhòngyào de wénjiàn nòngshī le, xiànzài zhèngzài xiǎng bànfǎ bǔjiù.", "meaningVi": "Anh ấy vô tình làm ướt tập tài liệu quan trọng, giờ đang tìm cách cứu vãn."}]', N'PUBLISHED', N'362CB9D4-5F0C-4C98-A09B-BC3EBFCDBAA3', N'2026-11-10 13:22:16.300000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'nòng'),
    (N'98540DDC-2DEB-5552-B424-87F12EBD9CA7', 4, N'许多', N'許多', N'xǔ duō', N'nhiều, rất nhiều', N'many', N'数', NULL, N'[{"zh": "中国传统节日如中秋节和端午节，如今在世界许多国家都受到了当地居民的热烈欢迎。", "pinyin": "Zhōngguó chuántǒng jiérì rú Zhōngqiūjié hé Duānwǔjié, rújīn zài shìjiè xǔduō guójiā dōu shòudào le dāngdì jūmín de rèliè huānyíng.", "meaningVi": "Các ngày lễ truyền thống Trung Quốc như Tết Trung thu và Tết Đoan ngọ ngày nay ở rất nhiều quốc gia trên thế giới đều nhận được sự chào đón nồng nhiệt của cư dân bản địa."}]', N'PUBLISHED', N'C8DC9FD6-E848-464D-A0F0-80259D92C427', N'2026-11-10 13:22:18.386666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'xǔduō'),
    (N'65D9DE6B-8FA2-4539-A3C8-880E2FF7833D', 2, N'找', N'找', N'zhǎo', N'tìm kiếm, thối lại (tiền thừa)', N'to try to find', N'Động từ', NULL, N'[{"zh": "我在找我的钥匙。", "pinyin": "Wǒ zài zhǎo wǒ de yàoshi.", "meaningVi": "Tôi đang tìm chìa khóa của mình."}]', N'PUBLISHED', N'AAAC8210-0D40-4D88-81A2-F1C0D3C02B93', N'2026-11-11 10:10:25.304391', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary inserted cleanly', N'', N'zhǎo'),
    (N'37A4B244-5157-5D39-90CF-886DCADAD81C', 4, N'道', NULL, N'dào', N'con đường, lối; đạo lý', NULL, N'名、量', NULL, N'[{"chinese": "通往真理的道路漫长曲折，唯有无畏的攀登者方能领略无限风光。", "pinyin": "Tōngwǎng zhēnlǐ de dàolù màncháng qūzhé, wéiyǒu wúwèi de pāndēngzhě fāng néng lǐnglüè wúxiàn fēngguāng.", "translation": "Con đường dẫn tới chân lý dài dằng dặc gập ghềnh, chỉ có người leo núi không sợ hãi mới có thể thưởng ngoạn cảnh đẹp vô tận."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:16.090000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'dào'),
    (N'31944003-89A5-51A5-B69F-887182648E76', 4, N'证明', N'證明', N'zhèng míng', N'chứng minh, bằng chứng; chứng thực', N'proof', N'动、名', NULL, N'[{"zh": "他用亲身徒步穿越戈壁荒原的非凡经历证明，只要心怀坚定的信念，就能跨越常人无法想象的艰难险阻。", "pinyin": "Tā yòng qīnshēn túbù chuānyuè gēbì huāngyuán de fēifán jīnglì zhèngmíng, zhǐyào xīnhuái jiāndìng de xìnniàn, jiù néng kuàyuè chángrén wúfǎ xiǎngxiàng de jiānnán xiǎnzǔ.", "meaningVi": "Anh ấy dùng chính trải nghiệm phi thường tự mình đi bộ xuyên qua hoang mạc gô-bi để chứng minh rằng, chỉ cần trong lòng ôm ấp niềm tin kiên định thì có thể vượt qua mọi hiểm trở gian nan mà người bình thường không thể tưởng tượng nổi."}]', N'PUBLISHED', N'575F094F-5298-41BE-B343-46849DDB0E1E', N'2026-11-10 13:22:18.826666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'zhèngmíng'),
    (N'5D15E548-583E-4717-A11A-887892487D34', 3, N'了解', N'了解', N'liǎo jiě', N'hiểu rõ, tìm hiểu', N'to understand', N'动', NULL, N'[{"zh": "来到中国以后，我更加了解中国文化了。", "pinyin": "Lái dào Zhōngguó yǐhòu, wǒ gèngjiā liǎojiě Zhōngguó wénhuà le.", "meaningVi": "Sau khi đến Trung Quốc, tôi càng hiểu rõ hơn về văn hóa Trung Quốc."}]', N'PUBLISHED', N'B9B9A099-644D-4591-821E-11620077739E', N'2026-11-10 06:58:48.610000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'liǎojiě'),
    (N'87871EE8-42DA-57CD-92BF-88AF16B3E58E', 4, N'健身', NULL, N'jiànshēn', N'tập thể dục, rèn luyện thể lực', NULL, N'动', NULL, N'[{"chinese": "坚持每天健身半小时有助于增强身体免疫力。", "pinyin": "Jiānchí měitiān jiànshēn bàn xiǎoshí yǒu zhù yú zēngqiáng shēntǐ miǎnyìlì.", "translation": "Kiên trì tập thể dục nửa tiếng mỗi ngày giúp tăng cường khả năng miễn dịch của cơ thể."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:15.583333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'jiànshēn'),
