    (N'28DF4794-61B8-5543-AF11-99A53C1D1F89', 4, N'缺点', N'缺點', N'quē diǎn', N'khuyết điểm, nhược điểm', N'weak point', N'名', NULL, N'[{"zh": "虽然早期的纯电动汽车存在电池续航偏短的缺点，但随着电池技术的突破，这一问题已得到根本改善。", "pinyin": "Suīrán zǎoqī de chún diàndòng qìchē cúnzài diànchí xùháng piān duǎn de quēdiǎn, dàn suízhe diànchí jìshù de tūpò, zhè yì wèntí yǐ dédào gēnběn gǎishàn.", "meaningVi": "Tuy các dòng xe thuần điện thời kỳ đầu có nhược điểm cự ly chạy của pin hơi ngắn, nhưng với sự đột phá của công nghệ pin thì vấn đề này đã được cải thiện căn bản."}]', N'PUBLISHED', N'17F5C0E2-6A2D-45BC-99EA-637AA85D6508', N'2026-11-10 13:22:18.500000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'quēdiǎn'),
    (N'749E01C8-BE6C-484D-BCF6-99AEE9D8C3E0', 3, N'小区', NULL, N'xiǎoqū', N'khu dân cư, khu đô thị', NULL, N'名', NULL, N'[{"chinese": "我们小区环境优美，配套设施很齐全。", "pinyin": "Wǒmen xiǎoqū huánjìng yōuměi, pèitào shèshī hěn qíquán.", "translation": "Khu dân cư chúng tôi môi trường tươi đẹp, tiện ích xung quanh rất đầy đủ."}]', N'ARCHIVED', NULL, N'2026-11-10 06:58:49', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'xiǎoqū'),
    (N'8330CD8F-8124-58B2-99E9-99C5C92301D6', 4, N'接受', N'接受', N'jiē shòu', N'tiếp nhận, chấp nhận', N'to accept', N'动', NULL, N'[{"zh": "面对别人的善意批评，我们应当虚心接受并改正。", "pinyin": "Miànduì biérén de shànyì pīpíng, wǒmen yīngdāng xūxīn jiēshòu bìng gǎizhèng.", "meaningVi": "Đối mặt với lời phê bình thiện chí của người khác, chúng ta nên khiêm tốn tiếp nhận và sửa đổi."}]', N'PUBLISHED', N'CB223D54-B351-4EBC-9A47-018CA23AE6CE', N'2026-11-10 13:22:15.630000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'jiēshòu');
