    (N'8F87F281-51BB-4966-9BAD-99DB09953C09', 1, N'去', N'去', N'qù', N'đi', N'to go', N'Động từ', NULL, N'[{"zh": "我想去中国。", "pinyin": "Wǒ xiǎng qù Zhōngguó.", "meaningVi": "Tôi muốn đi Trung Quốc."}]', N'PUBLISHED', N'EA11A07D-2642-4D98-B3FD-588CC8CB7BFE', N'2026-11-10 17:06:23.681985', N'2026-11-11 08:55:45.476659', N'167', N'去', N'', N'1', 84, N'HSK 2.0', N'167', NULL, NULL, NULL, NULL, N'Verified HSK 2.0 (DIALOGUE_AND_THEME_MATCH)', N'', N'qù'),
    (N'34DF5E9B-C52A-5A38-9A8C-9A172F14ED49', 4, N'地球', N'地球', N'dì qiú', N'Trái Đất', N'the Earth', N'名', NULL, N'[{"zh": "地球是我们全人类繁衍生息的唯一蓝色家园，保护她就是保护人类的未来。", "pinyin": "Dìqiú shì wǒmen quán rénlèi fányǎnshēngxī de wéiyī lánsè jiāyuán, bǎohù tā jiù shì bǎohù rénlèi de wèilái.", "meaningVi": "Trái Đất là mái nhà xanh duy nhất nuôi dưỡng toàn nhân loại, bảo vệ Trái Đất chính là bảo vệ tương lai."}]', N'PUBLISHED', N'E7F82F5D-5ED2-440B-8369-FE116EE51ABC', N'2026-11-10 13:22:16.143333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'dìqiú'),
    (N'F5F423BD-7FF1-4CA8-BDA7-9A7D9967F0A6', 3, N'照', NULL, N'zhào', N'chụp (ảnh), chiếu rọi', NULL, N'动', NULL, N'[{"chinese": "阳光照在湖面上，金光闪闪。", "pinyin": "Yángguāng zhào zài húmiàn shang, jīnguāng shǎnshǎn.", "translation": "Ánh nắng chiếu lên mặt hồ lấp lánh ánh vàng."}]', N'ARCHIVED', NULL, N'2026-11-10 06:58:48.343333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'zhào'),
    (N'67AF4514-22E1-592E-84CF-9A82D6DED64D', 4, N'暂停', NULL, N'zàntíng', N'tạm dừng, tạm hoãn', NULL, N'动', NULL, N'[{"chinese": "因受暴雨极端恶劣天气影响，风景区的所有户外索道设施暂时停止运营。", "pinyin": "Yīn shòu bàoyǔ jíduān èliè tiānqì yǐngxiǎng, fēngjǐngqū de suǒyǒu hùwài suǒdào shèshī zàntíng yíngyùn.", "translation": "Do ảnh hưởng của thời tiết mưa bão khắc nghiệt, toàn bộ hệ thống cáp treo ngoài trời của khu danh lam thắng cảnh tạm dừng vận hành."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:17.833333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'zàntíng'),
