    (N'18D9139B-DC12-53D1-A7BD-9B76FB31A5EF', 4, N'却', N'㕁', N'què', N'nhưng, lại (biểu thị chuyển ý)', N'but', N'副', NULL, N'[{"zh": "虽然经过了连续好几天的细致搜寻，却依然没有找到遗失的钱包。", "pinyin": "Suīrán jīngguò le liánxù hǎojǐ tiān de xìzhì sōuxún, què yīrán méiyǒu zhǎodào yíshī de qiánbāo.", "meaningVi": "Mặc dù đã trải qua nhiều ngày liên tiếp tìm kiếm tỉ mỉ, nhưng vẫn chưa tìm thấy chiếc ví tiền bị mất."}]', N'PUBLISHED', N'17F5C0E2-6A2D-45BC-99EA-637AA85D6508', N'2026-11-10 13:22:16.910000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'què'),
    (N'574CBFFF-AC11-48D3-B036-9B94530E86A4', 2, N'词', NULL, N'cí', N'từ, từ ngữ', NULL, N'名', NULL, N'[{"zh": "这个生词是什么意思？", "pinyin": "Zhè gè shēngcí shì shénme yìsi?", "meaningVi": "Từ mới này có nghĩa là gì?"}]', N'ARCHIVED', NULL, N'2026-11-10 06:02:08.120000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'cí'),
    (N'121A580C-2D02-537C-B49D-9BF66D3ECC9D', 4, N'应聘', NULL, N'yìngpìn', N'ứng tuyển, dự tuyển (việc làm)', NULL, N'动', NULL, N'[{"chinese": "几位充满理想抱负的环境科学专业应届毕业生，积极来到国家大熊猫公园应聘一线生态管护岗位。", "pinyin": "Jǐ wèi chōngmǎn lǐxiǎng bàofù de huánjìng kēxué zhuānyè yīngjiè bìyèshēng, jījí lái dào Guójiā Dàxióngmāo Gōngyuán yìngpìn yíxiàn shēngtài guǎnhù gǎngwèi.", "translation": "Mấy cử nhân mới tốt nghiệp chuyên ngành khoa học môi trường tràn đầy hoài bão lý tưởng đã hăng hái đến Công viên Gấu trúc Quốc gia để ứng tuyển các vị trí quản lý bảo vệ sinh thái tiền tuyến."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:18.590000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'yìngpìn'),
