    (N'C5B0BB37-30C0-59B4-884B-9F6B58D3A333', 4, N'图片', NULL, N'túpiàn', N'hình ảnh, bức tranh ảnh', NULL, N'名', NULL, N'[{"chinese": "这本百科全书图文并茂，配有上千张高清精美图片。", "pinyin": "Zhè běn bǎikē quánshū túwénbìngmào, pèi yǒu shàng qiān zhāng gāoqīng jīngměi túpiàn.", "translation": "Cuốn bách khoa toàn thư này hình ảnh và câu chữ hòa quyện, kèm theo hàng nghìn bức hình ảnh sắc nét tuyệt đẹp."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:15.743333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'túpiàn'),
    (N'AADC7497-2E27-5762-98C5-9FAEE6F125B0', 4, N'零花钱', NULL, N'línghuāqián', N'tiền tiêu vặt', NULL, N'名', NULL, N'[{"chinese": "父母教育孩子要合理规划自己的零花钱，从小养成节约习惯。", "pinyin": "Fùmǔ jiàoyù háizi yào hélǐ guīhuà zìjǐ de línghuāqián, cóngxiǎo yǎngchéng jiéyuē xíguàn.", "translation": "Cha mẹ dạy con cái phải lên kế hoạch hợp lý cho tiền tiêu vặt của mình, rèn luyện thói quen tiết kiệm từ nhỏ."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:16.393333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'línghuāqián'),
    (N'7E91A655-7488-5FB2-961A-9FC79C062017', 4, N'不得不', N'不得不', N'bù dé bù', N'buộc phải, không thể không', N'have no choice or option but to', N'副', NULL, N'[{"zh": "由于突发暴雨造成航班大面积延误，我们不得不改变行程计划。", "pinyin": "Yóuyú tūfā bàoyǔ zàochéng hángbān dà miànjī yánwù, wǒmen bùdébù gǎibiàn xíngchéng jìhuà.", "meaningVi": "Do mưa bão bất ngờ khiến các chuyến bay trễ diện rộng, chúng tôi buộc phải thay đổi kế hoạch hành trình."}]', N'PUBLISHED', N'1E19300E-0BA0-4EA1-9D52-2247C8892171', N'2026-11-10 13:22:16.883333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'bùdébù'),
    (N'11713B87-C793-4799-B49F-A00440754A12', 3, N'葡萄', N'葡萄', N'pú táo', N'nho, quả nho', N'grape', N'名', NULL, N'[{"zh": "八月份的新疆吐鲁番瓜果飘香，架上挂满了一串串晶莹剔透的水晶葡萄。", "pinyin": "Bā yuèfèn de Xīnjiāng Tǔlǔfān guāguǒ piāoxiāng, jià shàng guàmǎn le yí chuànchuàn jīngyíng-tītòu de shuǐjīng pútao.", "meaningVi": "Tháng tám tại Thổ Lỗ Phiên thuộc Tân Cương cây trái ngát hương, trên giàn treo lủng lẳng từng chùm nho pha lê trong suốt long lanh."}]', N'PUBLISHED', N'945C8303-F9B3-4D6E-87A4-9550ED57C553', N'2026-11-11 10:10:25.304391', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary inserted cleanly', N'', N'pútáo'),
    (N'D7A8ACB4-9628-46FA-B752-A023BC505F50', 3, N'沙发', NULL, N'shāfā', N'ghế xô-pha, sa-lông', NULL, N'名', NULL, N'[{"chinese": "累了一天，他躺在沙发上看电视。", "pinyin": "Lèi le yì tiān, tā tǎng zài shāfā shang kàn diànshì.", "translation": "Mệt mỏi cả ngày, anh ấy nằm trên ghế xô-pha xem ti vi."}]', N'ARCHIVED', NULL, N'2026-11-10 06:58:48.776666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'shāfā'),
    (N'54AA53BE-2341-4B42-B660-A08629FA8F35', 3, N'半天', NULL, N'bàntiān', N'nửa ngày; rất lâu, hồi lâu', NULL, N'数量', NULL, N'[{"chinese": "我在这儿等了半天，他终于赶到了。", "pinyin": "Wǒ zài zhèr děng le bàntiān, tā zhōngyú gǎndào le.", "translation": "Tôi đợi ở đây suốt cả buổi, anh ấy cuối cùng cũng đã tới."}]', N'ARCHIVED', NULL, N'2026-11-10 06:58:49.106666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'bàntiān');
