    (N'C9EC1B61-070D-5586-A74F-A08833EFF521', 4, N'茶叶', NULL, N'cháyè', N'lá trà, búp chè', NULL, N'名', NULL, N'[{"chinese": "西湖龙井是中国历史悠久的名贵绿茶，其茶叶扁平挺直、色泽翠绿。", "pinyin": "Xīhú Lóngjǐng shì Zhōngguó lìshǐ yōujiǔ de míngguì lǜchá, qí cháyè biǎnpíng tǐngzhí, sèzé cuìlǜ.", "translation": "Long Tỉnh Tây Hồ là loại trà xanh quý giá lâu đời của Trung Quốc, búp chè dẹp thẳng, sắc xanh biếc."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:16.076666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'cháyè'),
    (N'91A33215-2DCD-51F2-A7AA-A0E16D1D7C62', 4, N'感人', NULL, N'gǎnrén', N'cảm động, lay động lòng người', NULL, N'形', NULL, N'[{"chinese": "这部纪录片真实记录了志愿者救助野生动物的感人故事，深深触动了观众的心灵。", "pinyin": "Zhè bù jìlùpiàn zhēnshí jìlù le zhìyuànzhě jiùzhù yěshēng dòngwù de gǎnrén gùshi, shēnshēn chùdòng le guānzhòng de xīnlíng.", "translation": "Bộ phim tài liệu này ghi lại chân thực câu chuyện cảm động của các tình nguyện viên cứu hộ động vật hoang dã, chạm đến tận đáy lòng người xem."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:17.993333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'gǎnrén'),
    (N'B6DE3DB0-248D-5A8E-B327-A0E3C57B4614', 4, N'排队', NULL, N'páiduì', N'xếp hàng', NULL, N'动', NULL, N'[{"chinese": "借助未来生物识别与自动通关无感支付技术，机场和车站旅客登机检票将彻底告别漫长的排队等待。", "pinyin": "Jièzhù wèilái shēngwù shíbié yǔ zìdòng tōngguān wúgǎn zhīfù jìshù, jīchǎng hé chēzhàn lǚkè dēngjī jiǎnpiào jiāng chèdǐ gàobié màncháng de páiduì děngdài.", "translation": "Nhờ vào công nghệ nhận diện sinh trắc học và thanh toán không cảm ứng thông quan tự động trong tương lai, hành khách tại sân bay bến xe khi lên máy bay soát vé sẽ hoàn toàn tạm biệt việc phải xếp hàng chờ đợi dằng dặc."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:18.940000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'páiduì'),
    (N'5AEA8AB2-017C-5529-A81B-A0E7521C91AE', 4, N'文字', NULL, N'wénzì', N'chữ viết, văn tự', NULL, N'名', NULL, N'[{"chinese": "汉字作为世界上持续使用至今的古老文字，承载着中华文明的博大精深。", "pinyin": "Hànzì zuòwéi shìjiè shang chíxù shǐyòng zhìjīn de gǔlǎo wénzì, chéngzài zhe zhōnghuá wénmíng de bódàjīngshēn.", "translation": "Chữ Hán là thứ chữ viết cổ xưa duy nhất còn tiếp tục được dùng cho tới ngày nay, chuyên chở nền văn minh Trung Hoa uyên thâm quảng đại."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:15.910000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'wénzì'),
