    (N'0560E362-6631-5AD5-9FBF-A4B7AB0A456C', 4, N'究竟', N'究竟', N'jiū jìng', N'rốt cuộc, kết cục, thực chất', N'after all (when all is said and done)', N'副、（名）', NULL, N'[{"zh": "科学家们通过大量的实地勘探，终于弄清了这处古建筑地质下沉的究竟原因。", "pinyin": "Kēxuéjiāmen tōngguò dàliàng de shídì kāntàn, zhōngyú nòngqīng le zhè chù gǔ jiànzhù dìzhì xiàchén de jiūjìng yuányīn.", "meaningVi": "Các nhà khoa học qua nhiều đợt thăm dò thực địa rốt cuộc đã làm rõ nguyên nhân thực chất dẫn tới sụt lún địa chất của công trình cổ này."}]', N'PUBLISHED', N'CB223D54-B351-4EBC-9A47-018CA23AE6CE', N'2026-11-10 13:22:17.866666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'jiūjìng'),
    (N'CC2FA77B-83A0-4B2D-9BA9-A4CF7407887D', 4, N'后来', N'後來', N'hòu lái', N'sau đó, về sau', N'afterwards', N'名', NULL, N'[{"zh": "他先去当了兵，后来考上了著名的大学。", "pinyin": "Tā xiān qù dāng le bīng, hòulái kǎoshàng le zhùmíng de dàxué.", "meaningVi": "Cậu ấy trước đi bộ đội, sau đó đã thi đỗ vào một trường đại học nổi tiếng."}]', N'PUBLISHED', N'95268DAC-D50C-442A-8436-85C845D1C72F', N'2026-11-11 10:10:25.304391', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary inserted cleanly', N'', N'hòulái'),
    (N'BA156229-6AD2-50A8-BB78-A4EEA8A7A4A1', 4, N'年底', NULL, N'niándǐ', N'cuối năm', NULL, N'名', NULL, N'[{"chinese": "每到年底，各大公司都会对全年的财务收支进行系统性盘点。", "pinyin": "Měi dào niándǐ, gè dà gōngsī dōuhuì duì quán nián de cáiwù shōuzhī jìnxíng xìtǒngxìng pándiǎn.", "translation": "Cứ mỗi dịp cuối năm, các công ty lớn đều tiến hành kiểm kê có hệ thống toàn bộ thu chi tài chính cả năm."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:16.810000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'niándǐ');
