    (N'FA5FD86A-44BE-4057-BA48-A692411E7351', 3, N'勺子', NULL, N'sháozi', N'cái thìa, cái muỗng', NULL, N'名', NULL, N'[{"chinese": "喝汤的时候请用勺子，不要用筷子。", "pinyin": "Hē tāng de shíhou qǐng yòng sháozi, bú yào yòng kuàizi.", "translation": "Khi húp canh xin hãy dùng thìa, đừng dùng đũa."}]', N'ARCHIVED', NULL, N'2026-11-10 06:58:48.933333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'sháozi'),
    (N'DBF8D455-6F0E-5044-8941-A6BD51D37A51', 4, N'重视', N'重視', N'zhòng shì', N'coi trọng, xem trọng, chú trọng', N'to attach importance to sth', N'动', NULL, N'[{"zh": "现代旅游业越来越重视生态环境的保护与当地传统文化的传承，杜绝过度商业开发。", "pinyin": "Xiàndài lǚyóuyè yuèláiyuè zhòngshì shēngtài huánjìng de bǎohù yǔ dāngdì chuántǒng wénhuà de chuánchéng, dùjué guòdù shāngyè kāifā.", "meaningVi": "Ngành du lịch hiện đại ngày càng coi trọng việc bảo vệ môi trường sinh thái và kế thừa văn hóa truyền thống bản địa, kiên quyết chấm dứt việc khai thác thương mại hóa quá mức."}]', N'PUBLISHED', N'3815613C-581A-4EA8-92A8-F907E35F8BD4', N'2026-11-10 13:22:18.840000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'zhòngshì'),
    (N'90033D18-1C53-4683-AC48-A6BD8936BF58', 2, N'自行车', N'自行車', N'zì xíng chē', N'xe đạp', N'bicycle', N'名', NULL, N'[{"zh": "天气好的时候，我喜欢骑自行车去上班。", "pinyin": "Tiānqì hǎo de shíhou, wǒ xǐhuan qí zìxíngchē qù shàngbān.", "meaningVi": "Những khi thời tiết đẹp, tôi thích đạp xe đạp đi làm."}]', N'PUBLISHED', N'AAAC8210-0D40-4D88-81A2-F1C0D3C02B93', N'2026-11-11 10:10:25.304391', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary inserted cleanly', N'', N'zìxíngchē'),
    (N'8009FE08-B885-59FA-AC05-A6CC2E615E4F', 4, N'家乡', NULL, N'jiāxiāng', N'quê hương, quê nhà', NULL, N'名', NULL, N'[{"chinese": "不论走得多远，游子心中永远深藏着对家乡青山绿水的眷恋。", "pinyin": "Búlùn zǒu de duō yuǎn, yóuzǐ xīn zhōng yǒngyuǎn shēn cáng zhe duì jiāxiāng qīngshānlǜshuǐ de juànliàn.", "translation": "Dù đi xa đến đâu, trong tim người con xa xứ mãi mãi khắc sâu nỗi tha thiết nhớ về non xanh nước biếc quê nhà."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:15.886666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'jiāxiāng'),
    (N'B91A80E5-49A3-53CD-97D1-A6D176AEC564', 4, N'改', NULL, N'gǎi', N'sửa đổi, thay đổi, cải chính', NULL, N'动', NULL, N'[{"chinese": "老师在作文本上细心地为学生改出了几处错别字。", "pinyin": "Lǎoshī zài zuòwénběn shang xìnxīn de wèi xuéshēng gǎi chū le jǐ chù cuòbiézì.", "translation": "Thầy giáo cẩn thận sửa vài chỗ dùng sai chữ Hán trong vở tập làm văn cho học sinh."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:15.773333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'gǎi'),
    (N'F7485683-E967-59D5-AFAE-A6EED924C866', 4, N'不仅', N'不僅', N'bù jǐn', N'không chỉ, không những', N'not only (this one)', N'连', NULL, N'[{"zh": "学习一门外语不仅能开阔眼界，更能让我们深刻理解不同文化的思维方式。", "pinyin": "Xuéxí yì mén wàiyǔ bùjǐn néng kāikuò yǎnjiè, gèng néng ràng wǒmen shēnkè lǐjiě bù tóng wénhuà de sīwéi fāngshì.", "meaningVi": "Học một ngoại ngữ không chỉ mở rộng tầm mắt mà còn giúp chúng ta hiểu sâu sắc phương thức tư duy của các nền văn hóa khác nhau."}]', N'PUBLISHED', N'1E19300E-0BA0-4EA1-9D52-2247C8892171', N'2026-11-10 13:22:16.100000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'bùjǐn'),
    (N'BAA65785-BB94-5787-8F0A-A6F148641D0F', 4, N'操场', NULL, N'cāochǎng', N'sân vận động, sân tập, sân chơi trường học', NULL, N'名', NULL, N'[{"chinese": "每天傍晚放学后，许多热爱运动的同学都会来到学校操场上跑步踢球。", "pinyin": "Měitiān bàngwǎn fàngxué hòu, xǔduō rè''ài yùndòng de tóngxué dōu huì lái dào xuéxiào cāochǎng shang pǎobù tīqiú.", "translation": "Mỗi buổi chiều muộn sau khi tan học, rất nhiều bạn yêu thể thao đều đến sân thể dục của trường để chạy bộ và đá bóng."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:18.003333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'cāochǎng'),
