    (N'FA8C3758-5016-547D-B1D4-A9F25045C483', 4, N'答案', N'答案', N'dá àn', N'đáp án, câu trả lời', N'answer', N'名', NULL, N'[{"zh": "通过反复推演数学公式，他终于找出了这道压轴思考题的正确答案。", "pinyin": "Tōngguò fǎnfù tuīyǎn shùxué gōngshì, tā zhōngyú zhǎochū le zhè dào yāzhóu sīkǎotí de zhèngquè dá''àn.", "meaningVi": "Qua việc diễn giải đi diễn giải lại công thức toán học, anh ấy cuối cùng đã tìm ra đáp án chính xác cho bài toán khó cuối cùng này."}]', N'PUBLISHED', N'C6B083F2-715D-4E95-A8FC-4A0414E25C30', N'2026-11-10 13:22:16.983333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'dáàn'),
    (N'35C24F24-8615-4BCD-9152-A9FB7C331A54', 3, N'打算', N'打算', N'dǎ suàn', N'dự định, tính toán', N'to plan', N'动、名', NULL, N'[{"zh": "放假以后你有什么打算？", "pinyin": "Fàngjià yǐhòu nǐ yǒu shénme dǎsuàn?", "meaningVi": "Nghỉ lễ xong bạn có dự định gì?"}]', N'PUBLISHED', N'54C011CD-652B-41AB-AC23-06C892A3B608', N'2026-11-10 06:58:48.570000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'dǎsuàn'),
    (N'CA23B57D-D343-4640-96C9-AA26ADB03C01', 2, N'上去', NULL, N'shàngqù', N'đi lên', NULL, N'动', NULL, N'[{"zh": "他已经走上去了，我们在楼下等吧。", "pinyin": "Tā yǐjīng zǒu shàngqu le, wǒmen zài lóu xià děng ba.", "meaningVi": "Anh ấy đã đi lên trên rồi, chúng ta đợi ở dưới lầu nhé."}]', N'ARCHIVED', NULL, N'2026-11-10 06:02:08.220000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'shàngqù'),
    (N'899D25F2-9B38-44AF-802B-AA8F05B6363E', 3, N'表示', N'表示', N'biǎo shì', N'bày tỏ, biểu thị, cho thấy', N'to express', N'动', NULL, N'[{"zh": "联合国环境规划署高级官员在新闻发布会上明确表示，中国在生态文明建设方面取得了令世界瞩目的卓越成就。", "pinyin": "Liánhéguó Huánjìng Guīhuàshǔ gāojí guānyuán zài xīnwén fābùhuì shang míngquè biǎoshì, Zhōngguó zài shēngtài wénmíng jiànshè fāngmiàn qǔdé le lìng shìjiè zhǔmù de zhuóyuè chéngjiù.", "meaningVi": "Quan chức cấp cao của Chương trình Môi trường Liên Hợp Quốc tại buổi họp báo đã bày tỏ rõ ràng rằng, Trung Quốc trong xây dựng văn minh sinh thái đã đạt được những thành tựu xuất sắc khiến toàn thế giới chú ý."}]', N'PUBLISHED', N'B8B44E04-3823-441C-B43C-88E473DEDCE4', N'2026-11-11 10:10:25.304391', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary inserted cleanly', N'', N'biǎoshì'),
    (N'D7C0F451-CE43-487B-B20D-AA99A1FB432E', 3, N'饱', N'飽', N'bǎo', N'no, ăn no', N'to eat till full', N'形', NULL, N'[{"zh": "今天的饭菜太丰盛了，大家都吃饱了。", "pinyin": "Jīntiān de fàncài tài fēngshèng le, dàjiā dōu chī bǎo le.", "meaningVi": "Cơm canh hôm nay thịnh soạn quá, mọi người đều đã ăn no nê."}]', N'PUBLISHED', N'46AC4A4F-4F6A-4B90-BBBF-37FF149FD73D', N'2026-11-10 06:58:48.800000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'bǎo'),
    (N'2DBA90FB-E723-5852-A391-AA9E49649590', 4, N'景点', NULL, N'jǐngdiǎn', N'điểm tham quan, danh lam thắng cảnh', NULL, N'名', NULL, N'[{"chinese": "颐和园是北京最具知名度的皇家园林风景名胜景点之一。", "pinyin": "Yíhéyuán shì Běijīng zuì jù zhīmíngdù de huángjiā yuánlín fēngjǐng míngshèng jǐngdiǎn zhīyī.", "translation": "Di Hòa Viên là một trong những điểm tham quan danh thắng vườn hoa hoàng gia nổi tiếng nhất Bắc Kinh."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:17.226666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'jǐngdiǎn'),
