    (N'C4D09CBF-7EB1-4931-AD6F-B0E99F775DAD', 1, N'太', N'太', N'tài', N'quá, lắm', N'highest', N'Phó từ', NULL, N'[{"zh": "太好了！", "pinyin": "Tài hǎo le!", "meaningVi": "Tốt quá rồi!"}]', N'PUBLISHED', N'778CF4E8-1BDD-4C63-8352-C9DB74CFAA70', N'2026-11-10 17:06:23.681998', N'2026-11-11 08:55:45.496259', N'206', N'太', N'', N'1', 85, N'HSK 2.0', N'206', NULL, NULL, NULL, NULL, N'Verified HSK 2.0 (DIALOGUE_AND_THEME_MATCH)', N'', N'tài'),
    (N'00701325-C471-5EB8-B39A-B1091767B371', 4, N'网友', NULL, N'wǎngyǒu', N'cư dân mạng, bạn trên mạng', NULL, N'名', NULL, N'[{"chinese": "全国数千万热心网友通过手机在线认领树木，积极参与到阿拉善防沙治沙绿化公益项目中。", "pinyin": "Quánguó shù qiānwàn rèxīn wǎngyǒu tōngguò shǒujī zàixiàn rènlǐng shùmù, jījí cānyù dào Ālāshàn fángshā zhìshā lǜhuà gōngyì xiàngmù zhōng.", "translation": "Hàng chục triệu cư dân mạng nhiệt huyết trên cả nước thông qua điện thoại nhận cây trực tuyến, tích cực tham gia vào dự án công ích phủ xanh chống cát sa mạc Alashan."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:18.646666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'wǎngyǒu'),
    (N'CD49BD1A-B462-4084-915D-B127C911DBF0', 3, N'对话', NULL, N'duìhuà', N'đối thoại, trò chuyện', NULL, N'动', NULL, N'[{"chinese": "请听下面一段对话，然后回答问题。", "pinyin": "Qǐng tīng xiàmiàn yí duàn duìhuà, ránhòu huídá wèntí.", "translation": "Xin nghe một đoạn đối thoại dưới đây rồi trả lời câu hỏi."}]', N'ARCHIVED', NULL, N'2026-11-10 06:58:48.883333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'duìhuà'),
    (N'EFEEFF5D-6D3A-5479-A5DF-B146061B7407', 4, N'自', NULL, N'zì', N'kể từ, từ; tự mình', NULL, N'介', NULL, N'[{"chinese": "自去年在老舍茶馆看过一场京剧表演后，他就深深爱上了这一门古老艺术。", "pinyin": "Zì qùnián zài Lǎoshě Cháguǎn kànguo yì chǎng jīngjù biǎoyǎn hòu, tā jiù shēnshēn àishàng le zhè yì mén gǔlǎo yìshù.", "translation": "Kể từ sau khi xem một buổi diễn kinh kịch tại Quán trà Lão Xá năm ngoái, anh ấy đã say mê sâu sắc môn nghệ thuật cổ kính này."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:17.883333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'zì'),
    (N'1E78F24B-2FD2-5138-8538-B162D8592BFF', 4, N'重点', N'重點', N'zhòng diǎn', N'trọng điểm, điểm mấu chốt, phần cốt lõi', N'important point', N'名、副', NULL, N'[{"zh": "流域生态综合治理的战略重点，应当放在上游涵养水源和中下游湿地生态系统的系统性恢复上。", "pinyin": "Liúyù shēngtài zōnghé zhìlǐ de zhànlüè zhòngdiǎn, yīngdāng fàng zài shàngyóu hányǎng shuǐyuán hé zhōng-xiàyóu shīdì shēngtài xìtǒng de xìtǒngxìng huīfù shang.", "meaningVi": "Trọng điểm chiến lược của việc quản lý tổng hợp sinh thái lưu vực sông cần phải đặt vào việc bảo tồn nguồn nước thượng nguồn và khôi phục có hệ thống hệ sinh thái đất ngập nước ở trung và hạ lưu."}]', N'PUBLISHED', N'3815613C-581A-4EA8-92A8-F907E35F8BD4', N'2026-11-10 13:22:18.666666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'zhòngdiǎn'),
    (N'A2688055-EE07-5C1E-921A-B17178A23858', 4, N'值', NULL, N'zhí', N'đáng, có giá trị; trực (ban)', NULL, N'动、形', NULL, N'[{"chinese": "这本经典著作虽然读起来有一定难度，但认真读完绝对很值。", "pinyin": "Zhè běn jīngdiǎn zhùzuò suīrán dú qǐlái yǒu yídìng nándù, dàn rènzhēn dú wán juéduì hěn zhí.", "translation": "Cuốn trước tác kinh điển này tuy đọc có phần khó nhằn, nhưng đọc xong một cách nghiêm túc thì tuyệt đối rất đáng."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:17.090000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'zhí');
