    (N'8D589962-8811-45AC-A193-B18977A7115B', 2, N'红茶', NULL, N'hóngchá', N'trà đen, hồng trà', NULL, N'名', NULL, N'[{"zh": "英国人喜欢在下午喝红茶。", "pinyin": "Yīngguó rén xǐhuan zài xiàwǔ hē hóngchá.", "meaningVi": "Người Anh thích uống hồng trà vào buổi chiều."}]', N'ARCHIVED', NULL, N'2026-11-10 06:02:08.450000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'hóngchá'),
    (N'540897A5-5771-5BB5-B69B-B1A08A7D0819', 4, N'甚至', N'甚至', N'shèn zhì', N'thậm chí, ngay cả', N'even', N'连', NULL, N'[{"zh": "他对京剧艺术痴迷至极，甚至能一字不差地背诵好几出长篇大戏的戏词。", "pinyin": "Tā duì jīngjù yìshù chīmí zhìjí, shènzhì néng yí zì bú chà de bèisòng hǎojǐ chū chángpiān dàxì de xìcí.", "meaningVi": "Anh ấy đam mê nghệ thuật kinh kịch tột độ, thậm chí có thể đọc thuộc lòng từng chữ lời thoại của mấy vở diễn lớn dài tập."}]', N'PUBLISHED', N'1C92848C-099F-4B61-A466-F6381B0E9519', N'2026-11-10 13:22:17.856666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'shènzhì'),
    (N'C7C89D0A-4AFC-4DE3-A358-B1B38F40BEE9', 3, N'认真', N'認真', N'rèn zhēn', N'chăm chỉ, nghiêm túc', N'conscientious', N'形', NULL, N'[{"zh": "他每天都认真地完成老师布置的作业。", "pinyin": "Tā měitiān dōu rènzhēn de wánchéng lǎoshī bùzhì de zuòyè.", "meaningVi": "Ngày nào cậu ấy cũng chăm chỉ hoàn thành bài tập thầy giáo giao."}]', N'PUBLISHED', N'8740279E-4223-43BE-B424-9071F24126AE', N'2026-11-10 06:58:48.970000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'rènzhēn'),
    (N'3F7D353B-5843-4461-80B0-B1B7DF9A8CAB', 3, N'其实', N'其實', N'qí shí', N'kỳ thực, thực ra', N'actually', N'副', NULL, N'[{"zh": "其实这个问题没有你想的那么复杂。", "pinyin": "Qíshí zhè gè wèntí méiyǒu nǐ xiǎng de nàme fùzá.", "meaningVi": "Thực ra vấn đề này không phức tạp như bạn nghĩ đâu."}]', N'PUBLISHED', N'8740279E-4223-43BE-B424-9071F24126AE', N'2026-11-10 06:58:48.110000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'qíshí'),
    (N'FDC851ED-36D5-4A8F-89EB-B1CD382026A4', 3, N'换', N'換', N'huàn', N'đổi, thay đổi', N'to change', N'动', NULL, N'[{"zh": "我想把手里的外币换成人民币。", "pinyin": "Wǒ xiǎng bǎ shǒulǐ de wàibì huàn chéng rénmínbì.", "meaningVi": "Tôi muốn đổi số ngoại tệ trong tay sang nhân dân tệ."}]', N'PUBLISHED', N'522FC009-A8BB-411F-A048-62C62D56E649', N'2026-11-10 06:58:49.066666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'huàn'),
    (N'3896886E-4860-517A-8E97-B1D3EF054C5B', 4, N'酸', N'酸', N'suān', N'chua; đau nhức, ê ẩm; chua xót', N'sour', N'形', NULL, N'[{"zh": "爬完一整天的山路后，双腿感到有些酸痛，但心情格外舒畅。", "pinyin": "Pá wán yì zhěng tiān de shānlù hòu, shuāng tuǐ gǎndào yǒuxiē suāntòng, dàn xīnqíng géwài shūchàng.", "meaningVi": "Sau khi leo đường núi suốt cả ngày, hai chân cảm thấy hơi nhức mỏi nhưng tâm trạng lại vô cùng sảng khoái."}]', N'PUBLISHED', N'226C0C08-EE32-4846-B8F3-FED582E3F873', N'2026-11-10 13:22:17.646666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'suān'),
    (N'D661D443-4F05-4B92-AB30-B1E408A83922', 3, N'担心', N'擔心', N'dān xīn', N'lo lắng, băn khoăn', N'anxious', N'动', NULL, N'[{"zh": "别担心，医生说你的身体没有什么大问题。", "pinyin": "Bié dānxīn, yīshēng shuō nǐ de shēntǐ méiyǒu shénme dà wèntí.", "meaningVi": "Đừng lo lắng, bác sĩ nói cơ thể bạn không có vấn đề gì lớn đâu."}]', N'PUBLISHED', N'46BA2193-6813-47AD-B210-6379BC7B76E6', N'2026-11-10 06:58:48.890000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'dānxīn'),
    (N'BD51CCC2-5BBF-56E2-89DF-B1EDA3589E7B', 4, N'压', NULL, N'yā', N'đè, ép, đè nặng', NULL, N'动', NULL, N'[{"chinese": "沉重的工作和生活负担常常压得现代职场青年喘不过气来。", "pinyin": "Chénzhòng de gōngzuò hé shēnghuó fùdān chángcháng yā de xiàndài zhíchǎng qīngnián chuǎnbúguò qì lái.", "translation": "Gánh nặng công việc và cuộc sống trĩu nặng thường đè khiến thanh niên công sở hiện đại nghẹt thở."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:17.773333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'yā'),
    (N'5F962C18-77E2-4801-971B-B1EFB23887E9', 1, N'上', N'上', N'shàng', N'trên, lên, đi lên', N'on top', N'Danh từ / Động từ', NULL, N'[{"zh": "猫在椅子上。", "pinyin": "Māo zài yǐzi shang.", "meaningVi": "Con mèo ở trên ghế."}]', N'PUBLISHED', N'C1A616F0-FFE9-485D-8E5A-301EE014730A', N'2026-11-10 17:06:23.681988', N'2026-11-11 08:55:45.479656', N'175', N'上', N'', N'1', 84, N'HSK 2.0', N'175', NULL, NULL, NULL, NULL, N'Verified HSK 2.0 (THEMATIC_HSK20_MAPPING)', N'', N'shàng'),
    (N'023E46A2-FE4F-5819-84D4-B1F2A3675C29', 4, N'质量', N'質量', N'zhì liàng', N'chất lượng, phẩm chất', N'quality', N'名', NULL, N'[{"zh": "旅行的真正精髓不在于打卡景点的数量，而在于旅途中深度体验与感悟的文化质量。", "pinyin": "Lǚxíng de zhēnzhèng jīngsuǐ bú zàiyú dǎkǎ jǐngdiǎn de shùliàng, ér zàiyú lǚtú zhōng shēndù tǐyàn yǔ gǎnwù de wénhuà zhìliàng.", "meaningVi": "Tinh hoa thực sự của du lịch không nằm ở số lượng địa điểm tham quan chụp ảnh check-in, mà nằm ở chất lượng văn hóa của những trải nghiệm và cảm ngộ sâu sắc trong chuyến đi."}]', N'PUBLISHED', N'575F094F-5298-41BE-B343-46849DDB0E1E', N'2026-11-10 13:22:18.830000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'zhìliàng'),
    (N'EAD53A1C-AECA-4B66-BE2A-B200D06E16C9', 3, N'拿', N'㧱', N'ná', N'cầm, lấy', N'to hold', N'Động từ', NULL, N'[{"zh": "为了学好汉语，我们需要了解拿。", "pinyin": "Wèile xuéhǎo Hànyǔ, wǒmen xūyào liǎojiě ná.", "meaningVi": "Để học tốt tiếng Trung, chúng ta cần hiểu rõ cầm, lấy."}]', N'PUBLISHED', N'B9B9A099-644D-4591-821E-11620077739E', N'2026-11-11 10:10:25.304391', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary inserted cleanly', N'', N'ná'),
