    (N'1E488543-80F5-49CE-8ECB-BAC746B6F943', 3, N'为', NULL, N'wèi', N'vì, cho', NULL, N'介', NULL, N'[{"chinese": "大家都为你的成功感到高兴。", "pinyin": "Dàjiā dōu wèi nǐ de chénggōng gǎndào gāoxìng.", "translation": "Mọi người đều cảm thấy vui mừng vì sự thành công của bạn."}]', N'ARCHIVED', NULL, N'2026-11-10 06:58:48.233333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'wèi'),
