    (N'9F28D4D6-AC79-4458-9C54-BB06AD12B0F5', 3, N'选', NULL, N'xuǎn', N'chọn lựa, bầu chọn', NULL, N'动', NULL, N'[{"chinese": "在琳琅满目的书店里，他精心选购了几本语言学专著。", "pinyin": "Zài línlángmǎnmù de shūdiàn lǐ, tā jīngxīn xuǎngòu le jǐ běn yǔyánxué zhuānzhù.", "translation": "Trong hiệu sách phong phú đa dạng, anh ấy đã cẩn thận chọn mua vài cuốn chuyên khảo ngôn ngữ học."}]', N'ARCHIVED', NULL, N'2026-11-10 06:58:49.396666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'xuǎn'),
    (N'EC828187-17BB-5FEE-A8A0-BB1C95D7921B', 4, N'查看', NULL, N'chákàn', N'xem xét, kiểm tra, tra cứu', NULL, N'动', NULL, N'[{"chinese": "护林巡护员每天都要亲自步行深入林区深处，仔细查看红外野外相机拍摄记录的动物出没数据。", "pinyin": "Hùlín xúnhùyuán měitiān dōu yào qīnzì bùxíng shēnrù línqū shēnchù, zǐxì chákàn hóngwài yěwài xiàngjī pāishè jìlù de dòngwù chūmò shùjù.", "translation": "Nhân viên kiểm lâm tuần tra rừng mỗi ngày đều phải đích thân đi bộ sâu vào trong rừng, kiểm tra tỉ mỉ dữ liệu hoạt động của thú rừng do máy ảnh hồng ngoại ghi lại."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:18.616666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'chákàn'),
    (N'2A7E2500-E746-49A4-9C50-BB24AE4FF4D8', 3, N'脏', NULL, N'zāng', N'bẩn thỉu, dơ bẩn', NULL, N'形', NULL, N'[{"chinese": "在泥土里尽情玩耍后，小男孩的衣服弄得脏兮兮的。", "pinyin": "Zài nítǔ lǐ jìnqíng wánshuǎ hòu, xiǎo nánhái de yīfu nòng de zāngxīxī de.", "translation": "Sau khi chơi đùa thỏa thích trong bùn đất, quần áo của cậu bé lấm lem dơ bẩn."}]', N'ARCHIVED', NULL, N'2026-11-10 06:58:49.470000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'zāng'),
