    (N'AFFF1430-C60F-57CC-AC48-BC01E26B5205', 4, N'对方', NULL, N'duìfāng', N'đối phương, bên kia, phía đối diện', NULL, N'名', NULL, N'[{"chinese": "在沟通的过程中，我们要学会倾听并尊重对方的观点。", "pinyin": "Zài gōutōng de guòchéng zhōng, wǒmen yào xuéhuì qīngtīng bìng zūnzhòng duìfāng de guāndiǎn.", "translation": "Trong quá trình giao tiếp, chúng ta cần học cách lắng nghe và tôn trọng quan điểm của đối phương."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:17.370000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'duìfāng'),
    (N'3268FA41-6630-5D2D-9C9D-BC0A5AA57E38', 4, N'填写', NULL, N'tiánxiě', N'điền vào, viết vào biểu mẫu', NULL, N'动', NULL, N'[{"chinese": "家长在给孩子办理入学登记手续时，请务必如实详细地填写各项基本信息。", "pinyin": "Jiāzhǎng zài gěi háizi bànlǐ rùxué dēngjì shǒuxù shí, qǐng wùbì rúshí xiángxì de tiánxiě gè xiàng jīběn xìnxī.", "translation": "Khi làm thủ tục đăng ký nhập học cho con, phụ huynh xin vui lòng điền các thông tin cơ bản một cách trung thực và chi tiết."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:18.146666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'tiánxiě'),
    (N'71C83D0A-1841-5E2D-A68D-BC5E8DCBBF94', 4, N'性', NULL, N'xìng', N'tính, bản tính, tính chất', NULL, N'后缀', NULL, N'[{"chinese": "勇于探索未知的科学精神是推动人类文明不断向前发展的关键驱动性因素。", "pinyin": "Yǒngyú tànsuǒ wèizhī de kēxué jīngshén shì tuīdòng rénlèi wénmíng búduàn xiàng qián fāzhǎn de guānjiàn qūdòngxìng yīnsù.", "translation": "Tinh thần khoa học dũng cảm khám phá cái chưa biết là nhân tố thúc đẩy then chốt đưa văn minh nhân loại không ngừng tiến lên."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:16.023333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'xìng'),
