    (N'E550F190-D702-45BF-962D-D5A808B71376', 3, N'最好', NULL, N'zuìhǎo', N'tốt nhất là', NULL, N'副', NULL, N'[{"chinese": "感冒了最好多喝温开水，多休息。", "pinyin": "Gǎnmào le zuì hǎo duō hē wēnkāishuǐ, duō xiūxi.", "translation": "Bị cảm cúm tốt nhất là uống nhiều nước ấm và nghỉ ngơi nhiều."}]', N'ARCHIVED', NULL, N'2026-11-10 06:58:48.336666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'zuìhǎo'),
    (N'F505E2ED-ED70-4FF4-B507-D5B67545449F', 2, N'高中', NULL, N'gāozhōng', N'trường cấp 3, trung học phổ thông', NULL, N'名', NULL, N'[{"zh": "我们是高中同学。", "pinyin": "Wǒmen shì gāozhōng tóngxué.", "meaningVi": "Chúng tôi là bạn học cấp ba."}]', N'ARCHIVED', NULL, N'2026-11-10 06:02:08.156666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'gāozhōng'),
    (N'BE0B8480-7915-5369-A25E-D5B6E88A614F', 4, N'数', NULL, N'shù', N'con số, số lượng (shù)', NULL, N'名、数', NULL, N'[{"chinese": "在这个班级里，热爱阅读科普书籍的学生数占了全班总人数的大半以上。", "pinyin": "Zài zhè gè bānjí lǐ, rè''ài yuèdú kēpǔ shūjí de xuéshēng shù zhàn le quán bān zǒng rénshù de dà bàn yǐshàng.", "translation": "Trong lớp học này, số lượng học sinh yêu thích đọc sách khoa học phổ biến chiếm hơn một nửa tổng số học sinh cả lớp."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:18.183333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'shù'),
    (N'70042621-DAF8-5EB2-B6A0-D5CC2747B641', 4, N'偶尔', N'偶爾', N'ǒu''ěr', N'thỉnh thoảng, đôi khi', N'occasionally', N'副、形', NULL, N'[{"zh": "虽然平日里科研工作十分繁忙，但他周末偶尔也会打一场羽毛球放松身心。", "pinyin": "Suīrán píngrì lǐ kēyán gōngzuò shífēn fánmáng, dàn tā zhōumò ǒu''ěr yě huì dǎ yì chǎng yǔmáoqiú fàngsōng shēnxīn.", "meaningVi": "Tuy ngày thường công việc nghiên cứu rất bận rộn, nhưng cuối tuần thỉnh thoảng anh ấy cũng chơi một trận cầu lông để thư giãn tâm thân."}]', N'PUBLISHED', N'362CB9D4-5F0C-4C98-A09B-BC3EBFCDBAA3', N'2026-11-10 13:22:15.856666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'ǒuěr'),
    (N'0E4817C3-8CEA-411C-B5A6-D5CE810E5898', 3, N'得到', NULL, N'dédào', N'nhận được, đạt được', NULL, N'动', NULL, N'[{"chinese": "通过努力，他得到了大家的认可和帮助。", "pinyin": "Tōngguò nǔlì, tā dédào le dàjiā de rènkě hé bāngzhù.", "translation": "Nhờ nỗ lực, cậu ấy đã nhận được sự công nhận và giúp đỡ của mọi người."}]', N'ARCHIVED', NULL, N'2026-11-10 06:58:48.490000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'dédào'),
    (N'DBF6824E-D058-4C22-81C5-D5D92EC808A7', 3, N'员', NULL, N'yuán', N'thành viên, nhân viên', NULL, N'后缀', NULL, N'[{"chinese": "作为志愿者团队的一员，他全心全意服务社区。", "pinyin": "Zuòwéi zhìyuànzhě tuánduì de yì yuán, tā quánxīnquányì fúwù shèqū.", "translation": "Là một thành viên của đội tình nguyện, cậu ấy toàn tâm toàn ý phục vụ cộng đồng."}]', N'ARCHIVED', NULL, N'2026-11-10 06:58:49.246666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'yuán'),
    (N'9B166E5D-A646-4A3C-B194-D5EB153A249E', 2, N'饭馆', NULL, N'fànguǎn', N'nhà hàng, quán ăn', NULL, N'名', NULL, N'[{"zh": "学校旁边有一家很有名川菜饭馆。", "pinyin": "Xuéxiào pángbiān yǒu yì jiā hěn yǒumíng Chuāncài fànguǎn.", "meaningVi": "Bên cạnh trường học có một quán ăn món Tứ Xuyên rất nổi tiếng."}]', N'ARCHIVED', NULL, N'2026-11-10 06:02:08.513333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'fànguǎn'),
    (N'80EE6578-F1E6-4A0C-ABFD-D5ED640356D9', 2, N'打车', NULL, N'dǎchē', N'bắt taxi, đi taxi', NULL, N'动', NULL, N'[{"zh": "时间快来不及了，我们打车去吧。", "pinyin": "Shíjiān kuài láibùjí le, wǒmen dǎchē qù ba.", "meaningVi": "Sắp không kịp thời gian rồi, chúng ta đi taxi thôi."}]', N'ARCHIVED', NULL, N'2026-11-10 06:02:08.420000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'dǎchē'),
    (N'4319D5B5-296B-50E4-9CB8-D5F977F00DA1', 4, N'底', N'底', N'dǐ', N'đáy, phần dưới; cuối (tháng/năm) (dǐ)', N'background', N'名', NULL, N'[{"zh": "每年十月底秋风拂过的时候，九寨沟清澈见底的湖水与漫山遍野的彩林交相辉映。", "pinyin": "Měinián shí yuè dǐ qiūfēng fúguò de shíhou, Jiǔzhàigōu qīngchè jiàn dǐ de húshuǐ yǔ mànshān-biànyě de cǎilín jiāoxiāng-huìyìng.", "meaningVi": "Mỗi năm vào cuối tháng mười khi gió thu lướt qua, làn nước trong vắt nhìn tận đáy hồ Cửu Trại Câu cùng rừng cây rực rỡ khắp non ngàn hòa quyện phản chiếu lẫn nhau tuyệt đẹp."}]', N'PUBLISHED', N'E7F82F5D-5ED2-440B-8369-FE116EE51ABC', N'2026-11-10 13:22:18.740000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'dǐ'),
    (N'1E7D6796-BF43-57A7-9E64-D603A41686BE', 4, N'低', NULL, N'dī', N'thấp, cúi xuống', NULL, N'形、动', NULL, N'[{"chinese": "遇到挫折时不要灰心丧气，更不要轻易低下头颅。", "pinyin": "Yùdào cuòzhé shí bú yào huīxīnsàngqì, gèng bú yào qīngyì dī xià tóulú.", "translation": "Khi gặp khó khăn chớ có nản lòng thoái chí, càng không nên dễ dàng cúi đầu."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:15.716666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'dī'),
    (N'E8897D58-2742-5283-8135-D60A00835587', 4, N'速度', N'速度', N'sù dù', N'tốc độ, vận tốc', N'speed', N'名', NULL, N'[{"zh": "高铁以每小时三百五十公里的高速平稳穿行在辽阔的华北平原上。", "pinyin": "Gāotiě yǐ měi xiǎoshí sānbǎi wǔshí gōnglǐ de gāosù píngwěn chuānxíng zài liáokuò de huáběi píngyuán shang.", "meaningVi": "Tàu cao tốc chạy êm ái với tốc độ ba trăm năm mươi cây số một giờ trên đồng bằng Hoa Bắc bao la."}]', N'PUBLISHED', N'226C0C08-EE32-4846-B8F3-FED582E3F873', N'2026-11-10 13:22:15.960000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'sùdù'),
    (N'39C8DE46-39CF-5415-A35B-D60E5BDEDD50', 4, N'粗', NULL, N'cū', N'thô, to; bất cẩn, sơ sài', NULL, N'形', NULL, N'[{"chinese": "在翻译文学作品时切忌粗枝大叶，必须细致斟酌每一个词句背后的文化内涵。", "pinyin": "Zài fānyì wénxué zuòpǐn shí qièjì cūzhī-dàyè, bìxū xìzhì zhēnzhuó měi yí gè cíjù bèihòu de wénhuà nèihán.", "translation": "Khi dịch tác phẩm văn học chớ nên sơ sài cẩu thả, cần phải cân nhắc tỉ mỉ hàm ý văn hóa đằng sau mỗi câu mỗi chữ."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:18.373333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'cū'),
    (N'30DD9A0F-8AE4-48E9-B8D5-D63082B3282A', 3, N'相同', N'相同', N'xiāng tóng', N'giống nhau, tương đồng', N'identical', N'形', NULL, N'[{"zh": "尽管来自完全不同的文化背景，但他们对美好艺术的追求是完全相同的。", "pinyin": "Jǐnguǎn láizì wánquán bù tóng de wénhuà bèijǐng, dàn tāmen duì měihǎo yìshù de zhuīqiú shì wánquán xiāngtóng de.", "meaningVi": "Dù đến từ những nền văn hóa hoàn toàn khác biệt, nhưng khát vọng theo đuổi nghệ thuật cái đẹp của họ lại hoàn toàn giống nhau."}]', N'PUBLISHED', N'8DA33634-03F8-4F90-9BF6-86AC2A793D7D', N'2026-11-11 10:10:25.304391', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary inserted cleanly', N'', N'xiāngtóng'),
    (N'C6994B40-448E-44C3-AC4C-D6662F76DDAD', 2, N'唱歌', N'唱歌', N'chàng gē', N'hát, ca hát', N'to sing a song', N'Động từ / Danh động từ', NULL, N'[{"zh": "他每天都用唱歌。", "pinyin": "Tā měitiān dōu yòng chàng.", "meaningVi": "Anh ấy mỗi ngày đều dùng to sing a song (唱歌)."}]', N'PUBLISHED', N'AFE42FE5-7D93-47A6-B77B-447DAD1E36F6', N'2026-11-11 10:10:25.304391', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary inserted cleanly', N'', N'chànggē'),
    (N'FEFEDE1F-7AC6-5718-85BF-D66CDE898F5A', 4, N'座位', N'座位', N'zuò wèi', N'chỗ ngồi', N'seat', N'名', NULL, N'[{"zh": "乘坐公共交通工具时，我们应当自觉主动为老幼病残让出爱心座位。", "pinyin": "Chéngzuò gōnggòng jiāotōng gōngjù shí, wǒmen yīngdāng zìjué zhǔdòng wèi lǎoyòubìngcán ràng chū àixīn zuòwèi.", "meaningVi": "Khi đi phương tiện giao thông công cộng, chúng ta nên tự giác chủ động nhường chỗ ngồi ưu tiên cho người già, trẻ nhỏ và người tàn tật."}]', N'PUBLISHED', N'3815613C-581A-4EA8-92A8-F907E35F8BD4', N'2026-11-10 13:22:15.893333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'zuòwèi'),
    (N'80E4CFC1-0388-4579-AE53-D6948BAECA66', 3, N'又', N'又', N'yòu', N'lại (hành động đã lặp lại)', N'(once) again', N'副', NULL, N'[{"zh": "今天你怎么又迟到了？", "pinyin": "Jīntiān nǐ zěnme yòu chídào le?", "meaningVi": "Hôm nay sao bạn lại đi muộn nữa thế?"}]', N'PUBLISHED', N'084119FC-96CC-4DD6-90AA-DE3C1CF66CCA', N'2026-11-10 06:58:48.243333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'yòu'),
    (N'4A0FB20D-E405-5E28-A1A6-D69D9BA2D438', 4, N'多么', NULL, N'duōme', N'biết bao, biết chừng nào', NULL, N'副', NULL, N'[{"chinese": "在异国他乡遇到多年未见的老同学，心情是多么激动！", "pinyin": "Zài yìguótāxiāng yùdào duō nián wèi jiàn de lǎo tóngxué, xīnqíng shì duōme jīdòng!", "translation": "Tại nơi đất khách quê người gặp lại bạn học cũ nhiều năm chưa gặp, tâm trạng xúc động biết bao!"}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:15.746666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'duōme'),
