    (N'5FB50EC9-59B2-4303-A3E8-E295A063B57A', 3, N'鼻子', N'鼻子', N'bí zi', N'mũi, chiếc mũi', N'nose', N'名', NULL, N'[{"zh": "科学家最新研制的人造仿生电子鼻子，能够敏锐探测出空气中极其微量的有毒有害化学气体泄漏。", "pinyin": "Kēxuéjiā zuìxīn yánzhì de rénzào fǎngshēng diànzǐ bízi, nénggòu mǐnruì tàncè chū kōngqì zhōng jíqí wēiliàng de yǒudú yǒuhài huàxué qìtǐ xièlòu.", "meaningVi": "Chiếc mũi điện tử phỏng sinh học nhân tạo mới nhất do các nhà khoa học chế tạo có thể nhạy bén phát hiện ra lượng khí hóa học độc hại rò rỉ cực nhỏ trong không khí."}]', N'PUBLISHED', N'B8B44E04-3823-441C-B43C-88E473DEDCE4', N'2026-11-11 10:10:25.304391', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary inserted cleanly', N'', N'bízi'),
    (N'1D7C731A-F3F6-4473-9D9B-E2AA12AC6041', 1, N'昨天', N'昨天', N'zuó tiān', N'hôm qua', N'yesterday', N'Danh từ', NULL, N'[{"zh": "昨天我去看电影了。", "pinyin": "Zuótiān wǒ qù kàn diànyǐng le.", "meaningVi": "Hôm qua tôi đi xem phim."}]', N'PUBLISHED', N'9F74EEE4-2746-4EFC-A1F2-3402079AB3EF', N'2026-11-10 17:06:23.682028', N'2026-11-11 08:55:45.514939', N'297', N'昨天', N'', N'1', 87, N'HSK 2.0', N'297', NULL, NULL, NULL, NULL, N'Verified HSK 2.0 (DIALOGUE_TEXT_MATCH)', N'', N'zuótiān'),
    (N'868F7F2D-ACEB-5B19-9B44-E2AD3C50EDC6', 4, N'顺便', N'順便', N'shùn biàn', N'tiện thể, nhân tiện', N'conveniently', N'副', NULL, N'[{"zh": "你下班回家的路上，请顺便在街口的特产店买一盒正宗的西湖龙井绿茶。", "pinyin": "Nǐ xiàbān huíjiā de lùshang, qǐng shùnbiàn zài jiēkǒu de tèchǎndiàn mǎi yì hé zhèngzōng de Xīhú Lóngjǐng lǜchá.", "meaningVi": "Trên đường tan làm về nhà, bạn nhân tiện ghé tiệm đặc sản đầu phố mua một hộp trà xanh Long Tỉnh Tây Hồ chính hiệu nhé."}]', N'PUBLISHED', N'226C0C08-EE32-4846-B8F3-FED582E3F873', N'2026-11-10 13:22:17.910000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'shùnbiàn'),
    (N'F8EB4DF5-F7D9-45EB-AA96-E2C8116D9752', 3, N'初中', NULL, N'chūzhōng', N'trường cấp hai, trung học cơ sở', NULL, N'名', NULL, N'[{"chinese": "她初中毕业后以优异成绩考入了重点高中。", "pinyin": "Tā chūzhōng bìyè hòu yǐ yōuyì chéngjì kǎorù le zhòngdiǎn gāozhōng.", "translation": "Sau khi tốt nghiệp cấp hai, cô ấy đã đỗ vào trường cấp ba trọng điểm với thành tích xuất sắc."}]', N'ARCHIVED', NULL, N'2026-11-10 06:58:49.163333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'chūzhōng');
