    (N'AB55146E-AE56-4EC6-896F-E648BAF92377', 4, N'马虎', N'馬虎', N'mǎ hu', N'qua loa, cẩu thả', N'careless', N'a / an', NULL, N'[{"zh": "考试的时候不能马虎，一定要仔细检查。", "pinyin": "Kǎoshì de shíhou bù néng mǎhu, yídìng yào zǐxì jiǎnchá.", "meaningVi": "Khi làm bài thi không được cẩu thả, nhất định phải kiểm tra thật kỹ."}]', N'PUBLISHED', N'C27413F4-ADC8-436F-9436-1530C708008E', N'2026-11-11 10:10:25.304391', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary inserted cleanly', N'', N'mǎhu'),
    (N'FC12E0EF-8699-5092-B4AE-E659ED2588CC', 4, N'厨师', NULL, N'chúshī', N'đầu bếp', NULL, N'名', NULL, N'[{"chinese": "未来的餐厅里，智能烹饪机器人将与五星级专业厨师协同配合，制作出兼顾营养与美味的特色佳肴。", "pinyin": "Wèilái de cāntīng lǐ, zhìnéng pēngrèn jīqìrén jiāng yǔ wǔxīngjí zhuānyè chúshī xiétóng pèihé, zhìzuò chū jiāngù yíngyǎng yǔ měiwèi de tèsè jiāyáo.", "translation": "Trong các nhà hàng tương lai, robot nấu nướng thông minh sẽ hiệp đồng phối hợp với các đầu bếp chuyên nghiệp chuẩn 5 sao để chế biến ra những món ăn đặc sắc vừa bổ dưỡng vừa thơm ngon."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:18.893333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'chúshī'),
    (N'9ECC2F5F-740F-5C90-96F7-E689F06B15A6', 4, N'气', NULL, N'qì', N'khí, hơi; tức giận', NULL, N'名、动', NULL, N'[{"chinese": "深秋的早晨呼吸着新鲜的空气，整个人都觉得神清气爽。", "pinyin": "Shēnqiū de zǎochen hūxīzhe xīnxiān de kōngqì, zhěng gè rén dōu juéde shénqīng qìshuǎng.", "translation": "Buổi sáng sớm cuối thu hít thở không khí trong lành, cả người đều cảm thấy sảng khoái dễ chịu."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:16.836666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'qì'),
    (N'3045E654-2EE3-4FAB-B765-E68B59DA75BC', 1, N'杯子', N'杯子', N'bēi zi', N'cái cốc, cái ly', N'cup', N'Danh từ', NULL, N'[{"zh": "桌上有一个杯子。", "pinyin": "Zhuō shàng yǒu yí gè bēizi.", "meaningVi": "Trên bàn có một cái cốc."}]', N'PUBLISHED', N'9C981888-67BD-41BB-B5B0-57D0A1268DD6', N'2026-11-10 17:06:23.681422', N'2026-11-11 08:55:45.403979', N'9', N'杯子', N'', N'1', 80, N'HSK 2.0', N'9', NULL, NULL, NULL, NULL, N'Verified HSK 2.0 (THEMATIC_HSK20_MAPPING)', N'', N'bēizi'),
    (N'D139BB4D-1153-5079-9C92-E6C7698E704A', 4, N'粗心', N'粗心', N'cū xīn', N'sơ ý, cẩu thả, bất cẩn', N'careless', N'形', NULL, N'[{"zh": "在编写航空航天控制软件时绝不能有一丝一毫的粗心大意，否则可能酿成严重事故。", "pinyin": "Zài biānxiě hángkōng hángtiān kòngzhì ruǎnjiàn shí jué bù néng yǒu yì sī yì háo de cūxīn-dàyì, fǒuzé kěnéng niàngchéng yánzhòng shìgù.", "meaningVi": "Khi viết phần mềm điều khiển hàng không vũ trụ tuyệt đối không được có một chút sơ ý bất cẩn nào, nếu không có thể gây ra tai nạn nghiêm trọng."}]', N'PUBLISHED', N'C6B083F2-715D-4E95-A8FC-4A0414E25C30', N'2026-11-10 13:22:18.496666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'cūxīn'),
    (N'1C544626-9D1F-59D3-A0CB-E6D8121C6A04', 4, N'材料', N'材料', N'cái liào', N'tài liệu; nguyên vật liệu', N'material', N'名', NULL, N'[{"zh": "撰写这篇历史学术论文需要查阅大量的古籍一手文献材料。", "pinyin": "Zhuànxiě zhè piān lìshǐ xuéshù lùnwén xūyào cháyuè dàliàng de gǔjí yīshǒu wénxiàn cáiliào.", "meaningVi": "Viết bài báo học thuật lịch sử này đòi hỏi phải tra cứu một lượng lớn tài liệu văn hiến gốc từ cổ tịch."}]', N'PUBLISHED', N'C6B083F2-715D-4E95-A8FC-4A0414E25C30', N'2026-11-10 13:22:17.230000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'cáiliào'),
    (N'AD5D6B6F-FDB0-40D3-9F40-E6E6EF942566', 2, N'阴', N'陰', N'yīn', N'âm u, râm', N'overcast (weather)', N'a / g', NULL, N'[{"zh": "他每天都用阴。", "pinyin": "Tā měitiān dōu yòng yīn.", "meaningVi": "Anh ấy mỗi ngày đều dùng âm u, râm."}]', N'PUBLISHED', N'7FB11B06-A247-43A7-8A74-1A73A796D060', N'2026-11-10 06:02:08.380000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'yīn'),
    (N'6B0A0684-C464-5F65-A4B4-E70E659C8062', 4, N'误会', N'誤會', N'wù huì', N'hiểu lầm', N'to misunderstand', N'动、名', NULL, N'[{"zh": "只要大家坦诚交流，许多不必要的误会都可以迎刃而解。", "pinyin": "Zhǐyào dàjiā tǎnchéng jiāoliú, xǔduō bú bìyào de wùhuì dōu kěyǐ yíngrèn''érjiě.", "meaningVi": "Chỉ cần mọi người giao tiếp chân thành, nhiều hiểu lầm không đáng có đều có thể được giải quyết dễ dàng."}]', N'PUBLISHED', N'90A35972-4CD6-46CB-8FC0-FF111D8DFB71', N'2026-11-10 13:22:16.376666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'wùhuì'),
    (N'13ADB598-C182-51E7-98DB-E7367A48BBF9', 4, N'午餐', NULL, N'wǔcān', N'bữa trưa', NULL, N'名', NULL, N'[{"chinese": "中午十二点，公司员工们结伴前往附近餐厅享用午餐。", "pinyin": "Zhōngwǔ shí''èr diǎn, gōngsī yuángōngmen jiébàn qiánwǎng fùjìn cāntīng xiǎngyòng wǔcān.", "translation": "12 giờ trưa, nhân viên công ty cùng nhau đến nhà hàng gần đó thưởng thức bữa trưa."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:15.733333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'wǔcān'),
    (N'3BEB6AF7-46CC-50C7-9A6A-E7859EC67AE2', 4, N'早晨', NULL, N'zǎochen', N'buổi sáng sớm, sớm mai', NULL, N'名', NULL, N'[{"chinese": "每天早晨迎着初升的朝阳跑跑步、呼吸新鲜空气，能为一整天的工作注入充沛的精力与活力。", "pinyin": "Měitiān zǎochen yíng zhe chū shēng de zhāoyáng pǎopǎobù, hūxī xīnxiān kōngqì, néng wèi yì zhěng tiān de gōngzuò zhùrù chōngpèi de jīnglì yǔ huólì.", "translation": "Mỗi buổi sáng sớm đón ánh mặt trời vừa lên chạy bộ, hít thở không khí trong lành có thể tiếp thêm nguồn sinh lực và năng lượng dồi dào cho cả ngày dài làm việc."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:18.950000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'zǎochen'),
    (N'43AB28B4-58C8-4CD7-A1FB-E787A84CA37E', 3, N'笔记本', NULL, N'bǐjìběn', N'vở ghi chép; máy tính xách tay', NULL, N'名', NULL, N'[{"chinese": "他在笔记本上认真地记录了老师讲的要点。", "pinyin": "Tā zài bǐjìběn shang rènzhēn de jìlù le lǎoshī jiǎng de yàodiǎn.", "translation": "Cậu ấy đã cẩn thận ghi lại các trọng điểm thầy giảng vào cuốn sổ tay."}]', N'ARCHIVED', NULL, N'2026-11-10 06:58:48.906666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'bǐjìběn'),
    (N'AEC010E6-E71A-5F58-993D-E7F54A1F57FC', 4, N'友情', NULL, N'yǒuqíng', N'tình bạn', NULL, N'名', NULL, N'[{"chinese": "真挚的友情需要彼此用真诚和理解来长期维系。", "pinyin": "Zhēnzhì de yǒuqíng xūyào bǐcǐ yòng zhēnchéng hé lǐjiě lái chángqī wéixì.", "translation": "Tình bạn chân thành cần đôi bên dùng sự chân thật và thấu hiểu để duy trì lâu dài."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:16.276666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'yǒuqíng'),
    (N'2ECE966C-1676-4F57-B02D-E82972C1ED67', 1, N'做', N'做', N'zuò', N'làm, chế tạo', N'to do', N'Động từ', NULL, N'[{"zh": "你在做什么？", "pinyin": "Nǐ zài zuò shénme?", "meaningVi": "Bạn đang làm gì vậy?"}]', N'PUBLISHED', N'AAAAAAAA-2222-2222-2222-222222222222', N'2026-11-10 17:06:23.682029', N'2026-11-11 08:55:45.514939', N'299', N'做', N'', N'1', 87, N'HSK 2.0', N'299', NULL, NULL, NULL, NULL, N'Verified HSK 2.0 (DIALOGUE_TEXT_MATCH)', N'', N'zuò'),
    (N'830DF64D-C033-5EDB-A594-E830075D7A1F', 4, N'体温', NULL, N'tǐwēn', N'nhiệt độ cơ thể, thân nhiệt', NULL, N'名', NULL, N'[{"chinese": "护士每天早晨都会来到病房，为住院病人测量体温。", "pinyin": "Hùshi měitiān zǎochén dōuhuì láidào bìngfáng, wèi zhùyuàn bìngrén cèliáng tǐwēn.", "translation": "Y tá mỗi buổi sáng đều đến phòng bệnh đo thân nhiệt cho các bệnh nhân nội trú."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:16.410000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'tǐwēn'),
    (N'80D40A54-29F6-5C3F-83D6-E871F17A8F67', 4, N'降温', NULL, N'jiàngwēn', N'hạ nhiệt, giảm nhiệt, trở lạnh', NULL, N'动', NULL, N'[{"chinese": "气象台发布了寒潮蓝色预警，预计明天夜间全市气温将明显降温六到八度。", "pinyin": "Qìxiàngtái fābù le háncháo lánsè yùjǐng, yùjì míngtiān yèjiān quán shì qìwēn jiāng míngxiǎn jiàngwēn liù dào bā dù.", "translation": "Đài khí tượng đã phát đi cảnh báo màu xanh về đợt không khí lạnh, dự kiến đêm mai nhiệt độ toàn thành phố sẽ hạ nhiệt rõ rệt từ sáu đến tám độ."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:18.253333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'jiàngwēn'),
    (N'316921B2-F815-45A5-B543-E89D46069900', 2, N'但', NULL, N'dàn', N'nhưng, nhưng mà', NULL, N'连、（副）', NULL, N'[{"zh": "汉语虽然难，但我很喜欢。", "pinyin": "Hànyǔ suīrán nán, dàn wǒ hěn xǐhuan.", "meaningVi": "Tiếng Hán tuy khó, nhưng tôi rất thích."}]', N'ARCHIVED', NULL, N'2026-11-10 06:02:08.250000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'dàn'),
    (N'CF5E4EEF-5F12-5A80-82F3-E8A06125982B', 4, N'工人', NULL, N'gōngrén', N'công nhân', NULL, N'名', NULL, N'[{"chinese": "车间里的工人们正一丝不苟地操作机器，保质保量完成生产任务。", "pinyin": "Chējiān lǐ de gōngrénmen zhèng yìsībùgǒu de cāozuò jīqì, bǎozhì-bǎoliàng wánchéng shēngchǎn rènwu.", "translation": "Các công nhân trong phân xưởng đang thao tác máy móc một cách tỉ mỉ, hoàn thành nhiệm vụ sản xuất bảo đảm cả chất lẫn lượng."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:16.930000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'gōngrén');
