    (N'58BA2BC2-6103-4BBB-A12B-ED76AFD88384', 2, N'件', N'件', N'jiàn', N'chiếc, cái (lượng từ quần áo, sự việc)', N'item', N'Lượng từ', NULL, N'[{"zh": "我想买一件衣服。", "pinyin": "Wǒ xiǎng mǎi yí jiàn yīfu.", "meaningVi": "Tôi muốn mua một bộ quần áo."}]', N'PUBLISHED', N'795A5C2A-A5C2-4579-A762-053840DD8373', N'2026-11-11 10:10:25.304391', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary inserted cleanly', N'', N'jiàn'),
    (N'CAA5F981-6259-4B7F-BB67-ED80DFF61D38', 2, N'公交车', NULL, N'gōngjiāochē', N'xe buýt công cộng', NULL, N'名', NULL, N'[{"zh": "我每天早上坐公交车去学校。", "pinyin": "Wǒ měitiān zǎoshang zuò gōngjiāochē qù xuéxiào.", "meaningVi": "Mỗi sáng tôi đều đi xe buýt đến trường."}]', N'ARCHIVED', NULL, N'2026-11-10 06:02:08.330000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'gōngjiāochē'),
    (N'445B08E5-6C50-5EB9-A93C-ED9FA5EE6B5A', 4, N'少数', NULL, N'shǎoshù', N'thiểu số, số ít', NULL, N'名', NULL, N'[{"chinese": "虽然大多数人持赞同意见，但我们也应当充分倾听并尊重少数人的不同声音。", "pinyin": "Suīrán dà duōshù rén chí zàntóng yìjiàn, dàn wǒmen yě yīngdāng chōngfèn qīngtīng bìng zūnzhòng shǎoshù rén de bù tóng shēngyīn.", "translation": "Tuy đại đa số mọi người tán thành, nhưng chúng ta cũng nên lắng nghe thấu đáo và tôn trọng tiếng nói khác biệt của số ít."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:16.013333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'shǎoshù'),
    (N'69454FA4-0BBC-53F1-AC15-EDCF3EDF0E25', 4, N'抱', N'抱', N'bào', N'ôm, ôm ấp', N'to hold', N'动', NULL, N'[{"zh": "分别两年的老朋友在火车站台上紧紧相抱，喜极而泣。", "pinyin": "Fēnbié liǎng nián de lǎo péngyou zài huǒchēzhàn tái shang jǐnjǐn xiāngbào, xǐ jí ér qì.", "meaningVi": "Đôi bạn cũ chia tay hai năm gặp lại trên sân ga siết chặt nhau ôm ấp, mừng đến rơi nước mắt."}]', N'PUBLISHED', N'1E19300E-0BA0-4EA1-9D52-2247C8892171', N'2026-11-10 13:22:16.026666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'bào'),
    (N'E9F3D5D8-6C1A-5240-B8F9-EDDBB0C143D9', 4, N'连', N'連', N'lián', N'ngay cả, đến cả (连...都...)', N'to link', N'介、（动、副）', NULL, N'[{"zh": "他今天身体实在太虚弱了，生病难受得连平时最喜欢吃的冰激凌都一口不碰。", "pinyin": "Tā jīntiān shēntǐ shízài tài xūruò le, shēngbìng nánshòu de lián píngshí zuì xǐhuan chī de bīngjīlíng dōu yì kǒu bù pèng.", "meaningVi": "Hôm nay cơ thể cậu ấy thực sự quá yếu ớt, ốm mệt đến mức ngay cả món kem ngày thường thích ăn nhất cũng không buồn động một miếng."}]', N'PUBLISHED', N'C27413F4-ADC8-436F-9436-1530C708008E', N'2026-11-10 13:22:18.246666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'lián'),
    (N'514491F1-2B90-529F-A8B8-EE010ED4327F', 4, N'汽水', NULL, N'qìshuǐ', N'nước ngọt có ga, nước soda', NULL, N'名', NULL, N'[{"chinese": "炎热的夏天在实验室工作了一整天，下班后喝上一罐冰镇柠檬汽水真是让人倍感清爽。", "pinyin": "Yánrè de xiàtiān zài shíyànshì gōngzuò le yì zhěng tiān, xiàbān hòu hē shang yí guàn bīngzhèn níngméng qìshuǐ zhēn shì ràng rén bèi gǎn qīngshuǎng.", "translation": "Mùa hè nóng bức làm việc suốt cả ngày trong phòng thí nghiệm, sau khi tan tầm uống một lon nước ngọt chanh ướp lạnh quả thật khiến người ta cảm thấy vô cùng sảng khoái."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:18.483333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'qìshuǐ'),
    (N'E4E7C320-D291-5DC1-B31B-EE025E8FD01B', 4, N'排', NULL, N'pái', N'hàng, dãy; sắp xếp; xả (nước thải)', NULL, N'动、名、量', NULL, N'[{"chinese": "在蜿蜒的小溪两旁，整整齐齐地生长着一排排茂密翠绿的天然垂柳与杨树。", "pinyin": "Zài wānyán de xiǎoxī liǎngpáng, zhěngzhěng-qíqí de shēngzhǎng zhe yì pái pái màomì cuìlǜ de tiānrán chuíliǔ yǔ yángshù.", "translation": "Hai bên bờ con suối nhỏ uốn lượn mọc lên từng hàng từng dãy liễu rủ và cây dương tự nhiên xanh biếc rậm rạp hết sức ngay ngắn."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:18.603333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'pái'),
    (N'874288E3-4F4D-5872-BCC2-EE0601414742', 4, N'推', N'推', N'tuī', N'đẩy, đùn đẩy', N'to push', N'动', NULL, N'[{"zh": "轻轻推开书房明净的木门，满屋古雅的书香之气迎面扑来。", "pinyin": "Qīngqīng tuī kāi shūfáng míngjìng de mùmén, mǎn wū gǔyǎ de shūxiāng zhī qì yíngmiàn pū lái.", "meaningVi": "Khẽ đẩy cánh cửa gỗ sáng bóng của phòng đọc, hương thơm sách vở cổ kính tao nhã khắp phòng ùa tới."}]', N'PUBLISHED', N'D551AD89-18F8-417A-BC0F-0FCBD23C1448', N'2026-11-10 13:22:15.903333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'tuī'),
    (N'5BA41421-4E7F-5703-A17F-EE1C14037A5F', 4, N'转发', NULL, N'zhuǎnfā', N'chuyển tiếp, chia sẻ bài đăng', NULL, N'动', NULL, N'[{"chinese": "这条关于普及心肺复苏急救常识的科普博文被广大网友迅速转发了数万次。", "pinyin": "Zhè tiáo guānyú pǔjí xīnfèi fùsū jíjiù chángshí de kēpǔ bówén bèi guǎngdà wǎngyǒu xùnsù zhuǎnfā le shù wàn cì.", "translation": "Bài viết phổ biến kiến thức cấp cứu hồi sinh tim phổi này đã được đông đảo cư dân mạng chia sẻ nhanh chóng hàng vạn lượt."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:15.956666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'zhuǎnfā'),
    (N'902E1C45-CBEE-532A-B7B5-EE70FFA45C0B', 4, N'旅行', NULL, N'lǚxíng', N'du lịch', NULL, N'动', NULL, N'[{"chinese": "利用难得的年假时光，他和家人一起去风景秀丽的云南旅行。", "pinyin": "Lìyòng nándé de niánjià shíguāng, tā hé jiārén yìqǐ qù fēngjǐng xiùlì de Yúnnán lǚxíng.", "translation": "Tận dụng kỳ nghỉ phép năm hiếm có, anh ấy cùng người nhà đi du lịch Vân Nam nơi phong cảnh hữu tình."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:16.653333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'lǚxíng'),
    (N'74C20C57-01EE-5B25-B48A-EEBC0D304C4B', 4, N'嗯', NULL, N'ǹg', N'ừ, vâng, ừm (thán từ biểu thị đồng ý hoặc đáp lời)', NULL, N'叹', NULL, N'[{"chinese": "“嗯，你说得很有道理，我们可以按照这个建议去修改方案。”", "pinyin": "“Ǹg, nǐ shuō de hěn yǒu dàolǐ, wǒmen kěyǐ ànzhào zhè gè jiànyì qù xiūgǎi fāng''àn.”", "translation": "“Ừm, bạn nói rất có lý, chúng ta có thể sửa đổi phương án theo đề xuất này.”"}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:17.353333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'ǹg'),
