    (N'D71528C7-2652-5026-89AB-EEE8007DAA62', 4, N'查找', NULL, N'cházhǎo', N'tra cứu, tìm kiếm', NULL, N'动', NULL, N'[{"chinese": "借助数字图书馆的高效检索算法，读者可以在几秒钟内精准查找到所需的科研论文资料。", "pinyin": "Jièzhù shùzì túshūguǎn de gāoxiào jiǎnsuǒ suànfǎ, dúzhě kěyǐ zài jǐ miǎozhōng nèi jīngzhǔn cházhǎo dào suǒ xū de kēyán lùnwén zīliào.", "translation": "Nhờ thuật toán tìm kiếm hiệu quả cao của thư viện số, độc giả có thể tra cứu chuẩn xác tài liệu bài báo nghiên cứu khoa học cần thiết chỉ trong vài giây."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:18.480000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'cházhǎo'),
    (N'5F6E3D05-A4AB-5C6B-8FED-EF0711D8F810', 4, N'忽然', N'忽然', N'hū rán', N'đột nhiên, bỗng nhiên', N'suddenly', N'副', NULL, N'[{"zh": "正在看书时，窗外忽然刮起了一阵猛烈的大风。", "pinyin": "Zhèngzài kàn shū shí, chuāngwài hūrán guā qǐ le yí zhèn měngliè de dàfēng.", "meaningVi": "Khi đang đọc sách, ngoài cửa sổ bỗng nhiên nổi lên một cơn gió lớn dữ dội."}]', N'PUBLISHED', N'95268DAC-D50C-442A-8436-85C845D1C72F', N'2026-11-10 13:22:15.623333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'hūrán'),
