    (N'0947F448-776C-55EB-BF16-F82041405975', 4, N'幸福', N'幸福', N'xìng fú', N'hạnh phúc, an lành', N'happiness', N'名、形', NULL, N'[{"zh": "能在闲暇午后陪伴在父母身边品茶聊天，就是人生最实在的幸福。", "pinyin": "Néng zài xiánxiá wǔhòu péibàn zài fùmǔ shēnbiān pǐnchá liáotiān, jiù shì rénshēng zuì shízài de xìngfú.", "meaningVi": "Có thể đồng hành bên cha mẹ vào buổi chiều thảnh thơi nhâm nhi tách trà trò chuyện chính là niềm hạnh phúc chân thực nhất của đời người."}]', N'PUBLISHED', N'C8DC9FD6-E848-464D-A0F0-80259D92C427', N'2026-11-10 13:22:17.806666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'xìngfú'),
    (N'E258564E-260C-4EF0-9D03-F863189FD9AD', 3, N'假期', NULL, N'jiàqī', N'kỳ nghỉ', NULL, N'名', NULL, N'[{"chinese": "这个假期你打算去哪里旅游？", "pinyin": "Zhè gè jiàqī nǐ dǎsuàn qù nǎlǐ lǚyóu?", "translation": "Kỳ nghỉ này bạn dự định đi đâu du lịch?"}]', N'ARCHIVED', NULL, N'2026-11-10 06:58:48.463333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'jiàqī'),
    (N'500FCCC9-B9F3-53E0-81C7-F890848E3426', 4, N'交通', N'交通', N'jiāo tōng', N'giao thông, việc đi lại', N'to be connected', N'名', NULL, N'[{"zh": "随着城市地铁线路的不断完善，市民的日常交通变得越来越便捷。", "pinyin": "Suízhe chéngshì dìtiě xiànlù de búduàn wánshàn, shìmín de rìcháng jiāotōng biànde yuèláiyuè biànjié.", "meaningVi": "Cùng với sự hoàn thiện không ngừng của các tuyến tàu điện ngầm đô thị, giao thông đi lại hằng ngày của người dân ngày càng thuận tiện."}]', N'PUBLISHED', N'CB223D54-B351-4EBC-9A47-018CA23AE6CE', N'2026-11-10 13:22:17.703333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'jiāotōng'),
    (N'A0CA75B4-2408-4FFE-9480-F8BD5B2E79EA', 2, N'这么', NULL, N'zhème', N'như thế này, đến mức này', NULL, N'代', NULL, N'[{"zh": "这个问题没有你想的这么难。", "pinyin": "Zhè gè wèntí méiyǒu nǐ xiǎng de zhème nán.", "meaningVi": "Vấn đề này không khó như bạn nghĩ đâu."}]', N'ARCHIVED', NULL, N'2026-11-10 06:02:08.323333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'zhème'),
    (N'A800287D-A3E9-5C68-BA7B-F8FDEE71118F', 4, N'提', NULL, N'tí', N'nhấc, xách; đề cập', NULL, N'动', NULL, N'[{"chinese": "离开超市时，他两只手都提着沉甸甸的购物袋。", "pinyin": "Líkāi chāoshì shí, tā liǎng zhī shǒu dōu tízhe chéndiāndiān de gòuwùdài.", "translation": "Khi rời siêu thị, hai tay anh ấy đều xách những chiếc túi mua sắm trĩu nặng."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:16.310000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'tí'),
    (N'F3A47AC2-76AB-5A7A-8CAD-F91DF6D63267', 4, N'另', NULL, N'lìng', N'khác, riêng biệt (另/另外)', NULL, N'代、（副）', NULL, N'[{"chinese": "除了不断优化现有的手机操作系统外，研发团队还在积极探索另一个前沿技术领域。", "pinyin": "Chúle búduàn yōuhuà xiànyǒu de shǒujī cāozuò xìtǒng wài, yánfā tuánduì hái zài jījí tànsuǒ lìng yí gè qiányán jìshù lǐngyù.", "translation": "Ngoài việc không ngừng tối ưu hóa hệ điều hành điện thoại hiện có, đội ngũ nghiên cứu còn tích cực tìm tòi một lĩnh vực công nghệ mũi nhọn khác."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:18.436666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'lìng'),
    (N'3442BE02-00D1-555E-913A-F93E9760BBA0', 4, N'院子', NULL, N'yuànzi', N'sân, sân nhà, vườn trong sân', NULL, N'名', NULL, N'[{"chinese": "爷爷在院子里安装了太阳能自动感应庭院灯，每当天黑就会自动亮起柔和的光芒。", "pinyin": "Yéye zài yuànzi lǐ ānzhuāng le tàiyángnéng zìdòng gǎnyìng tíngyuàndēng, měi dāng tiān hēi jiù huì zìdòng liàng qǐ róuhé de guāngmáng.", "translation": "Ông nội đã lắp đặt chiếc đèn sân vườn cảm ứng năng lượng mặt trời trong sân, cứ hễ trời tối là sẽ tự động sáng lên ánh sáng dịu dàng."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:18.530000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'yuànzi'),
    (N'F778F097-716C-585B-81C6-F949BDA3F3C9', 4, N'回信', NULL, N'huíxìn', N'hồi âm, viết thư trả lời', NULL, N'动、名', NULL, N'[{"chinese": "收到老朋友从远方寄来的问候信件后，他当天下午就认真地写了回信。", "pinyin": "Shōudào lǎo péngyou cóng yuǎnfāng jì lái de wènhòu xìnjiàn hòu, tā dāngtiān xiàwǔ jiù rènzhēn de xiě le huíxìn.", "translation": "Sau khi nhận được thư thăm hỏi của người bạn cũ gửi từ phương xa, chiều hôm đó anh ấy đã cẩn thận viết thư hồi âm ngay."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:17.783333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'huíxìn'),
    (N'47090B29-E843-5E52-AFE7-F96DFF4DDA7A', 4, N'确实', N'確實', N'què shí', N'thực sự, đích thực, quả thật', N'indeed', N'副', NULL, N'[{"zh": "大自然是一个相互依存、紧密联系的生命共同体，破坏任何一个生态链条确实都会引发连锁反应。", "pinyin": "Dàzìrán shì yí gè xiānghù yīcún, jǐnmì liánxì de shēngmìng gòngtóngtǐ, pòhuài rènhé yí gè shēngtài liàntiáo quèshí dōu huì yǐnfā liánsuǒ fǎnyìng.", "meaningVi": "Mẹ thiên nhiên là một cộng đồng sinh mệnh nương tựa lẫn nhau và gắn kết chặt chẽ, việc phá hoại bất kỳ mắt xích sinh thái nào quả thực cũng đều sẽ kích hoạt phản ứng dây chuyền."}]', N'PUBLISHED', N'17F5C0E2-6A2D-45BC-99EA-637AA85D6508', N'2026-11-10 13:22:18.636666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'quèshí'),
    (N'330D5D9D-522C-5737-B402-F96E242FB007', 4, N'解释', N'解釋', N'jiě shì', N'giải thích, phân trần', N'explanation', N'动', NULL, N'[{"zh": "请允许我当面向大家详细解释一下导致这次数据误差的具体原因。", "pinyin": "Qǐng yǔnxǔ wǒ dāngmiàn xiàng dàjiā xiángxì jiěshì yíxià dǎozhì zhè cì shùjù wùchā de jùtǐ yuányīn.", "meaningVi": "Xin cho phép tôi trực tiếp giải thích chi tiết với mọi người nguyên nhân cụ thể dẫn tới sai số dữ liệu lần này."}]', N'PUBLISHED', N'CB223D54-B351-4EBC-9A47-018CA23AE6CE', N'2026-11-10 13:22:16.863333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'jiěshì'),
    (N'79A27A04-38BF-4851-97E5-F98A3F3ABC9D', 4, N'网球', N'網球', N'wǎng qiú', N'môn quần vợt, tennis', N'tennis', N'名', NULL, N'[{"zh": "他每个周六下午都去打网球。", "pinyin": "Tā měi gè zhōuliù xiàwǔ dōu qù dǎ wǎngqiú.", "meaningVi": "Anh ấy đều đi đánh quần vợt vào mỗi chiều thứ Bảy."}]', N'PUBLISHED', N'D551AD89-18F8-417A-BC0F-0FCBD23C1448', N'2026-11-11 10:10:25.304391', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary inserted cleanly', N'', N'wǎngqiú'),
    (N'269EE142-2C02-5F45-B595-F99BCE17A851', 4, N'剧院', NULL, N'jùyuàn', N'nhà hát, rạp hát', NULL, N'名', NULL, N'[{"chinese": "国家大剧院利用虚拟现实数字技术，让观众足不出户就能身临其境地欣赏顶级舞台剧。", "pinyin": "Guójiā Dà Jùyuàn lìyòng xūnǐ xiànshí shùzì jìshù, ràng guānzhòng zúbùchūhù jiù néng shēnlínqíjìng de xīnshǎng dǐngjí wǔtáijù.", "translation": "Nhà hát Lớn Quốc gia đã ứng dụng công nghệ số thực tế ảo, giúp khán giả không cần bước chân ra khỏi nhà cũng có thể thưởng thức các vở kịch đỉnh cao như đang có mặt tại chỗ."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:18.426666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'jùyuàn'),
    (N'22679CBE-9FEA-4CFA-8174-F9C04B48E232', 3, N'凉快', NULL, N'liángkuai', N'mát mẻ, dễ chịu', NULL, N'形', NULL, N'[{"chinese": "一阵风吹来，感觉非常凉快。", "pinyin": "Yí zhèn fēng chuī lái, gǎnjué fēicháng liángkuai.", "translation": "Một cơn gió thổi tới, cảm thấy vô cùng mát mẻ."}]', N'ARCHIVED', NULL, N'2026-11-10 06:58:48.616666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'liángkuai'),
    (N'8F53C468-3E41-5E8C-BB05-F9CC3118C39B', 4, N'考虑', N'考慮', N'kǎo lǜ', N'suy nghĩ, cân nhắc', N'to think over', N'动', NULL, N'[{"zh": "在做出更换工作这个重大职业决定之前，请你务必认真充分地考虑各个方面的利弊。", "pinyin": "Zài zuòchū gēnghuàn gōngzuò zhè gè zhòngdà zhíyè juédìng zhīqián, qǐng nǐ wùbì rènzhēn chōngfèn de kǎolǜ gè gè fāngmiàn de lìbì.", "meaningVi": "Trước khi đưa ra quyết định nghề nghiệp quan trọng là đổi việc làm, xin bạn hãy cân nhắc thật kỹ càng và đầy đủ mọi mặt lợi hại."}]', N'PUBLISHED', N'D0A7BB74-A49C-4D2A-B5FB-C34AF6410CF9', N'2026-11-10 13:22:18.053333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'kǎolǜ'),
    (N'EF87A123-27B8-4943-974B-F9E3982E689C', 3, N'汽车', NULL, N'qìchē', N'xe ô tô, xe hơi', NULL, N'名', NULL, N'[{"chinese": "现在街上的新能源汽车越来越多了。", "pinyin": "Xiànzài jiē shang de xīn néngyuán qìchē yuèláiyuè duō le.", "translation": "Bây giờ xe hơi năng lượng mới trên đường phố ngày càng nhiều."}]', N'ARCHIVED', NULL, N'2026-11-10 06:58:48.716666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'qìchē'),
    (N'BBD2689A-8999-57C0-A84C-F9EABB12331A', 4, N'美丽', N'美麗', N'měi lì', N'xinh đẹp, tươi đẹp', N'beautiful', N'形', NULL, N'[{"zh": "春回大地，万物复苏，整个江南水乡展现出一派美丽迷人的迷人风光。", "pinyin": "Chūnhuídàdì, wànwù fùsū, zhěng gè jiāngnán shuǐxiāng zhǎnxiàn chū yí pài měilì mírén de mírén fēngguāng.", "meaningVi": "Xuân về trên đất mẹ, muôn vật hồi sinh, cả vùng sông nước Giang Nam hiện lên một cảnh sắc tươi đẹp say đắm lòng người."}]', N'PUBLISHED', N'C27413F4-ADC8-436F-9436-1530C708008E', N'2026-11-10 13:22:15.940000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'měilì'),
    (N'A7A9BD36-C590-40CB-85FB-FA506DA424B7', 4, N'猪', N'豬', N'zhū', N'con lợn, con heo', N'hog', N'Danh từ', NULL, N'[{"zh": "奶奶在乡下养了几头猪和一些小鸡。", "pinyin": "Nǎinai zài xiāngxià yǎng le jǐ tóu zhū hé yìxiē xiǎojī.", "meaningVi": "Bà nội ở dưới quê nuôi mấy con lợn và một ít gà con."}]', N'PUBLISHED', N'3815613C-581A-4EA8-92A8-F907E35F8BD4', N'2026-11-11 10:10:25.304391', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary inserted cleanly', N'', N'zhū');
