    (N'39215E80-F4A2-50E3-AF06-FF44E0D22EC6', 4, N'使馆', NULL, N'shǐguǎn', N'đại sứ quán, tòa đại sứ', NULL, N'名', NULL, N'[{"chinese": "为了方便海外华侨华人办理领事业务，中国驻外使馆全面推出了在线预约申办平台。", "pinyin": "Wèile fāngbiàn hǎiwài Huáqiáo Huárén bànlǐ lǐngshì yèwù, Zhōngguó zhùwài shǐguǎn quánmiàn tuīchū le zàixiàn yùyuē shēnbàn píngtái.", "translation": "Để tạo thuận tiện cho bà con kiều bào ở nước ngoài làm các thủ tục lãnh sự, đại sứ quán Trung Quốc ở nước ngoài đã triển khai toàn diện nền tảng hẹn trực tuyến."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:18.416666', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'shǐguǎn'),
    (N'8B2E94CC-CAC6-47BD-AA5A-FF46E132C85A', 4, N'行', N'行', N'xíng', N'được, ổn; hàng lối', N'to walk', N'动、形', NULL, N'[{"zh": "没问题，明天上午九点在校门口见面完全行。", "pinyin": "Méi wèntí, míngtiān shàngwǔ jiǔ diǎn zài xiàomén kǒu jiànmiàn wánquán xíng.", "meaningVi": "Không vấn đề gì, sáng mai đúng 9 giờ gặp nhau ở cổng trường hoàn toàn được."}]', N'PUBLISHED', N'90A35972-4CD6-46CB-8FC0-FF111D8DFB71', N'2026-11-11 10:10:25.304391', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary inserted cleanly', N'', N'xíng'),
    (N'6EFC48BD-CB48-5B86-BAA3-FF513544DB22', 4, N'本科', NULL, N'běnkē', N'đại học chính quy, cử nhân', NULL, N'名', NULL, N'[{"chinese": "他在北京大学完成了计算机专业的四年全日制本科学业。", "pinyin": "Tā zài Běijīng Dàxué wánchéng le jìsuànjī zhuānyè de sì nián quánrìzhì běnkē xuéyè.", "translation": "Anh ấy đã hoàn thành 4 năm đại học chính quy chuyên ngành máy tính tại Đại học Bắc Kinh."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:16.830000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'běnkē'),
    (N'DD3DFEF3-3D54-5B47-9AAE-FF6B1C665051', 4, N'够', N'夠', N'gòu', N'đủ, đạt mức', N'to reach', N'动、副', NULL, N'[{"zh": "这些准备材料已经足够充实，足以应对接下来的资格审查。", "pinyin": "Zhèxiē zhǔnbèi cáiliào yǐjīng zúgòu chōngshí, zúyǐ yìngduì jiēxiàlái de zīgé shěnchá.", "meaningVi": "Những tài liệu chuẩn bị này đã đủ đầy đặn, đủ để đáp ứng đợt xét duyệt tư cách sắp tới."}]', N'PUBLISHED', N'4D554AD3-4530-48D4-846E-25F026EEFF5D', N'2026-11-10 13:22:16.433333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'gòu'),
    (N'6F6252B0-EECC-4FBB-BA53-FF7B82528F58', 3, N'洗手间', N'洗手間', N'xǐ shǒu jiān', N'nhà vệ sinh', N'toilet', N'Danh từ', NULL, N'[{"zh": "为了学好汉语，我们需要了解洗手间。", "pinyin": "Wèile xuéhǎo Hànyǔ, wǒmen xūyào liǎojiě xǐshǒujiān.", "meaningVi": "Để học tốt tiếng Trung, chúng ta cần hiểu rõ nhà vệ sinh."}]', N'PUBLISHED', N'8DA33634-03F8-4F90-9BF6-86AC2A793D7D', N'2026-11-11 10:10:25.304391', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary inserted cleanly', N'', N'xǐshǒujiān'),
    (N'D330EA4E-92EA-5A44-A603-FF8E2152B28B', 4, N'全', NULL, N'quán', N'toàn bộ, tất cả, đầy đủ', NULL, N'形、副', NULL, N'[{"chinese": "我们全班同学都积极响应号召，参加了这次周末植树造林活动。", "pinyin": "Wǒmen quán bān tóngxué dōu jījí xiǎngyìng hàozhào, cānjiā le zhè cì zhōumò zhíshù zàolín huódòng.", "translation": "Toàn thể các bạn học sinh trong lớp chúng tôi đều tích cực hưởng ứng lời kêu gọi, tham gia hoạt động trồng cây gây rừng cuối tuần này."}]', N'ARCHIVED', NULL, N'2026-11-10 13:22:17.940000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Archived surplus non-HSK2.0 item', N'', N'quán'),
    (N'35BAF20E-A652-442C-B72C-FFAF5CA5B63B', 3, N'中间', N'中間', N'zhōng jiān', N'ở giữa, chính giữa', N'between', N'名', NULL, N'[{"zh": "坐在中间穿白衬衫的人是王经理。", "pinyin": "Zuò zài zhōngjiān chuān bái chènshān de rén shì Wáng jīnglǐ.", "meaningVi": "Người ngồi ở giữa mặc áo sơ mi trắng là giám đốc Vương."}]', N'PUBLISHED', N'6C60F3F0-E088-4219-84F1-639DF2878BE8', N'2026-11-10 06:58:48.170000', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'zhōngjiān'),
    (N'9AF0DF98-84D8-5DBE-8373-FFCC17F495C6', 4, N'提醒', N'提醒', N'tí xǐng', N'nhắc nhở, lưu ý', N'to remind', N'动', NULL, N'[{"zh": "出发去机场之前，母亲再次提醒他核对护照和登机证件。", "pinyin": "Chūfā qù jīchǎng zhīqián, mǔqīn zàicì tíxǐng tā héduì hùzhào hé dēngjī zhèngjiàn.", "meaningVi": "Trước khi xuất phát ra sân bay, mẹ lại một lần nữa nhắc nhở anh ấy kiểm tra lại hộ chiếu và giấy tờ lên máy bay."}]', N'PUBLISHED', N'D551AD89-18F8-417A-BC0F-0FCBD23C1448', N'2026-11-10 13:22:17.213333', N'2026-11-11 10:10:25.304391', NULL, NULL, NULL, NULL, NULL, N'HSK 2.0', NULL, NULL, N'D3DDED52-2254-4573-9A92-223554CBE1FC', N'E40BA5C2-F13D-4E0A-A0BB-629CA487F84A', N'2026-11-11 10:10:25.304391', N'HSK 2.0 vocabulary synced cleanly', N'', N'tíxǐng');
