  INSERT INTO [exercises] ([Id], [Type], [Skill], [HskLevel], [Title], [Instruction], [PromptHanzi], [PromptPinyin], [PromptVietnamese], [AudioUrl], [OptionsJson], [CorrectOptionIndex], [CorrectAnswer], [Explanation], [XpReward], [Status], [LessonId], [GrammarPointId], [CreatedAt], [UpdatedAt], [ContentHash], [Difficulty], [QualityScore], [ReviewNotes], [ReviewStatus], [ReviewedAt], [ReviewedByUserId], [SourceId], [SourceLicense], [Tags], [VocabularyId], [AdministrativeApprovalNotes], [AdministrativeApprovalScope], [AdministrativeApprovalSource], [AdministrativeApprovalStatus], [AdministrativeApprovedAt], [HumanAcademicReviewStatus], [LessonPresentationJson]) VALUES
    (N'56378901-7060-5730-A0D6-953F977EC8A0', N'sentence-order', N'grammar', 2, N'HSK 2 · Trật tự ngữ pháp: Cấp so sánh nhất với phó từ 最 (zuì)', N'Sắp xếp các thành phần câu theo đúng điểm ngữ pháp HSK.', N'[最好] [旅游] [九] [北京] [月] [去]', NULL, N'Ngữ pháp ''Cấp so sánh nhất với phó từ 最 (zuì)'': "Tháng 9 đi du lịch Bắc Kinh là tốt nhất."', NULL, NULL, NULL, N'九月去北京旅游最好。', N'Câu đúng theo mẫu ''Cấp so sánh nhất với phó từ 最 (zuì)'' (最 + Tính từ / Động từ tâm lý) là "九月去北京旅游最好。" (Jiǔ yuè qù běi jīng lǚ yóu zuì hǎo。) — "Tháng 9 đi du lịch Bắc Kinh là tốt nhất.". Thứ tự các cụm từ chuẩn: [九 → 月 → 去 → 北京 → 旅游 → 最好].', 10, N'DRAFT', N'AFE42FE5-7D93-47A6-B77B-447DAD1E36F6', N'E7B8BC74-CBFA-46BF-869D-78AAF5312C3F', N'2026-11-11 16:33:50.753333', N'2026-11-11 16:33:50.753333', N'fa92005f4264460a42897e2bac8cb45d6839e289241f77c4b3cee6576bf61a0d', N'MEDIUM', 95.0, N'Phase 2 expansion: Tự kiểm định thuật toán, giữ DRAFT/PENDING_REVIEW chờ kiểm duyệt.', N'PENDING_REVIEW', NULL, NULL, N'zhongwenhub-grammar-hsk20-v2', N'INTERNAL_AUTHORED', N'hsk2,grammar,sentence-order,gp-hsk2-l01a', NULL, N'Project owner bulk administrative approval for 4,663 unpublished HSK 1-4 questions. Status remains DRAFT; human academic review still pending.', N'BULK_HSK14_PROJECT_OWNER_ADMIN_APPROVAL', N'PROJECT_OWNER_BULK_ADMIN_DECISION', N'APPROVED', N'2026-11-11 17:04:44.141856', N'PENDING_HUMAN_REVIEW', NULL),
    (N'B446C7B4-F14C-52AB-9EEB-95462A0E47CC', N'fill-blank', N'vocabulary', 3, N'HSK 3 · Điền từ ngữ cảnh (Danh từ)', N'Chọn chữ Hán đúng nhất điền vào chỗ trống theo nghĩa câu.', N'学习一门语言也能了解一个国家的（　）。', N'Xuéxí yì mén yǔyán yě néng liǎojiě yí gè guójiā de wénhuà.', N'Điền từ thích hợp (Danh từ): "Học một ngoại ngữ cũng có thể hiểu về văn hóa của một đất nước."', NULL, N'["校园", "腿", "文化", "笔记本"]', 2, N'文化', N'Chỗ trống cần ''文化'' (wén huà, Danh từ) nghĩa là "văn hóa". Câu hoàn chỉnh: "学习一门语言也能了解一个国家的文化。" (Học một ngoại ngữ cũng có thể hiểu về văn hóa của một đất nước.). Phân biệt các lựa chọn khác: ''校园'' (xiàoyuán): khuôn viên trường; ''笔记本'' (bǐjìběn): sổ tay (văn phòng phẩm); máy tính xách tay; ''腿'' (tuǐ): chân, cẳng chân.', 10, N'DRAFT', N'8DA33634-03F8-4F90-9BF6-86AC2A793D7D', NULL, N'2026-11-11 16:33:50.753333', N'2026-11-11 16:33:50.753333', N'30cf8a4954cdb476bc38e8f74f91105bb7a1f198529888bb7d2d444030603e7f', N'MEDIUM', 96.0, N'Phase 2 expansion: Tự kiểm định thuật toán, giữ DRAFT/PENDING_REVIEW chờ kiểm duyệt.', N'PENDING_REVIEW', NULL, NULL, N'curriculum-vocab', N'INTERNAL_AUTHORED', N'hsk3,vocabulary,contextual-cloze', N'60372B7A-0180-4B7F-8EEC-DD620C20FEC2', N'Project owner bulk administrative approval for 4,663 unpublished HSK 1-4 questions. Status remains DRAFT; human academic review still pending.', N'BULK_HSK14_PROJECT_OWNER_ADMIN_APPROVAL', N'PROJECT_OWNER_BULK_ADMIN_DECISION', N'APPROVED', N'2026-11-11 17:04:44.141856', N'PENDING_HUMAN_REVIEW', NULL),
    (N'6A40E8A0-5C6D-5E5C-A973-956B3FF3E16A', N'fill-blank', N'grammar', 1, N'HSK 1 · Ngữ pháp: Biểu thị mong muốn với động từ năng nguyện 想', N'Chọn từ hoặc kết cấu ngữ pháp phù hợp điền vào chỗ trống.', N'那个地方很近，我不（　）开车。', N'nàgè dìfāng hěn jìn，wǒ bù xiǎng kāichē 。', N'Điền cấu trúc ngữ pháp phù hợp: "Nơi đó rất gần, tôi không muốn lái xe."', NULL, N'["它", "天", "想", "三"]', 2, N'想', N'Cần điền ''想'' theo điểm ngữ pháp ''Biểu thị mong muốn với động từ năng nguyện 想'' (Subj. + 想 + Verb (+ Obj.)). Động từ năng nguyện 想 (xiǎng) đứng trước động từ chính để biểu thị mong muốn, dự định làm việc gì đó. Phân biệt phương án nhiễu: ''它'' (tā): nó (chỉ con vật, đồ vật); ''天'' (tiān): ngày, trời; ''三'' (sān): ba (số 3).', 10, N'DRAFT', N'9C981888-67BD-41BB-B5B0-57D0A1268DD6', N'CDCA77FC-1AED-5777-8774-F7B58FF09216', N'2026-11-11 16:33:50.753333', N'2026-11-11 16:33:50.753333', N'6a163c4fc8b0045a01bf7a9460e451ae83d5c93c4314b2f7a32561bc3eaad3a8', N'EASY', 95.0, N'Phase 2 expansion: Tự kiểm định thuật toán, giữ DRAFT/PENDING_REVIEW chờ kiểm duyệt.', N'PENDING_REVIEW', NULL, NULL, N'zhongwenhub-grammar-hsk20-v2', N'INTERNAL_AUTHORED', N'hsk1,grammar,gp-hsk20-05a', NULL, N'Project owner bulk administrative approval for 4,663 unpublished HSK 1-4 questions. Status remains DRAFT; human academic review still pending.', N'BULK_HSK14_PROJECT_OWNER_ADMIN_APPROVAL', N'PROJECT_OWNER_BULK_ADMIN_DECISION', N'APPROVED', N'2026-11-11 17:04:44.141856', N'PENDING_HUMAN_REVIEW', NULL),
    (N'B8D25694-A62A-498B-9A8E-956EAD02CA18', N'multiple-choice', N'reading', 1, N'Luyện tập từ vựng: 你在做什么呢', N'Chọn nghĩa tiếng Việt đúng cho câu "你在做什么呢"', N'你在做什么呢', N'', N'Bạn đang làm gì thế', NULL, N'["Bạn đang làm gì thế", "Bạn đang đi đâu thế", "Bạn đã làm xong chưa", "Bạn có biết làm không"]', 0, N'Bạn đang làm gì thế', N'Phó từ ''在'' kết hợp với trợ từ ngữ khí ''呢'' biểu thị hành động đang diễn ra -> ''你在做什么呢'' là ''Bạn đang làm gì thế''.', 10, N'PUBLISHED', N'BC8E2F7F-91CD-4014-8BC4-BF4AEE182E41', NULL, N'2026-11-05 18:38:39', N'2026-11-11 08:55:45.645003', N'4360daee96a609e83147e7995119a67de9c7740a61999bf14b0b28108bc2e784', N'EASY', 100.0, NULL, N'APPROVED', NULL, NULL, N'curriculum-seed', N'INTERNAL_AUTHORED', NULL, NULL, N'Original published baseline question already approved and published prior to bulk administrative approval.', N'ORIGINAL_PUBLISHED_BASELINE', N'PROJECT_OWNER_BULK_ADMIN_DECISION', N'APPROVED', N'2026-11-11 17:04:44.253600', N'APPROVED_BASELINE', NULL),
    (N'5C52197D-8DC1-5E4B-BD8F-9576DE8310B2', N'fill-blank', N'vocabulary', 2, N'HSK 2 · Điền từ ngữ cảnh (Động từ)', N'Chọn chữ Hán đúng nhất điền vào chỗ trống theo nghĩa câu.', N'他每天都用（　）。', N'Tā měitiān dōu yòng cuò.', N'Điền từ thích hợp (Động từ): "Anh ấy mỗi ngày đều dùng sai, lỗi."', NULL, N'["拿", "走", "错", "上去"]', 2, N'错', N'Chỗ trống cần ''错'' (cuò, Động từ) nghĩa là "sai, lỗi". Câu hoàn chỉnh: "他每天都用错。" (Anh ấy mỗi ngày đều dùng sai, lỗi.). Phân biệt các lựa chọn khác: ''拿'' (ná): cầm, nắm, lấy; ''走'' (zǒu): đi, đi bộ; ''上去'' (shàngqù): đi lên.', 10, N'DRAFT', N'993A640F-2A33-4E82-A7BE-0787339EF4DD', NULL, N'2026-11-11 16:33:50.753333', N'2026-11-11 16:33:50.753333', N'5d2c5c007a48907ad4906887d1ca21681c49af90c5b32035887cd14ff2d8b358', N'MEDIUM', 96.0, N'Phase 2 expansion: Tự kiểm định thuật toán, giữ DRAFT/PENDING_REVIEW chờ kiểm duyệt.', N'PENDING_REVIEW', NULL, NULL, N'curriculum-vocab', N'INTERNAL_AUTHORED', N'hsk2,vocabulary,contextual-cloze', N'9597BEF4-D0BE-4C5E-A6D3-4D9C54767404', N'Project owner bulk administrative approval for 4,663 unpublished HSK 1-4 questions. Status remains DRAFT; human academic review still pending.', N'BULK_HSK14_PROJECT_OWNER_ADMIN_APPROVAL', N'PROJECT_OWNER_BULK_ADMIN_DECISION', N'APPROVED', N'2026-11-11 17:04:44.141856', N'PENDING_HUMAN_REVIEW', NULL),
    (N'23CA6196-0428-520B-97A5-957DA404175B', N'fill-blank', N'vocabulary', 4, N'HSK 4 · Điền từ ngữ cảnh (Động từ)', N'Chọn chữ Hán đúng nhất điền vào chỗ trống theo nghĩa câu.', N'清澈冰凉的山泉水顺着陡峭的青石板一路欢快地（　）向谷底的小溪。', N'Qīngchè bīngliáng de shānquánshuǐ shùnzhe dǒuqiào de qīngshíbǎn yílù huānkuài de liú xiàng gǔdǐ de xiǎoxī.', N'Điền từ thích hợp (Động từ): "Dòng nước suối nguồn mát lạnh trong vắt men theo vách đá xanh dốc đứng vui tươi chảy về khe suối dưới thung lũng."', NULL, N'["流", "租", "打扰", "谈"]', 0, N'流', N'Chỗ trống cần ''流'' (liú, Động từ) nghĩa là "chảy; truyền bá; lưu thông hoặc lan truyền". Câu hoàn chỉnh: "清澈冰凉的山泉水顺着陡峭的青石板一路欢快地流向谷底的小溪。" (Dòng nước suối nguồn mát lạnh trong vắt men theo vách đá xanh dốc đứng vui tươi chảy về khe suối dưới thung lũng.). Phân biệt các lựa chọn khác: ''打扰'' (dǎ rǎo): quấy rầy, làm phiền; ''租'' (zū): thuê, mướn; ''谈'' (tán): nói chuyện, trò chuyện, bàn luận, đàm đạo.', 10, N'DRAFT', NULL, NULL, N'2026-11-11 16:33:50.753333', N'2026-11-11 16:33:50.753333', N'6d69ef9b0955856d73dbdad6350631991bc36c92683d892d7fd3d2595d5cf24f', N'HARD', 96.0, N'Phase 2 expansion: Tự kiểm định thuật toán, giữ DRAFT/PENDING_REVIEW chờ kiểm duyệt.', N'PENDING_REVIEW', NULL, NULL, N'curriculum-vocab', N'INTERNAL_AUTHORED', N'hsk4,vocabulary,contextual-cloze', N'703331C1-00A9-50A1-ACC9-F30CD446F932', N'Project owner bulk administrative approval for 4,663 unpublished HSK 1-4 questions. Status remains DRAFT; human academic review still pending.', N'BULK_HSK14_PROJECT_OWNER_ADMIN_APPROVAL', N'PROJECT_OWNER_BULK_ADMIN_DECISION', N'APPROVED', N'2026-11-11 17:04:44.141856', N'PENDING_HUMAN_REVIEW', NULL),
    (N'6E9296E3-711F-5FBF-8EE5-958094254B02', N'multiple-choice', N'vocabulary', 4, N'HSK 4 · Từ vựng: 大量', N'Chọn nghĩa tiếng Việt chính xác nhất cho từ vựng sau.', N'大量', N'dàliàng', N'Từ loại: Tính từ', NULL, N'["thuận lợi, suôn sẻ, trôi chảy", "xin lỗi, lấy làm tiếc", "giả, nhân tạo; kỳ nghỉ (nghỉ phép)", "lượng lớn; số lượng nhiều; số lượng lớn"]', 3, N'lượng lớn; số lượng nhiều; số lượng lớn', N'Từ ''大量'' (dàliàng, Tính từ) mang nghĩa "lượng lớn; số lượng nhiều; số lượng lớn". Ví dụ: "课外阅读让孩子们接触了大量生动有趣的百科知识，极大地开阔了知识视野。" (Đọc sách ngoại khóa giúp các em tiếp xúc với một lượng lớn kiến thức bách khoa sinh động thú vị, mở rộng tầm nhìn hiểu biết rất nhiều.). Phân biệt: "xin lỗi, lấy làm tiếc" là nghĩa của ''抱歉'' (bào qiàn); "thuận lợi, suôn sẻ, trôi chảy" là nghĩa của ''顺利'' (shùn lì); "giả, nhân tạo; kỳ nghỉ (nghỉ phép)" là nghĩa của ''假'' (jiǎ).', 10, N'DRAFT', NULL, NULL, N'2026-11-11 16:33:50.753333', N'2026-11-11 16:33:50.753333', N'96db76eba09b4c9f49ed7892d274b5a2cf45bb6e34357fdf0abcf29cfbcf9c2d', N'HARD', 92.0, N'Phase 2 expansion: Tự kiểm định thuật toán, giữ DRAFT/PENDING_REVIEW chờ kiểm duyệt.', N'PENDING_REVIEW', NULL, NULL, N'curriculum-vocab', N'INTERNAL_AUTHORED', N'hsk4,vocabulary,meaning-recognition', N'9ACBAE40-4905-586B-963A-8EE69A6BE0B3', N'Project owner bulk administrative approval for 4,663 unpublished HSK 1-4 questions. Status remains DRAFT; human academic review still pending.', N'BULK_HSK14_PROJECT_OWNER_ADMIN_APPROVAL', N'PROJECT_OWNER_BULK_ADMIN_DECISION', N'APPROVED', N'2026-11-11 17:04:44.141856', N'PENDING_HUMAN_REVIEW', NULL),
    (N'8686791B-E9F6-4A14-B0F7-958347EA0D62', N'multiple-choice', N'sentence', 4, N'HSK 4 TEST-06 · Câu 61', N'Chọn thứ tự sắp xếp A-B-C logic nhất để tạo thành đoạn hoàn chỉnh.', N'61. 请将下列句子排列成正确顺序：A 一定要允许其他人有反对意见 B 一个合格的公司管理者 C 甚至表达自己的不满', NULL, N'Nguồn HSK 4 thực tế (InAnskr/HSK4Level-Test)', NULL, N'["BAC", "ABC", "BCA", "CAB"]', 0, N'BAC', N'Trình tự câu chính xác là ''BAC'' dựa trên quan hệ liên kết giữa các vế A–B–C. Chú ý mạch chủ ngữ dẫn nhập -> triển khai/nguyên nhân -> kết luận. Các trật tự nhiễu (ABC, BCA, CAB) làm đứt mạch thời gian hoặc quan hệ nhân-quả của câu HSK 4. (Nguồn: InAnskr/HSK4Level-Test/test-06.json#Q61, CC BY-NC-SA 4.0)', 10, N'DRAFT', NULL, NULL, N'2026-11-11 15:35:08.174409', N'2026-11-11 16:32:56.660000', N'ae4571068f2b5509e420de22955cd273174514659e9351946bfaa710e278ff36', N'HARD', 85.0, N'Phase 2 audit: Đã nâng cấp giải thích tiếng Việt; nguồn đề thi CC-BY-NC-SA-4.0 chờ giảng viên/kiểm duyệt học thuật rà soát trước khi xuất bản.', N'NEEDS_ACADEMIC_REVIEW', NULL, NULL, N'InAnskr/HSK4Level-Test/test-06.json#Q61', N'CC-BY-NC-SA-4.0', N'hsk4,sentence,reading_ordering,inanskr', NULL, N'Project owner bulk administrative approval for 4,663 unpublished HSK 1-4 questions. Status remains DRAFT; human academic review still pending.', N'BULK_HSK14_PROJECT_OWNER_ADMIN_APPROVAL', N'PROJECT_OWNER_BULK_ADMIN_DECISION', N'APPROVED', N'2026-11-11 17:04:44.141856', N'PENDING_HUMAN_REVIEW', NULL),
    (N'02183236-FD61-4217-9242-959720597DAC', N'multiple-choice', N'vocabulary', 1, N'HSK 1 · Nghĩa của từ "二"', N'Chọn nghĩa tiếng Việt đúng nhất cho từ tiếng Trung dưới đây.', N'二', N'èr', N'Từ vựng HSK 1', NULL, N'["bảy (số 7)", "ba (số 3)", "hai (số 2)", "một (số 1)"]', 2, N'hai (số 2)', N'Từ ''二'' (èr, Số từ) mang nghĩa "hai (số 2)". Ví dụ: "现在两点二十分。" (Bây giờ là hai giờ hai mươi phút.). Phân biệt: các lựa chọn còn lại (bảy (số 7); ba (số 3); một (số 1)) tương ứng với từ vựng khác trong HSK 1.', 10, N'DRAFT', N'AAAAAAAA-4444-4444-4444-444444444444', NULL, N'2026-11-11 15:35:08.174409', N'2026-11-11 16:32:56.666666', N'86c8301eb8d38e553ba6681ab223c21a031fdd190d0241b4e99510639831391f', N'EASY', 92.0, N'Phase 2 audit: Đã chuẩn hóa phương án loại trùng, ngữ cảnh hóa câu điền khuyết và nâng cấp giải thích tiếng Việt (chờ duyệt xuất bản).', N'VALIDATED', NULL, NULL, N'drkameleon/complete-hsk-vocabulary', N'MIT', N'hsk1,vocabulary,drkameleon-mit,zh-to-vi', N'3A4EE043-7F2C-4C26-AF67-54A56B261AA9', N'Project owner bulk administrative approval for 4,663 unpublished HSK 1-4 questions. Status remains DRAFT; human academic review still pending.', N'BULK_HSK14_PROJECT_OWNER_ADMIN_APPROVAL', N'PROJECT_OWNER_BULK_ADMIN_DECISION', N'APPROVED', N'2026-11-11 17:04:44.141856', N'PENDING_HUMAN_REVIEW', NULL),
    (N'4AE21AA1-37C7-477A-9BC5-95B01E1AC601', N'multiple-choice', N'reading', 5, N'Luyện tập từ vựng: 成语故事两则', N'Chọn nghĩa tiếng Việt chính xác của bài học “成语故事两则”.', N'成语故事两则', N'', N'Hai câu chuyện thành ngữ', NULL, N'["Hai câu chuyện thành ngữ", "Nghĩa khác A", "Nghĩa khác B", "Nghĩa khác C"]', 0, N'Hai câu chuyện thành ngữ', N'Nghĩa chính xác là: Hai câu chuyện thành ngữ', 10, N'DRAFT', N'CB8B00DF-95D6-4121-A46D-79D6196F813D', NULL, N'2026-11-05 18:38:39', NULL, N'ef1d7fa27cec35fabb716ac46cdde5099cee032a71a4920cff9ff0ffc7aaa17c', N'MEDIUM', NULL, NULL, N'DRAFT', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'NONE', NULL, N'NOT_REVIEWED', NULL),
    (N'847B400F-5C83-5427-AC4F-95B9BBE28A48', N'fill-blank', N'vocabulary', 4, N'HSK 4 · Điền từ ngữ cảnh (Tính từ)', N'Chọn chữ Hán đúng nhất điền vào chỗ trống theo nghĩa câu.', N'随着全国高铁网络的（　）延展，早上在西安吃泡馍、下午在成都看大熊猫已经成为现实。', N'Suízhe quánguó gāotiě wǎngluò de kuàisù yánzhǎn, zǎoshang zài Xī''ān chī pàomó, xiàwǔ zài Chéngdū kàn dàxióngmāo yǐjīng chéngwéi xiànshí.', N'Điền từ thích hợp (Tính từ): "Cùng với sự mở rộng nhanh chóng của mạng lưới tàu cao tốc toàn quốc, buổi sáng ở Tây An ăn bánh mì canh thịt, buổi chiều ở Thành Đô ngắm gấu trúc đã trở thành hiện thực."', NULL, N'["凉", "伤心", "窄", "快速"]', 3, N'快速', N'Chỗ trống cần ''快速'' (kuàisù, Tính từ) nghĩa là "nhanh; tốc độ cao; mau lẹ". Câu hoàn chỉnh: "随着全国高铁网络的快速延展，早上在西安吃泡馍、下午在成都看大熊猫已经成为现实。" (Cùng với sự mở rộng nhanh chóng của mạng lưới tàu cao tốc toàn quốc, buổi sáng ở Tây An ăn bánh mì canh thịt, buổi chiều ở Thành Đô ngắm gấu trúc đã trở thành hiện thực.). Phân biệt các lựa chọn khác: ''伤心'' (shāng xīn): đau lòng, buồn bã, tổn thương; ''凉'' (liáng): năm nước Lương trong Thập lục quốc, cụ thể là: Tiền Lương 前涼|前凉 (314-376), Hậu Lương 後涼|后凉 (386-403), Bắc Lương 北涼|北凉 (398-439), Nam Lương 南涼|南凉 (397-414), Tây Lương 西涼|西凉 (400-421); ''窄'' (zhǎi): hẹp, chật hẹp.', 10, N'DRAFT', NULL, NULL, N'2026-11-11 16:33:50.753333', N'2026-11-11 16:33:50.753333', N'e90cb0b7e0078ff7a4ce6b61e4c292537dca46da6000febaf1c09e7039759eb4', N'HARD', 96.0, N'Phase 2 expansion: Tự kiểm định thuật toán, giữ DRAFT/PENDING_REVIEW chờ kiểm duyệt.', N'PENDING_REVIEW', NULL, NULL, N'curriculum-vocab', N'INTERNAL_AUTHORED', N'hsk4,vocabulary,contextual-cloze', N'EF6742B7-F2FA-5C94-AA0C-B58CE2E0FB84', N'Project owner bulk administrative approval for 4,663 unpublished HSK 1-4 questions. Status remains DRAFT; human academic review still pending.', N'BULK_HSK14_PROJECT_OWNER_ADMIN_APPROVAL', N'PROJECT_OWNER_BULK_ADMIN_DECISION', N'APPROVED', N'2026-11-11 17:04:44.141856', N'PENDING_HUMAN_REVIEW', NULL),
    (N'E93299EA-1395-524B-BBC1-95DB52A179D8', N'multiple-choice', N'vocabulary', 4, N'HSK 4 · Từ vựng: 各地', N'Chọn nghĩa tiếng Việt chính xác nhất cho từ vựng sau.', N'各地', N'gèdì', N'Từ loại: Danh từ', NULL, N'["trước mắt; bây giờ; hiện tại", "ở khắp mọi nơi (của một quốc gia); các vùng khác nhau", "nhật ký", "diễn viên"]', 1, N'ở khắp mọi nơi (của một quốc gia); các vùng khác nhau', N'Từ ''各地'' (gèdì, Danh từ) mang nghĩa "ở khắp mọi nơi (của một quốc gia); các vùng khác nhau". Ví dụ: "来自全国各地的优秀青年学者齐聚北京，共同研讨学术前沿。" (Các học giả trẻ xuất sắc đến từ khắp nơi trên cả nước hội tụ tại Bắc Kinh, cùng thảo luận về tiền tuyến học thuật.). Phân biệt: "diễn viên" là nghĩa của ''演员'' (yǎn yuán); "trước mắt; bây giờ; hiện tại" là nghĩa của ''眼前'' (yǎnqián); "nhật ký" là nghĩa của ''日记'' (rì jì).', 10, N'DRAFT', NULL, NULL, N'2026-11-11 16:33:50.753333', N'2026-11-11 16:33:50.753333', N'685fe1f0cfd9e8192d3a667449e393f8b91baf18057cfe9683350eb75416cc66', N'HARD', 92.0, N'Phase 2 expansion: Tự kiểm định thuật toán, giữ DRAFT/PENDING_REVIEW chờ kiểm duyệt.', N'PENDING_REVIEW', NULL, NULL, N'curriculum-vocab', N'INTERNAL_AUTHORED', N'hsk4,vocabulary,meaning-recognition', N'4148F22C-6887-508A-B057-BF935507E722', N'Project owner bulk administrative approval for 4,663 unpublished HSK 1-4 questions. Status remains DRAFT; human academic review still pending.', N'BULK_HSK14_PROJECT_OWNER_ADMIN_APPROVAL', N'PROJECT_OWNER_BULK_ADMIN_DECISION', N'APPROVED', N'2026-11-11 17:04:44.141856', N'PENDING_HUMAN_REVIEW', NULL),
    (N'92823F1D-6506-5233-BB66-95E13F525469', N'sentence-order', N'grammar', 2, N'HSK 2 · Trật tự ngữ pháp: Cụm từ: Cụm danh từ (名词性短语)', N'Sắp xếp các thành phần câu theo đúng điểm ngữ pháp HSK.', N'[买两] [张去] [上海的] [票] [火车] [我想]', NULL, N'Ngữ pháp ''Cụm từ: Cụm danh từ (名词性短语)'': "Tôi muốn mua hai vé tàu hỏa đi Thượng Hải."', NULL, NULL, NULL, N'我想买两张去上海的火车票。', N'Câu đúng theo mẫu ''Cụm từ: Cụm danh từ (名词性短语)'' (Định ngữ + (的) + Danh từ trung tâm) là "我想买两张去上海的火车票。" (Wǒ xiǎng mǎi liǎng zhāng qù Shànghǎi de huǒchē piào.) — "Tôi muốn mua hai vé tàu hỏa đi Thượng Hải.". Thứ tự các cụm từ chuẩn: [我想 → 买两 → 张去 → 上海的 → 火车 → 票].', 10, N'DRAFT', NULL, N'CCB365EA-B286-48AF-AAAC-6347DA7821DF', N'2026-11-11 16:33:50.753333', N'2026-11-11 16:33:50.753333', N'6a5f4ee8d9fb6e55b01af73b0406f63fe402d34058cf7c8e46ad7d355cbf814a', N'MEDIUM', 95.0, N'Phase 2 expansion: Tự kiểm định thuật toán, giữ DRAFT/PENDING_REVIEW chờ kiểm duyệt.', N'PENDING_REVIEW', NULL, NULL, N'zhongwenhub-grammar-hsk20-v2', N'INTERNAL_AUTHORED', N'hsk2,grammar,sentence-order,gr30-hsk2-108', NULL, N'Project owner bulk administrative approval for 4,663 unpublished HSK 1-4 questions. Status remains DRAFT; human academic review still pending.', N'BULK_HSK14_PROJECT_OWNER_ADMIN_APPROVAL', N'PROJECT_OWNER_BULK_ADMIN_DECISION', N'APPROVED', N'2026-11-11 17:04:44.141856', N'PENDING_HUMAN_REVIEW', NULL),
    (N'63AE276B-E270-5940-9339-95E9325BD8C1', N'multiple-choice', N'vocabulary', 2, N'HSK 2 · Từ vựng: 红色', N'Chọn nghĩa tiếng Việt chính xác nhất cho từ vựng sau.', N'红色', N'hóngsè', N'Từ loại: Danh từ', NULL, N'["sự việc, công việc", "màu đỏ (màu sắc); cách mạng", "trà sữa", "cà phê"]', 1, N'màu đỏ (màu sắc); cách mạng', N'Từ ''红色'' (hóngsè, Danh từ) mang nghĩa "màu đỏ (màu sắc); cách mạng". Phân biệt: "cà phê" là nghĩa của ''咖啡'' (kā fēi); "trà sữa" là nghĩa của ''奶茶'' (nǎichá); "sự việc, công việc" là nghĩa của ''事情'' (shì qíng).', 10, N'DRAFT', NULL, NULL, N'2026-11-11 16:33:50.753333', N'2026-11-11 16:33:50.753333', N'37c7937de4d841e2adca9d78ae1040673da8a5642b5175b19dfceb54bda38641', N'MEDIUM', 92.0, N'Phase 2 expansion: Tự kiểm định thuật toán, giữ DRAFT/PENDING_REVIEW chờ kiểm duyệt.', N'PENDING_REVIEW', NULL, NULL, N'curriculum-vocab', N'INTERNAL_AUTHORED', N'hsk2,vocabulary,meaning-recognition', N'7AAD318D-CFC7-4F63-909F-D13108A046D8', N'Project owner bulk administrative approval for 4,663 unpublished HSK 1-4 questions. Status remains DRAFT; human academic review still pending.', N'BULK_HSK14_PROJECT_OWNER_ADMIN_APPROVAL', N'PROJECT_OWNER_BULK_ADMIN_DECISION', N'APPROVED', N'2026-11-11 17:04:44.141856', N'PENDING_HUMAN_REVIEW', NULL),
    (N'82A0C53C-94A9-5AEF-9B55-95EC0FF01505', N'sentence-order', N'grammar', 4, N'HSK 4 · Trật tự ngữ pháp: Kết cấu phủ định lựa chọn 不是……而是……', N'Sắp xếp các thành phần câu theo đúng điểm ngữ pháp HSK.', N'[的而是最] [不是最好] [商品往往] [合适] [自己的] [最贵的]', NULL, N'Ngữ pháp ''Kết cấu phủ định lựa chọn 不是……而是……'': "Món đắt nhất thường không phải món tốt nhất, mà là món hợp nhất với mình."', NULL, NULL, NULL, N'最贵的商品往往不是最好的，而是最合适自己的。', N'Câu đúng theo mẫu ''Kết cấu phủ định lựa chọn 不是……而是……'' (主语 + 不是 + A + ，而是 + B) là "最贵的商品往往不是最好的，而是最合适自己的。" (Zuì guì de shāng pǐn wǎng wǎng bú shì zuì hǎo de， ér shì zuì hé shì zì jǐ de。) — "Món đắt nhất thường không phải món tốt nhất, mà là món hợp nhất với mình.". Thứ tự các cụm từ chuẩn: [最贵的 → 商品往往 → 不是最好 → 的而是最 → 合适 → 自己的].', 10, N'DRAFT', N'4D554AD3-4530-48D4-846E-25F026EEFF5D', N'65C7CEE4-F3FE-475B-8529-A34B0F8F0BF6', N'2026-11-11 16:33:50.753333', N'2026-11-11 16:33:50.753333', N'43ad8d7bab21004bf5f806a8a47b27e1777e1996b52c99e0bb1a40aa8cd1ff6f', N'HARD', 95.0, N'Phase 2 expansion: Tự kiểm định thuật toán, giữ DRAFT/PENDING_REVIEW chờ kiểm duyệt.', N'PENDING_REVIEW', NULL, NULL, N'zhongwenhub-grammar-hsk20-v2', N'INTERNAL_AUTHORED', N'hsk4,grammar,sentence-order,gp-hsk4-l05b', NULL, N'Project owner bulk administrative approval for 4,663 unpublished HSK 1-4 questions. Status remains DRAFT; human academic review still pending.', N'BULK_HSK14_PROJECT_OWNER_ADMIN_APPROVAL', N'PROJECT_OWNER_BULK_ADMIN_DECISION', N'APPROVED', N'2026-11-11 17:04:44.141856', N'PENDING_HUMAN_REVIEW', NULL),
    (N'56DA037B-F339-5E60-9390-95FA320C3E0E', N'fill-blank', N'vocabulary', 3, N'HSK 3 · Điền từ ngữ cảnh (Động từ)', N'Chọn chữ Hán đúng nhất điền vào chỗ trống theo nghĩa câu.', N'旅游团明天早上七点准时从酒店（　）。', N'Lǚyóutuán míngtiān zǎoshang qī diǎn zhǔnshí cóng jiǔdiàn chūfā.', N'Điền từ thích hợp (Động từ): "Đoàn du lịch sáng mai đúng 7 giờ sẽ xuất phát từ khách sạn."', NULL, N'["结束", "提高", "出发", "洗澡"]', 2, N'出发', N'Chỗ trống cần ''出发'' (chūfā, Động từ) nghĩa là "khởi hành; bắt đầu (một hành trình)". Câu hoàn chỉnh: "旅游团明天早上七点准时从酒店出发。" (Đoàn du lịch sáng mai đúng 7 giờ sẽ xuất phát từ khách sạn.). Phân biệt các lựa chọn khác: ''结束'' (jié shù): kết thúc, chấm dứt; ''洗澡'' (xǐ zǎo): tắm, tắm rửa; ''提高'' (tí gāo): nâng cao, cải thiện.', 10, N'DRAFT', NULL, NULL, N'2026-11-11 16:33:50.753333', N'2026-11-11 16:33:50.753333', N'c326cf510e95bad32578a1c2cc61b157769130275a3d3cb672ed900b2eb523c2', N'MEDIUM', 96.0, N'Phase 2 expansion: Tự kiểm định thuật toán, giữ DRAFT/PENDING_REVIEW chờ kiểm duyệt.', N'PENDING_REVIEW', NULL, NULL, N'curriculum-vocab', N'INTERNAL_AUTHORED', N'hsk3,vocabulary,contextual-cloze', N'6D91C2AE-3430-4C61-9348-AC402B6DD215', N'Project owner bulk administrative approval for 4,663 unpublished HSK 1-4 questions. Status remains DRAFT; human academic review still pending.', N'BULK_HSK14_PROJECT_OWNER_ADMIN_APPROVAL', N'PROJECT_OWNER_BULK_ADMIN_DECISION', N'APPROVED', N'2026-11-11 17:04:44.141856', N'PENDING_HUMAN_REVIEW', NULL),
    (N'5B5D1CF7-5C5D-404D-B39C-95FF086C3B49', N'fill-blank', N'vocabulary', 1, N'HSK 1 · Gõ chữ Hán (jīn tiān)', N'Gõ đúng chữ Hán tương ứng với Pinyin và nghĩa tiếng Việt.', N'（　）天气很好。', N'Jīntiān tiānqì hěn hǎo.', N'Hoàn thành câu: "Hôm nay thời tiết rất đẹp."', NULL, N'["歌", "先生", "今天", "出租车"]', 2, N'今天', N'Đáp án là ''今天'' (jīn tiān, Danh từ) nghĩa là "hôm nay". Ví dụ: "今天天气很好。" (Hôm nay thời tiết rất đẹp.). Phân biệt phương án nhiễu: ''歌'' (gē): bài hát, ca khúc; ''先生'' (xiān shēng): tiên sinh, ông, thầy, chồng; ''出租车'' (chū zū chē): xe taxi.', 10, N'DRAFT', N'F6AC147D-5091-4495-B018-A935385F4B87', NULL, N'2026-11-11 15:35:08.174409', N'2026-11-11 16:32:56.673333', N'd7eb89da2b1d07db1b069c403f4f64321375caa72bdc1bc4df2415fdaabf5ae1', N'EASY', 92.0, N'Phase 2 audit: Đã chuẩn hóa phương án loại trùng, ngữ cảnh hóa câu điền khuyết và nâng cấp giải thích tiếng Việt (chờ duyệt xuất bản).', N'VALIDATED', NULL, NULL, N'drkameleon/complete-hsk-vocabulary', N'MIT', N'hsk1,fill-blank,drkameleon-mit', N'ED6DC171-23C6-40E0-9A5C-266BB70C0E26', N'Project owner bulk administrative approval for 4,663 unpublished HSK 1-4 questions. Status remains DRAFT; human academic review still pending.', N'BULK_HSK14_PROJECT_OWNER_ADMIN_APPROVAL', N'PROJECT_OWNER_BULK_ADMIN_DECISION', N'APPROVED', N'2026-11-11 17:04:44.141856', N'PENDING_HUMAN_REVIEW', NULL),
    (N'91D3814D-03AF-4907-8EAF-961FBBB122A1', N'listen-choice', N'listening', 3, N'Nghe hiểu hội thoại - Bài 18', N'Nghe đoạn ghi âm và chọn đáp án đúng:', NULL, NULL, N'Bạn thân đã nhắn tin động viên Tiểu Trương trước việc gì?', N'/audio/hsk3/les18_listening.mp3', N'["Kỳ thi lái xe", "Buổi phỏng vấn tại công ty lớn", "Chuyến đi máy bay đầu tiên", "Cuộc thi chạy marathon"]', 1, N'Buổi phỏng vấn tại công ty lớn', N'Đoạn nghe nêu rõ: "明天的面试是小张第一次去大公司应聘".', 15, N'PUBLISHED', N'AEFDEADE-2E81-43D6-A78C-F397B3E74F06', NULL, N'2026-11-11 10:10:28.304391', N'2026-11-11 10:10:28.304391', N'cac1a41e388120a16709705eeabf521a4b20b362ea1b23add2ec465ff55ed7e0', N'MEDIUM', 100.0, NULL, N'APPROVED', NULL, NULL, N'curriculum-seed', N'INTERNAL_AUTHORED', NULL, NULL, N'Original published baseline question already approved and published prior to bulk administrative approval.', N'ORIGINAL_PUBLISHED_BASELINE', N'PROJECT_OWNER_BULK_ADMIN_DECISION', N'APPROVED', N'2026-11-11 17:04:44.253600', N'APPROVED_BASELINE', NULL),
    (N'E8A08EFF-8E63-5677-8AC0-964D56792D2B', N'fill-blank', N'vocabulary', 4, N'HSK 4 · Điền từ ngữ cảnh (Phó từ)', N'Chọn chữ Hán đúng nhất điền vào chỗ trống theo nghĩa câu.', N'新算法的采用（　）提升了超级计算机处理海量数据的速度。', N'Xīn suànfǎ de cǎiyòng dàdà tíshēng le chāojí jìsuànjī chǔlǐ hǎiliàng shùjù de sùdù.', N'Điền từ thích hợp (Phó từ): "Việc áp dụng thuật toán mới đã nâng cao đáng kể tốc độ xử lý dữ liệu khổng lồ của siêu máy tính."', NULL, N'["大大", "从中", "基本上", "顺便"]', 0, N'大大', N'Chỗ trống cần ''大大'' (dàdà, Phó từ) nghĩa là "rất nhiều; cực kỳ; (phương ngữ) ba". Câu hoàn chỉnh: "新算法的采用大大提升了超级计算机处理海量数据的速度。" (Việc áp dụng thuật toán mới đã nâng cao đáng kể tốc độ xử lý dữ liệu khổng lồ của siêu máy tính.). Phân biệt các lựa chọn khác: ''从中'' (cóngzhōng): từ bên trong; từ đó; ''基本上'' (jīběnshàng): về cơ bản; nhìn chung; ''顺便'' (shùn biàn): tiện thể, nhân tiện.', 10, N'DRAFT', NULL, NULL, N'2026-11-11 16:33:50.753333', N'2026-11-11 16:33:50.753333', N'd15457a22a2c94b11f4a81deb7df49fba7ebecd9a27c30a9cdd125b82aff3741', N'HARD', 96.0, N'Phase 2 expansion: Tự kiểm định thuật toán, giữ DRAFT/PENDING_REVIEW chờ kiểm duyệt.', N'PENDING_REVIEW', NULL, NULL, N'curriculum-vocab', N'INTERNAL_AUTHORED', N'hsk4,vocabulary,contextual-cloze', N'B22A3B2C-3FDB-53A3-916B-6033581B5C89', N'Project owner bulk administrative approval for 4,663 unpublished HSK 1-4 questions. Status remains DRAFT; human academic review still pending.', N'BULK_HSK14_PROJECT_OWNER_ADMIN_APPROVAL', N'PROJECT_OWNER_BULK_ADMIN_DECISION', N'APPROVED', N'2026-11-11 17:04:44.141856', N'PENDING_HUMAN_REVIEW', NULL),
    (N'761125CF-C7B8-54FC-B711-964F6AD34972', N'vietnamese-to-chinese', N'vocabulary', 2, N'HSK 2 · Phản xạ Việt - Hán', N'Chọn chữ Hán tương ứng với nghĩa tiếng Việt và từ loại gợi ý.', NULL, NULL, N'vị trí; địa điểm; chỗ (Lượng từ)', NULL, N'["起来", "位", "公斤", "第一"]', 1, N'位', N'Chữ Hán tương ứng với "vị trí; địa điểm; chỗ" là ''位'' (wèi, Lượng từ). Phân biệt các phương án còn lại: ''公斤'' (gōng jīn): ki-lô-gam (kg); ''第一'' (dì yī): thứ nhất, đầu tiên; ''起来'' (qǐlái): đứng lên; thức dậy.', 10, N'DRAFT', NULL, NULL, N'2026-11-11 16:33:50.753333', N'2026-11-11 16:33:50.753333', N'f1014d5a7a06b4ee1f0664c619e6e6a75bbe7b09dd407fc15c79058435d7a178', N'MEDIUM', 90.0, N'Phase 2 expansion: Tự kiểm định thuật toán, giữ DRAFT/PENDING_REVIEW chờ kiểm duyệt.', N'PENDING_REVIEW', NULL, NULL, N'curriculum-vocab', N'INTERNAL_AUTHORED', N'hsk2,vocabulary,active-recall', N'45FDD0CE-915B-4B28-AD78-49C4354D886B', N'Project owner bulk administrative approval for 4,663 unpublished HSK 1-4 questions. Status remains DRAFT; human academic review still pending.', N'BULK_HSK14_PROJECT_OWNER_ADMIN_APPROVAL', N'PROJECT_OWNER_BULK_ADMIN_DECISION', N'APPROVED', N'2026-11-11 17:04:44.141856', N'PENDING_HUMAN_REVIEW', NULL),
    (N'FAFCA5CA-FAC4-5737-B40A-9658107282F0', N'fill-blank', N'vocabulary', 3, N'HSK 3 · Điền từ ngữ cảnh (Danh từ)', N'Chọn chữ Hán đúng nhất điền vào chỗ trống theo nghĩa câu.', N'他们在学校附近租了一套新（　）。', N'Tāmen zài xuéxiào fùjìn zū le yí tào xīn fángzi.', N'Điền từ thích hợp (Danh từ): "Họ đã thuê một căn nhà mới ở gần trường học."', NULL, N'["环境", "房子", "东南", "草"]', 1, N'房子', N'Chỗ trống cần ''房子'' (fángzi, Danh từ) nghĩa là "nhà; tòa nhà (một hoặc hai tầng); căn hộ". Câu hoàn chỉnh: "他们在学校附近租了一套新房子。" (Họ đã thuê một căn nhà mới ở gần trường học.). Phân biệt các lựa chọn khác: ''环境'' (huán jìng): môi trường, cảnh quan xung quanh; ''草'' (cǎo): cỏ; ''东南'' (dōngnán): đông nam.', 10, N'DRAFT', NULL, NULL, N'2026-11-11 16:33:50.753333', N'2026-11-11 16:33:50.753333', N'3be2e076539d0dfbea377a6c4dc5ac1e0f3b24b2d43ad6ab34249f649189f58f', N'MEDIUM', 96.0, N'Phase 2 expansion: Tự kiểm định thuật toán, giữ DRAFT/PENDING_REVIEW chờ kiểm duyệt.', N'PENDING_REVIEW', NULL, NULL, N'curriculum-vocab', N'INTERNAL_AUTHORED', N'hsk3,vocabulary,contextual-cloze', N'8C325C79-7FA9-48CC-9B0E-A2F278CE680B', N'Project owner bulk administrative approval for 4,663 unpublished HSK 1-4 questions. Status remains DRAFT; human academic review still pending.', N'BULK_HSK14_PROJECT_OWNER_ADMIN_APPROVAL', N'PROJECT_OWNER_BULK_ADMIN_DECISION', N'APPROVED', N'2026-11-11 17:04:44.141856', N'PENDING_HUMAN_REVIEW', NULL),
    (N'2B5507BD-D715-5551-BF27-966594FEBFC7', N'sentence-order', N'grammar', 1, N'HSK 1 · Trật tự ngữ pháp: Động từ năng nguyện: 可以', N'Sắp xếp các thành phần câu theo đúng điểm ngữ pháp HSK.', N'[语法点的] [注意这个] [和语序] [请大家] [具体] [位置]', NULL, N'Ngữ pháp ''Động từ năng nguyện: 可以'': "Xin mọi người chú ý vị trí cụ thể và trật tự từ của điểm ngữ pháp này."', NULL, NULL, NULL, N'请大家注意这个语法点的具体位置和语序。', N'Câu đúng theo mẫu ''Động từ năng nguyện: 可以'' (S + 可以 + V + (O)) là "请大家注意这个语法点的具体位置和语序。" (Qǐng dàjiā zhùyì zhè ge yǔfǎdiǎn de jùtǐ wèizhì hé yǔxù.) — "Xin mọi người chú ý vị trí cụ thể và trật tự từ của điểm ngữ pháp này.". Thứ tự các cụm từ chuẩn: [请大家 → 注意这个 → 语法点的 → 具体 → 位置 → 和语序].', 10, N'DRAFT', NULL, N'2B80D0B3-2F33-4C48-86B0-C481298AF715', N'2026-11-11 16:33:50.753333', N'2026-11-11 16:33:50.753333', N'a93a7fab9290804fed3666747349bcf13801d109a86a48a46cf9fef6dcc4a92d', N'MEDIUM', 95.0, N'Phase 2 expansion: Tự kiểm định thuật toán, giữ DRAFT/PENDING_REVIEW chờ kiểm duyệt.', N'PENDING_REVIEW', NULL, NULL, N'zhongwenhub-grammar-hsk20-v2', N'INTERNAL_AUTHORED', N'hsk1,grammar,sentence-order,gr30-hsk1-006', NULL, N'Project owner bulk administrative approval for 4,663 unpublished HSK 1-4 questions. Status remains DRAFT; human academic review still pending.', N'BULK_HSK14_PROJECT_OWNER_ADMIN_APPROVAL', N'PROJECT_OWNER_BULK_ADMIN_DECISION', N'APPROVED', N'2026-11-11 17:04:44.141856', N'PENDING_HUMAN_REVIEW', NULL),
    (N'61309236-6F37-5F4D-97F3-966D647879BF', N'fill-blank', N'vocabulary', 4, N'HSK 4 · Điền từ ngữ cảnh (数量)', N'Chọn chữ Hán đúng nhất điền vào chỗ trống theo nghĩa câu.', N'他们（　）是从小一起长大的好朋友，感情非常深厚。', N'Tāmen liǎ shì cóngxiǎo yìqǐ zhǎngdà de hǎo péngyou, gǎnqíng fēicháng shēnhòu.', N'Điền từ thích hợp (数量): "Hai người họ là bạn thân lớn lên cùng nhau từ bé, tình cảm vô cùng sâu đậm."', NULL, N'["光", "感", "俩", "星星"]', 2, N'俩', N'Chỗ trống cần ''俩'' (liǎ, 数量) nghĩa là "hai người, hai (cách nói khẩu ngữ)". Câu hoàn chỉnh: "他们俩是从小一起长大的好朋友，感情非常深厚。" (Hai người họ là bạn thân lớn lên cùng nhau từ bé, tình cảm vô cùng sâu đậm.). Phân biệt các lựa chọn khác: ''感'' (gǎn): cảm thấy; làm cảm động; chạm vào; ''光'' (guāng): ánh sáng; chỉ; hết; ''星星'' (xīngxing): (thông tục) một ngôi sao; những ngôi sao trên trời.', 10, N'DRAFT', N'C27413F4-ADC8-436F-9436-1530C708008E', NULL, N'2026-11-11 16:33:50.753333', N'2026-11-11 16:33:50.753333', N'c2ae323190aeb777ebec09c560bf252f38b27f371d37caac3ecb19648b3fe79b', N'HARD', 96.0, N'Phase 2 expansion: Tự kiểm định thuật toán, giữ DRAFT/PENDING_REVIEW chờ kiểm duyệt.', N'PENDING_REVIEW', NULL, NULL, N'curriculum-vocab', N'INTERNAL_AUTHORED', N'hsk4,vocabulary,contextual-cloze', N'CC7EFFB8-7A6A-59B2-B09F-105B6B2D1D20', N'Project owner bulk administrative approval for 4,663 unpublished HSK 1-4 questions. Status remains DRAFT; human academic review still pending.', N'BULK_HSK14_PROJECT_OWNER_ADMIN_APPROVAL', N'PROJECT_OWNER_BULK_ADMIN_DECISION', N'APPROVED', N'2026-11-11 17:04:44.141856', N'PENDING_HUMAN_REVIEW', NULL),
    (N'78002425-7715-5CF4-8054-9676C2846FA1', N'fill-blank', N'vocabulary', 3, N'HSK 3 · Điền từ ngữ cảnh (Danh từ)', N'Chọn chữ Hán đúng nhất điền vào chỗ trống theo nghĩa câu.', N'下个月学校将举行一年一度的秋季（　）。', N'Xià gè yuè xuéxiào jiāng jǔxíng yì nián yí dù de qiūjì yùndònghuì.', N'Điền từ thích hợp (Danh từ): "Tháng sau nhà trường sẽ tổ chức đại hội thể thao mùa thu thường niên."', NULL, N'["矿泉水", "运动会", "以下", "名单"]', 1, N'运动会', N'Chỗ trống cần ''运动会'' (yùndònghuì, Danh từ) nghĩa là "cuộc thi thể thao". Câu hoàn chỉnh: "下个月学校将举行一年一度的秋季运动会。" (Tháng sau nhà trường sẽ tổ chức đại hội thể thao mùa thu thường niên.). Phân biệt các lựa chọn khác: ''矿泉水'' (kuàngquánshuǐ): nước khoáng; ''名单'' (míngdān): danh sách tên; ''以下'' (yǐxià): mức đó hoặc thấp hơn; số lượng đó hoặc ít hơn; những điều sau.', 10, N'DRAFT', NULL, NULL, N'2026-11-11 16:33:50.753333', N'2026-11-11 16:33:50.753333', N'1acb9bf8bf1556f0d5ac10fb46272704e9e984be486917285830392c7065cb5e', N'MEDIUM', 96.0, N'Phase 2 expansion: Tự kiểm định thuật toán, giữ DRAFT/PENDING_REVIEW chờ kiểm duyệt.', N'PENDING_REVIEW', NULL, NULL, N'curriculum-vocab', N'INTERNAL_AUTHORED', N'hsk3,vocabulary,contextual-cloze', N'9A4AD5B0-06B5-4EC5-A34A-79A1C55C7D5A', N'Project owner bulk administrative approval for 4,663 unpublished HSK 1-4 questions. Status remains DRAFT; human academic review still pending.', N'BULK_HSK14_PROJECT_OWNER_ADMIN_APPROVAL', N'PROJECT_OWNER_BULK_ADMIN_DECISION', N'APPROVED', N'2026-11-11 17:04:44.141856', N'PENDING_HUMAN_REVIEW', NULL),
    (N'817ED3AA-27EC-4ADA-AF9E-968683B93BD6', N'fill-blank', N'vocabulary', 1, N'HSK 1 · Gõ chữ Hán (lěng)', N'Gõ đúng chữ Hán tương ứng với Pinyin và nghĩa tiếng Việt.', N'今天不（　）。', N'Jīntiān bù lěng.', N'Hoàn thành câu: "Hôm nay không lạnh."', NULL, N'["早", "热", "好玩儿", "冷"]', 3, N'冷', N'Đáp án là ''冷'' (lěng, Tính từ) nghĩa là "lạnh". Ví dụ: "今天不冷。" (Hôm nay không lạnh.). Phân biệt phương án nhiễu: ''早'' (zǎo): sớm, buổi sáng; ''热'' (rè): nóng, nhiệt độ cao; ''好玩儿'' (hǎowánr): vui vẻ, thú vị, hấp dẫn.', 10, N'DRAFT', N'778CF4E8-1BDD-4C63-8352-C9DB74CFAA70', NULL, N'2026-11-11 15:35:08.174409', N'2026-11-11 16:32:56.680000', N'd2e0c9a4d0f2059c7701484efb97cf158179c38583f161ed12ed9b6edafd6049', N'EASY', 92.0, N'Phase 2 audit: Đã chuẩn hóa phương án loại trùng, ngữ cảnh hóa câu điền khuyết và nâng cấp giải thích tiếng Việt (chờ duyệt xuất bản).', N'VALIDATED', NULL, NULL, N'drkameleon/complete-hsk-vocabulary', N'MIT', N'hsk1,fill-blank,drkameleon-mit', N'73F238FB-F78A-4B9B-8F9C-D1C655A7CF4A', N'Project owner bulk administrative approval for 4,663 unpublished HSK 1-4 questions. Status remains DRAFT; human academic review still pending.', N'BULK_HSK14_PROJECT_OWNER_ADMIN_APPROVAL', N'PROJECT_OWNER_BULK_ADMIN_DECISION', N'APPROVED', N'2026-11-11 17:04:44.141856', N'PENDING_HUMAN_REVIEW', NULL),
