  INSERT INTO [exercises] ([Id], [Type], [Skill], [HskLevel], [Title], [Instruction], [PromptHanzi], [PromptPinyin], [PromptVietnamese], [AudioUrl], [OptionsJson], [CorrectOptionIndex], [CorrectAnswer], [Explanation], [XpReward], [Status], [LessonId], [GrammarPointId], [CreatedAt], [UpdatedAt], [ContentHash], [Difficulty], [QualityScore], [ReviewNotes], [ReviewStatus], [ReviewedAt], [ReviewedByUserId], [SourceId], [SourceLicense], [Tags], [VocabularyId], [AdministrativeApprovalNotes], [AdministrativeApprovalScope], [AdministrativeApprovalSource], [AdministrativeApprovalStatus], [AdministrativeApprovedAt], [HumanAcademicReviewStatus], [LessonPresentationJson]) VALUES
    (N'13DE2346-40C3-5F6C-83B0-A79C4C84AACD', N'sentence-order', N'grammar', 4, N'HSK 4 · Trật tự ngữ pháp: Kết cấu 同时 (tóngshí) — đồng thời, cùng lúc', N'Sắp xếp các thành phần câu theo đúng điểm ngữ pháp HSK.', N'[心参与社] [非常出色] [同时还热] [她工作] [区志愿] [服务]', NULL, N'Ngữ pháp ''Kết cấu 同时 (tóngshí) — đồng thời, cùng lúc'': "Cô ấy làm việc rất xuất sắc, đồng thời còn nhiệt tình tham gia tình nguyện cộng đồng."', NULL, NULL, NULL, N'她工作非常出色，同时还热心参与社区志愿服务。', N'Câu đúng theo mẫu ''Kết cấu 同时 (tóngshí) — đồng thời, cùng lúc'' (Vế A + ，同时 + Vế B / ……的同时) là "她工作非常出色，同时还热心参与社区志愿服务。" (Tā gōng zuò fēi cháng chū sè， tóng shí hái rè xīn cān yù shè qū zhì yuàn fú wù。) — "Cô ấy làm việc rất xuất sắc, đồng thời còn nhiệt tình tham gia tình nguyện cộng đồng.". Thứ tự các cụm từ chuẩn: [她工作 → 非常出色 → 同时还热 → 心参与社 → 区志愿 → 服务].', 10, N'DRAFT', N'C8DC9FD6-E848-464D-A0F0-80259D92C427', N'3EC6EABD-62F8-42F4-B1E5-45DFFCC8722F', N'2026-11-11 16:33:50.753333', N'2026-11-11 16:33:50.753333', N'1bd5ab39ad2eb76bee81ad35002f179ae047150148250ef335042d2d9e0d760c', N'HARD', 95.0, N'Phase 2 expansion: Tự kiểm định thuật toán, giữ DRAFT/PENDING_REVIEW chờ kiểm duyệt.', N'PENDING_REVIEW', NULL, NULL, N'zhongwenhub-grammar-hsk20-v2', N'INTERNAL_AUTHORED', N'hsk4,grammar,sentence-order,gp-hsk4-l17b', NULL, N'Project owner bulk administrative approval for 4,663 unpublished HSK 1-4 questions. Status remains DRAFT; human academic review still pending.', N'BULK_HSK14_PROJECT_OWNER_ADMIN_APPROVAL', N'PROJECT_OWNER_BULK_ADMIN_DECISION', N'APPROVED', N'2026-11-11 17:04:44.141856', N'PENDING_HUMAN_REVIEW', NULL),
    (N'F0F2DEFE-1D8F-5231-83E7-A7A0499273D9', N'fill-blank', N'vocabulary', 4, N'HSK 4 · Điền từ ngữ cảnh (Danh từ)', N'Chọn chữ Hán đúng nhất điền vào chỗ trống theo nghĩa câu.', N'他的性格（　）开朗乐于助人，是同学们心目中最受欢迎的班干部。', N'Tā de xìnggé yángguāng kāilǎng lèyú-zhùrén, shì tóngxuémen xīnmù zhōng zuì shòu huānyíng de bān gànbù.', N'Điền từ thích hợp (Danh từ): "Tính cách anh ấy ấm áp, hoạt bát, hay giúp đỡ mọi người, là cán sự lớp được chào đón nhất trong mắt các bạn học."', NULL, N'["阳光", "酸奶", "风景", "底"]', 0, N'阳光', N'Chỗ trống cần ''阳光'' (yáng guāng, Danh từ) nghĩa là "ánh nắng, ánh mặt trời; (tính cách) ấm áp, lạc quan". Câu hoàn chỉnh: "他的性格阳光开朗乐于助人，是同学们心目中最受欢迎的班干部。" (Tính cách anh ấy ấm áp, hoạt bát, hay giúp đỡ mọi người, là cán sự lớp được chào đón nhất trong mắt các bạn học.). Phân biệt các lựa chọn khác: ''酸奶'' (suānnǎi): sữa chua; ''底'' (dǐ): đáy, phần dưới; cuối (tháng/năm) (dǐ); ''风景'' (fēng jǐng): phong cảnh, cảnh sắc.', 10, N'DRAFT', N'C8DC9FD6-E848-464D-A0F0-80259D92C427', NULL, N'2026-11-11 16:33:50.753333', N'2026-11-11 16:33:50.753333', N'4c3ef56464c2b60d40f9999bdf0c8e7323af4ee4c67a66bd20412d138875d943', N'HARD', 96.0, N'Phase 2 expansion: Tự kiểm định thuật toán, giữ DRAFT/PENDING_REVIEW chờ kiểm duyệt.', N'PENDING_REVIEW', NULL, NULL, N'curriculum-vocab', N'INTERNAL_AUTHORED', N'hsk4,vocabulary,contextual-cloze', N'7662FF71-01CA-5C96-A796-AF6A044E75A6', N'Project owner bulk administrative approval for 4,663 unpublished HSK 1-4 questions. Status remains DRAFT; human academic review still pending.', N'BULK_HSK14_PROJECT_OWNER_ADMIN_APPROVAL', N'PROJECT_OWNER_BULK_ADMIN_DECISION', N'APPROVED', N'2026-11-11 17:04:44.141856', N'PENDING_HUMAN_REVIEW', NULL),
    (N'A1C8C1CD-AE93-51BF-A601-A7A2B511FC10', N'sentence-order', N'grammar', 1, N'HSK 1 · Trật tự ngữ pháp: Câu phức: ……，还……', N'Sắp xếp các thành phần câu theo đúng điểm ngữ pháp HSK.', N'[和语序] [位置] [语法点的] [请大家] [注意这个] [具体]', NULL, N'Ngữ pháp ''Câu phức: ……，还……'': "Xin mọi người chú ý vị trí cụ thể và trật tự từ của điểm ngữ pháp này."', NULL, NULL, NULL, N'请大家注意这个语法点的具体位置和语序。', N'Câu đúng theo mẫu ''Câu phức: ……，还……'' (……，还……) là "请大家注意这个语法点的具体位置和语序。" (Qǐng dàjiā zhùyì zhè ge yǔfǎdiǎn de jùtǐ wèizhì hé yǔxù.) — "Xin mọi người chú ý vị trí cụ thể và trật tự từ của điểm ngữ pháp này.". Thứ tự các cụm từ chuẩn: [请大家 → 注意这个 → 语法点的 → 具体 → 位置 → 和语序].', 10, N'DRAFT', NULL, N'9B8369BA-A76D-43B6-A0AB-24A9A02759F5', N'2026-11-11 16:33:50.753333', N'2026-11-11 16:33:50.753333', N'12a8d1c023489beecb0a9c790c02013ab3a8fd26d498bad515fb57d2cedfff58', N'MEDIUM', 95.0, N'Phase 2 expansion: Tự kiểm định thuật toán, giữ DRAFT/PENDING_REVIEW chờ kiểm duyệt.', N'PENDING_REVIEW', NULL, NULL, N'zhongwenhub-grammar-hsk20-v2', N'INTERNAL_AUTHORED', N'hsk1,grammar,sentence-order,gr30-hsk1-061', NULL, N'Project owner bulk administrative approval for 4,663 unpublished HSK 1-4 questions. Status remains DRAFT; human academic review still pending.', N'BULK_HSK14_PROJECT_OWNER_ADMIN_APPROVAL', N'PROJECT_OWNER_BULK_ADMIN_DECISION', N'APPROVED', N'2026-11-11 17:04:44.141856', N'PENDING_HUMAN_REVIEW', NULL),
    (N'E782DD67-7AF3-428F-B92D-A7A56A6A81F3', N'multiple-choice', N'grammar', 2, N'Luyện tập ngữ pháp bài 8', N'Phân tích cấu trúc câu và trật tự từ chuẩn của bài học 8.', N'让我想想再告诉你', N'', N'Để tôi suy nghĩ rồi nói cho bạn biết nhé', NULL, N'["Đúng trật tự cú pháp HSK 2", "Sai vị trí tân ngữ", "Thiếu phó từ", "Dùng sai trợ từ"]', 0, N'Đúng trật tự cú pháp HSK 2', N'Câu mẫu tuân theo đúng trật tự từ HSK 2.', 10, N'ARCHIVED', NULL, NULL, N'2026-11-05 18:38:39', N'2026-11-11 10:10:25.304391', N'6de229bee24574a0b5d47862a9da7bb2033dd90631678ef04ed1a56115d7c0c5', N'MEDIUM', NULL, NULL, N'DRAFT', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'NONE', NULL, N'NOT_REVIEWED', NULL),
