  INSERT INTO [exercises] ([Id], [Type], [Skill], [HskLevel], [Title], [Instruction], [PromptHanzi], [PromptPinyin], [PromptVietnamese], [AudioUrl], [OptionsJson], [CorrectOptionIndex], [CorrectAnswer], [Explanation], [XpReward], [Status], [LessonId], [GrammarPointId], [CreatedAt], [UpdatedAt], [ContentHash], [Difficulty], [QualityScore], [ReviewNotes], [ReviewStatus], [ReviewedAt], [ReviewedByUserId], [SourceId], [SourceLicense], [Tags], [VocabularyId], [AdministrativeApprovalNotes], [AdministrativeApprovalScope], [AdministrativeApprovalSource], [AdministrativeApprovalStatus], [AdministrativeApprovedAt], [HumanAcademicReviewStatus], [LessonPresentationJson]) VALUES
    (N'CE4BA79F-FF03-4094-9397-B0211D9D33A5', N'multiple-choice', N'vocabulary', 4, N'L02.E2: Từ vựng chỉ tình bạn 友谊', N'Chọn từ vựng đúng để hoàn thiện câu văn.', N'真正的______需要经得起时间和困难的考验，不会因为距离遥远而淡漠。', N'Zhēnzhèng de ______ xūyào jīngdéqǐ shíjiān hé kùnnan de kǎoyàn, bú huì yīnwèi jùlí yáoyuǎn ér dànmò.', N'______ chân chính cần chịu được thử thách của thời gian và khó khăn, không vì khoảng cách xa xôi mà phai nhạt.', NULL, N'["友谊 (yǒuyì - tình bạn, tình hữu nghị)", "压力 (yālì - áp lực)", "脾气 (píqi - tính khí)", "礼貌 (lǐmào - lễ phép)"]', 0, N'友谊 (yǒuyì - tình bạn, tình hữu nghị)', N'Trong ngữ cảnh nói về sự gắn bó giữa bạn bè qua thời gian, ''友谊'' là danh từ chính xác nhất.', 10, N'ARCHIVED', NULL, NULL, N'2026-11-05 18:38:39', N'2026-11-11 10:10:25.304391', N'fc8d2f7a29706e1a789ca77b731f06aad2caeff9f31e1376fc85ef249a1067ff', N'MEDIUM', NULL, NULL, N'DRAFT', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'NONE', NULL, N'NOT_REVIEWED', NULL),
